vvi b;

bool possible(int mid) {
  vi lis(mid+2);
  rep (i, mid) {
    lis[i] = b[i][1];
  }
  lis[mid] = -1;
  lis[mid+1] = n;
  sort(all(lis));
  int cnt = 0;
  rep (i, mid+1) {
    int d = lis[i+1] - lis[i] - 1;
    cnt += max(0, d - k + 1);
  }
  if (cnt >= q) {
    return true;
  } else {
    return false;
  }
}

int main() {
  scanf("%d %d %d", &n, &k, &q);
  vi a(n);
  rep (i, n) {
    scanf("%d", &a[i]);
  }
  b.assign(n, vi(2));
  rep (i, n) {
    b[i][0] = a[i];
    b[i][1] = i;
  }
  sort(all(b));

  int l = 0; // possible
  int r = n; // impossible
  while (r - l > 1) {
    int mid = (l + r) / 2;
    if (possible(mid)) {
      l = mid;
    } else {
      r = mid;
    }
  }
  int ans = 1e9;
  rep (i, r) {
    ans = min(ans, b[i + q - 1][0] - b[i][0]);
  }
