int n, m, Q;
int a[maxN];
pair<int, int> val[maxN], b[maxN];
bool vis[maxN];
int num[maxN];

int calc() {
	int tt = 0, bl = 0;
	for (int i = 1, j = 1; i <= n; i = j) {
		while (i <= n && vis[i]) ++i;
		if (i > n) break;
		for (j = i; j <= n && !vis[j]; ++j);
		int len = j - i;
		if (len < m) continue;
		num[++bl] = len - m + 1;
		rep (k, i, j-1) b[++tt] = (pair<int, int>){a[k], bl};
	}
	int cnt = 0, mx = 0;
	sort(b+1, b+tt+1);
	rep (i, 1, tt) if (num[b[i].second] > 0) {
		--num[b[i].second];
		mx = b[i].first;
		if (++cnt == Q) return mx;
	}
	return INF;
}

