template <class T> using Tree = tree<T, null_type, less<T>, 
	rb_tree_tag, tree_order_statistics_node_update>; 

ostream & operator << (ostream & os, const pii & x) { return os << '(' << x.first << ' ' << x.second << ')';}
const int maxn = 1e5 + 10;
int a[maxn], fa[maxn];
int ans = 2e9;
vector<pii> b; 
Tree<pii> t[maxn], all, ret;
bool vis[maxn];
int getfa(int x) { return fa[x] == x ? x : fa[x] = getfa(fa[x]);} 
void join(Tree<pii> & x, Tree<pii> & y)
{
	if(x.size() >= y.size())
	{
		for(auto v : y)
			x.insert(v);
		y.clear();
	}
	else
	{
		for(auto v : x)
			y.insert(v);
		x.clear();
		swap(x, y);
	}
}
int main()
{
	int n, k, q;
	scanf("%d%d%d", &n, &k, &q);
	for(int i = 1; i <= n; ++i)
	{
		scanf("%d", &a[i]);
		b.push_back(mp(a[i], i));
		fa[i] = i;
		t[i].insert(mp(a[i], i));
	}
	sort(b.begin(), b.end(), greater<pii>());
	for(auto item : b)
	{
		int i = item.second;
		vis[i] = 1;
		if(vis[i - 1])
		{
			int u = getfa(i), v = getfa(i - 1);
			fa[u] = getfa(v);
			join(t[v], t[u]);
		}
		if(vis[i + 1])
		{
			int u = getfa(i + 1), v = getfa(i);
			fa[u] = getfa(v);
			join(t[v], t[u]);
		}
		int x = getfa(i);
		if(t[x].size() >= k)
		{
			t[x].split(*t[x].find_by_order(t[x].size() - k), ret);
			swap(t[x], ret);
			join(all, ret);
		}
		if(all.size() >= q)
			ans = min(ans, all.find_by_order(q - 1)->first - all.begin()->first);
	}
	printf("%d\n", ans);
	return 0;
}

