struct Node{
	int val;
	Node *l, *r;
	Node(int val, Node *l, Node *r) : val(val), l(l), r(r){}
	Node *update(int pos, int x, int y){
		if(pos < x || pos > y)	return this;
		if(x == y){
			return new Node(val + 1, NULL, NULL);
		}
		int mid = (x + y) / 2;
		return new Node(val + 1, l->update(pos, x, mid), r->update(pos, mid + 1, y));
	}
}*seg[100005];

int query(Node *le, Node *ri, int x, int y, int k){
	if(x == y)	return x;
	int mid = (x + y) / 2;
	int cnt = ri->l->val - le->l->val;
	if(cnt >= k)	return query(le->l, ri->l, x, mid, k);
	return query(le->r, ri->r, mid + 1, y, k - cnt);
}


ll func(int l, int r, int dep){
	if(l > r)	return 1e18;
	if(dep == Q - 1){
		return rmp[query(seg[l - 1], seg[r], 1, N, Q)] - rmp[query(seg[l - 1], seg[r], 1, N, 1)];
	}
	ll &ret = dp[l][r];
	if(ret != -1)	return ret;
	ret = 1e18;
	if(1 <= l - 1)	ret = min(ret, func(l - 1, r, dep + 1));
	if(r + 1 <= N)	ret = min(ret, func(l, r + 1, dep + 1));
	return ret;
}

int main(){
