		mp[A[i].second] = i;
		rmp[i] = A[i].first;
	}
	for(int i = 1; i <= N; i++){
		seg[i] = seg[i - 1]->update(mp[i], 1, N);
	}
	ll ans = 1e18;
	for(int i = 1; i + K - 1 <= N; i++){
		ans = min(ans, func(i, i + K - 1, 0));
	}
