const int inf = 1 << 30;
int N, K, Q;
int A[2010], L[2010], R[2010];
vector<pii> vs;

void update(pii p){
    int val = p.first;
    int idx = p.second;
    for(int i = 0; i < idx; i++){
        R[i] = min(R[i], idx - i - 1);
    }
    for(int i = idx + 1; i < N; i++){
        L[i] = min(L[i], i - idx - 1);
    }
}

int solve(){
    int ans = inf;
    for(int i = 0; i < N; i++){
        int val = vs[i].first;
        int idx = vs[i].second;
        if(L[idx] + R[idx] + 1 >= K){
            int cnt = 1;
            for(int j = i + 1; j < N; j++){
                idx = vs[j].second;
                if(L[idx] + R[idx] + 1 >= K) cnt++;
                if(cnt == Q){
                    ans = min(ans, vs[j].first - val);
                    break;
                }
            }
        }
        update(vs[i]);
    }
    if(Q == 1) ans = 0;
    return ans;
}

void init(){
    cin >> N >> K >> Q;
    for(int i = 0; i < N; i++){
        cin >> A[i];
        vs.push_back({A[i], i});
