    sort(vs.begin(), vs.end());
    for(int i = 0; i < N; i++){
        for(int j = 0; j < i; j++){
            if(A[j] > A[i]) L[i]++;
        }
        for(int j = i + 1; j < N; j++){
            if(A[j] >= A[i]) R[i]++;
        }
    }
}

int main(){
    init();
    cout << solve() << endl;
    return 0;
}

