            for(int j=0;j<N;j++){
                if(i==j) continue;

                if(A[j]<A[i]){
                    if(S.size()<K) vector<int> S;
                    else{
                        sort(all(S));
                        for(int k=0;k<=S.size()-K;k++){
                            T.push_back(S[k]);
                        }
                        vector<int> S;
                    }
                }else{
                    S.push_back(A[j]);
                }

                if(j==N-1){
                    if(S.size()>=K){
                        sort(all(S));
                        for(int k=0;k<=S.size()-K;k++){
                            T.push_back(S[k]);
                        }
                    }
                }
            }

            sort(all(T));

