class LazySegmentTree {
public:
	int n;
	vector<pii> node, lazy;

	LazySegmentTree(vector<pii> a) {
		int _n = a.size();
		n = 1; while (n < _n) n *= 2;
		node.resize(2 * n - 1);
		lazy.resize(2 * n - 1, pii(-2 * inf, -2 * inf));
		for (int i = 0; i < _n; i++) node[i + n - 1] = a[i];
		for (int i = n - 2; i >= 0; i--) {
			node[i].first = node[i * 2 + 1].first + node[i * 2 + 2].first;
			node[i].second = node[i * 2 + 1].second + node[i * 2 + 2].second;
		}
	}

	// k番目のノードについて遅延評価を行う
	inline void eval(int k, int l, int r) {
		if (lazy[k].first != -2 * inf) {
			node[k].first = (r - l) * lazy[k].first;
			node[k].second = (r - l) * lazy[k].second;
			if (r - l > 1) {
				lazy[2 * k + 1] = lazy[k]; /////
				lazy[2 * k + 2] = lazy[k]; /////
			}
			lazy[k] = pii(-2 * inf, -2 * inf);
		}
	}

	// [a, b)をxにする
	void add(int a, int b, pii x, int k, int l, int r) {
		// k 番目のノードに対して遅延評価を行う
		eval(k, l, r);
		if (b <= l || r <= a) return;
		if (a <= l && r <= b) {
			lazy[k] = x;
			eval(k, l, r);
		}
		else {
			add(a, b, x, 2 * k + 1, l, (l + r) / 2);
			add(a, b, x, 2 * k + 2, (l + r) / 2, r);
			node[k].first = node[2 * k + 1].first + node[2 * k + 2].first;
			node[k].second = node[2 * k + 1].second + node[2 * k + 2].second;
		}
	}

	pii getsum(int a, int b, int k, int l, int r) {
		eval(k, l, r);
		if (b <= l || r <= a) return pii(0, 0);
		if (a <= l && r <= b) return node[k];
		pii resl = getsum(a, b, 2 * k + 1, l, (l + r) / 2);
		pii resr = getsum(a, b, 2 * k + 2, (l + r) / 2, r);
		return pii(resl.first + resr.first, resl.second + resr.second);
	}
};

class Bit {
public:
	int n;
	vl bit; // 1-index

	Bit(int _n) { n = _n; bit.resize(n); }


	// [1, i]の和
	// [0, i)の和
	ll sum(int i) {
		ll s = 0;
		while (i > 0) {
			s += bit[i - 1];
			i -= i & -i;
		}
		return s;
	}

	//iは1-index
	void add(int i, ll x) {
		i++;
		while (i <= n) {
			bit[i - 1] += x;
			i += i & -i;
		}
	}

	// bitに入ってる中でx番目に小さい数を求める
	// 1番小さい数はx = 1;
	// bitに3を入れる→add(3, 1), 3を出す→add(3, -1)
	ll min_xth(int x) {
		int left = 0, right = 200000;
		while (left + 1 < right) {
			int mid = (left + right) / 2;
			int temp = sum(mid);
			if (temp < x) {
				left = mid;
			}
			else {
				right = mid;
			}
		}
		return right;
	}

};


int main() {
	int n, k, q;
