	rep(i, n) {
		ai[i].first = a[i]; ai[i].second = i;
	}
	sort(ai.begin(), ai.end());
	vi idx(n);
	rep(i, n) {
		idx[i] = ai[i].second;
	}
	vector<bool> used(n);
	vector<pii> b(n, pii(-1, n));
	int ans = inf;
	rep(i, n) {
		LazySegmentTree lst(b);
		Bit bit(n);
		rep(j, i) {
			used[idx[j]] = true;
			pii now = lst.getsum(idx[j], idx[j] + 1, 0, 0, lst.n);
			lst.add(now.first + 1, idx[j], pii(now.first, idx[j]), 0, 0, lst.n);
			lst.add(idx[j] + 1, now.second, pii(idx[j], now.second), 0, 0, lst.n);
		}
		int cnt = 0;
		int j = i;
		int mi = inf;
		int ma = 0;
		while (cnt < q && j < n) {
			//DEBUG(j);
			//DEBUG(idx[j]);
