			mi = min(mi, a[idx[j]]);
			ma = max(ma, a[idx[j]]);
			cnt++;
			bit.add(idx[j], 1);
			j++;
		}
		//DEBUG(cnt);
		if (cnt < q) {
			break;
		}
		else {
			ans = min(ma - mi, ans);
		}
	}
