vector<int> adj[maxn];
int ufs[maxn];
inline int find(int u){
	if (ufs[u]==u) return u;
	else return ufs[u]=find(ufs[u]);
}
multiset<int> st[maxn];
inline void upd(int u,int x){
	if (st[u].size()<k-1){
		st[u].insert(x);
		return;
	}
	else{
		multiset<int>::iterator it1;
		it1=st[u].begin();
		if ((*it1)<x){
			int tp=(*it1);
			//cout<<"print tp x "<<tp<<' '<<x<<endl;
			st[u].erase(it1);
			st[u].insert(x);
			insert(1,1,len,tp,1);
		}
		else{
			insert(1,1,len,x,1);
		}
	}
}
inline void prints(multiset<int> s){
	for (multiset<int>::iterator it2=s.begin();it2!=s.end();it2++){
		cout<<(*it2)<<' ';
	}
	cout<<endl;
}
inline void join(int u,int v){
	if (u==0||v==0) return ;
	int ru=find(u),rv=find(v);
	if (ru==rv) return;
	if (st[ru].size()<st[rv].size()) swap(ru,rv);
	for (multiset<int>::iterator it2=st[rv].begin();it2!=st[rv].end();it2++){
		upd(ru,(*it2));
	}
	st[rv].clear();
	ufs[rv]=ru;
}
inline void add(int id){
	upd(find(id),a[id]);
	int u=id-1,v=id+1;
	if (v==n+1) v=0;
	if (a[u]<a[id]) u=0;
	if (a[v]<a[id]) v=0;
	if (u==0&&v==0) return;
	join(id,u);
	join(id,v);
}
