template<class T>bool chmin(T& a, const T& b) { if (b < a) { a = b; return 1; } return 0; }



void func(long long N, long long K, long long Q, std::vector<long long> A){

    set<lli> s;
    //step1,
    lli cnt=0;
    while(1){
        if(s.size()>=Q)break;
        lli minNum = INF;
        lli minIndex=0;
        REP(i,0,K)if(chmin(minNum,A[i]))minIndex=i;

        bool execute=true;
        REP(i,1,A.size()-K+1){
            lli minNum2 = INF;
            REP(j,0,K)chmin(minNum2,A[i+j]);
            if(minNum != minNum2)execute=false;
        }
        if(!execute)break;
        s.insert(minNum);
        A.erase(A.begin()+minIndex);
    }

    sort(A.begin(),A.end());

    lli leftS = Q-s.size();
    REP(i,0,leftS){
        s.insert(A[i]);
    }

    auto itr = s.begin();
    auto itr2 = s.rbegin();

    cout<<abs((*itr)-(*itr2))<<endl;


}

