	vector<P> v(N);
	vector<int> A(N);
	for(int i=0;i<N;i++){
		cin >> A[i];
		v[i] = P(A[i],i);
	}
	sort(v.begin(),v.end());
	vector<int> fix;
	fix.push_back(-1);
	int ans = v[Q-1].first-v[0].first;
	for(int i=0;i<N-Q;i++){
		fix.push_back(v[i].second);
		fix.push_back(N);
		vector<int> u;
		for(int j=0;j<fix.size()-1;j++){
			priority_queue<int> q;
			if(fix[j+1]-fix[j]>K){
				for(int k=fix[j]+1;k<fix[j+1];k++){
					q.push(-A[k]);
				}
			}
			while(q.size()>fix[j+1]-fix[j]){
				int a = q.top();
				u.push_back(-a);
				q.pop();
			}
		}
		sort(u.begin(),u.end());
		if(u.size()>=Q) ans = min(ans,u[Q-1]-u[0]);
		fix.pop_back();
	}
	cout << ans << endl;
