bool take[2002];
ll solve(ll x)
{
        for(ll i=1;i<=n;i++) {
                if(a[i] < x) take[i] = false;
                else take[i] = true;
        }
        vector<ll> t;
        for(ll i=1;i<=n;i++) {
                if(take[i] == false) continue;
                ll j = i;
                while(j <= n && take[j] == true) j++;
                vector<ll> v;
                for(ll p = i ; p < j ; p++) v.pb(a[p]);
                ll sz = v.size();
                if(sz - k + 1 <= 0) continue;
                sort(v.begin() , v.end());
                for(ll p=0;p < sz-k+1 ; p++) t.pb(v[p]);
                i = j-1;
        }
        sort(t.begin() , t.end());
        if(t.size() < q) return inf;
        return t[q-1] - t[0];
}
