    for (int i = 0; i < N; i++) {
        cin >> A.at(i);
    }
    vector<int> S = A;
    sort(ALL(S));

    vector<Range> ranges;
    ranges.push_back(Range(A, 0, N));
    int ans = INF;
    for (int yid = 0; yid < N; yid++) {
