	}

	sort(challengers.begin(), challengers.end());
	challengers.erase(unique(challengers.begin(), challengers.end()), challengers.end());
	int ans = mx;
	int label = 0;

	for (int v : challengers)
	{
		int l = v - 1, r = mx + 1;

		while (r - l > 1)
		{
			values2 = values;
			create_tree();
			vector<int> used(n);

			int m = (l + r) >> 1;
			int d = -1, u = -1, num = 0;

			int lb = 0, rb = 0, cnt = 0;
			while (lb < n)
			{
				while (rb < n && cnt != k)
				{
					if (!used[rb])
					{
						cnt++;
						used[rb] = 1;
					}
					else
						rb++;
				}

				if (rb == n)
					break;

				int ind = get(lb + 1, rb + 1, 1, sze, 1);

				if (values2[ind] >= v && values2[ind] <= m)
				{
					num++;
					cnt--;

					if (d == -1)
						d = u = values2[ind];
					else
					{
						d = min(d, values2[ind]);
						u = max(u, values2[ind]);
					}

					update(ind, INF);
				}
				else
				{
					cnt--;
