void solve(int x)
{
	D[0] = 0;
	for (int i = 1, j; i <= n; i = j + 1) {
		j = i; if (A[i] < x) continue;
		while (j < n && A[j + 1] >= x) j++;
		C[0] = 0;
		FOR(l, i, j) C[++C[0]] = A[l];
