void solve(long long N, long long K, long long Q, std::vector<long long> A){
  auto AA = A;
  sort(AA.begin(),AA.end());
  set<ll> a(A.begin(),A.end());
  ll ans=AA[Q-1]-AA[0];
  for(auto x:a){
    vector<vector<ll>::iterator> tmp;
    For(j,A.size()){
      if(A[j]<=x){
        tmp.push_back(A.begin()+j);
      }
    }
    tmp.push_back(A.end());
    vector<ll> prob;
    auto itr=A.begin();
    For(j,tmp.size()){
      vector<ll> t(itr,tmp[j]);
      ll tt=max(0LL,(ll)t.size()-K+1);
      if(tt!=0){
        sort(t.begin(),t.end());
        For(k,tt){
          prob.push_back(t[k]);
        }
      }
      if(tmp[j]!=A.end())
        itr=next(tmp[j]);
    }
    if(prob.size()>=Q){
      sort(prob.begin(),prob.end());
      ans=min(ans,prob[Q-1]-prob[0]);
    }else{
      break;
    }
  }
  cout<<ans<<endl;
}

