bool ok(int mn, int mx) {
  int can = 0;
  set < pair<int, int> > st;  
  set < int > st2;
  for (int i = 0; i < n; i++) {
    if (a[i] < mn) {
      st.clear();
      st2.clear();
      continue;
    }
    if (sz(st) == k) {
      int idx = *st2.begin();
      st2.erase(st2.begin());
      st.erase({a[idx], idx});
    }
    st.insert({a[i], i});
    st2.insert(i);
    if (sz(st) == k && (*(st.begin())).first <= mx) {
      can++;
      st2.erase((*st.begin()).second);
      st.erase(st.begin());
    }
  }
  // cerr << mn << " " << mx << " " << can << endl;
  return can >= qn;
}

