void solve(long long N, long long K, long long Q, std::vector<long long> A){
  auto AA = A;
  sort(AA.begin(),AA.end());
  set<ll> a(A.begin(),A.end());
  ll l=0;
  ll ans=AA[Q-1]-AA[0];
  for(auto x:a){
    ll l=upper_bound(AA.begin(),AA.end(),x)-AA.begin();
    ll cnt=0;
    ll sum=0;
    list<ll> tmp;
    REP(N){
      if(A[i]!=x){
        cnt++;
      }else{
        tmp.push_back(cnt);
        sum+=max(0LL,cnt-K+1);
        cnt=0;
      }
    }
    cnt=0;
    while(!tmp.empty()&&sum<Q){
      auto itr=tmp.begin();
      auto aitr=itr;
      auto prev=itr;
      itr=next(itr);
      ll mx=0;
      for(;itr!=tmp.end();itr=next(itr)){
        if(mx<*itr+*prev){
          aitr=prev;
          mx=*itr+*prev;

        }
        prev=itr;
      }
      auto aaitr=next(aitr);
      *aaitr+=*aitr;
      sum+=max(*aaitr-K+1,0LL);
      *aaitr=min(*aaitr,K-1);
      tmp.erase(aitr);
      cnt++;
    }
    l-=cnt;
    dump(l);
    ans=min(ans,AA[l+Q-1]-AA[l]);
    if(cnt)break;
  }
  cout<<ans<<endl;
}

