vector<vector<ll>> ope(vector<ll> v, ll low) {
    vector<vector<ll> > ret;
    vector<ll> tmp;
    rep(i, 0, v.size()) {
        if (v[i] >= low) {
            tmp.push_back(v[i]);
        }
        if (v[i] < low || i == v.size() - 1) {
            ret.push_back(tmp);
            tmp.clear();
        }
    }
    return ret;
}

