void solve() {
  int n, k, q; cin >> n >> k >> q;
  vector<pii> arr(n);
  rep(i,n) {
    int a; cin >> a;
    arr[i] = {a, i};
  }

  sort(ALL(arr));
  map<int, int> mp;
  mp.emplace(n, 0);
  int ans = arr[q-1].first - arr[0].first;

  rep(i,n-q) {
    mp.emplace(arr[i].second, 0);
    int idx = -1;
    int cnt = 0;
    for (auto &p : mp) {
      int tmp = p.first - idx - k;
      if (tmp > 0) cnt += p.second = tmp;
      else p.second = 0;
      idx = p.first;
    }
    if (cnt >= q) {
      cnt = q;
      int j = i;
      int value = 0;
      while (cnt && ++j < n) {
        auto itr = mp.lower_bound(arr[j].second);
        if (itr->second) {
          --cnt;
          --(itr->second);
          if (!value) value = arr[j].first;
        }
      }
      if (!cnt) {
        chmin(ans, arr[j].first - value);
      }
    }
  }

  cout << ans << endl;
}


