void append(vector<int>& mini, vector<int>& tmp)
{
	sort(tmp.begin(), tmp.end());
	if(tmp.size()>K-1)
		copy(tmp.begin(), tmp.end() - K + 1, back_inserter(mini));
	tmp.clear();
}

int X_Y(int base) {
	vector<int> mini, tmp;
	REP(i, N) {
		if (A[i] >= base) {
			tmp.push_back(A[i]);
		}
		else {
			append(mini, tmp);
		}
	}
	append(mini, tmp);

	if (mini.size() < Q)return INF;
	sort(mini.begin(), mini.end());
	return mini[Q - 1] - mini[0];
}

//計算
void calc()
{
	priority_queue<int,vector<int>,greater<int>> pq;
	set<int> si;
	for (auto num : A)si.insert(num);
	for (auto num : si)pq.push(num);

	int ans = INF;
	REP(i,N){
		int base = pq.top(); pq.pop();
		int tmp = X_Y(base);
		if (tmp == INF)break;
		ans = min(ans,tmp);
	}
	cout << ans << endl;
}


