bool solve(int x,int sm,int k,int q,int n)
{
	vector<int> cur;
	int tot=0;
	for(int i=1;i<=n;i++)
	{
		if(a[i]<sm)
		{
			sort(all(cur));
			for(int i=0;i<=sz(cur)-k;i++)
			{
				if(cur[i]<=x)
					tot++;
			}
			cur.clear();
		}
		else
		{
			cur.pb(a[i]);
		}
	}
	sort(all(cur));
	for(int i=0;i<=sz(cur)-k;i++)
	{
		if(cur[i]<=x)
			tot++;
	}
	// if(x==1 && sm==1)
	// {
	// 	cout<<tot<<endl;
	// }
	if(tot>=q)
		return 1;
	return 0;
}
int main()
{
	ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0);
	int n,k,q;
	cin>>n>>k>>q;
	vector<int> v;
	for(int i=1;i<=n;i++)
	{
		cin>>a[i];
		v.pb(a[i]);
	}
	sort(all(v));
	int res=1e9;
	for(int i=1;i<=n;i++)
	{
		int l=0,r=sz(v)-1,p=-1;
		r=0;
		while(r<sz(v) && v[r]<a[i])
			r++;
		bool f=0;
		if(l==r)
		{
			if(solve(a[i],v[l],k,q,n))
			{
				res=min(res,a[i]-v[l]);
			}
			continue;
		}
		while(l<r)
		{
			int m=(l+r)/2;
			if(m==p)
				m++;
			p=m;
			if(solve(a[i],v[p],k,q,n))
			{
				f=1;
				l=m;
			}
			else
			{
				r=m-1;
			}
		}
		if(f)
		{
			// if(a[i]==1)
				// cout<<v[l]<<endl;
			res=min(res,a[i]-v[l]);
		}
	}
	cout<<res<<"\n";
	return 0;
}

