namespace bit{
    const ll S = (1<<17);
    ll bit[S];
    void ins(ll x, ll k)
    {
        while(x < S)bit[x] += k, x += x & -x;
    }
    ll f(ll x){
        ll l = 0, len = (S>>1);
        while(len){
            if(bit[l + len] < x)x -= bit[l + len], l += len;
            len >>= 1;
        }
        return l + 1;
    }
    ll qr(ll x){
        ll ret = 0;
        while(x)ret += bit[x], x -= x & -x;
        return ret;
    }
};

