    vector<ll> A(N), B(N);
    for (int i = 0; i < N; i++) {
        cin >> A.at(i);
    }

    B = A;
    sort(ALL(B));

    vector<Range> ranges;
    ranges.push_back(Range(A, 0, N));

    ll ans = INF;
    for (int i = 0; i < N; i++) {
        ll first = B[i];
        ll qth = B[i + Q - 1];

        vector<Range> new_ranges;
        for (auto range : ranges) {
            int r = 0;
            for (int l = 0; l < range.len;) {
                while (r < range.len && range.val[r] >= first) {
                    r++;
                }
                if (l == r) {
                    l++;
                    r++;
                    continue;
                }
                new_ranges.push_back(Range(range.val, l, r));
                r++;
                l = r;
            }
        }
        int sum = 0;
        for (auto range : new_ranges) {
            int cnt = 0;
            for (auto v : range.val) {
                if (v <= qth) {
                    cnt++;
                }
            }
            sum += max(min(range.len - K + 1, cnt), 0);
        }
        if (sum < Q) {
            break;
        }
        chmin(ans, qth - first);
        ranges = new_ranges;
    }
    cout << ans << endl;
    return 0;
}

