const int N = 2005, inf = 1e18;
int n, K, q, a[N], ans = inf;
bool unUse[N];

int solve () {
    int ret = 0, cnt = 0;
    priority_queue<int, vector<int>, greater<int> > pq;
    for (int i = 1; i <= n; ++i) {
        if (unUse[i]) {
            int tmp = pq.size();
            if (tmp >= K) {
                while (pq.size() >= K && cnt < q) ret = max(ret, pq.top() ), pq.pop(), cnt ++;
            }
            while (!pq.empty() ) pq.pop();
        }
        else pq.push(a[i]);
    }
    int tmp = pq.size();
    if (tmp >= K) {
        while (pq.size() >= K && cnt < q) ret = max(ret, pq.top() ), pq.pop(), cnt ++;
    }
    while (!pq.empty() ) pq.pop();
    if (cnt < q) ret = 2 * inf;
    return ret;
}

signed main () {
    ios_base::sync_with_stdio(0); cin.tie(0); cout.tie(0);
    cin >> n >> K >> q;
    for (int i = 1; i <= n; ++i) cin >> a[i];

    for (int i = 1; i <= n; ++i) {
        memset(unUse, 0, sizeof unUse);
        for (int j = 1; j <= n; ++j) if (a[j] < a[i]) unUse[j] = 1;
        ans = min(ans, solve() - a[i]);
    }

    cout << ans;

    return 0;
}

