const ll MAX=1e9+7,MAXL=1LL<<61,dx[4]={-1,0,1,0},dy[4]={0,1,0,-1};
typedef pair<int,int> P;

class RMQ{
public:
  int n;
  P dat[555555];
  void init(int _n){
    n=1;
    while(n<_n)n*=2;
    rep(i,2*n) dat[i]=P(MAX,-1);
  }
  void update(int k,P a){
    k+=n-1;dat[k]=a;
    while(k>0){
      k=(k-1)/2;
      dat[k]=min(dat[k*2+1],dat[k*2+2]);
    }
  }
  P query(int a,int b){return query(a,b,0,0,n);}
  P query(int a,int b,int k,int l,int r){
    if(r<=a||b<=l) return P(MAX,-1);
    if(a<=l&&r<=b) return dat[k];
    P vl=query(a,b,k*2+1,l,(l+r)/2);
    P vr=query(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }
};

RMQ r;
void Main() {
  ll n,m,k;
  cin >> n >> m >> k;
  ll a[n];
  rep(i,n) R a[i];
  set<int> s;
  rep(i,n) s.in(a[i]);
  s.in(0);
  int ans=MAX;
  tr(it,s) {
    r.init(n);
    int x=0;
    priority_queue<int,vector<int>,greater<int> > que[n];
    rep(i,n) {
      if(a[i]<=*it) x=i+1;
      else que[x].push(a[i]);
    }
    int cnt=0;
    rep(i,n) {
      if(que[i].size()>=m) {
        r.update(i,P(que[i].top(),i));
        cnt+=que[i].size()-m+1;
      }
    }
    if(cnt<k) break;
    int Mi=MAX,Ma=-MAX;
    rep(i,k) {
      P p=r.query(0,n);
      Mi=min(Mi,p.F);
      Ma=max(Ma,p.F);
      que[p.S].pop();
      if(que[p.S].size()>=m) r.update(p.S,P(que[p.S].top(),p.S));
      else r.update(p.S,P(MAX,-1));
    }
    ans=min(ans,Ma-Mi);
  }
  pr(ans);
}

