int a[MAXN+5], b[MAXN+5], N, K, Q;
vector<int> v;
priority_queue<int, vector<int>, greater<int>> pq;

void extract() {
	while (pq.size() >= K) {
		v.push_back(pq.top());
		pq.pop();
	}
	while (!pq.empty()) pq.pop();
}

int test(int x) {
	v.clear();
	while (!pq.empty()) pq.pop();
	for (int i = 0; i <= N; i++) {
		if (i == N || a[i] < x) {
			extract();
			continue;
		}

		pq.push(a[i]);
	}

	assert(pq.empty());
	sort(v.begin(), v.end());
	if (v.size() < Q) return INF;
	return v[Q - 1] - v[0];
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0);
	cin >> N >> K >> Q;
	for (int i = 0; i < N; i++) {
		cin >> a[i];
		b[i] = a[i];
	}

	int ans = INF;
	sort(b, b + N);
	for (int i = 0; N - i >= Q; i++) {
		ans = min(ans, test(b[i]));
	}

	assert(ans != INF);
	cout << ans << "\n";
	/**** Note MAXN ****/
}

