                    whole.push_back(seg.top());
                    seg.pop();
                }
                while(seg.size()) seg.pop();
            }
            else {
                seg.push(B[i]);
            }
        }

        sort(whole.begin(), whole.end());
        if(whole.size() >= Q) chmin(ans, whole[Q-1] - whole[0]);
