int f(int mn){
    vector<int> v;
    for(int i=0;i<n;i++){
        if(a[i] < mn) continue;
        int j = i+1;
        while(j < n && a[j] >= mn) j++;
        if(j-i >= k){
            vector<int> t(a.begin()+i, a.begin()+j);
            sort(t.begin(), t.end());
            for(int l=0;l<=j-i-k;l++) v.push_back(t[l]);
