        if(i-K+1>=0){
            B[i-K+1]=A[deq[s]];
            if(deq[s]==i-K+1) s++;
        }
    }

    int ans=INF;

    if(Q==1) cout<<0<<endl;
    else{
        for(int i=0;i<N;i++){
            bool flag=false;
            if(N-i<Q) continue;
            for(int j=i-K+1;j<=i;j++){
                if(j<0) continue;
                if(B[j]==A[i]){
                    flag=true;
                    break;
                }
            }
            if(!flag) continue;

            vector<int> S,T;

            for(int j=0;j<N;j++){
                if(i==j) continue;

                if(A[j]<A[i]){
                    if(S.size()<K) vector<int> S;
                    else{
                        sort(all(S));
                        for(int k=0;k<=S.size()-K;k++){
                            T.push_back(S[k]);
                        }
                        vector<int> S;
                    }
                }else{
                    S.push_back(A[j]);
                }
            }

            if(S.size()>=K){
                sort(all(S));
                for(int k=0;k<=S.size()-K;k++){
                    T.push_back(S[k]);
                }
            }
            if(T.size()<Q-1) continue;

            sort(all(T));

            ans=min(ans,T[Q-2]-A[i]);
        }

        cout<<ans<<endl;
    }
}

