const ll MOD = 1000000007;


bool check(auto& vs_part, int th, int K, int Q){
    int cnt = 0;
    for(auto& vs_part_i : vs_part){
        if(vs_part_i.size() < K) continue;
        int k = 0;
        for(int v : vs_part_i){
            if(v <= th){
                k++;
            }
        }
        cnt += min(k, int(vs_part_i.size()) - (K - 1));
    }
    return cnt >= Q;
}

int main(){
    int N, K, Q;
    cin >> N >> K >> Q;

    vector<int> A(N);
    for(int i=0;i<N;i++){
        cin >> A[i];
    }

    ll ans = 1LL << 60;
    for(int i=0;i<N;i++){
        ll min_value = A[i];

        vector<vector<ll>> vs_part;
        set<ll> vs;
        vs_part.push_back({});
        for(int j=0;j<N;j++){
            if(min_value <= A[j]){
                vs_part.back().push_back(A[j]);
                vs.insert(A[j]);
            }else{
                if(vs_part.back().size() > 0){
                    vs_part.push_back({});
                }
            }
        }
        if(vs_part.back().size() == 0){
            vs_part.pop_back();
        }

        vector<ll> vs_vec(vs.begin(), vs.end());
        reverse(vs_vec.begin(), vs_vec.end());

        int l = 0, r = vs_vec.size();
        while(r - l > 1){
            int mid = (r + l) / 2;
            if(check(vs_part, vs_vec[mid], K, Q)){
                l = mid;
            }else{
                r = mid;
            }
        }

        if(check(vs_part, vs_vec[l], K, Q)){
            ans = min(ans, vs_vec[l] - min_value);
        }
    }
    cout << ans << endl;

    return 0;
}

