			else {
				if (r - l + 1 >= K) {

					vector<int>vec;
					for (int j = l; j <= r; j++) {
						vec.pb(A[j]);
					}
					VSORT(vec);
					REP(k, r - l + 2 - K) {
						res.pb(vec[k]);
					}
				}
				l = r + 2;
				r += 2;
			}
		}
		VSORT(res);
		if (res.size() >= Q) {
			ans = min(ans, res[Q - 1] - res[0]);
		}
	}
	print(ans);
}

