#include <bits/stdc++.h>
using namespace std;
#define lowbit(x) (x & (-x))
#define mp(a, b) make_pair(a, b)
const int maxn = 2000 + 10;
typedef pair<int, int> pii;
int n, k, q, ans = 2e9;
vector<pii> b;
int a[maxn], C[maxn];
void add(int x)
{
	for(int i = x; i < maxn; i += lowbit(i))
		++C[i];
}
int sum(int x)
{
	int ret = 0;
	for(int i = x; i; i -= lowbit(i))
		ret += C[i];
	return ret;
}
bool solve(int now)
{
	memset(C, 0, sizeof(C));
	pii x = b[now];
	int val = x.first, pos = x.second;
	vector<int> S;
	S.push_back(0);
	for(int i = 1; i <= n; ++i)
		if(a[i] < val)
			S.push_back(i);
	S.push_back(n + 1);
	int cnt = 0;
	while(cnt < q && now < n)
	{
		val = b[now].first, pos = b[now].second;
		auto it = upper_bound(S.begin(), S.end(), pos);
		int r = *it;
		int l = *(--it);
		if(r - 1 - l - (sum(r - 1) - sum(l)) >= k)
		{
			++cnt;
			add(pos);
		}
		++now;
	}
	if(cnt == q)
	{
		ans = min(ans, b[now - 1].first - x.first);
		return 1;
	}
	else
		return 0;
}
int main()
{
	scanf("%d%d%d", &n, &k, &q);
	for(int i = 1; i <= n; ++i)
	{
		scanf("%d", &a[i]);
		b.push_back(mp(a[i], i));
	}
	sort(b.begin(), b.end());
	for(int i = 0; i < n; ++i)
		if(!solve(i))
			break;
	printf("%d\n", ans);
	return 0;
}

