int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  int n, k, q; std::cin >> n >> k >> q;
  std::vector<int> a(n);
  for (int i = 0; i < n; i++) std::cin >> a[i];
  auto sub_count = [&] (int l, int r, int X) {
    assert(0 <= l && l <= r && r <= n);
    int ret = std::count_if(a.begin() + l, a.begin() + r, [X](int z){return z <= X;});
    cmn(ret, r - l - k + 1);
    cmx(ret, 0);
    return ret;
  };
  auto count = [&] (int X, int Y) {
    int ret = 0;
    int l = 0;
    for (int r = 0; r <= n; r++) {
      if (r == n || a[r] < Y) {
        if (l < r) ret += sub_count(l, r, X);
        l = r + 1;
      }
    }
    return ret;
  };
  constexpr int inf = 1 << 30;
  int ret = inf;
  for (auto Y : a) {
    auto check = [&] (int X) {
      return count(X, Y) >= q;
    };
    if (!check(inf)) continue;
    int ok = inf, ng = Y - 1, md;
    while (abs(ok - ng) > 1) {
      md = (ok + ng) >> 1;
      if (check(md)) ok = md;
      else ng = md;
    }
    cmn(ret, ok - Y);
  }
  std::cout << ret << std::endl;
  return 0;
}

