		while(dat[root[p.second]].size()>=K){
			int r=dat[root[p.second]].top();dat[root[p.second]].pop();
			que.push(r);
		}
		while(que.size()>q)que.pop();
		if(que.size()==q){
			ans=min(ans,que.top()-p.first);
		}
	}
	cout<<ans<<endl;
}

