  for(int i=0;i<N;i++) v.push_back(mkp(A[i],i));
  sort(v.begin(),v.end());

  ll ans=v.back().first-v[0].first;
  for(int i=0;i<N;i++){
      int now=v[i].second;
      SegmentTree<int> seg(N+2,[](int a,int b){return a+b;},0);
      int sum=0;
      int last=0;
      set<int> se;
      se.insert(-1);
      se.insert(N);
      for(int j=0;j<i;j++) se.insert(v[j].second);

      for(int j=i;j<N;j++){
          if(sum>=Q) break;
          int tar=v[j].second;
          auto itr=se.lower_bound(tar);
          int r=*itr;
          itr--;
          int l=*itr;

          int used=seg.query(l+1,r);
          int num=r-l-1-used;
          if(num>=K){
              last=A[tar];
              sum++;
              seg.update(tar,1);
          }else{
              se.insert(tar);
          }
      }
      if(sum>=Q) ans=min(ans,last-A[now]);
  }

