int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    int n, k, q;
    cin >> n >> k >> q;
    vector<int> a(n), idxs(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        idxs[i] = i;
    }
    sort(idxs.begin(), idxs.end(), [&](const int& i1, const int& i2){return a[i1] < a[i2];});

    set<int> s;
    int hoge = n - k + 1;
    ll ans = 2000000000;
    for (int i = 0; i < n; i++) {
        if (hoge < q) {
            break;
        }
        int prv = 0, tar = a[idxs[i]];
        priority_queue<int> pq;
        for (int j : s) {
            priority_queue<int> pq2;
            for (int ii = prv; ii < j; ii++) {
                pq2.push(-a[ii]);
            }

            int num = max(j - prv - k + 1, 0);
            for (int ii = 0; ii < num; ii++) {
                pq.push(pq2.top());
                pq2.pop();
            }

            prv = j + 1;
        }

        priority_queue<int> pq2;
        for (int ii = prv; ii < n; ii++) {
            pq2.push(-a[ii]);
        }

        int num = max(n - prv - k + 1, 0);
        for (int ii = 0; ii < num; ii++) {
            pq.push(pq2.top());
            pq2.pop();
        }

        for (int ii = 0; ii < q; ii++) {
            tar = max(tar, -pq.top());
            pq.pop();
        }
        ans = min(ans, (ll)tar - a[idxs[i]]);

        auto itr = s.upper_bound(idxs[i]);
        int r2;
        if (itr == s.end()) {
            r2 = n - 1;
        } else {
            r2 = *itr - 1;
        }
        int l2;
        if (itr == s.begin()) {
            l2 = 0;
        } else {
            itr--;
            l2 = *itr + 1;
        }
        hoge -= max(r2 - l2 + 1 - k + 1, 0);
        hoge += max(idxs[i] - l2 - k + 1, 0) + max(r2 - idxs[i] - k + 1, 0);
        s.insert(idxs[i]);
    }
    cout << ans << endl;
    return 0;
}

