using namespace std;
const int MAXN = 100000;
const int INF = 1e9 + 5;

int pa[MAXN+5], sz[MAXN+5], a[MAXN+5], N, K, Q;
PII b[MAXN+5];
bool enable[MAXN+5];
multiset<int> global;
priority_queue<int, vector<int>, greater<int>> candidate[MAXN+5];

void init() {
	for (int i = 0; i < N; i++) {
		pa[i] = i;
		sz[i] = 1;
		enable[i] = false;
		candidate[i].push(a[i]);
	}
}

int find_root(int x) {
	return pa[x] == x ? x : pa[x] = find_root(pa[x]);
}

void merge(int x, int y) {
	x = find_root(x);
	y = find_root(y);
	if (x == y) return;
	if (sz[x] < sz[y]) swap(x, y);
	while (!candidate[y].empty()) {
		candidate[x].push(candidate[y].top());
		candidate[y].pop();
	}
	pa[y] = x;
	sz[y] += x;
}

int test(PII p) {
	int x = p.first, pos = p.second;
	enable[pos] = true;
	if (pos > 0 && enable[pos - 1]) merge(pos, pos - 1);
	if (pos < N - 1 && enable[pos + 1]) merge(pos, pos + 1);

	int root = find_root(pos);
	while (candidate[root].size() >= K) {
		if (global.size() < Q) {
			global.insert(candidate[root].top());
			candidate[root].pop();
		}
		else if (*global.rbegin() > candidate[root].top()) {
			global.erase(--global.end());
			global.insert(candidate[root].top());
			candidate[root].pop();
		}
		else break;
	}

//	cout << "SZ " << candidate[root].size() << "\n";
//	cout << "Test " << p.first << " at " << p.second << "\n";
//	for (int x : global) cout << x << " "; cout << "\n";

	if (global.size() < Q) return INF;
	return *global.rbegin() - *global.begin();
}

int main() {
	ios_base::sync_with_stdio(0); cin.tie(0);
	cin >> N >> K >> Q;
	for (int i = 0; i < N; i++) {
		cin >> a[i];
		b[i] = {a[i], i};
	}

	int ans = INF;
	sort(b, b + N);
	init();
	for (int i = N - 1; i >= 0; i--) {
		ans = min(ans, test(b[i]));
	}

	cout << ans << '\n';
	/**** Note MAXN ****/
}

