struct UnionFind{
  vector<int> v;
  UnionFind(int n) : v(n, -1) {}
  void init(){ for(int i = 0;i < v.size();i++)v[i]=-1; }
  int find(int x) { return v[x] < 0 ? x : v[x] = find(v[x]); }
  bool unite(int x, int y) {
    x = find(x); y = find(y);
    if (x == y) return false;
    if (-v[x] < -v[y]) swap(x, y);
    v[x] += v[y]; v[y] = x;
    return true;
  }
  bool root(int x) { return v[x] < 0; }
  bool same(int x, int y) { return find(x) == find(y); }
  int size(int x) { return -v[find(x)]; }
};


ll n,K,Q;
ll a[2001];
bool used[2001];

int main(){
  cin>>n>>K>>Q;
  rep(i,n)cin>>a[i];
  ll res=INF;
  rep(i,n){
    UnionFind uf(n);
    memset(used,0,sizeof(used));
    rep(j,n-1){
      if(a[j]>=a[i]&&a[j+1]>=a[i])uf.unite(j,j+1);
    }
    ll sz=0;
    rep(j,n){
      if(a[j]>=a[i]&&uf.size(j)>=K){
        if(used[uf.find(j)])continue;
        used[uf.find(j)]=true;
        sz+=uf.size(j)-K+1;
      }
    }
    if(sz<Q)continue;
    vector<ll> b;
    rep(j,n){
      if(a[j]>=a[i]&&uf.size(j)>=K){
        b.push_back(a[j]);
      }
    }
    sort(all(b));
    minch(res,b[Q-1]-a[i]);
  }
  cout<<res<<endl;
  return 0;
}

