void solve(){
	int N,K,Q;
	cin>>N>>K>>Q;
	vector<int> A(N),uni(N);
	for(int i=0;i<N;++i){
		cin>>A[i];
	}
	uni = A;
	uni.push_back( 0 );
	UNIQUE(uni);
	int size = uni.size();

	LL ans = LINF;
	for(int i=0;i<size;++i){
		int X = uni[i];
		vector<int> kouho;
		vector<int> dat;
		for(int j=0;j<N;++j){
			if(A[j] >= X ){
				dat.push_back( A[j] );
			}else{
				sort(dat.begin(),dat.end());
				int Len = dat.size();
				for(int k=0;k<Len-K+1;++k){
					kouho.push_back( dat[k] );
				}
				dat.clear();
			}
		}
		{
			sort(dat.begin(),dat.end());
			int Len = dat.size();
			for(int k=0;k<Len-K+1;++k){
				kouho.push_back( dat[k] );
			}
		}
		int Len = kouho.size();
		if(Len >= Q ){
			sort(kouho.begin(),kouho.end());
			LL ter = kouho[Q-1] - kouho[0];
			ans = min(ans,ter);
		}
	}
	cout << ans << endl;
}

