template<class Val, class Cmp>
class SparseTableRMQ {
public:
    SparseTableRMQ() {
    }
    SparseTableRMQ(const vector<Val> &ar) : n((int)ar.size()), data(n) {
        for (int i = 0; i < n; ++i) data[i] = ar[i];
        table = buildRMQ();
    }

    int queryPos(int l, int r) {
        int k = lgInt(r - l - 1);
        int lid = table[l + n*k], rid = table[r + n*k - (1 << k)];
        return (cmp(data[lid], data[rid])) ? lid : rid;
    }

    int queryValue(int l, int r) {
        return data[queryPos(l, r)];
    }
private:
    int n;
    vector<Val> data;
    vector<int> table;
    Cmp cmp;
    int lgInt(int v) {
        static const unsigned b[] = { 0x2, 0xC, 0xF0, 0xFF00, 0xFFFF0000 };
        static const unsigned S[] = { 1, 2, 4, 8, 16 };
        int res = 0;
        for (int i = 4; i >= 0; i--) {
            if (v & b[i]) {
                v >>= S[i];
                res |= S[i];
            }
        }
        return res;
    }

    vector<int> buildRMQ() {
        int logn = 1;
        for (int k = 1; k < n; k *= 2) ++logn;
        vector<int> b(n*logn);
        for (int i = 0; i < n; ++i)b[i] = i;
        int cur = 0;
        for (int k = 1; k < n; k *= 2) {
            copy(b.begin() + cur, b.begin() + cur + n, b.begin() + cur + n);
            cur += n;
            for (int i = 0; i < n - k; ++i) {
                int idl = b[cur + i], idr = b[cur + i + k];
                if (cmp(data[idl], data[idr])) {
                    b[cur + i] = idl;
                } else {
                    b[cur + i] = idr;
                }
            }
        }
        return b;
    }
};
typedef SparseTableRMQ<int, less_equal<int>> RMinQ;
typedef SparseTableRMQ<int, greater_equal<int>> RMaxQ;

