    const int INF = 1 << 30;
    int N, K, Q;
    cin >> N >> K >> Q;
    vi A(N), vis(N);
    each(a, A)cin >> a;
    A.push_back(-1);
    priority_queue<int, vector<int>, greater<int> > pq;
    int re = INF;
    rep(a, N - K + 1) {
        int mi = INF;
        FOR(b, a, a + K) {
            smin(mi, A[b]);
        }
        vi ps;
        FOR(b, a, a + K) {
            if (mi == A[b])ps.push_back(b);
        }
        each(b, ps)if (!vis[b]++) {
            vi B;
            rep(c, N+1) {
                if (A[c] >= mi) {
                    B.push_back(A[c]);
                } else {
                    if (sz(B) >= K) {
                        sort(all(B));
                        for (int d = 0; d + K <= sz(B); ++d) {
                            pq.push(B[d]);
                        }
                    }
                    B.clear();
                }
            }
            if (sz(pq) >= Q) {
                int ma = mi;
                rep(c, Q) {
                    ma = pq.top();
                    pq.pop();
                }
                smin(re, ma - mi);
            }
            while (sz(pq)) pq.pop();
        }
    }
    cout << re << endl;
}

