bool chk(int v)
{
	int x;
	for(int i=1;i<=tot;i++)
		if(c[i]==v)
		{
			x=i;
			break;
		}
	head=1,tail=0;
	for(int j=max(x-k+1,1);j<=min(x+k-1,tot);j++)
	{
		while(head<=tail&&q[head]<j-k+1)
			head++;
		while(head<=tail&&c[j]<=c[q[tail]])
			tail--;
		q[++tail]=j;
		if(c[q[head]]==v)
			return 1;
	}
	return 0;
}

void del(int v)
{
	int pos;
	for(int i=1;i<=tot;i++)
		if(c[i]==v)
		{
			pos=i;
			break;
		}
	tot--;
	for(int i=pos;i<=tot;i++)
		c[i]=c[i+1];
}

