		del(x);
		int cnt=1,mx=0;
		for(int j=i+1;j<=n;j++)
		{
			if(cnt==Q)
				break;
			if(chk(b[j]))
				del(b[j]),cnt++,mx=max(mx,b[j]);
		}
		if(cnt<Q)
			continue;
		ans=min(ans,mx-b[i]);
	}
	printf("%d",ans); 
}

