#include <bits/stdc++.h>

#define MAX_N 2000
#define MAX_P2 10

#define sqrInf 999999999

using namespace std;

int rez;
int n, k, q;

int a[MAX_N + 1];
int b[MAX_N + 1];

int st[MAX_N + 1];
int dr[MAX_N + 1];
int stk[MAX_N + 1];

void readFile()
{
    cin >> n >> k >> q;

    int i;
    for(i = 1; i <= n; i ++)
    {
        cin >> a[i];
        b[i] = a[i];
    }
}

void done(int &elim, int &cate, int &good)
{
    if(cate + good >= k)
        elim += min(good, cate + good - k + 1);

    cate = 0;
    good = 0;
}

bool pos(int dr, int st)
{
    int i;
    int good = 0;
    int cate = 0;
    int elim = 0;
    for(i = 1; i <= n; i ++)
    {
        if(a[i] < a[st])
            done(elim, cate, good);

        else
            if(a[i] > b[dr])
                cate ++;

        else
            good ++;
    }

    done(elim, cate, good);

    return (elim >= q);
}

void cautBin(int poz)
{
    int i = 0;
    int pas = 1 << 10;
    while(pas != 0)
    {
        if(i + pas < n && pos(i + pas, poz) == 0)
            i += pas;

        pas >>= 1;
    }

    i ++;

    if(pos(i, poz) == 0)
        return;

    rez = min(rez, b[i] - a[poz]);
}

void baga(int dr[], int lst, int ldr, int sign)
{
    int i;
    int stkLen = 0;
    for(i = lst; i != ldr + sign; i += sign)
    {
        while(stkLen > 0 && a[stk[stkLen]] > a[i])
        {
            dr[stk[stkLen]] = i;
            stkLen --;
        }

        stk[++ stkLen] = i;
    }

    while(stkLen > 0)
    {
        dr[stk[stkLen]] = ldr + sign;
        stkLen --;
    }
}

void getRez()
{
    rez = sqrInf;

    sort(b + 1, b + n + 1);

    int i;
    baga(dr, 1, n, 1);
    baga(st, n, 1, -1);

    for(i = 1; i <= n; i ++)
    {
        st[i] ++;
        dr[i] --;

        if(i - st[i] + dr[i] - i + 1 >= k)
            cautBin(i);
    }
}

void solve()
{
    getRez();
}

void printFile()
{
    cout << rez << "\n";
}

int main()
{
    readFile();

    solve();

    printFile();

    return 0;
}

