set <int> smalls;

int aib[N];

bool cmp(int i, int j) {
	return a[i] < a[j];
}

int lsb(int k){
	return k & -k;
}

int que(int pos) {
	int ans = 0;
	for(; pos > 0; pos-=lsb(pos)) ans += aib[pos];
	return ans;
}

int query(int left, int right) {
	if(left <= 1) return que(right);
	return que(right) - que(left - 1);
}

void upd(int pos, int val) {
	for(; pos < N; pos += lsb(pos)) 
		aib[pos] += val;
}


bool canTake(int pos) {
	// tre sa vad cmpel mai apropiat nr < pos si cel mai apropiat > pos
	// dbg(pos);
	auto it2 = smalls.upper_bound(pos);
	auto it1 = it2;
	it1--;
	// dbg(*it1);
	// dbg(*it2);
	int nr = (*it2 - *it1 - 1) - query(*it1 + 1, *it2 - 1);
	// dbg(nr);
	if(nr >= k)
		return true;
	return false;
}

