bool ck(int x,int mid){
	s[0]=0; int tot=0;
	for (int i=1;i<=n;i++){
	if (a[i]<x) b[i]=0,d[++tot]=i;
	if (a[i]>=x&&a[i]<=mid) b[i]=1;
	if (a[i]>mid) b[i]=2;
	if (b[i]==1) s[i]=s[i-1]+1; else s[i]=s[i-1];
	}
	int cnt=0; d[0]=0;
	d[++tot]=n+1;
	for (int i=1;i<=tot;i++){
		int l=d[i-1]+1,r=d[i]-1;
		if (l>r) continue;
		if (r-l+1<k) continue;
		cnt+=min(s[r]-s[l-1],r-l+2-k);
	}
	return (cnt>=q);
}
