signed main() {
	INIT;

	VAR(int, n, k, q);
	VEC(int, a, n);

	int ans = INFINT;
	std::set<int> set;
	REP(i, n) set.insert(a[i]);

	for (auto& mi : set) {
		std::priority_queue<int, std::vector<int>, std::greater<int>> pq;
		std::vector<int> b;
		REP(r, n + 1) {
			if (r == n || a[r] < mi) {
				while (pq.size() >= k) {
					int t = pq.top(); pq.pop();
					b.emplace_back(t);
				}
				while (!pq.empty()) pq.pop();
			}
			else {
				pq.push(a[r]);
			}
		}
		if (b.size() < q) break;
		std::sort(ALL(b));
		CHMIN(ans, b[q - 1] - b[0]);
	}
	OUT(ans)BR;
	return 0;
}

