inline int check(int d){
	memset(b,0,n+1<<2);
	for(int i=1;i<=n;++i){
		int s0=0,s1=0,cnt=0;
		for(int j=1;j<=n;++j)
			if(a[j].v>a[i].v+d)++s0;
