        for(int j = 0; j < d.size(); j++){
            sort(d[j].begin(), d[j].end());
            for(int l = 0; l < (int)d[j].size() - k + 1; l++){
                c.push_back(d[j][l]);
            }
        }
        if(c.size() >= q){
            sort(c.begin(), c.end());
