const int MAXN=2211;

static int n,k,q,b[MAXN];

static struct poi
{
	int w,id;
	friend bool operator<(poi a,poi b)
	{return a.w<b.w;}
}p[MAXN];

inline void init()
{
	read(n);read(k);read(q);
	Rep(i,1,n)read(p[i].w),b[i]=p[i].w,p[i].id=i;
}

inline bool Judge(int mi,int ma)
{
	static int lef,fr,cnt;cnt=lef=fr=0;
	Rep(i,1,n)
	{
		if(b[i]<mi){lef=fr=0;continue;}
		++lef;if(b[i]<=ma)++fr;
		if(lef>=k&&fr)++cnt,--fr,--lef;
	}
	return cnt>=q;
}

static int ans=1e9;

inline void solve()
{
	static int l,r,mid;
	sort(p+1,p+n+1);
	p[n+1].w=2e9;
	Rep(i,1,n-q+1)
	{
		l=i;r=n;
		while(l<=r)
		{
			mid=(l+r)>>1;
			if(Judge(p[i].w,p[mid].w))r=mid-1;
			else l=mid+1;
		}
		Chkmin(ans,p[l].w-p[i].w);
	}
	printf("%d\n",ans);
}
int main()
{
    init();
    solve();
    return 0;
}

