vector<vector<int> > split_vector(vector<int> &a, int pivot){
    vector<vector<int> > res;
    a.push_back(pivot - 1);
    for(int i = 0; i < a.size(); i++){
        vector<int> tmp;
        while(i < a.size() && a[i] >= pivot){
            tmp.push_back(a[i++]);
        }
        if(tmp.size() != 0) res.push_back(tmp);
    }
    a.pop_back();
    return res;
}

signed main(){
    int n, k, q, ans = INF;
    cin >> n >> k >> q;
    vector<int> a(n);
    for(int i = 0; i < n; i++){
        cin >> a[i];
    }
    vector<int> b = a;
    sort(b.begin(), b.end());
    for(int i = 0; i < n - q; i++){
        vector<vector<int> > d = split_vector(a, b[i]);
        vector<int> c;
        for(int j = 0; j < d.size(); j++){
            sort(d[j].begin(), d[j].end());
            for(int l = 0; l < (int)d[j].size() - k + 1; l++){
                c.push_back(d[j][l]);
            }
        }
        if(c.size() >= q){
            sort(c.begin(), c.end());
            ans = min(ans, c[q - 1] - c[0]);
        }
    }
    cout << ans << endl;
}

