void func(long long N, long long K, long long Q, std::vector<long long> A){

    lli small = -1,large = 1e9;

    lli ans = INF;

    REP(f,0,N){
        lli middle = A[f];

        //middle以上のものが撮れるかどうか？？？
        vector<lli> q;
        vector<lli> p;
        REP(i,0,N){
            if(A[i]>=middle)p.push_back(A[i]);
            else{
                if(p.size()>=K){
                    SORT(p);
                    lli size = p.size();
                    REP(i,0,size-K+1){
                        q.push_back(p[i]);
                    }
                }
                p.clear();
            }
        }
        if(p.size()>=K){
            SORT(p);
            lli size = p.size();
            REP(i,0,size-K+1){
                q.push_back(p[i]);
            }
        }
        SORT(q);
        LOG2(middle,q.size());
        if(q.size()>=Q){
            chmin(ans,q[Q-1]-q[0]);
        }
    }

    cout<<ans<<endl;

}

