inline int calc(int mn) {
  int tot = 0, l = 1, r = 1;
  while (l <= n) {
    while (a[l] < mn && l <= n) ++l;
    r = l;
    while (a[r] >= mn && r <= n) ++r;

    int len = 0;
    for (int i = l; i < r; ++i) b[++len] = a[i];
    if (len >= k) {
      sort(b + 1, b + 1 + len);
      for (int i = 1; i <= len - k + 1; ++i) c[++tot] = b[i];
    }
    l = r;
  }

  sort(c + 1, c + 1 + tot);
  if (tot >= q) {
    return c[q] - c[1];
  } else {
    return INF;
  }
}

