	sort(B+1,B+1+N);
	for (int i=1;i<=N-Q+1;i++){
		int Res=B[i+Q-1].x-B[i].x;
		for (int j=1;j<Q;j++){
			if (DMn[i+j]<B[i].x) break;
			if (j==Q-1) Ans=min(Ans,Res);
		}
	}
	printf("%d\n",Ans);
	return 0;
}

