    let=0;
    while(true){//Yより小さいのが出るまでガーってやる
      //cout<<i<<endl;
      int now=let;if(now==i)now++;
      while(now<N&&v[now]>=Y){
        que.push(v[now++]);
        if(now==i)now++;
      }
      rit=now;//[l,r)が区間
      int wide=rit-let;if(rit>i&&let<=i)wide--;
      while(wide-K>=0){
        tmp.push(que.top());
        que.pop();wide--;
      }
      if(rit==N)break;
      let=rit+1;
    }
    if(tmp.size()+1<Q)continue;
    for(int i=0;i<Q-2;i++)tmp.pop();ans=min(ans,tmp.top()-v[i]);
    //cout<<i<<" "<<ans<<endl;
  }
  cout<<ans<<endl;
}

