ll N, K, Q;
ll A[MAX_N];
ll ans = INF;

int main()
{
  scanf( "%lld%lld%lld", &N, &K, &Q );

  rep( i, N )
    scanf( "%lld", A+i );

  rep( i, N )
  {
    ll X = A[i];

    std::vector<std::vector<ll> > vss;
    std::vector<ll> vs, qs;

    rep( j, N+1 )
    {
      if( j < N && A[j] >= X )
        vs.push_back( A[j] );

      if( j == N || A[j] < X )
      {
        if( !vs.empty() )
          vss.push_back( vs );

        vs.clear();
      }
    }

    rep( j, vss.size() )
    {
      std::sort( all(vss[j]) );

      rep( k, std::max<ll>( 0, vss[j].size()-K+1 ) )
        qs.push_back( vss[j][k] );
    }

    std::sort( all(qs) );

    if( qs.size() >= Q )
      ans = std::min( ans, qs[Q-1]-qs[0] );
  }

  printf( "%lld\n", ans );

  return 0;
}

