int getBest()
{
	vector <int> cur;
	vector <int> tot;
	for (int i = 0; i < n; i++)
		if (tk[i]) {
			sort(cur.begin(), cur.end());
			for (int j = 0; j + k <= cur.size(); j++)
				tot.push_back(cur[j]);
			cur.clear();
		} else cur.push_back(a[i]);
	sort(cur.begin(), cur.end());
	for (int j = 0; j + k <= cur.size(); j++)
		tot.push_back(cur[j]);
	sort(tot.begin(), tot.end());
	if (tot.size() < q) return -1;
	return tot[q - 1];
}

