	rep(i,N){
		//最小値をa[i]にしたい
		vector<ll> candidate;
		ll l=0;
		while(l<N){
			ll r=-1;
			for(ll j=l;j<N;j++){
				if(a[i]>a[j]){
					r=j;break;
				}
			}
			if(r==-1)r=N;
			vector<ll> v;
			for(ll j=l;j<r;j++){
				v.push_back(a[j]);
			}
			sort(all(v));
			rep(i,v.size()-(K-1)){
				candidate.push_back(v[i]);
			}
			l=r+1;
		}
		sort(all(candidate));
		if(candidate.size()>=Q){
			ll t=candidate[Q-1]-candidate[0];
			chmin(ans,t);
		}

	}

	p(ans);

}

