multiset<int> mstPos;

bool check(int lo, int hi) {
	mstPos.clear(); mstVal.clear();
	int remQ = q;
	for (int i = 0; i < n; i++) {
		mstVal.insert(mp(a[i], i)); mstPos.insert(i);
		if (remQ == 0) return true;
		if (mstVal.size() == m) {
			if (lo <= mstVal.begin()->fi && mstVal.begin()->fi <= hi) {
				mstPos.erase(mstVal.begin() -> se);
				mstVal.erase(mstVal.begin());
				remQ--;
			}
			else {
				mstVal.erase(mp(a[*mstPos.begin()], *mstPos.begin()));
				mstPos.erase(mstPos.begin());
			}
		}
	}
	if (remQ == 0) return true;
	return false;
}

