void cal(int x){
    int l,r;
    l = r = 1;
    vector<int> choice;
    while(l <= N){
        vector<int> tmp;
        while(a[l] < x && l <= N) l++;
        r = l;
        while(a[r] >= x && r <= N) r++;
        for(int i = l; i < r; i++) tmp.push_back(a[i]);
        l = r;
        if(tmp.size() < K) continue;
        sort(tmp.begin(),tmp.end());
        for(int i = 0; i < tmp.size() - K + 1; i++) choice.push_back(tmp[i]);
    }
    if(choice.size() < Q) return;
    sort(choice.begin(),choice.end());
    ans = min(ans, choice[Q - 1] - x);
}

