int tree[sze << 1];
int n, k, q, mx = 0;
vector<int> values, values2;


int get_min(int i, int j)
{
	if (i == -1)
		return j;
	else if (j == -1)
		return i;

	if (values2[i] <= values2[j])
		return i;
	else
		return j;
}


void create_tree()
{
	fill(tree, tree + (sze << 1), -1);

	for (int i = 0; i < n; ++i)
		tree[i + sze] = i;

	for (int i = sze - 1; i; --i)
		tree[i] = get_min(tree[i << 1], tree[i << 1 | 1]);
}


int get(int l, int r, int lb, int rb, int ind)
{
	if (l == lb && r == rb)
		return tree[ind];

	int m = (lb + rb) >> 1;
	int first = -1, second = -1;

	if (l <= m)
		first = get(l, min(m, r), lb, m, ind << 1);

	if (r > m)
		second = get(max(l, m + 1), r, m + 1, rb, ind << 1 | 1);

	return get_min(first, second);
}


void update(int ind, int vl)
{
	values2[ind] = vl;

	ind = (ind + sze) >> 1;

	while (ind)
	{
		tree[ind] = get_min(tree[ind << 1], tree[ind << 1 | 1]);
		ind >>= 1;
	}
}


