				H.emplace(t.top());
				t = t.pop();
			}
		}
		if (i != n-1 && used[i + 1]) {
			int x, y;
			::std::tie(x, y) = T.unite(i, i + 1);
			auto &t = heaps[x];
			t = t + heaps[y];
			while (t.size() >= k) {
				H.emplace(t.top());
				t = t.pop();
			}
		}
		if (H.size() >= q) {
			while (H.size() > q)
				H.pop_max();
			ans = ::std::min(ans, H.max() - H.min());
