        n*=2;
    }
    rep(i,n*2-1){
        RMQ[i]=linf;
    }
}
void update(ll k,ll a){
    k+=n-1;
    RMQ[k]=a;
    while(k>0){
        k--;
        k/=2;
        RMQ[k]=min(RMQ[2*k+1],RMQ[2*k+2]);
    }
}
//半開区間
ll query(ll a,ll b,ll k,ll l,ll r){
    if(r<=a||l>=b)return linf;
    if(l>=a&&r<=b)return RMQ[k];
    else {
        return min(query(a,b,k*2+1,l,(l+r)/2),query(a,b,k*2+2,(l+r)/2,r));
    }
}
