                ll mid=(r+l)/2;
                if(query(b[j].second,mid,0,0,n)==b[j].first)l=mid;
                else r=mid;
            }
            border+=l-b[j].second;
            if(border>=k+cnt){
                cnt++;
                update(b[j].second,inf);
            }
            if(cnt==1){
                s=b[j].first;
            }
            if(cnt==q){
                g=b[j].first;
                break;
            }
        }
        if(cnt==q){
            ans=min(ans,g-s);
        }
