    if (kek.back().empty())
        kek.pop_back();

    for (auto& v : kek)
        sort(v.begin(), v.end());

    ll l = x, r = INF;

    for (; l < r; ) {
        auto m = (l + r) / 2;

        if (check(kek, m))
            r = m;
        else
            l = m + 1;
    }

    if (!check(kek, r))
        return INF;

    return r - x;
}

