    rep(j, N){
      ll k = j + K;
      if(query(j, k, 0, 0, N_) >= A[i]){
        while(query(j, k+1, 0, 0, N_) >= A[i]) k++;
        can.pb({j, k});
        j = k;
      }
    }

    ll cnt = 0;
    rep(j, can.size()) cnt += (can[j].s - can[j].f) - K + 1;

    if(cnt < Q) continue;
    vector<ll> xs;
    rep(j, can.size()) for(ll k = can[j].f; k < can[j].s; k++) xs.pb(A[k]);
    sort(xs.begin(), xs.end());
    ans = min(ans, xs[Q-1] - A[i]);
  }
  cout << ans << endl;
}

