      int now=v[i].second;
      SegmentTree<int> seg(N+2,[](int a,int b){return a+b;},0);
      int sum=0;
      int last=0;
      for(int j=i;j<N;j++){
          if(sum>=Q) break;
          int tar=v[j].second;
          auto itr=se.lower_bound(tar);
          int r=*itr;
