/*
31536000のコメント解説欄
ここテンプレで用意してるから、A問題とかだとこの先空欄の危険あり

まず、1回の操作で必ず1個は取り除かれる
Q回操作するのでQ個必ず取り除かれる
ここで、XとYを決め打ってみる(O(N^2))
この時、Y以上X以下の要素を取り除くことができる
さて、となると困るのはYより小さい要素だ
連続したK個の間にYより小さい要素があればその瞬間に不可能が証明できる
また、そうでない時
例えば 4 4 4 4 4 4 1 5 5 5 でK=4の時
左側の方からは最大で3個、右側からは0個取れる→連続したY以上の範囲からは最大で連続数-K+1個取れる
この時、この中からは小さい順に取ることができる
……Xを決め打つ必要は無さそう、Yだけ決め打つ(O(N))
この時、取れる範囲の要素を取り出していってソート、(O(NlogN))、その時の範囲を見れば分かる
*/

#include<bits/stdc++.h>
using namespace std ;
int a[2010] ;
bool ok[2010] ;
int pos[2010] , d[2010] ;
struct Node{
       int id , val ;
}no[2010] ;
int XG ;
bool cmp( Node a , Node b ){
    if ( a.val == b.val ){
        if ( b.id == XG ) return 0 ;
        return a.id < b.id ;
    }
    return a.val < b.val ;
}
int main(){
    int n , k , q ;
    cin >> n >> k >> q ;
    for( int i = 1 ; i <= n ; i++ )
        scanf( "%d" , &a[i] ) ;
    for( int i = 1 ; i <= n - k + 1 ; i++ ){
        int minx = a[i] ;
        for( int j = i ; j <= i + k - 1 ; j++ )
            minx = min( minx , a[j] ) ;
        for( int j = i ; j <= i + k - 1 ; j++ )
            if ( a[j] == minx ) ok[j] = true ;
    }
    for( int i = 1 ; i <= n ; i++ ){
        no[i].id = i ; no[i].val = a[i] ;
    }
    int ans = 0x3f3f3f3f ;
    for( int i = 1 ; i <= n ; i++ ){
        if ( !ok[i] ) continue ;
        int cnt = 0 ;
        int res = 0 ;
        for( int j = 1 ; j <= n ; j++ ){
            if ( a[j] < a[i] ){
                res = 0 ; continue ;
            }
            if ( j != i ){
                res++ ;
                if ( res == 1 ) cnt++ ;
                pos[j] = cnt ; d[cnt] = res ;
            }
        }
        XG = i ;
        sort( no + 1 , no + 1 + n , cmp ) ;
        int p ;
        for( int j = 1 ; j <= n ; j++ )
            if ( no[j].id == i ) p = j ;
        int x = a[i] ;
        int y = a[i] ;
        int qaq = 0 ;
        for( int j = p + 1 ; j <= n ; j++ ){
            int r = no[j].id ;
            if ( d[pos[r]] < k ) continue ;
            qaq++ ; d[pos[r]]-- ; y = no[j].val ;
            if ( qaq == q - 1 ) break ;
        }
        if ( qaq != q - 1 ) continue ;
        ans = min( ans , y - x ) ;
    }
    cout << ans << endl ;
    return 0 ;
}

