inline bool check(int a, int b, int n, int k, int q) {
    int cnt = 0;
    int i = 1;
    vector <int> v;
    while(i <= n) {
        int j = i;
        while(j <= n && aux[a] <= arr[j] && arr[j] <= aux[b]) {
            v.push_back(arr[j]);
            j++;
        }
        cnt += (j - i - k + 1);
        i = j + 1;
    }
    if(cnt < q)
        return 0;
    sort(v.begin(), v.end());
    ans = min(ans, v[q - 1] - v[0]);
    return 1;
}

