bool unUse[N];

int solve () {
    int ret = 0, cnt = 0;
    priority_queue<int, vector<int>, greater<int> > pq;
    for (int i = 1; i <= n; ++i) {
        if (unUse[i]) {
            int tmp = pq.size();
            if (tmp >= K) {
                while (pq.size() >= K && cnt < q) ret = max(ret, pq.top() ), pq.pop(), cnt ++;
            }
            while (!pq.empty() ) pq.pop();
        }
        else pq.push(a[i]);
    }
    int tmp = pq.size();
    if (tmp >= K) {
        while (pq.size() >= K && cnt < q) ret = max(ret, pq.top() ), pq.pop(), cnt ++;
    }
    while (!pq.empty() ) pq.pop();
    if (cnt < q) ret = inf;
    return ret;
}

