					sort(stock.begin(),stock.end());
					rep(k,stock.size()-K+1){
						stockall.push_back(stock[k]);
					}
				}
				retusize=0;
				stock.clear();
			}
		}
		if(stockall.size()<Q) continue;
		sort(stockall.begin(),stockall.end());
		ll Y=stockall[Q-1];
		minsa=min(minsa,Y-X);
		//printf("i:%d stockallsize:%d Y:%lld minsa:%lld\n",i,stockall.size(),Y,minsa);
	}
	prin(minsa);
	return 0;
}

