bool trial(int l, int r){
	int cnt = 0;
	for(int i=0; i<n;){
		if(a[i] < l){
			i++;
			continue;
		}
		int e = i;
		while(e < n && a[e] >= l) e++;
		if(e - i >= k){
			int tcnt = 0;
			for(int j=i; j<e; j++){
				if(a[j] <= r) tcnt++;
			}
			cnt += min(tcnt, e - i - k + 1);
		}
		i = e;
	}
	return cnt >= q;
}

