template<class T> string out_m2(vector<set<T> > &a, ll H = inf, ll W = inf, int key = -1) {    vector<vector<T> > b(sz(a));    rep(i, sz(a)) { fora_f(v, a[i]) { fora_f_init(v, a[i]); b[i].push_back(v); }}    return out_m2(b, H, W, key);}
