using namespace std;
ll larger[2019][2019]; // count of nums same or larger than i th from 0 through j
ll lef[2019],rig[2019]; // ind of nearest <mi 
int main(){
	ll n,k,q;
	ll ans = mod;
	cin>>n>>k>>q;
	vector<ll> a;
	a.pb(-1);
	for(int i=1;i<=n;i++){
		ll x;
		cin>>x;
		a.pb(x);
	}
	a.pb(-1);
	larger[0][0]=1;
	larger[n+1][0]=1;
	for(int i=0;i<=n+1;i++){
		for(int j=1;j<=n+1;j++){
			if( a[j] >= a[i]){
				larger[i][j] = larger[i][j-1]+1;
			}
			else{
				larger[i][j] = larger[i][j-1];
			}
		}
	}
	vector< pair<ll,ll> > sa;
	for(int i=0;i<=n+1;i++){
		sa.pb(mp(a[i],i));
	}
	sort(sa.begin(),sa.end());
	for(int i=2;i<n+2-q;i++){
		ll flag = 0;
		ll mi = sa[i].first;
		ll ma = sa[i+q-1].first;
		lef[0]=0;
		for(int j=1;j<=n+1;j++){
			if(a[j]<mi){
				lef[j]=j;
			}
			else{
				lef[j]=lef[j-1];
			}
		}
		rig[n+1]=n+1;
		for(int j=n;j>=0;j--){
			if(a[j]<mi){
				rig[j]=j;
			}
			else{
				rig[j]=rig[j+1];
			}
		}
		for(int j=0;j<q;j++){
			ll cval = sa[i+j].first;
			ll cpos = sa[i+j].second;
			ll clef = lef[cpos];
			ll crig = rig[cpos];
			ll cnt = larger[cpos][crig-1] - larger[cpos][clef];
			if(cnt<k){
				flag = 1;
			}
		}
		if(flag == 0){
			ll tans = ma - mi;
			if(tans < ans)ans = tans;
		}
	}
	cout<<ans<<endl;
	return 0;
}

