  rep(i,N) cin>>A[i];

  vector<pair<ll,int>> v;
  for(int i=0;i<N;i++) v.push_back(mkp(A[i],i));
  sort(A.begin(),A.end());

  set<int> se;
  se.insert(-1);
  se.insert(N);
  ll ans=MOD;
  for(int i=0;i<N;i++){
      int now=v[i].second;
      if(N-i-K+1<Q) break;
      SegmentTree<int> seg(N+2,[](int a,int b){return a+b;},0);
      int sum=0;
      int last=0;
      for(int j=i;j<N;j++){
          if(sum>=Q) break;
          int tar=v[j].second;
          auto itr=se.lower_bound(tar);
          int r=*itr;
          itr--;
          int l=*itr;

          int used=seg.query(l+1,r);
          int num=r-l-1-used;
          if(num>=K){
              last=A[tar];
              sum++;
              seg.update(tar,1);
          }
      }
      if(sum>=Q) ans=min(ans,last-A[now]);
      se.insert(now);
  }

  cout<<ans<<endl;


