const int N = 2005, inf = 1e18;
int n, K, q, a[N], ans = inf;
bool unUse[N];

int solve (int pos) {
    int ret = 0, cnt = 0;
    priority_queue<int, vector<int>, greater<int> > pq;
    for (int i = 1; i <= n; ++i) {
        if (unUse[i]) {
            int tmp = pq.size();
            if (tmp >= K) {
                while (pq.size() >= K && cnt < q) ret = max(ret, pq.top() ), pq.pop(), cnt ++;
            }
            while (!pq.empty() ) pq.pop();
        }
        else pq.push(a[i]);
    }
    int tmp = pq.size();
    if (tmp >= K) {
        while (pq.size() >= K && cnt < q) ret = max(ret, pq.top() ), pq.pop(), cnt ++;
    }
    while (!pq.empty() ) pq.pop();
    if (cnt < q) ret = 2 * inf;
    cnt = 1;
    for (int i = pos + 1; i <= n; ++i) {
        if (unUse[i]) break;
        cnt ++;
    }
    for (int i = pos - 1; i > 0; --i) {
        if (unUse[i]) break;
        cnt ++;
    }
    if (cnt < K) ret = 2 * inf;
    return ret;
}

