template <class T, class Container = ::std::vector<T>,
	class Compare = ::std::less<typename Container::value_type>>
	class IntervalHeap {

	public:
		using container_type = Container;
		using value_compare = Compare;
		using value_type = typename container_type::value_type;
		using reference = typename container_type::reference;
		using const_reference = typename container_type::const_reference;
		using size_type = typename container_type::size_type;

	protected:
		container_type c;
		value_compare comp;

	private:
		static size_type left(const size_type i) { return (i - 1) << 1; }
		static size_type right(const size_type i) { return (i << 1) - 1; }
		bool normalize(const size_type l, const size_type g) {
			return comp(c[g], c[l]) ? (::std::swap(c[l], c[g]), true) : false;
		}
		void build() {
			const size_type s = (size() + 1) >> 1;
			if (!(size() & 1))
				if (normalize(left(s), right(s)))
					buildmin(s);
				else
					buildmax(s);
			else if (size() != 1)
				if (normalize(left(s), right(s >> 1)))
					buildmax(s >> 1);
				else
					buildmin(s);
		}
		void buildmin(size_type i) {
			while (i != 1 && normalize(left(i >> 1), left(i)))
				i >>= 1;
		}
		void buildmax(size_type i) {
			while (i != 1 && normalize(right(i), right(i >> 1)))
				i >>= 1;
		}

	public:
		IntervalHeap() : c(), comp() {}
		explicit IntervalHeap(const value_compare &x) : c(), comp(x) {}
		explicit IntervalHeap(const value_compare &x, const container_type &other)
			: c(other), comp(x) {}
		explicit IntervalHeap(const value_compare &x, container_type &&other)
			: c(::std::move(other)), comp(x) {}

		bool empty() const { return c.empty(); }
		size_type size() const { return c.size(); }

		const_reference min() const {
			assert(!empty());
			return c[0];
		}
		const_reference max() const {
			assert(!empty());
			return size() == 1 ? c[0] : c[1];
		}

		void push(const value_type &x) {
			c.push_back(x);
			build();
		}
		void push(value_type &&x) {
			c.push_back(::std::move(x));
			build();
		}
		template <class... Args> void emplace(Args &&... args) {
			c.emplace_back(::std::forward<Args>(args)...);
			build();
		}
		void pop_min() {
			assert(!empty());
			::std::swap(c.front(), c.back());
			c.pop_back();
			const size_type s = size();
			size_type i = 2;
			while (left(i) < s) {
				if (left(i | 1) < s && !comp(c[left(i)], c[left(i | 1)]))
					i |= 1;
				if (!normalize(left(i >> 1), left(i)))
					return;
				if (right(i) < s)
					normalize(left(i), right(i));
				i <<= 1;
			}
		}
		void pop_max() {
			assert(!empty());
			if (size() == 1) {
				c.pop_back();
				return;
			}
			::std::swap(c[1], c.back());
			c.pop_back();
			const size_type s = size();
			size_type i = 2;
			while (right(i) < s) {
				if (right(i | 1) < s && !comp(c[right(i | 1)], c[right(i)]))
					i |= 1;
				if (!normalize(right(i), right(i >> 1)))
					return;
				normalize(left(i), right(i));
				i <<= 1;
			}
		}
};

