template <class T, class Container = std::vector<T>,
          class Compare = std::less<typename Container::value_type>>
class meld_priority_queue : public std::priority_queue<T, Container, Compare> {

  void cascade_up(const std::size_t i) {
    auto &c = this->c;
    auto &comp = this->comp;
    const std::size_t l = i * 2 + 1;
    const std::size_t r = i * 2 + 2;
    if (r < c.size() && comp(c[l], c[r])) {
      if (comp(c[i], c[r])) {
        std::swap(c[i], c[r]);
      }
    } else {
      if (comp(c[i], c[l])) {
        std::swap(c[i], c[l]);
      }
    }
  }

public:
  template <class... Args>
  meld_priority_queue(Args &&... args)
      : std::priority_queue<T, Container, Compare>(
            std::forward<Args>(args)...) {}

  void meld(meld_priority_queue &&x) {
    if (x.empty()) {
      return;
    }
    auto &c = this->c;
    std::size_t l = c.size();
    for (T &v : x.c) {
      c.push_back(std::move(v));
    }
    std::size_t r = c.size() - 1;
    while (r != 0) {
      if(l)
      l = (l - 1) / 2;
      if(r)
      r = (r - 1) / 2;
      for (std::size_t i = l; i <= r; ++i) {
        cascade_up(i);
      }
    }
  }
};

