    for (ll b : Bs) {
        using Queue = priority_queue<ll, vector<ll>, greater<ll>>;
        auto compare_queue = [](Queue& lhs, Queue& rhs){ return lhs.top() > rhs.top(); };
        priority_queue<Queue, vector<Queue>, decltype(compare_queue)> groups(compare_queue);
        ll i = 0;
        while (i < N) {
