        ll mx = numeric_limits<ll>::min();
        while (groups.size() > 0) {
            cnt++;
            Queue moved = (Queue&&)groups.top();
            groups.pop();
            ll elem = moved.top();
            mn = min(mn, elem);
            mx = max(mx, elem);
            moved.pop();
            if (moved.size() >= K) {
                groups.push(move(moved));
            }
            if (cnt >= Q) {
                break;
            }
        }
        if (cnt >= Q) {
            ans = min(ans, mx - mn);
        }
    }
