int solve_sub(vector<int> a, int l, int r, int k) {
	int n = (int)a.size();
	sort(a.begin(), a.end());
	int c = 0;
	for (int i = 0; i < n - k + 1; i++) {
		assert(a[i] >= l);
		if (a[i] <= r) c++;
	}
	return c;
}

int can(vector<int> a, int l, int r, int q, int k) {
	int n = (int)a.size();
	int c = 0;
	for (int i = 0; i < n; i++) {
		if (a[i] < l) {
			continue;
		} else {
			int p = i;
			assert(a[i] >= l);
			vector<int> sb = {a[i]};
			while (p + 1 < n && a[p + 1] >= l) {
				assert(a[p + 1] >= l);
				sb.push_back(a[p + 1]);
				p++;
			}
			c += solve_sub(sb, l, r, k);
			i = p;
		}
	}
	return c >= q;
}

