    rep(i,N) A[i]=lower_bound(compress.begin(),compress.end(),A[i])-compress.begin()+1;
    vector<Pll> B(N);
    rep(i,N) B[i]=Pll(A[i],i);
    sort(B.begin(),B.end());
    int s=compress.size();
    BinaryIndexedTree BIT(++s);
    rep(i,N) BIT.add(A[i],1);
    vector<int> notmin(N,0);
    ll ans=INF,rest=N;
    for (int i=0;rest>=Q;++i){
        int sup=BIT.binarysearch(Q+1);
        int center=B[i].second;
        if (notmin[center]) continue;
        chmin(ans,compress[sup-1]-compress[i]);
        rep(j,K){
            if (center+j<N&&chmax(notmin[center+j],1)) BIT.add(A[center+j],-1),--rest;
            if (center-j>=0&&chmax(notmin[center-j],1)) BIT.add(A[center-j],-1),--rest;
        }
    }
    cout << ans << endl;
}

