void solve() {
  int n, k, q; cin >> n >> k >> q;
  vector<pii> arr(n);
  rep(i,n) {
    int a; cin >> a;
    arr[i] = {a, i};
  }

  sort(ALL(arr));
  set<int> s;
  s.emplace(n);
  int ans = arr[q-1].first - arr[0].first;

  rep(i,n-q) {
    s.emplace(arr[i].second);
    int idx = -1;
    int cnt = 0;
    for (int p : s) {
      int tmp = p - idx - k;
      if (tmp > 0) cnt += tmp;
      idx = p;
    }
    if (cnt >= q) {
      chmin(ans, arr[i+q].first - arr[i+1].first);
    }
  }

  cout << ans << endl;
}


