const ll mod=1e9+7;
ll linf=(1LL<<31)-1LL;
ll n;
vector<ll>RMQ(1<<21);
void init(ll n_){
    n=1;
    while(n<n_){
        n*=2;
    }
    rep(i,n*2-1){
        RMQ[i]=linf;
    }
}
void update(ll k,ll a){
    k+=n-1;
    RMQ[k]=a;
    while(k>0){
        k--;
        k/=2;
        RMQ[k]=min(RMQ[2*k+1],RMQ[2*k+2]);
    }
}
//半開区間
ll query(ll a,ll b,ll k,ll l,ll r){
    if(r<=a||l>=b)return linf;
    if(l>=a&&r<=b)return RMQ[k];
    else {
        return min(query(a,b,k*2+1,l,(l+r)/2),query(a,b,k*2+2,(l+r)/2,r));
    }
}
int main(){
    ll n_,k,q;cin>>n_>>k>>q;
    vector<ll>a(n_+1);
    vector<pll>b(n_+1);
    b[0]=mp(0,0);
    rep(i,n_){
        cin>>a[i+1];
        b[i+1]=mp(a[i+1],i+1);
    }
    sort(all(b));
    ll ans=inf;
    init(n_+2);
    rep(i,n_){
        rep(j,n_){
            update(j+1,a[j+1]);
        }
        update(0,0LL);
        update(n_+1,0LL);
        ll cnt=0;
        ll g;
        ll s;
        REP(j,i+1,n_+1){
            ll border=0;
            ll l=0,r=b[j].second;
            while(r-l>1){
                ll mid=(r+l)/2;
                if(query(mid,b[j].second+1,0,0,n)==b[j].first)r=mid;
                else l=mid;
            }
            border+=b[j].second-r;
            l=b[j].second+1,r=n_+2;
            while(r-l>1){
                ll mid=(r+l)/2;
                if(query(b[j].second,mid,0,0,n)==b[j].first)l=mid;
                else r=mid;
            }
            border+=l-b[j].second;
            if(border>=k+cnt){
                cnt++;
                update(b[j].second,inf);
            }
            if(cnt==1){
                s=b[j].first;
            }
            if(cnt==q){
                g=b[j].first;
                break;
            }
        }
        if(cnt==q){
            ans=min(ans,g-s);
        }
    }
    cout<<ans<<endl;
}

