void solve() {
	int N, K, Q;
	cin >> N >> K >> Q;
	vector<int> A(N);
	for (int i = 0; i < N; ++i) {
		cin >> A[i];
	}
	int ans = INF;
	vector<int> temp(N);//候補
	vector<int> temp2(N);//候補候補
	for (int i = 0; i < N; ++i) {
		int X = A[i];
		int num = 0;//選択候補確定
		int cnt = 0;
		/*
		数列分解して、除ける最小値候補を選択
		*/
		for (int j = 0; j < N; ++j) {
			if (A[j] >= X) {
				temp2[cnt] = A[j];
				++cnt;
			}
			if(A[j] < X || j+1==N){
				int ter = cnt - K +1;
				if (ter <= 0) {
					continue;
				}
				else {
					sort(temp2.begin(),temp2.begin()+cnt);
					for (int k = 0; k < ter; ++k) {
						temp[num] = temp2[k];
						++num;
					}
				}
				cnt = 0;
			}
		}
		if (num >= Q) {//Q個以上取り除ける候補がある。
			sort(temp.begin(), temp.begin() + num);
			ans = min(ans, temp[Q - 1] - temp[0]);
		}
	}
	cout << ans << endl;
}

