  for (int i = 0, j = 0; i < cntv; ++i) {
    while (j + 1 < cntv && !Solve(val[i], val[j])) {
      ++j;
    }
    if (j == cntv - 1 && !Solve(val[i], val[j])) {
      break;
    }
    ans = min(ans, val[j] - val[i]);
  }
  printf("%d\n", ans);
  return 0;
}

