			byPos.erase(make_pair(p, a[p]));
		}
		if(len(byVal) >= k) {
			auto iter = byVal.begin();
			if(iter->first >= low && iter->first <= high) {
				++ops;
				int p = iter->second;
				byVal.erase(make_pair(a[p], p));
				byPos.erase(make_pair(p, a[p]));
			}
		}
		++ptr;
	}
	return ops >= q;
}
void solve() {
	cin >> n >> k >> q; for(int i = 0; i < n; ++i) a[i] = ord[i] = fetch<int>();
	sort(ord, ord + n);
	int r = 0;
	for(int l = 0; l < n; ++l) {
		if(r < l) r = l;
		while(r < n && !check(ord[l], ord[r])) ++r;
		if(r < n) answ = min(answ, ord[r] - ord[l]);
	}
	cout << answ << '\n';
}

