typedef pair<int, int> pii;
int n, k, q, ans = 2e9;
vector<pii> b;
int a[maxn], C[maxn];
void add(int x)
{
	for(int i = x; i < maxn; i += lowbit(i))
		++C[i];
}
int sum(int x)
{
	int ret = 0;
	for(int i = x; i; i -= lowbit(i))
		ret += C[i];
	return ret;
}
bool solve(int now)
{
	memset(C, 0, sizeof(C));
	pii x = b[now];
	int val = x.first, pos = x.second;
	set<int> S;
	S.insert(0); S.insert(n + 1);
	for(int i = 1; i <= n; ++i)
		if(a[i] < val)
			S.insert(i);
	int cnt = 0;
	while(cnt < q && now < n)
	{
		val = b[now].first, pos = b[now].second;
		auto it = upper_bound(S.begin(), S.end(), pos);
		int r = *it;
		int l = *(--it);
		//	if(now == 0) cout << pos << ' ' << l << ' ' << r << endl;
		if(r - 1 - l - (sum(r - 1) - sum(l)) >= k)
		{
			++cnt;
			add(pos);
		}
		++now;
	}
	if(cnt == q)
	{
		ans = min(ans, b[now - 1].first - x.first);
		return 1;
	}
	else
		return 0;
}
