int cal(int x){

  priority_queue<int,vector<int>,greater<int> > Q, tmp;

  for(int i=0;i<n;i++){

    if( x <= A[i] ){
      tmp.push( A[i] );
    }
    else{

      while( (int)tmp.size() >= K ){
	Q.push( tmp.top() );
	tmp.pop();
      }

      while( !tmp.empty() ) tmp.pop();

    }

  }

  while( (int)tmp.size() >= K ){
    Q.push( tmp.top() );
    tmp.pop();
  }

  while( !tmp.empty() ) tmp.pop();

  int cnt = q;

  if( cnt > (int)Q.size() ) return 1e9;

  int maxv = 0;

  while( cnt-- ){
    maxv = max( maxv, Q.top() );
    Q.pop();
  }

  return maxv - x;
}

