        min_a = min(min_a, A[i]);
        max_a = max(max_a, A[i]);
        rmq.update(i, A[i]);
    }

    int ans = max_a - min_a;
    // 最大値を決め打ち
    for(int i = 0; i < N; i++){
        int c = 0;
        for(int j = 0; j < N; j++){
            if(A[i] >= A[j]){
                c++;
            }
        }
        if(c < Q ){
            continue;
        }


        int max_pos = i;
        vector<int> overs;
        for(int j = 0; j < N; j++){
            // 最大値より大きい要素を列挙
            if(A[j] >= A[max_pos]){
                overs.push_back(j);
            }
        }

        // oversにはmax_posもはいるので、そのmax_posを含むようにK個選んで、それをスライドさせていく
        if((int)overs.size() >= K){
            deque<int> dq;
            bool ok = false;
            for(int j = 0; j < (int)overs.size(); j++){
