                        int cnt = pos2 - pos1 + 1 - K;
                        if(cnt < Q){
                            ans = min(ans,A[i] - min_a);
                        }
                        else if(cnt == Q){
                            ans = min(ans, A[i] - rmq.query(pos1, pos2 + 1));
                        }

                        // cout << ans << endl << endl;

                        if(dq[0] == i) break;
                        dq.pop_front();
                    }
                    else{
                        dq.pop_front();
                    }
                }
            }
        }
        else{
            continue;
        }
    }

    cout << ans << endl;

}

