	ll A[2002];
	int LR[2002];
	rep(i, 1 << K) dat[i] = 2e18;
	rep1(i, N) {
		A[i] = ((ll)getint() << 16) + i;
		add(i, A[i]);
	}
	rep(i, N + 2) LR[i] = -1;

