bool ok(int id, int x) {
	//cout << id << endl;
	for(int i = 1; i <= N; ++i) ban[i] = a[i] < a[id];
	ban[0] = ban[N + 1] = 1;
	int len = 0, cnt = 0;
	int ans = 0;
	int ls = id, rs = id;
	while(!ban[ls - 1]) ls--;
	while(!ban[rs + 1]) rs++;
	if(rs - ls + 1 < K) return 0;
	//cout << "************" << endl;
	//cout << ls << ' ' << rs << endl;
	for(int i = 1; i <= N + 1; ++i) {
		if(ban[i]) {
			if(len >= K) ans += min(len - K + 1, cnt);
			len = cnt = 0;
			//if(cnt) cout << id << ' ' << cnt << endl;
			continue;
		} 
		len++;
		//cout << id << ' ' << cnt << ' ' << a[i] << ' ' << a[id] << ' ' << x << endl;
		if(a[i] - a[id] <= x) cnt++;
	}
	//cout << ans << endl;
