void renew(int x,int val){
	while(x<=N+1){
		Tree[x]+=val;
		x+=(x&(-x));
	}
	return;
}

int query(int x){
	int ans=0;
	while(x>0){
		ans+=Tree[x];
		x-=(x&(-x));
	}
	return ans;
}

