}

void judge(){
	for(int i=0;i<Q;i++){
		renew(node[i].pos,1);
	}
	res=node[Q-1].val-node[0].val;
	for(int i=Q;i<N;i++){
		renew(node[i-Q].pos,-1);
		renew(node[i].pos,1);
		S.insert(node[i-Q].pos);
		set<int>::iterator iter=S.find(node[i-Q].pos);
		iter--;
		if(query(node[i-Q].pos)-query(*iter)==0||query(node[i-Q].pos)-query(*iter)+K<=(node[i-Q].pos-(*iter))){

		}else{
			break;
		}
		iter++;iter++;
		if(query(*iter)-query(node[i-Q].pos)==0||query(*iter)-query(node[i-Q].pos)+K<=((*iter)-node[i-Q].pos)){
			int now=node[i].val-node[i+1-Q].val;
			if(now<res)res=now;
