    }
    print(v, "sorted v: ");

    vector<ll> ans;
    ans.reserve(N);
    for (int i = 1; i < (int)seps.size(); i++) {
        ans.insert(ans.end(), v.begin() + seps[i - 1] + 1,
                   v.begin() + seps[i - 1] + 1 +
                       max(0, seps[i] - seps[i - 1] - 1 - K + 1));
    }
    print(ans, "ans: ");
    auto a = *min_element(ans.begin(), ans.end());
    nth_element(ans.begin(), ans.begin() + Q - 1, ans.end());
    sort(ans.begin(), ans.end());
    seps.pop_back();
