int v[2010];
int nr[2010], id;
int n, k, q;

void solve(int st, int dr)
{
    int max_taken = dr - st - k + 2;
    if (max_taken <= 0)
        return;
    int start = id;
    while (st <= dr)
        nr[id++] = v[st++];

    sort(nr + start, nr + id);
    id = start + max_taken;
}

int main()
{
    cin >> n >> k >> q;

    for (int i = 1; i <= n; i++)
        cin >> v[i];

    int ans = 2e9;

    for (int idv = 1; idv <= n; idv++) {
        int val = v[idv];
        id = 0;
        for (int i = 1, prev = 1; i <= n; i++) {
            if (v[i] >= val) {
                if (i == n)
                    solve(prev, i);
            }
            else {
                if (prev <= i - 1)
                    solve(prev, i - 1);
                prev = i + 1;
            }
        }
        sort(nr, nr + id);
        if (id >= q)
            ans = min(ans, nr[q - 1] - nr[0]);
    }

    cout << ans << '\n';
