const int MAXN = 2007;
int a[MAXN], ord[MAXN], n, k, q, answ = INT_INF;
int check(int low, int high) {
	int ops = 0;
	multiset<int> cur;
	int ptr = 0;
	while(ptr < n) {
		cur.insert(a[ptr]);
		if(len(cur) >= k) {
			auto iter = cur.begin();
			if(*iter >= low && *iter <= high) {
				++ops;
				cur.erase(iter);
			}
		}
		if(len(cur) > k) {
			auto iter = cur.find(a[ptr - k]);
			if(iter != cur.end()) cur.erase(iter);
		}
		++ptr;
	}
	return ops >= q;
}
