    auto B = A;
    std::sort(B.begin(), B.end());
    ll ans = B[Q - 1] - B[0];
    std::vector<bool> ok(N, true);
    for (int i = 1; i < N; i++) {
        const ll L = B[i - 1];
        for (const auto e : mp[L]) { ok[e] = false; }
        std::vector<ll> v;
        std::vector<ll> buf;
        buf.reserve(N);
        for (int pos = 0; pos < N; pos++) {
            if (ok[pos]) {
                buf.push_back(A[pos]);
            } else {
                if (buf.size() > K - 1) {
