                    for (int i = 0; i < buf.size() - K + 1; i++) { v.push_back(buf[i]); }
                }
                buf.clear();
            }
        }
        if (v.size() < Q) { break; }
        std::sort(v.begin(), v.end());
        ans = std::min(ans, v[Q - 1] - B[i]);
    }
    std::cout << ans << std::endl;

