const int MAXN = 2048;

ll ans;
int n, k, q, least, A[MAXN];
map<int, vector<int>> M;
int p[MAXN], sz[MAXN];
bool valid[MAXN];
vector<pair<int, int>> V;
int findParent(int a){
  while(a != p[a]){
    p[a] = p[p[a]];
    a = p[a];
  }
  return a;
}
void unir(int a, int b){
  if(a < 0 || a >= n) return;
  if(b < 0 || b >= n) return;
  if(!valid[a] || !valid[b]) return;
  a = findParent(a);
  b = findParent(b);
  if(a == b) return;
  sz[b] += sz[a];
  p[a] = b;
}
void crear(int a){
  if(a < 0 || a >= n) return;
  p[a] = a;
  sz[a] = 1;
  valid[a] = true;
}

void solve(){
  memset(valid, false, sizeof valid);
  //~ printf("Resolviendo con least = %d\n", least);
  forn(i, n){
    if(A[i] > least){
      crear(i);
      //~ printf("Creando at %d\n", i);
    }
  }
  forn(i, n){
    unir(i, i-1);
    unir(i, i+1);
  }
  //~ forn(i, n){
    //~ if(!valid[i]) printf("x ");
    //~ else printf("%d[%d] ", findParent(i), sz[findParent(i)]);
  //~ }
  //~ puts("");
  //~ puts("");
  int t = 0;
  ll mn = (ll)1e18;
  ll mx = 0;
  forn(i, V.size()){
    int p = V[i].snd;
    if(!valid[p]) continue;
    //~ printf("Valor %d en %d, tiene sz %d\n", V[i].fst, p, sz[findParent(p)]);
    if(sz[findParent(p)] >= k){
      sz[findParent(p)]--;
      mx = max(mx, (ll)A[p]);
      mn = min(mn, (ll)A[p]);
      t++;
      //~ printf("T == %d\n", t);
      if(t == q){
        //~ printf("Got there with %lld %lld\n", mn, mx);
        ans = min(ans, mx - mn);
        return;
      }
    }
  }
}

int main() {
  //~ freopen("input.in", "r", stdin);
  while( scanf("%d %d %d", &n, &k, &q) >= 1 ){
    ans = (ll)1e18;
    V.clear();
    forn(i, n){
      scanf("%d", &A[i]);
      V.pb({A[i], i});
    }
    sort(V.begin(), V.end());
    least = -1;
    solve();
    forn(i, V.size()){
      if(V[i].fst != least){
        least = V[i].fst;
        solve();
      }
    }
    printf("%lld\n", ans);
  }
  return 0;
}

