inline int check(int d){
	memset(b+1,0,n<<2);
	for(int i=1,j=1;i<=n;++i){
		b[a[i-1].id]=-1;
		if(a[i].v==a[i-1].v)continue;
		for(;j<=n&&a[j].v<=a[i].v+d;)b[a[j++].id]=1;
		int s1=0,s0=0,cnt=0;
		for(int k=1;k<=n;++k){
			if(!b[k])++s0;
			else if(b[k]==1)++s1;
			else{
				cnt+=max(0,min(s1+s0-m+1,s1));
				s1=s0=0;
			}
		}
		cnt+=max(0,min(s1+s0-m+1,s1));
		if(cnt>=q)return 1;
	}
	return 0;
}

