            ok = ok || tree.get(left, right + 1) == a[p];
        }
        if(!ok)
            continue;

        c.erase(c.begin() + p, c.begin() + p + 1);
        dump(c);
        vector<pair<int, int>> ds;
        int left = 0;
        int n = c.size();
        while (left < n) {
            while(left < n && c[left] < a[p]) {
                left++;
            }
            int right = left;
            while(right < n && c[right] >= a[p]) {
                right++;
            }
            if (right == n)
                right--;
            if (right - left + 1 >= k) {
                ds.push_back({ left, right });
            }
            left = right + 1;
        }
        std::vector<int> vv;
        for (auto p : ds) {
            sort(c.begin() + p.first, c.begin() + p.second + 1);

            for (int i = 0; i < p.second - p.first + 1 - k + 1; i++){
                vv.push_back(c[p.first + i]);
            }
        }
        dump(vv);
        if (vv.size() < q-1)
            continue;
        dump(c);
        dump(vv);
        sort(all(vv));
        int m = vv[q - 2];
        ret = min(ret, m - a[p]);
    }
    cout << ret << endl;
    return 0;
}

