const int maxN = (int)2e3 + 10;
int N, K, Q, A[maxN];

void input()
{
    scanf("%d%d%d", &N, &K, &Q);
    for (int i = 1; i <= N; i++)
        scanf("%d", A + i);
}

int bit[maxN];
inline int lowbit(int x) { return x & -x; }
void initBit() { memset(bit, 0, sizeof(bit)); }
inline void add(int pos, int val = 1)
{
    for (; pos <= N; pos += lowbit(pos))
        bit[pos] += val;
}
inline int queryPref(int pos)
{
    int ans = 0;
    for (; pos > 0; pos -= lowbit(pos))
        ans += bit[pos];
    return ans;
}
inline int queryRange(int l, int r) {
    return queryPref(r) - queryPref(l - 1);
}

struct Node { int val, pos; }node[maxN];
void initNode() {
    for (int i = 1; i <= N; i++)
        node[i] = {A[i], i};
    std::sort(node + 1, node + N + 1, [] (Node x, Node y) -> bool {
        return x.val < y.val;
    });
}

int leftMost[maxN], rightMost[maxN];
bool ban[maxN];

int solve()
{
    initNode();
    rightMost[N + 1] = N + 1;
    int ans = node[Q].val - node[1].val;

    for (int t = 1; t + Q <= N; t++) //ban first t vals
    {
        memset(ban, 0, sizeof(ban));
        for (int i = 1; i <= t; i++)
            ban[node[i].pos] = true;

        for (int i = 1; i <= N; i++)
            leftMost[i] = (ban[i] ? i : leftMost[i - 1]);
        for (int i = N; i >= 1; i--)
            rightMost[i] = ban[i] ? i : rightMost[i + 1];

        initBit();
        for (int i = 1; i <= N; i++)
            if (!ban[i])
                add(i, 1);

        int curMin = INT_MAX, curMax = 0;
        int curCnt = 0;

        for (int i = t + 1; i <= N && curCnt < Q; i++) //i-th val
        {
            int cv = node[i].val, cp = node[i].pos;
            int qn = queryRange(leftMost[cp] + 1, rightMost[cp] - 1);
            if (qn >= K) //enough for length K
            {
                curMin = std::min(curMin, cv);
                curMax = std::max(curMax, cv);
                curCnt += 1;
                add(cp, -1); //remove
            }
        }
        if (curCnt == Q)
            ans = std::min(ans, curMax - curMin);
    }

    return ans;
}

int main()
{
    input();
    printf("%d\n", solve());
    return 0;
}

