// ---------------------- template ----------------------

class UnionFind{
	vector<int> to;
	vector<int> cnt;
	vector<int> rank;

public:
	UnionFind(int N) {
		to = vector<int>(N); REP(i, N) to[i] = i;
		cnt = vector<int>(N, 1);
		rank = vector<int>(N, 1);
	}

	size_t size() {
		return to.size();
	}

	int root(int node) {
		if (node == to[node]) {
			return node;
		}
		to[node] = root(to[node]);
		return to[node];
	}

	int& count(int node) {
		return cnt[root(node)];
	}

	int same(int a, int b) {
		return root(a) == root(b);
	}


	void unite(int a,int b){
		if (rank[a] < rank[b]) swap(a, b);
		int rootb = root(b), roota = root(a);
		to[rootb] = roota;
		cnt[roota] += cnt[rootb];
		if (rank[a] == rank[b]) ++rank[a];
	}
};

void solve() {
	int N, K, Q; cin >> N >> K >> Q;
	vector<int> A(N); for(auto &a : A) cin >> a;

	vector<pii> pos(N);
	REP(i, N) {
		pos[i] = { A[i], i };
	}
	sort(ALL(pos));
	vector<bool> isCheck(N); // true: can't use

	int res = inf;
	for (int tar = 0; tar < N; ++tar) {
		int r = inf;
		UnionFind uf(N);
		for (int i = 1; i < N; ++i) {
			if ((not isCheck[i]) and (not isCheck[i - 1])) {
				uf.unite(i, i - 1);
			}
		}
		int cnt = 0;
		for (int i = tar; i < N; ++i){
			if (cnt >= Q) break;
			int v = pos[i].first;
			int p = pos[i].second;
			if (uf.count(p) >= K) {
				r = v;
				++cnt;
				uf.count(p)--;
			}
		}
		if (cnt < Q) break;
		res = min(res, r-pos[tar].first);
		isCheck[pos[tar].second] = true;
	}
	cout << res << endl;
}

