using min_que = priority_queue<ll, vector<ll>, greater<ll>>;

int main(){
    int N, K, Q;
    cin >> N >> K >> Q;

    vector<int> A(N);
    for(int i=0;i<N;i++){
        cin >> A[i];
    }

    ll ans = 1LL << 60;
    for(int i=0;i<N;i++){
        ll min_value = A[i];

        vector<min_que> ques;
        set<ll> vs;
        ques.push_back(min_que());
        for(int j=0;j<N;j++){
            if(min_value <= A[j]){
                ques.back().push(A[j]);
                vs.insert(A[j]);
            }else{
                if(ques.back().size() > 0){
                    ques.push_back(min_que());
                }
            }
        }
        if(ques.back().size() == 0){
            ques.pop_back();
        }

        vector<ll> vs_vec(vs.begin(), vs.end());
        reverse(vs_vec.begin(), vs_vec.end());

        int l = 0, r = vs_vec.size();
        while(r - l > 1){
            int mid = (r + l) / 2;
            int th = vs_vec[mid];

            int cnt = 0;
            for(auto q : ques){
                while(q.size() >= K && q.top() <= th){
                    q.pop();
                    cnt++;
                }
            }
            if(cnt >= Q){
                l = mid;
            }else{
                r = mid;
            }
        }

        int cnt = 0;
        for(auto q : ques){
            while(q.size() >= K && q.top() <= vs_vec[l]){
                q.pop();
                cnt++;
            }
        }

        if(cnt >= Q){
            ans = min(ans, vs_vec[l] - min_value);
        }
    }
    cout << ans << endl;

    return 0;
}

