    rep( j, vss.size() )
    {
      std::sort( all(vss[j]) );

      rep( k, vss[j].size()-K+1 )
        qs.push_back( vss[j][k] );
    }

    if( qs.size() < Q )
      goto end;

    std::sort( all(qs) );

    ans = std::min( ans, qs[Q-1]-qs[0] );

end:;
  }

  printf( "%lld\n", ans );

  return 0;
}

