const int N = 2007;

int parent[N];
int fake_sz[N];
int sz[N];
bool am[N];

void make_set(int v) {
	assert(!am[v]);
	am[v] = 1;
	parent[v] = v;
	sz[v] = 1;
}

int find_set(int v) {
	if (parent[v] == v) return v;
	return parent[v] = find_set(parent[v]);
}

void union_sets(int a, int b) {
	a = find_set(a);
	b = find_set(b);
	if (a == b) return;
	if (sz[a] < sz[b]) swap(a, b);
	sz[a] += sz[b];
	parent[b] = a;
}

