  using size_type = typename container_type::size_type;

protected:
  container_type c;
  value_compare comp;

private:
  static constexpr size_type z = ~static_cast<size_type>(1);
  bool normalize(const size_type x, const size_type y) {
    if (!comp(c[y], c[x]))
      return false;
    std::swap(c[x], c[y]);
    return true;
  }
  void build() {
    const size_type s = size() + 1;
    if (s & 1) {
      normalize(s & z, s);
      buildmin(s >> 1);
      buildmax(s >> 1);
      return;
    }
    if (s == 2)
      return;
    if (normalize(s, s >> 1 | 1))
      buildmax(s >> 2);
    buildmin(s >> 1);
  }
  void buildmin(size_type i) {
    while (i > 1 && normalize(i & z, i << 1))
      i >>= 1;
  }
  void buildmax(size_type i) {
    while (i > 1 && normalize(i << 1 | 1, i | 1))
      i >>= 1;
  }

public:
  explicit IntervalHeap(const value_compare &x = value_compare())
      : c(2), comp(x) {}
  bool empty() const { return c.size() == 2; }
  size_type size() const { return c.size() - 2; }
  const_reference min() const {
    assert(!empty());
    return c[2];
  }
  const_reference max() const {
    assert(!empty());
    return size() == 1 ? c[2] : c[3];
  }
  void push(const value_type &x) {
    c.push_back(x);
    build();
  }
  void push(value_type &&x) {
    c.push_back(std::move(x));
    build();
  }
  template <class... Args> void emplace(Args &&... args) {
    c.emplace_back(std::forward<Args>(args)...);
    build();
  }
  void pop_min() {
    assert(!empty());
    const size_type s = size() + 1;
    std::swap(c[2], c[s]);
    c.pop_back();
    size_type i = 4;
    while (i < s) {
      if ((i | 2) < s && !comp(c[i], c[i | 2]))
        i |= 2;
      if (!normalize(i >> 1 & z, i))
        return;
      if ((i | 1) < s)
        normalize(i, i | 1);
      i <<= 1;
    }
  }
  void pop_max() {
    assert(!empty());
    const size_type s = size() + 1;
    if (s == 2)
      return pop_min();
    std::swap(c[3], c[s]);
    c.pop_back();
    size_type i = 5;
    while (i < s) {
      if ((i | 2) < s && !comp(c[i | 2], c[i]))
        i |= 2;
      if (!normalize(i, i >> 1 | 1))
        return;
      normalize(i & z, i);
      i = (i & z) << 1 | 1;
    }
  }
};

#include <functional>
#include <queue>
#include <utility>
#include <vector>

template <class T, class Container = std::vector<T>,
          class Compare = std::less<typename Container::value_type>>
class meld_priority_queue : public std::priority_queue<T, Container, Compare> {

  void cascade_up(const std::size_t i) {
    auto &c = this->c;
    auto &comp = this->comp;
    const std::size_t l = i * 2 + 1;
    const std::size_t r = i * 2 + 2;
    if (r < c.size() && comp(c[l], c[r])) {
      if (comp(c[i], c[r])) {
        std::swap(c[i], c[r]);
      }
    } else {
      if (comp(c[i], c[l])) {
        std::swap(c[i], c[l]);
      }
    }
  }

public:
  template <class... Args>
  meld_priority_queue(Args &&... args)
      : priority_queue(std::forward<Args>(args)...) {}

  void meld(meld_priority_queue &&x) {
    if (x.empty()) {
      return;
    }
    auto &c = this->c;
    std::size_t l = c.size();
    for (T &v : x.c) {
      c.push_back(std::move(v));
    }
    std::size_t r = c.size() - 1;
    while (r != 0) {
      l = (l - 1) / 2;
      r = (r - 1) / 2;
      for (std::size_t i = l; i <= r; ++i) {
        cascade_up(i);
      }
    }
  }
};

