						tree.push(-values[rb]);
					}
					else
						rb++;
				}

				if (rb == n)
					break;

				int vl = -tree.top();
				if (vl >= v && vl <= m)
				{
					num++;
					cnt--;

					if (d == -1)
						d = u = vl;
					else
					{
						d = min(d, vl);
						u = max(u, vl);
					}

					tree.pop();
				}
				else
				{
					cnt--;
					lb++;

					rb = max(lb, rb);
				}
			}

			if (num >= q)
			{
				label = 1;
				r = m;
				ans = min(ans, u - d);
			}
			else
				l = m;
		}
	}

	assert(label);
	cout << ans;

	return 0;
}

