    vector<ll> added;
    for (int i = 0; i < vec.size(); i++) {
        if (vec[i] < lft) {
            sort(kt.begin(), kt.end());

            for (int t = 0; t < s - k + 1; t++) {
                added.push_back(kt[t]);
            }
            vl += (s - k + 1);
            s = 0;
            pr = 0;
            kt.clear();
        }
        else {
            s++;
            kt.push_back(vec[i]);
            pr = 1;
        }
    }

    sort(added.begin(), added.end());
    mn = INT64_MAX;
    for (int i = 0; i < q && i < added.size(); i++) {
        mx = max(mx, added[i]);
        mn = min(mn, added[i]);
    }
    if (added.size() >= q) return mx - mn;
    else {
        return -1;
    }
}

