const int INF = 1e9 + 9;

using namespace std;

bool exact(int idx, int K, vector<long long>& A){
  int left = idx, right = idx;

  for(int i = idx; i > max(idx - K, -1); --i){
    if(A[i] >= A[idx]) left = i;
    else break;
  }

  for(int i = idx; i < min(idx + K, (int)A.size()); ++i){
    if(A[i] >= A[idx]) right = i;
    else break;
  }

  return right - left + 1 >= K;
}

int main(){
  int N, K, Q;
  cin >> N >> K >> Q;

  vector<long long> A(N);
  for(int i = 0; i < N; ++i) cin >> A[i];

  long long min_diff = INF;
  for(int i = 0; i < N; ++i){
    int erasable = 0;
    int len = 0;
    vector<long long> max_candidate;
    for(int j = 0; j < N; ++j){
      if(A[j] >= A[i]){
        ++len;
        max_candidate.push_back(A[j]);
      }else{
        erasable += max(len - K + 1, 0);
        len = 0;
      }
    }
    erasable += max(len - K + 1, 0);

    if(erasable >= Q && exact(i, K, A)){
      sort(max_candidate.begin(), max_candidate.end());
      min_diff = min(max_candidate[Q - 1] - A[i], min_diff);
    }
  }

  cout << min_diff << endl;

  return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define pii pair<int,int>
const int inf = 1 << 30;
int N, K, Q;
int A[2010], L[2010], R[2010];
vector<pii> vs;

void update(pii p){
    int val = p.first;
    int idx = p.second;
    for(int i = 0; i < idx; i++){
        R[i] = min(R[i], idx - i - 1);
    }
    for(int i = idx + 1; i < N; i++){
        L[i] = min(L[i], i - idx - 1);
    }
}

int solve(){
    int ans = inf;
    for(int i = 0; i < N; i++){
        int val = vs[i].first;
        int idx = vs[i].second;
        if(L[idx] + R[idx] + 1 >= K){
            int cnt = 1;
            for(int j = i + 1; j < N; j++){
                idx = vs[j].second;
                if(L[idx] + R[idx] + 1 >= K) cnt++;
                if(cnt == Q){
                    ans = min(ans, vs[j].first - val);
                    break;
                }
            }
        }
        update(vs[i]);
    }
    return ans;
}

void init(){
    cin >> N >> K >> Q;
    for(int i = 0; i < N; i++){
        cin >> A[i];
        vs.push_back({A[i], i});
    }
    sort(vs.begin(), vs.end());
    for(int i = 0; i < N; i++){
        for(int j = 0; j < i; j++){
            if(A[j] > A[i]) L[i]++;
        }
        for(int j = i + 1; j < N; j++){
            if(A[j] >= A[i]) R[i]++;
        }
    }
}

int main(){
    init();
    cout << solve() << endl;
    return 0;
}

