int n, k, q;
int a[N];

int tree[N];
int size;
#define lowbit(x) (x) & (-x)
inline void Add(int x, int t)
{
	while(x <= size)
	{
		tree[x] += t;
		x += lowbit(x);
	}
}
inline int Query(int x)
{
	int Ans = 0;
	while(x > 0)
	{
		Ans += tree[x];
		x -= lowbit(x);
	}
	return Ans;
}
struct D{
	int x, p;
}B[N];
inline bool cmp(D x, D y)
{
	return x.x < y.x;
}
int x[N];
int y[N];
int main()
{
	scanf("%d%d%d", &n, &k, &q);
	for(int i = 1; i <= n; ++ i)
		scanf("%d", &a[i]);
	for(int i = 1; i <= n; ++ i)
		B[i].x = a[i], B[i].p = i;
	sort(B + 1, B + n + 1, cmp);
	int Ans = 2147483647;
	for(int i = 0; i <= n; ++ i)
	{
		memset(tree, 0, sizeof(tree));
		size = n;
		x[0] = -1;
		for(int j = 1; j <= n; ++ j)
			if(a[j] <= B[i].x)
				x[j] = -1;
			else
				x[j] = x[j - 1] + 1;
		y[n + 1] = -1;
		for(int j = n; j >= 1; -- j)
			if(a[j] <= B[i].x)
				y[j] = -1;
			else
				y[j] = y[j + 1] + 1;
		for(int j = 1; j <= n; ++ j)
		{
			Add(j, x[j] + y[j] + 1);
			Add(j + 1, - x[j] - y[j] - 1);
		}
		int tot = 0;
		int Min = 2147483647;
		int Max = 0;
		for(int j = i + 1; j <= n; ++ j)
		{
			if(Query(B[j].p) >= k)
			{
				++ tot;
				Add(B[j].p - x[B[j].p], -1);
				Add(B[j].p + y[B[j].p] + 1, 1);
				Min = min(B[j].x, Min);
				Max = max(B[j].x, Max);
			}
			if(tot == q)
				break;

		}
		if(tot != q)
			break;
		else
			Ans = min(Ans, Max - Min);
	}
	printf("%d", Ans);
	return 0;
}

