    sort(a, a + n);
    int best = 1e9;
    int rd = 0;
    for(int e = 0; e < n - k + 1; e++){
        int lo = max(rd, e), hi = e, fu = n - 1;
        while(hi < n - 1 && a[hi + 1] - a[lo] < best) hi++;
        while(lo <= hi){
            int mid = (lo + hi)>>1;
            int L = a[e], R = a[mid];
            set<pair<int,int> > sweep;
            int bg = 0, ed = 0;
            for(int f = 0; f < n; f++) bad[f] = 0;
            for(int f = 0; f < k; f++, ed++)
                sweep.insert(make_pair(p[ed], ed) );
            int ops = 0;
            for(int f = 0; f < n && ops < q; f++){
                auto it = *sweep.begin();
                if(L <= it.first && it.first <= R){
                    bad[it.second] = 1;
                    sweep.erase(sweep.begin());
                    ops++;
                } else {
                    while(bg < n && bad[bg]) bg++;
                    sweep.erase(make_pair(p[bg], bg));
                    bad[bg] = 1;
                }
                if(ed == n) break;
                sweep.insert(make_pair(p[ed], ed)); ed++;
            }
            if(ops >= q){
                best = min(best, R - L);
                hi = mid - 1;
                fu = min(fu, mid);
            } else {
                lo = mid + 1;
            }
        }
        rd = max(rd, fu);
        fu -= 20;
    }
