int find(int x){
	int L=1,R=hs,mid;
	while (L<=R){
		mid=(L+R)>>1;
		if (Ha[mid]==x)
			return mid;
		if (x>Ha[mid])
			L=mid+1;
		else
			R=mid-1;
	}
}
