int find(int x){
	if( x == pa[x] ) return x;
	return pa[x] = find(pa[x]);
}
void uni(int a, int b){
	a = find(a); b = find(b);
	if( a == b ) return;
	pa[b] = a;
	sz[a] += sz[b];
}

int solve(int x){

	repp(i,N){
		if( p[i] < x ) continue;
		pa[i] = i; sz[i] = 1;
		if( p[i-1] >= x ) uni(i,i-1);
	}

	int cnt = 0;
	int mx = -1;
	int mn = INF;
	for(auto e : mp){
		if( e.Fi < x ) continue;
		int val = e.Fi;
		vector<int>& ev = e.Se;
		for(auto pos : ev){
			if( sz[find(pos)] < K ) continue;
			sz[find(pos)]--;
			cnt++;
			mx = max(mx,val);
			mn = min(mn,val);
			if( cnt == Q ) return mx-mn;
		}
	}

	if( cnt < Q ) return 2*1e9;
	return mx-mn;
}


