int get(int x) {
	while (!pq.empty()) pq.pop();
	int len = 0;
	for (int i = 1; i <= n; i++) {
		if (a[i] < x) continue;
		len++;
		cur.push(a[i]);
		if (i == n || a[i + 1] < x) {
