template<class T> struct SumSeg { 
	const T ID = 0; // comb(ID,b) must equal b
	T combine(T a, T b) { return a+b; } 
	int n; vector<T> seg;
	void init(int _n) { n = _n; seg.assign(2*n,ID);}

	void update(int p, T value) {	// set value at position p
		seg[p += n] = value;
		for (p /= 2; p; p /= 2) seg[p] = combine(seg[2*p], seg[2*p+1]);
	}

	T query(int l, int r) {	 // sum on interval [l, r]
		T ra = ID, rb = ID; 
		for (l += n, r += n+1; l < r; l /= 2, r /= 2) {
			if (l&1) ra = combine(ra,seg[l++]);
			if (r&1) rb = combine(seg[--r],rb);
		}
		return combine(ra,rb);
	}
};

vi arr;

int main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	int N, K, Q; cin >> N >> K >> Q;

	arr.resize(N);
	F0R(i, N) cin >> arr[i];

	vi perm (N);
	F0R(i, N) perm[i] = i;
	sort(perm.begin(), perm.end(), [] (const auto& lhs, const auto& rhs) { 
		return arr[lhs] < arr[rhs];
	});

	int best = 1e9;
	F0R(i, N) {
		SumSeg<int> sumSeg; sumSeg.init(N);
		SumSeg<int> minSeg; minSeg.init(N);
		F0R(j, i) minSeg.update(perm[j], 1);

		int cur = i;
		int C = Q;

		int hi = arr[perm[cur]];

		while (C) {
			int j = perm[cur];

			// left binary search
			int l1 = 0;
			int h1 = j;
			while (l1 < h1) {
				int m = l1 + (h1 - l1) / 2;
				if (minSeg.query(m, j) != 0) {
					l1 = m + 1;
				} else {
					h1 = m;
				}
			}

			int l2 = j;
			int h2 = N - 1;
			while (l2 < h2) {
				int m = l2 + (h2 - l2 + 1) / 2;
				if (minSeg.query(j, m) != 0) {
					h2 = m - 1;
				} else {
					l2 = m;
				}
			}



			int dist = l2 - l1 + 1;
			int remo = sumSeg.query(l1, l2);
			if (dist - remo >= K) {
				// remove
				hi = arr[j];
				C--;
				sumSeg.update(j, 1);
			} else {
				// dont remove
				minSeg.update(j, 1);
			}

			++cur;
			if (cur >= N) break;
		}
		if (C == 0) {
			best = min(best, hi - arr[perm[i]]);
		}
	}
	print(best);

}

