int N, K, Q;

struct Segment {
	int r, l;
	mutable int gen;
	mutable int cnt;

	Segment(int l, int r) : l(l), r(r), gen(-1), cnt(0) { }

	int Count(int gen) const {
		if (gen != this->gen) {
			this->gen = gen;
			this->cnt = r - l;
		}
		return cnt;
	}

	bool Good() {
		return l < r;
	}
};

bool operator < (const Segment& l, const Segment& r) {
	return l.r < r.r;
}

set<Segment> s;
vector<pair<int, int>> pA;

int solve(int left) {
	int q = Q;
	Segment t(0, N);
	for (int i = left; i < N; i++) {
		t.r = pA[i].second;
		auto it = s.upper_bound(t);
		if (it->Count(left) >= K) {
			it->cnt--;
			if (!--q) {
				return pA[i].first - pA[left].first;
			}
		}
	}
	return INT_MAX;
}

int main(int argc, const char* argv[]) {
	read(N);
	read(K);
	read(Q);
	VI A(N);
	read(A);
	pA.resize(N);
	for (int i = 0; i < N; i++)
		pA[i] = {A[i], i};
	sort(all(pA));
	s.emplace(0, N);
	int ret = INT_MAX;
	for (int l = 0; l <= N - Q; l++) {
		mini(ret, solve(l));
		int splitter = pA[l].second;
		auto it = s.upper_bound(Segment(0, splitter));
		Segment left(it->l, splitter);
		Segment right(splitter+1, it->r);
		s.erase(it);
		if (left.Good())
			s.insert(left);
		if (right.Good())
			s.insert(right);
	}
	printf("%d\n", ret);
	return 0;
}

