struct segment_tree{
    const long INF = 2*1e9;
    long n = 1;
    long data[10000];
    segment_tree(int a){
        while(n<a) n*=2;
        for(int i = 0;i<2*n;i++) data[i] = INF;
    }
    //segment treeの大きさ取得
    long nreturn(){
        return n;
    }
    //0-indexでk番目の値をaに変更
    void change(long k,long a){
        k+=n-1;
        data[k] = a;
        while(k>0){
            k = (k-1)/2;
            data[k] = min(data[2*k+1],data[2*k+2]);
            /*cout << "data" << k << "is changed to" << data[k] << endl;*/
        }
        return;
    }
    //区間[a,b)の最小値:呼ぶときはrmq(a,b,0,0,n)
    long rmq(long a,long b,long k,long l,long r){
        if(a>=r || b<=l) return INF;
        if(a<=l && b>=r) return data[k];
        long teml = rmq(a,b,2*k+1,l,(l+r)/2);
        long temr = rmq(a,b,2*k+2,(l+r)/2,r);
        return min(teml,temr);
    }
    //最小値を返す0-indexの添え字を返す
    long tmp(long a,long k){
        if(n-1<=k) return k-n+1;
        if(data[2*k+1]==a) return tmp(a,2*k+1);
        return tmp(a,2*k+2); 
    }
};
