ll n , k , q;
ll a[2002];
const ll inf = 1e9;
bool take[2002];
ll solve(ll x)
{
        for(ll i=1;i<=n;i++) {
                if(a[i] < x) take[i] = false;
                else take[i] = true;
        }
        vector<ll> t;
        for(ll i=1;i<=n;i++) {
                if(take[i] == false) continue;
                ll j = i;
                while(j <= n && take[j] == true) j++;
                vector<ll> v;
