int main()
{
	ios_base::sync_with_stdio(false);cout.tie(0);cin.tie(0);

	ll x, y, z, i, j, n, k, q, a, b, ans = 1e18;
	cin >> n >> k >> q;
	for (i = 1; i <= n; ++i) {
			cin >> A[i];
			B[i] = A[i];
	}
	sort(B+1, B+n+1);
	s.insert(mkp(1ll, n));

	ll tot_moves = (n - k + 1);
	for (i = q; i <= n; ++i) {
		ll tmp = B[i] - B[i-q+1];
		ans = min(ans, tmp);
		x = B[i-q+1];
		ll cur = 0;
		ll moves = 0;

		ll ids, ide, idm;
		for (auto it: s) {
			ll start = it.fi;
