					a = j+1;
					b = end;
					if (b-a+1 >= k) cur += (b-a+1 - k + 1);
					cur = tot_moves + cur;
					if (end-start+1 >= k) cur -= (end-start+1 - k + 1);
					if (cur > moves) {
