const int N = 2e3 + 5;

int n , k , q , A[N] , L[N] , R[N] , id[N] , fa[N]  , S[N];

bool cmp(int x , int y) {
	return A[x] < A[y];
}

int getf(int x) {
	return (fa[x] == x) ? x : fa[x] = getf(fa[x]);
}

bool pd(int x) {
	for(int i = 1;i <= n;++ i) {
		int now = 0;
		for(int ii = 1;ii <= n;++ ii)
		S[ii] = 0 , fa[ii] = ii;
		for(int j = 1;j <= n;++ j) {
			if(A[j] < A[i])
			continue;
			else {
				if(j == 1 || A[j - 1] < A[i])
				S[j] = 1;
				else {
					fa[j] = getf(j - 1);
					++ S[getf(j)];
				}
			}
		}
		for(int j = 1;j <= n;++ j) {
			if(A[id[j]] >= A[i] && A[id[j]] - A[i] <= x) {
				if(S[getf(id[j])] >= k) {
					-- S[getf(id[j])];
					++ now;
				}
			}
		}
		if(now >= q)
		return 1;
	}
	return 0;
}

