		for( int j = N ; j >= 1 ; j -- ) nxt[j] = ban[j] ? j : nxt[j+1] ;

		cnt = st = 0 , reset( root , 1 , N ) ;

		for( int j = i + 1 ; j <= N && cnt < Q ; j ++ ){
			if( nxt[ sa[j] ] - pre[ sa[j] ] - 1 < K ) continue ;
			if( Query( root , 1 , N , pre[ sa[j] ] + 1 , nxt[ sa[j] ] - 1 ) >= K ){
