			}
		} if( cnt != Q ) break ;

		smin( ans , a[ sa[ed] ] - a[ sa[st] ] ) ;
		for( int j = 1 ; j <= i ; j ++ ) ban[ sa[j] ] = false ;

	} printf( "%d" , ans ) ;
}

