bool removable(int idx)
{
        int floor = 0;
        int ceil = 0;

        rrep (i, idx) {
                if (alist[i] < alist[idx]) {
                        floor = i;
                        break;
                }
        }

        srep (i, idx + 1, n + 2) {
                if (alist[i] < alist[idx]) {
                        ceil = i;
                        break;
                }
        }

        return ((ceil - floor) > k);
}

void cplist(V<ll> &copylist, int rmidx)
{
        rep (i, n+2) {
                if (i != rmidx) copylist.pb(alist[i]);
        }
}

void make_ahareas(V<t2> &areas, const V<ll> &copylist, ll border)
{
        bool inarea = false;
        ll start;

        rep (i, n+1) {
                if (copylist[i] < border) {
                        if (inarea) {
                                areas.pb(t2(start, i));
                        }
                        inarea = false;
                        continue;
                }
                if (!inarea) {
                        start = i;
                        inarea = true;
                }
        }
}

