inline int ok(int x, int y, int k, int q) {
    int cnt = 0, go = 0, good = 0;
    for (int i = 1; i <= n; ++i) {
        if (a[i] < x) {
            cnt += max(0, min(good, go - k + 1));
            go = 0, good = 0;
        }
        else {
            go++;
            if (a[i] <= y) good++;
        }
    }
    cnt += max(0, min(good, go - k + 1));
    return cnt >= q;
