const int N = 1e6 + 5;


int n , m , q , a[N] ,ans;
vector<int> vs(N , 0);
int id = 0;
bool check(int L , int R)
{
    id++;
    multiset< pair<int , int> > Q;
    queue<int> idxs;
    int ret = 0;
    for(int  i= 0;i<n;i++)
    {
        Q.insert({ a[i] , i });
        idxs.push(i);
        if(Q.size()==m)
        {
            pair<int , int> ltl = *Q.begin();
            if( ltl.first>=L && ltl.first<=R )
            {
                ret++;
                Q.erase(Q.begin());
                vs[ltl.second] = id;
            }
            else
            {
                while( idxs.size() && vs[idxs.front()]==id )
                    idxs.pop();
                int ix =idxs.front();
                Q.erase({ a[ix],ix });
                idxs.pop();
            }
        }
    }
    return ret>=q;
}

