		{
			int k = lower_bound(as + 1, as + n + 1, mp(a[j], 0)) - as;
			if(k<i)
			{
				qus.pb(j);
				ql[SZ(qus) - 1] = qus[SZ(qus) - 1] - qus[SZ(qus) - 2] - 1;
			}
