bool used[MAX_N];

bool check(int l, int r)
{
    memset(used, 0, sizeof(used));
    for(int i = 0; i < N; i++) {
        if(l <= A[i]) {
            used[i] = true;
        }
    }

    int cnt = 0;
    for(int i = 0; i < N; ) {
        if(!used[i]) {
            i++;
            continue;
        }
        int j = i;
        int k = 0;
        for(; j < N; j++) {
            if(!used[j]) {
                break;
            } else if(A[j] < r) {
                k++;
            }
        }
        if(j-i >= K) {
            cnt += min(k, j-i-K+1);
        }
        i = j;
    }

    // cerr << "Cnt: " << cnt << endl;

    return cnt >= Q;
}

