vector<int> splitter(vector<int> A, int base)
{
	vector<int> res(1,-1);
	REP(i, N)if (A[i] < base)res.push_back(i);
	res.push_back(N);

	return res;
}

int X_Y(const vector<int> sp, int K,int Q) {
	vector<int> mini;
	REP(k, sp.size()-1) {
		vector<int> tmp;
		FOR(i, sp[k] + 1, sp[k+1]) {
			tmp.push_back(A[i]);
		}
		sort(tmp.begin(), tmp.end());
		REP(i, (int)tmp.size() - K+1) {
			mini.push_back(tmp[i]);
		}
	}
	if (mini.size() < Q)return INF;
	sort(mini.begin(), mini.end());
	return mini[Q - 1] - mini[0];
}

