void solve() {
    int N, K, Q; cin >> N >> K >> Q;
    vector<int> A, B;
    rep(i, N) {
        cin >> A[i];
        B[i] = A[i];
    }
    sort(all(B));
    int ans = B[Q - 1] - B[0];
    rep(i, N) {
        int X = A[i];
        vector<int> C;
        rep(j, N) {
            if(j == i) continue;
            C.pb(A[j]);
        }
        vector<int> vec, res;
        res.pb(X);
        rep(j, N - 1) {
            if(C[j] >= X) {
                vec.pb(C[j]);
            } 
            if(C[j] < X || j == N - 1) {
                sort(all(vec));
                int M = vec.size();
                rep(k, M - K + 1) {
                    res.pb(vec[k]);
                }
                vec.resize(0);
            }
        }
        sort(all(res));
        if(Q > res.size()) continue;
        int Y = res[Q - 1];
        int ret = Y - X;
        ans = min(ans, ret);
    }
    cout << ans << endl;
}

