		num[p[i].second]=0;
		int sum=0, now=1;
		for(int j=0; j<N; ++j){
			if(num[j]==0){
				sum += max(0, flake[now]-K+1);
				++now;
			}else{
				num[j]=now;
				++flake[now];
			}
		}
		sum += max(0, flake[now]-K+1);
