ll solve() {
#ifdef DEBUG
    printf("N=%d K=%d Q=%d\n", N,K,Q);
#endif
//    vector<ii> u(N);
    map<int,vi> mu;
    rep(i,N) mu[ a[i] ].pb(i);

    vector<ii> ranges;
    ranges.pb(ii(0, N-1)); // inclusive
#ifdef DEBUG
    cerr << ranges << endl;
#endif
    vi tmp(ALL(a));
    sort(ALL(tmp));
    int best = tmp[Q-1] - tmp[0];

    for (auto p: mu) {
        // int v = p.first;
#ifdef DEBUG
        cerr << p.first << " " << p.second << endl;
#endif
        int minp = p.first;
        for (int i : p.second) {
            // dividing
            for (int j=ranges.size()-1; j>=0; --j) {
                if (IN(i, ranges[j].first, ranges[j].second)) {
#ifdef DEBUG
                    printf(" %d in (%d,%d)...\n", i, ranges[j].first, ranges[j].second);
#endif
                    if (i+1+(K-1) <= ranges[j].second) {
                        ranges.insert(ranges.begin()+j+1, ii(i+1, ranges[j].second));
                    }
                    if (ranges[j].first <= i-1-(K-1)) {
                        ranges[j].second = i-1;
                    } else {
                        ranges.erase(ranges.begin()+j);
                    }
                    break;
                }
            }
#ifdef DEBUG
            cerr <<  "  >> " << ranges << endl;
#endif
            if (ranges.empty()) goto break_loop;

            vi tmp; tmp.reserve(N);
            for (auto r: ranges) {
                for (int c=r.first; c<=r.second; ++c){
                    assert(IN(c, 0, N-1));
                    tmp.pb(a[c]);
                }
