            sort(ALL(tmp));
            if (tmp.size() < Q-2) break;
            // tmp.erase(tmp.begin()+Q);
            int score = tmp[Q-2] - minp;
#ifdef DEBUG
            cerr << ranges << tmp << " " << score << endl;
#endif
            best = min(best, score);
        }
    }
break_loop:

    return best;
}


