bool chk(int x) {
    for(int i = 1; i <= n; i++) {
        int Min = a[i];
        int res = 0;
        for(int l = 1, r; l <= n; l = r) {
            r = l;
            if(a[l] < Min) {
                ++r; continue;
            }
            int cnt = 0;
            while(r <= n && a[r] >= Min) {
                if(a[r] <= Min + x) ++cnt;
                ++r;
            }
            if(r - l >= k) res += min(r - l + 1 - k, cnt);
        }
        if(res >= q) return true;
    }
    return false;
}

