int solve(int N, int K, int Q, vector<int> &A, int x){
    priority_queue<int, vector<int>, greater<int>> pq_all;
    priority_queue<int, vector<int>, greater<int>> pq;
    REP(i, N+1){
        if(A[i] < x){
            while(!pq.empty()){
                if(pq.size() >= K){
                    pq_all.push(pq.top());
                }
                pq.pop();
            }
        }else{
            pq.push(A[i]);
        }
    }
    if(pq_all.size() < Q) return 1<<30;
    int mx = 0;
    int mn = 1<<30;
    REP(i, Q){
        int tp = pq_all.top();
        pq_all.pop();
        mx = max(mx, tp);
        mn = min(mn, tp);
    }
    return mx - mn;
}

