int t[4 * MAXN];

void build(int v, int tl, int tr) {
	if (tl == tr) t[v] = 1;
	else {
		int tm = (tl + tr) >> 1;
		build(v * 2, tl, tm);
		build(v * 2 + 1, tm + 1, tr);
		t[v] = t[v * 2] + t[v * 2 + 1];
	}
}

void add(int v, int tl, int tr, int k) {
	if (tl == tr) t[v]--;
	else {
		int tm = (tl + tr) >> 1;
		if (k <= tm) add(v * 2, tl, tm, k);
		else add(v * 2 + 1, tm + 1, tr, k);
		t[v] = t[v * 2] + t[v * 2 + 1];
	}
}

int get(int v, int tl, int tr, int l, int r) {
	if (tl == l && tr == r) return t[v];
	else {
		int tm = (tl + tr) >> 1;
		int res = 0;
		if (l <= tm) res += get(v * 2, tl, tm, l, min(tm, r));
		if (r > tm) res += get(v * 2 + 1, tm + 1, tr, max(tm + 1, l), r);
		return res;
	}
}

void solve() {
	int n, k, q;
	cin >> n >> k >> q;
	vector<pair<int, int> > v(n + 1);
	repn(i, 1, n) {
		cin >> v[i].fi;
		v[i].se = i;
	}
	sort(all(v));

	int ans = v[n].fi - v[1].fi;
	repn(i, 1, n) {
		set<int> pos;
		pos.insert(0);
		pos.insert(n + 1);
		build(1, 0, n + 1);
		rep(j, 1, i) {
			pos.insert(v[j].se);
			add(1, 0, n + 1, v[j].se);
		}
		int cnt = 0;
		repn(j, i, n) {
			auto l = *(--pos.lower_bound(v[j].se));
			auto r = *(pos.lower_bound(v[j].se));
			if (get(1, 0, n + 1, l + 1, r - 1) >= k) {
				add(1, 0, n + 1, v[j].se);
				cnt++;
			}
			if (cnt >= q) {
				ans = min(ans, v[j].fi - v[i].fi);
				break;
			}
		}
	}

	cout << ans;
}

int main() {
	ios::sync_with_stdio(false);
	cin.tie(0);
	cout.tie(0);

	solve();
}

