long long subSolve(ll lb, vector<ll> A, int Q, int K) {
    memset(seg, 0, sizeof(seg));

    long long ans = 0;

    vector<pair<ll, int> > items;
    set<int> guard;
    for (int i = 0; i < A.size(); i++)
        if (A[i] >= lb) items.push_back({A[i], i});
        else guard.insert(i);
    sort(items.begin(), items.end());
    guard.insert(-1);
    guard.insert(A.size());
    int cnt = 0;
    for (auto &&p : items) {
        int l = *--guard.lower_bound(p.second) + 1;
        int r = *guard.lower_bound(p.second) - 1;
        cnt += r - l + 1 - get(l, r) >= K;
        ans = p.first;
        if (cnt >= Q) break;
        add(p.second, 1);
    }
    if (cnt < Q) return 1e18;
    return ans - lb;
}

void solve(ll N, ll K, ll Q, vector<ll> A) {
    long long ans = 1e18;
    for (int i = 0; i < A.size(); i++) {
        ans = min(ans, subSolve(A[i], A, Q, K));
        //cout << A[i] << " " << subSolve(A[i], A, Q, K) << endl;
    }
    cout << ans << endl;
}


