void solve_e_fast() {
  int n,k,q;
  cin >> n >> k >> q;
  vi a(n);
  vector<multiset<int>> S(n);
  multiset<int> S0, S1;
  vector<int> dsu(n); forn(i, n) dsu[i] = i;
  auto merge = [&] (int i, int j) {
    if ((i = get(dsu, i)) == (j = get(dsu, j))) return ;
    if (S[i].size() < S[j].size()) swap(i, j);
    dsu[j] = i;
    for (int x: S[j]) S[i].insert(x);
    S[j].clear();
  };
  forn(i, n) {
    cin >> a[i];
    S[i].insert(a[i]);
  }
  int ans = inf;
  vi ord(n); forn(i, n) ord[i] = i; sort(all(ord), [&] (int i, int j) { return mp(a[i], i) > mp(a[j], j); });
  vi used(n, 0);
  for (int i: ord) {
    if (i + 1 < n && used[i + 1]) merge(i, i + 1);
    if (i > 0 && used[i - 1]) merge(i, i - 1);
    used[i] = 1;
    i = get(dsu, i);
    while (S[i].size() > k - 1) {
      S0.insert(*S[i].begin());
      S[i].erase(S[i].begin());
    }
    while (S0.size() >= q) {
      S1.insert(*S0.rbegin());
      S0.erase(prev(S0.end()));
    }
    if (S0.size() == q - 1 && !S1.empty()) {
      uin(ans, *(S1.begin()) - *(S0.begin()));
    }
  }
  cout << ans << endl;
}

