vector<int> vs(N , 0) , vis(N);
int id = 0 , id2;
bool check(int L , int R)
{
    id++;
    id2++;
    int tax = 0;
    priority_queue< pair<int , int> > Q;
    queue<int> idxs;
    int ret = 0;
    for(int  i= 0;i<n;i++)
    {
        Q.push({ -a[i] , i });
        idxs.push(i);
        while( vis[Q.top().second]==id2 )
        {
            Q.pop();
            tax--;
        }
        if(Q.size() - tax==m)
        {
            pair<int , int> ltl = Q.top();
            if( -ltl.first>=L && -ltl.first<=R )
            {
                ret++;
                Q.pop();
                vs[ltl.second] = id;
            }
            else
            {
                while( idxs.size() && vs[idxs.front()]==id )
                    idxs.pop();
                int ix =idxs.front();
                vis[ix] = id2;
                tax++;
                idxs.pop();
            }
        }
    }
    return ret>=q;
}

