  // 枚举被删除的最小的数x。
  // 小于x的数把序列分成若干段。考虑长度大于等于k的段。
  int n, k, q;
  scan(n, k, q);
  vi a(n);
  scan(a);
  int ans = INT_MAX;
  FOR (x, a) {
    pq<int> que;
    vi c;
    int mi = INT_MAX;
    for (int i = 0; i <= n; ++i) {
      if (a[i] < x || i == n) {
        sort(all(c));
        if (SZ(c) >= k) {
          chkmin(mi, c[0]);
        }
        for (int j = 0; j <= SZ(c) - k; ++j) {
          if (que.size() < q) que.push(c[j]);
          else if (que.top() > c[j]) {
            que.pop();
            que.push(c[j]);
          }
        }
        c.clear();
      } else {
        c.pb(a[i]);
      }
    }
    if (mi != x || que.size() != q) continue;
    chkmin(ans, que.top() - x);
  }
  println(ans);

