                    left = j+1;
                    right = j+1;
                }
            }
            if(cnt < Q)break;
            else {
                sort(D, D+cnt);
                ans = min(ans, D[Q-1]-D[0]);
            }
        }
        prev = B[i];
    }
    cout << ans << endl;
