typedef long long ll;
typedef long double ld;


const int sze = 1 << 11, INF = 1e9 + 10;


int n, k, q, m;
int kick[sze];
vector<int> positions[sze];
priority_queue<int, vector<int>> challengers;



bool check(int up, int down, const vector<int> &values)
{
	fill(kick, kick + m, 0);

	for (int i = n - 1; i >= 0; --i)
		positions[values[i]].push_back(i);


	int l = 0, r = 0, cnt = 0, num = 0;

	while (l < n)
	{
		while (r < n && num < k)
		{
			challengers.push(-values[r]);
			num++;
			r++;

			while (challengers.size() && kick[-challengers.top()])
			{
				kick[-challengers.top()]--;
				challengers.pop();
			}
		}

		if (num != k)
			break;

		int vl = -challengers.top();
		if (vl <= up && vl >= down)
		{
			cnt++;
			num--;
			challengers.pop();
			positions[vl].pop_back();
		}
		else
		{
			if (positions[values[l]].size() && positions[values[l]][positions[values[l]].size() - 1] == l)
			{
				positions[values[l]].pop_back();
				kick[values[l]]++;
				num--;
			}

			l++;
		}
	}

	while (challengers.size())
		challengers.pop();

	for (int i = 0; i < sze; ++i)
		positions[i].clear();

	return cnt >= q;
}


signed main()
{
	scanf("%d%d%d", &n, &k, &q);

	vector<int> values(n), challengers;

	for (int i = 0; i < n; ++i)
		scanf("%d", &values[i]);

	challengers = values;
	sort(challengers.begin(), challengers.end());


	int M = unique(challengers.begin(), challengers.end()) - challengers.begin();
	challengers.resize(M);

	unordered_map<int, int> trans;
	for (int i = 0; i < M; ++i)
		trans[challengers[i]] = i;

	for (int i = 0; i < n; ++i)
		values[i] = trans[values[i]];

	int ans = INF;
	m = challengers.size();
	for (int i = 0; i < m; ++i)
	{
		int l = i - 1, r = m;

		while (r - l > 1)
		{
			int mid = (l + r) >> 1;
			int up = mid, down = i;

			if (check(up, down, values))
				r = mid;
			else
				l = mid;
		}

		if (r != m)
			ans = min(ans, challengers[r] - challengers[i]);
	}

	printf("%d", ans);
	return 0;
}

