void solve()
{
	READ(int, N, K, Q);
	auto A = read<int>(N);
	if (Q == 1)
	{
		WRITE(0);
		return;
	}

	int ans = INF(int);
	auto C = A; sort(allof(C));
	REP(i, N)
	{
		int k = C[i];

		int cnt = 0;
		int ok = 0;
		REP(j, N)
		{
			if (A[j] <= k) { cnt = 0; }
			else { cnt++; }
			if (cnt >= K) { ok++; }
		}

		ans = min(ans, C[i + Q - 1] - C[i]);

		if (ok <= Q-1)
		{
			break;
		}
	}
	WRITE(ans);
}

