bool check(int up, int down, const vector<int> &values)
{
	vector<int> challengers = values;
	vector<int> positions[3];

	for (int i = n - 1; i >= 0; --i)
	{
		if (challengers[i] > up)
			challengers[i] = 2;
		else if (challengers[i] < down)
			challengers[i] = 0;
		else
			challengers[i] = 1;

		positions[challengers[i]].push_back(i);
	}

	int l = 0, r = 0, cnt = 0, num = 0;
	int a[3] = {};

	while (l < n)
	{
		while (r < n && num < k)
		{
			a[challengers[r]]++;
			num++;
			r++;
		}

		if (num != k)
			break;

		int vl = 0;
		while (!a[vl])
			vl++;

		if (vl == 1)
		{
			cnt++;
			num--;
			a[vl]--;
			positions[vl].pop_back();
		}
		else
		{
			if (positions[challengers[l]].size() && positions[challengers[l]][positions[challengers[l]].size() - 1] == l)
			{
				a[challengers[l]]--;
				positions[challengers[l]].pop_back();
				num--;
			}

			l++;
		}
	}

	return cnt >= q;
}


signed main()
{
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	cout.tie(NULL);

	cin >> n >> k >> q;

	vector<int> values(n), challengers;

	for (int i = 0; i < n; ++i)
		cin >> values[i];

	challengers = values;
	sort(challengers.begin(), challengers.end());


	int M = unique(challengers.begin(), challengers.end()) - challengers.begin();
	challengers.resize(M);

	map<int, int> trans;
	for (int i = 0; i < M; ++i)
		trans[challengers[i]] = i;

	for (int i = 0; i < n; ++i)
		values[i] = trans[values[i]];

	int ans = INF;
	int m = challengers.size();
	for (int i = 0; i < m; ++i)
	{
		int l = i - 1, r = m;

		while (r - l > 1)
		{
			int mid = (l + r) >> 1;
			int up = mid, down = i;

			if (check(up, down, values))
				r = mid;
			else
				l = mid;
		}

		if (r != m)
			ans = min(ans, challengers[r] - challengers[i]);
	}

	cout << ans;
	return 0;
}

