void solve(int border,vector<int> &a){
    using PQ = priority_queue<int,vector<int>,greater<int>>;
    PQ qu,seg;
    rep(i,n){
        if(a[i] < border){
            while(!seg.empty()){
                if((int)seg.size() >= k){
                    qu.push(seg.top());
                }
                seg.pop();
            }
        }else{
            seg.push(a[i]);
        }
    }
    while(!seg.empty()){
        if((int)seg.size() >= k){
            qu.push(seg.top());
        }
        seg.pop();
    }
