template <class T>
vector<pair<T,pair<int,int> > > RLE(vector<T> const& v) {
    if (v.empty()) return {};
    vector<pair<T,pair<int,int> > > ret;
    int ii = -1, n = v.size();
    rep (i,n) if (i == n-1 || v[i] != v[i+1]) {
        ret.emplace_back(v[i],mp(ii+1,i+1));
        ii = i;
    }
    return ret;
}

