void solve() {
    ll n, k, q;
    cin >> n >> k >> q;
    vec<ll> a(n);
    REP(i, n) cin >> a[i];
    vec<ll> b = a;
    sort(all(b));
    ll ans = b[q - 1] - b[0];
    //cout << b[q - 1] << " " << b[0] << en;

    REP(i,n) {
        vvec<ll> aa(1);
        vec<ll> ret;
        int pos = 0;
        REP(j,n){
            if(b[i]<a[j]){
                aa[pos].push_back(a[j]);
            }else{
                if(aa[pos].size()){
                    sort(all(aa[pos]));
                    pos++;
                    aa.push_back(vec<ll>());
                }
            }
        }
        sort(all(aa[pos]));

        auto check = [&](ll x) {
            ll con = 0;
            REP(j,aa.size()){
                if(aa[j].size() < k)
                    continue;
                auto it = upper_bound(all(aa[j]), b[x]);
                con += min((ll)aa[j].size() - k + 1, (ll)(it - aa[j].begin()));
            }
            return con >= q;
        };

        ll l = i;
        ll r = n;
        while(l+1<r){
            ll m = l + r >> 1;
            if(check(m)) r = m;
            else l = m;
        }
        if(r == n) continue;
        chmin(ans, b[r] - b[i + 1]);
        //cout << b[r] << " " << b[i + 1] << en;

    }
    cout << ans << en;
}

