    for(int end=0;end<=n;end++){
        ll imos[n]={};
        for(int j=0;j<end;j++){
            int q=p[j].second-k+1;
            imos[max(0,q)]++;
            imos[p[j].second]--;
        }
        for(int j=1;j<n;j++){
            imos[j] += imos[j-1];
        }
        for(int i=0;i<end;i++){
            imos[p[i].second]+=INF;
        }
        ll ret=0;
        priority_queue<ll,vector<ll>,greater<ll>> pq;
        for(int i=0;i<n;){
            int cnt=0;
            int cnt2=0;
            priority_queue<ll,vector<ll>,greater<ll>> pq2;
            while(i<n && imos[i]<INF){
