	x++;
	for(int i=x;i<maxn;i+=i&-i){
	    s[i]--;
	}
    }
    int getr(int x){
	x++;
	int ans=x;
	for(int i=x;i>0;i-=i&-i){
	    ans+=s[i];
	}
	return ans;
    }
    // [l,r]
    int get(int l,int r){
	return getr(r)-getr(l);
    }

    void reset(){
	fill(s,s+maxn,0);
    }
}fen;

