int main() {
  int n, k, q;
  std::cin >> n >> k >> q;
  std::vector<int> a(n), b(n);
  for (auto &e : a)
    std::cin >> e;
  std::iota(b.begin(), b.end(), 0);
  std::sort(b.begin(), b.end(), [&](int x, int y) { return a[x] > a[y]; });

  std::vector<char> used(n, 0);
  UnionFind T(n);
  IntervalHeap<int> H;
  std::vector<meld_priority_queue<int, std::vector<int>, std::greater<int>>>
      heaps(n);
  int ans = std::numeric_limits<int>::max();
  for (int i = 0; i < n; ++i)
    heaps[i].emplace(a[i]);
  for (const auto i : b) {
    used[i] = 1;
    if (i != 0 && used[i - 1]) {
      int x, y;
      std::tie(x, y) = T.unite(i, i - 1);
      if (heaps[x].size() < heaps[y].size()) {
        std::swap(heaps[x], heaps[y]);
      }
      heaps[x].meld(std::move(heaps[y]));
    }
    if (i != n - 1 && used[i + 1]) {
      int x, y;
      std::tie(x, y) = T.unite(i, i + 1);
      if (heaps[x].size() < heaps[y].size()) {
        std::swap(heaps[x], heaps[y]);
      }
      heaps[x].meld(std::move(heaps[y]));
    }
    auto &t = heaps[T.find(i)];
    while (t.size() >= k) {
      H.emplace(t.top());
      t.pop();
    }
    if (H.size() >= q) {
      while (H.size() > q)
        H.pop_max();
      ans = std::min(ans, H.max() - H.min());
    }
  }

  std::cout << ans << std::endl;

  return 0;
}

