bool solve(ll y,ll x){
    int s=0,t=0,l=0;
    FOR(i,0,n+1){
        if(a[i]<y){
            l+=min(s-k+1,t);
            s=t=0;
        }else{
            if(a[i]<=x){
                t++;
            }
            s++;
        }
    }
    return q<=l;
}

