// 最小値yを固定して最大値を最小化する
// 最小値をa[i]にすると決めると、y未満の数を含む区間は選べない
// そういう区間を消すといくつか列が残る
// ある長さmの列からはmax(0,m-k+1)個まで好きに取れる
// これらの候補がq個以上あればq番目に小さいものがxになる

int n, k, q, a[2020], res = inf;

int main() {
	cin >> n >> k >> q;
	rep(i,n) cin >> a[i];
	rep(i,n) {
		int y = a[i];
		vector<int> mn;
		rep(l,n) if (y<=a[l]) {
			int r = l;
			vector<int> t;
			while (r<n && y<=a[r]) t.push_back(a[r++]);
			sort(all(t));
			rep(j,(int)t.size()-k+1) mn.push_back(t[j]);
			l = r-1;
		}
		sort(all(mn));
		if (mn.size()>=q) chmin(res, mn[q-1]-y);
	}
	cout << res;
}

