int n, k, q, ans = inf, a[N], l[N];

int main() {
	read(n, k, q);
	for (int i = 1; i <= n; i++) {
		read(a[i]);
	}
	for (int j = 1; j <= n; j++) {
		indexed_multiset im;
		int pre = 0;
		for (int i = 1; i <= n; i++) {
			if (a[i] < j) {
				im.clear();
				pre = i;
			} else {
				l[i] = i - pre - im.order_of_key({a[i], i});
				im.insert({a[i], i});
			}
		}
		pre = n + 1;
		im.clear();
		vector<int> v;
		for (int i = n; i >= 1; i--) {
			if (a[i] < j) {
				im.clear();
				pre = i;
			} else {
				int cur = l[i] + pre - i - im.order_of_key({a[i], i}) + 1;
				if (cur >= k) {
					v.push_back(a[i]);
				}
				im.insert({a[i], i});
			}
		}
		sort(all(v));
		if (size(v) >= q) {
			ans = min(ans, v[q - 1] - v[0]);
		}
	}
	write(ans);
}

