int solve(int x) {
    // cerr<<x<<":"<<endl;
    for (int i=1;i<=n;++i) {
        f[i]=!(a[i]>=x);
        // putchar(f[i]+'0');
    }
    // cerr<<endl;
    priority_queue <int> que;
    for (int l=1;l<=n;++l) {
        if (f[l]==1) {
            continue;
        }
        int r=l;
        while (r<=n&&f[r]==0) {
            ++r;
        }
        --r;
        int len=r-l+1;
        int cnt=len-k+1;
        // cerr<<l<<" "<<r<<" "<<cnt<<endl;
        if (cnt<=0) {
            l=r;
            continue;
        }
        vector <int> v;
        for (int j=l;j<=r;++j) {
            v.push_back(a[j]);
        }
        sort(v.begin(),v.end());
        for (int j=0;j<cnt;++j) {
            que.push(-v[j]);
        }
        l=r;
    }
    if (que.size()<q) {
        return -1;
    }
    for (int i=1;i<q;++i) {
        // cerr<<que.top()<<endl;
        que.pop();
    }
    return -que.top();
}

