        int k=solve(a[i]);
        if (k==-1) {
            continue;
        }
        // cerr<<"ans="<<k<<" "<<a[i]<<endl;
        ans=min(k-a[i],ans);
    }
    cout<<ans<<endl;
    return 0;
}

