        for (int i=2;i<=n;i++)
        {
            int temp=a[i]/m;
            for (int j=1;j<m;j++) mp[i][j]=temp;
            mp[i][m]=a[i]-temp*(m-1);
        }
        for (int j=1;j<=m;j++)
        {
            int temp=b[j];
            for (int i=2;i<=n;i++) temp-=mp[i][j];
            mp[1][j]=temp;
        }

        for (int i=1;i<=n;i++)
            for (int j=1;j<=m;j++)
                check(i,j);

