	}
	int ans = INT32_MAX;
	set<int> S;
	S.insert(-1);
	S.insert(N);
	vector<int> V;
	priority_queue<int> P, PS;
	for (int i = 0;i < Q;i++) {
		V = A;P = PS;
		for (auto it = S.begin();it != S.end();it++) {
			auto it2 = it;it2++;
			if (*it2 - 1 != *it) {
				sort(V.begin() + *it + 1, V.begin() + *it2);
			}
			if (*it2 >= N)break;
			V[*it2] = -1;
		}
		int cnt = 0;
		for (int j = N - 1;j >= 0;j--) {
			if (V[j] < 0) {
				cnt = 0;
				continue;
			}
			cnt++;
			if (cnt > K - 1) {
				P.push(-V[j]);
			}
		}
		if (P.empty())break;
		int f = -P.top(), s;
		for (int j = 0;j < Q - 1;j++) {
			if (P.empty())
				break;
			P.pop();
		}
		if (P.empty())break;
		s = -P.top();
		ans = min(ans, s - f);
