bool cmp(const int &o,const int &p){
    return a[o] < a[p];
}
void inc(int o,int val){
    for(int i = o;i <= n; i += i &(-i)){
        tr[i] += val;
    }
}
int sum(int o){
    int ret = 0;
    for(int i = o;i;i -=i &(-i)){
        ret += tr[i];
    }
    return ret;
}
int main(){
    scanf("%d%d%d",&n,&k,&q);
    for(int i = 1;i <= n; ++i){
        scanf("%d",&a[i]);
        h[i]=i;
    }
    sort(h+1, h + n+1,cmp);
    set<int> e;
    e.insert(0);
    e.insert(n + 1);
    int ans = 2e9 + 1000;
    for(int i = 1; i <= n; ++i){
        inc(i,1);
    }
    //cout <<"???" << endl;
    for(int i = 1;i <= n; ++i){
        int cnt = 0;
        int j = i;
        for(;cnt < q && j<=n;++j){
            int r = *e.lower_bound(h[j]);
            int l = *(--e.lower_bound(h[j]));
            //cout << l <<" "<<r<<endl;
            int ret = sum(r - 1) - sum(l);
            if(ret >= k){
                cnt++;
                inc(h[j], -1);
            }
        }
//        cout << endl;
//        cout << i <<"  "<<j <<endl;
        e.insert(h[i]);
        if(cnt == q){
            ans = min(ans,a[h[j - 1]] - a[h[i]]);
        }
        for(int j=i;j<=n;++j){
            if(sum(h[j]) - sum(h[j] - 1) == 0){
                inc(h[j],1);
            }
        }
        inc(h[i],-1);
    }
    cout << ans << endl;
    return 0;
}

