            if (n - prev >= k + s - 1)
                c += s;

            if (c >= q)
            {
                l = mid;
                hi = mid - 1;
            }
            else
            {
                lo = mid + 1;
            }
        }

        if (l != -1)
            ans = min(ans, l - sorted[i]);
    }

    printf("%d\n", ans);

