  for (int i = 0; i < N; i++) {
    multiset<ll> Sum;
    int p = 0;
    for (auto itr = next(Set.begin(),1); p <= i; itr++) {
      p++;
      auto pitr = prev(itr,1);
      multiset<ll> S;
      for (int j = *pitr+1; j < *itr; j++) {
        S.insert(A[j]);
      }

      int len = 0;
      int sz = (int)S.size();
      if (*pitr == -1 && *itr == N) {
        len = max(len,sz);
      } else if (*pitr == -1 || *itr == N) {
        len = max(len,sz - K);
      } else {
        len = max(len,sz - K);
      }
      int cnt = 0;
      for (auto itr = S.begin(); cnt < len; itr++) {
        Sum.insert(*itr);
        cnt++;
      }
    }
    if ((int)Sum.size() >= Q) {
      ans = min(ans,*(next(Sum.begin(),Q-1)) - *(Sum.begin()));
      Set.insert(As[i].S);
    } else {
      break;
    }
  }
  assert(ans != INF);
