using namespace std;

typedef long long int64;

const int M = 2e3 + 11;

int lim, n, q, ans = 2e9;

int A[M], R[M], Ok[M], C[M];

inline void Input()
{
	n = read(), lim = read(), q = read();
	for (int i = 1;i <= n; ++i)
		A[i] = R[i] = read();
	std::sort(R + 1, R + 1 + n);
}

inline void Solve(int Min)
{
	Ok[0] = 0;
	int l = 1, r = 1;
	while (l <= n)
	{
		C[0] = 0;
		while (A[l] < Min && l <= n) ++l;
		r = l;
		while (A[r] >= Min && r <= n) ++r;
		if (r - l < lim) goto end;
		for (int i = l;i < r; ++i)
			C[++C[0]] = A[i];
		std::sort(C + 1, C + 1 + C[0]);
		for (int i = 1;i <= C[0] - lim + 1; ++i)
			Ok[++Ok[0]] = C[i];
		end:; l = r;
	}
	if (Ok[0] < q) return ;
	std::sort(Ok + 1, Ok + 1 + Ok[0]);
	ans = std::min(ans, Ok[q] - Ok[1]);
}

int main(void)
{
	Input();
	for (int i = 1;i <= n - lim + 1; ++i)
		Solve(R[i]);
	printf("%d\n", ans);
	return 0;
}

