            if(origin_arr[en] >= origin_arr[i]) count++;
            if(origin_arr[en] < origin_arr[i]) rev_count++;
        }

        if(real_count > k) {
            memo[origin_arr[i]] = 1;
        } else if(count > k && rev_count < q){
            memo[origin_arr[i]] = q;
        }

    }
