class dsu{
   public :
   int n, max_component, ans, k;
   vector<int> P , R , S;
   dsu(int n, int k){
       this->n = n ;
       this->k = k;
       P.resize(n+1) ;
       R.resize(n+1) ;
       S.resize(n+1) ;
       for(int i=1;i<=n;i++){
           R[i] = 0 ;
           P[i] = i ;
           S[i] = 1 ;
           ans += max(0, S[i] - k + 1);
       }
       max_component = 1 ;
       ans = 0;
   }
   int find(int x){
       if(x != P[x]){
           P[x] = find(P[x]) ;
       }
       return P[x] ;
   }
   bool add_edge(int x,int y){
       int rx , ry ;
       rx = find(x) ;
       ry = find(y) ;
       if(rx != ry){
           if(R[rx] < R[ry]){
               P[rx] = ry ;
               ans -= max(0, S[ry] - k + 1);
               S[ry] += S[rx] ;
               ans += max(0, S[ry] - k + 1);
               max_component = max(max_component,S[ry]) ;
           }else{
               P[ry] = rx ;
               ans -= max(0, S[rx] - k + 1);
               S[rx] += S[ry] ;
               ans += max(0, S[rx] - k + 1);
               max_component = max(max_component,S[rx]) ;
           }
           if(R[rx] == R[ry]){
               R[rx] ++ ;
           }
           return true ;
       }
       return false ;
   }

} ;

