void body() {
    auto N = read<i64>();
    auto K = read<i64>();
    auto Q = read<i64>();
    auto As = read<i64>(N);

    i64 ans = numeric_limits<i64>::max();
    REP (k, N) {
        auto Y = As[k];

        /*
         * 最小値をYにする
         * 1) Yより小さい値を取らずに操作ができる => Y以上の値のみをとって操作できるかはO(N)
         * 2) Yをとる かつ 残りは小さい方から貪欲
         */

        priority_queue<i64> cands;
        // 1) + 2)の前計算
        {
            // 前計算
            auto update = [&](auto b, auto e) {
                Vector<i64> xs(As.begin() + b, As.begin() + e);
                sort(CTR(xs));
                REP (i, max(0L, e - b - K + 1)) {
                    cands.push(-xs[i]);
                }
            };

            i64 num = 0;
            i64 index = 0;
            REP (i, N) {
                if (As[i] < Y && index != -1) {
                    num += max(0L, i - index - K + 1);
                    update(index, i);
                    index = -1;
                } else if (index < 0) {
                    index = i;
                }
            }
            if (index >= 0) {
                num += max(0L, N - index - K + 1);
                update(index, N);
            }

            if (num < Q) {
                // 条件を満たさない
                continue;
            }
        }

        // 2)
        {
            if (cands.size() < Q) {
                // Q個とれない
                continue ;
            }
            if (cands.top() != -Y) {
                // Yをとれない
                continue ;
            }

            auto Y2 = -cands.top();
            REP (i, Q - 1) {
                cands.pop();
            }
            auto X = -cands.top();

            ans = std::min(ans, X - Y2);
        }
    }

    cout << ans << endl;
}

