ll pos(ll x, ll dt) // erase is from [x~x+dt]
{
	int i, lst=0, tp=0, ret=0;
	for(i=1 ; i<=n ; i++)
	{
		if(x<=a[i] && a[i]<=x+dt) chk[i]=1;
		if(a[i]<x) chk[i]=-5000;
		if(a[i]>x+dt) chk[i]=0;
		ps[i]=ps[i-1]+chk[i];
	}	
	for(i=1 ; i<=n ; i++)
	{
		if(ps[i]<ps[lst]) // lst+1~i -> negative exist
		{
			lst=i; tp=0; 
		}
		if(lst+k<=i) // array leng>=k
		{
			if(ps[i]>ps[lst]+tp)
			{
				ret++; tp++;
			}
			else if(ps[i]<ps[lst])
			{
				lst=i; tp=0;
			}
		}
	}
	return ret;
}

ll gv(ll x)
{
	lef=0; rig=1e9; best=1e9;
	while(lef<=rig)
	{
		mid=(lef+rig)/2;
		if(pos(x,mid)>=q)
		{
			best=mid;
			rig=mid-1;
		}
		else
		{
			lef=mid+1;
		}
	}	
	return best;
}

