const int N = (int)2e4 + 100;
int a[N], lmin[N], rmin[N], left_less[N], right_less[N];
int t[4 * N];

int add(int v, int tl, int tr, int u) {
    if (tl == tr) {
        t[v]++;
    } else {
        int tm = (tl + tr) / 2;
        if (u <= tm)
            add(2 * v, tl, tm, u);
        else
            add(2 * v + 1, tm + 1, tr, u);
        t[v]++;
    }
}

int gets(int v, int tl, int tr, int l, int r) {
    if (l > r) {
        return 0;
    }
    if (tl == l && tr == r) {
        return t[v];
    }

    int tm = (tl + tr) / 2;
    return gets(2 * v, tl, tm, l, min(r, tm)) + gets(2 * v + 1, tm + 1, tr, max(l, tm + 1), r);
}


int main() {
    ios_base::sync_with_stdio(0);
