    }

    vector<pair<int, int>> b(n);
    for (int i = 0; i < n; ++i) {
        b[i] = {a[i], i};
    }

    sort(b.begin(), b.end());

    stack<pair<int, int>> st;
    for (int i = 0; i < n; ++i) {
        while (!st.empty() && st.top().first >= a[i]) {
            st.pop();
        }
        if (st.empty()) {
            lmin[i] = -1;
        } else {
            lmin[i] = st.top().second;
        }
        st.push({a[i], i});
    }

    while (!st.empty()) st.pop();

    for (int i = n - 1; i >= 0; --i) {
        while (!st.empty() && st.top().first >= a[i]) {
            st.pop();
        }
        if (st.empty()) {
            rmin[i] = n;
        } else {
            rmin[i] = st.top().second;
        }
        st.push({a[i], i});
    }

//    for (int i = 0; i < n; ++i) {
//        for (int j = 0; j < n; ++j) {
//            cout << i << " " << j << " " << a[i] - a[j] << '\n';
//        }
//    }

    int ans = inf;
    for (int j = 0; j < n; ++j) {
        for (int i = 0; i < 4 * n; ++i) {
            t[i] = 0;
        }
        int mnval = b[j].first;
        int last = -1;
        for (int i = 0; i < n; ++i) {
            if (a[i] < mnval) {
                last = i;
            } else {
                left_less[i] = last;
            }
        }
        last = n;
        for (int i = n - 1; i >= 0; --i) {
            if (a[i] < mnval) {
                last = i;
            } else {
                right_less[i] = last;
            }
        }

        set<int> not_del_left, not_del_right;
        int used = 0;
        int el, left, right;
        int pos = j;
        if (rmin[b[j].second] - lmin[b[j].second] - 1 < k) continue;
        while (used < q && pos < n) {
            el = b[pos].second;

            if (rmin[el] - lmin[el] - 1 - gets(1, 0, n - 1, lmin[el] + 1, rmin[el] - 1) >= k) {
                used++;
                add(1, 0, n - 1, el);
            } else {
                auto it = not_del_left.upper_bound(-el);
                int left_bad = -1;
                if (it != not_del_left.end()) {
                    left_bad = *it;
                }
                left = min(lmin[el], max(left_less[el], left_bad));
                it = not_del_right.upper_bound(el);
                int right_bad = n;
                if (it != not_del_right.end()) {
                    right_bad = *it;
                }
                right = max(rmin[el], min(right_less[el], right_bad));
                if (right - left - 1 - gets(1, 0, n - 1, left + 1, right - 1) >= k) {
                    used++;
                    add(1, 0, n - 1, el);
                } else {
                    not_del_left.insert(-el);
                    not_del_right.insert(el);
                }
            }
            pos++;
        }

        if (used == q) {
            ans = min(ans, b[pos - 1].first - b[j].first);
        }
    }

    cout << ans;


    return 0;
}

