        for(int i = 0;i<q;i++){
            for(int j = 0;j<nn-k+1-i;j++){
                if(tree.rmq(j,j+k,0,0,n)>=vec[l] && tree.rmq(j,j+k,0,0,n)<=vec[l+q-1]) {
                    tem = tree.rmq(j,j+k,0,0,n);
                    fl = false;
                }
            }
            if(fl){
                cout << ans << endl;
                return 0;
            }
            fl = true;
            st.insert(tem);
            for(int j = 0;j<nn-i;j++){
                if(tree.data[j+n-1]==tem){
                    tem2 = j;
                    break;
                }
            }
            for(int j = tem2;j<=nn-i-2;j++){
                tree.change(j,tree.data[j+n]);
            }
            tree.change(nn-i-1,tree.INF);
            tem = tree.INF;
        }
        auto itr = st.end();
        itr--;
        ans = min(ans,*itr-*st.begin());
        st = {};
    }
    cout << ans << endl;
}

