/* SegTree<X>(n,fx,ex): モノイド(集合X, 二項演算fx, 単位元ex)についてサイズnで構築
    set(int i, X x), build(): i番目の要素をxにセット。まとめてセグ木を構築する。O(n)
    update(i,x): i 番目の要素を x に更新。O(log(n))
    query(a,b): [a,b) 全てにfxを作用させた値を取得。O(log(n))
*/

//一点更新RQM用テンプレート
// auto fx = [](int x1, int x2) -> int { return min(x1, x2); };
// int ex = numeric_limits<int>::max();
// SegTree<int> rmq(n, fx, ex);

template <typename X>
struct SegTree
{
  using FX = function<X(X, X)>; // X•X -> X となる関数の型
  int n;
  FX fx;
  const X ex;
  vector<X> dat;
  SegTree(int n_, FX fx_, X ex_) : n(), fx(fx_), ex(ex_), dat(n_ * 4, ex_)
  {
    int x = 1;
    while (n_ > x)
    {
      x *= 2;
    }
    n = x;
  }

  void set(int i, X x) { dat[i + n - 1] = x; }
  void build()
  {
    for (int k = n - 2; k >= 0; k--)
      dat[k] = fx(dat[2 * k + 1], dat[2 * k + 2]);
  }

  void update(int i, X x)
  {
    i += n - 1;
    dat[i] = x;
    while (i > 0)
    {
      i = (i - 1) / 2; // parent
      dat[i] = fx(dat[i * 2 + 1], dat[i * 2 + 2]);
    }
  }

  X query(int a, int b) { return query_sub(a, b, 0, 0, n); }
  X query_sub(int a, int b, int k, int l, int r)
  {
    if (r <= a || b <= l)
    {
      return ex;
    }
    else if (a <= l && r <= b)
    {
      return dat[k];
    }
    else
    {
      X vl = query_sub(a, b, k * 2 + 1, l, (l + r) / 2);
      X vr = query_sub(a, b, k * 2 + 2, (l + r) / 2, r);
      return fx(vl, vr);
    }
  }
};
void solve(void)
{
  int n, k, q;
  cin >> n >> k >> q;
  auto fx = [](int x1, int x2) -> int { return min(x1, x2); };
  auto gx = [](int x1, int x2) -> int { return max(x1, x2); };
  int ex = numeric_limits<int>::max();
  SegTree<int> st1(n, fx, INF);  //miq
  SegTree<int> st2(n, gx, -INF); //maq
  vector<int> vec(n, 0);
  for (int i = 0; i < n; i++)
  {
    cin >> vec[i];
  }
  sort(ALL(vec));
  for (int i = 0; i < n; i++)
  {
    st1.set(i, vec[i]);
    st2.set(i, vec[i]);
  }
  st1.build();
  st2.build();
  int res = 0;
  for (int i = 0; i < n - k; i++)
  {
    chmax(res, st2.query(i, q) - st1.query(i, q));
    // DEBUG(res, st2.query(i, q), st1.query(i, q), "\n");
  }
  cout << res << endl;

  return;
}

