int get_max(const V<int>& A, int K, int MIN, int Q) {
   priority_queue<int, vector<int>, greater<int>> tmp, que;
   FOR(i, 0, SZ(A)+1) {
      if (i < SZ(A) && A[i] >= MIN) {
         tmp.push(A[i]);
         continue;
      }
      while (SZ(tmp) >= K) {
         que.push(tmp.top()); tmp.pop();
      }
      tmp = priority_queue<int, vector<int>, greater<int>>();
   }
   if (SZ(que) < Q) {
      return -1;
   }
   REP(i, Q-1) que.pop();
   return que.top();
}

signed main()
{
   int N, K, Q; cin >> N >> K >> Q;
   V<int> A(N);
   REP(i, N) {
      cin >> A[i];
   }

   V<int> B(N);
   COPY(A, B);
   UNIQUE(B);

   int ans = INF;
   FOR(i, 0, N) {
      int MIN = B[i];
      int MAX = get_max(A, K, MIN, Q);
      if (MAX == -1) continue;
      ans = min(ans, MAX - MIN);
   }
   cout << ans << endl;

   return 0;
}

