int solve(const vector<int> &a, int k, int v, int q) {
  const int n = a.size();

  vector<int> t;

  for(int i = 0; i < n; ){
    if(a[i] < v){ i++; continue; }

    vector<int> tt;
    for(; i < n && a[i] >= v; i++) tt.push_back(a[i]);

    if(k <= (int)tt.size()){
      sort(tt.begin(), tt.end());
      REP(j,k-1) tt.pop_back();
      for(int j : tt) t.push_back(j);
    }
  }

  sort(t.begin(), t.end());

  if(q >(int)t.size()) return inf;
  return t[q - 1] - t[0];
}

