void solve(long long N, long long K, long long Q, std::vector<long long> A){
  auto AA = A;
  sort(AA.begin(),AA.end());
  set<ll> a(A.begin(),A.end());
  ll ans=AA[Q-1]-AA[0];
  for(auto x:a){
    ll l=0,r=0;
    vector<vector<ll>::iterator> tmp;
    For(j,A.size()){
      if(A[j]<=x){
        tmp.push_back(A.begin()+j);
      }
    }
    ll sum=0;
    For(j,tmp.size()-1){
      sum+=max(0LL,tmp[j+1]-tmp[j]-1-Q+1);
    }
    if(sum>=Q){
      ll l=upper_bound(A.begin(),A.end(),x)-A.begin();
      ans=min(ans,AA[l+Q-1]-AA[l]);
    }
  }
  cout<<ans<<endl;
}

