const int MAXN = 2e3+3;

int n, k, q;

multiset<int> nonu[MAXN], ans;
int rep[MAXN];

int find(int v){
	if(rep[v] == v) return v;
	return rep[v] = find(rep[v]);
}
void unite(int v, int u){
	v = find(v); u = find(u);
	if(nonu[v].size() > nonu[u].size())
		swap(v, u);
	rep[v] = u;
	for(int x : nonu[v])
		nonu[u].insert(x);
}
void fix(int v){
	while((int)nonu[v].size() >= k){
		ans.insert(*(nonu[v].begin()));
		nonu[v].erase(nonu[v].begin());
	}
}
int main(){
	scan(n, k, q);
	for(int i=0; i<n; i++) rep[i] = i;
	vector<ii> v; v.resize(n);
	for(int i=0; i<n; i++){
		int a; scan(a);
		v[i] = {a, i};
	}
	sort(all(v), greater<ii>());
	int anss = 2e9;
	for(int j=0; j<n; j++){
		int a = v[j].fst, i = v[j].snd;
		nonu[i].insert(a);
		if(i>0 && nonu[i-1].size())
			unite(i, i-1);
		if(i<n-1 && nonu[i+1].size())
			unite(i, i+1);
		fix(find(i));
		while((int) ans.size() > q){
			auto it = ans.end();
			it--;
			ans.erase(it);
		}
		if((int) ans.size() == q){
			auto it = ans.end();
			it--;
			mnze(anss, *it - *ans.begin());
		}
	}
	printf("%d\n", anss);
}

