int solve(int N, int cur, int K, int Q) {
    vector<int> ans, tmp;
    for (int l = 1; l <= N + 1; l++) {
        if (l == N + 1 || a[l] < cur) {
           sort(tmp.begin(), tmp.end());
           for (int i = 0; i < (int)tmp.size() - K + 1; i++)
               ans.push_back(tmp[i]);
           tmp.clear();
        } else tmp.push_back(a[l]);
    }
    sort(ans.begin(), ans.end());
    if ((int)ans.size() < Q) return (int)2e9;
    return ans[Q - 1] - cur;
}

