pair<int, int> lower_and_upper(set<int> &s, int t) {
    auto p1 = s.lower_bound(t);
    auto p2 = p1; p2++;
    assert (p1 != s.begin());
    assert (p2 != s.end());
    return {*(--p1), *p2};
}

int query_count(int len) {
    return max(len - K + 1, 0);
}

int main() {
