const int N = 2003, inf = 2e9;
int n, k, q, a[N], b[N];

priority_queue <int, vector <int>, greater <int> > cur, pq;

int get(int x) {
	while (!pq.empty()) pq.pop();
	int len = 0;
	for (int i = 1; i <= n; i++) {
		if (a[i] < x) continue;
		len++;
		cur.push(a[i]);
		if (i == n || a[i + 1] < x) {
			int can = max(0, len - k + 1);
			while (can--) {
				pq.push(cur.top());
				cur.pop();
			}
			len = 0;
			while (!cur.empty()) cur.pop();
		}
	}
	if ((int)pq.size() < q) return inf;
	int res = 0;
	for (int i = 0; i < q; i++)
		res = max(res, pq.top()), pq.pop();
	return res;
}

