        // oversにはmax_posもはいるので、そのmax_posを含むようにK個選んで、それをスライドさせていく
        if((int)overs.size() >= K){
            deque<int> dq;
            bool ok = false;
            for(int j = 0; j < (int)overs.size(); j++){
                if((int)dq.size() < K){
                    dq.push_back(overs[j]);
                    if(overs[j] == i){
                        ok = true;
                    }
                }
                if((int)dq.size() == K){
                    if(ok){

                        // 処理
                        int pos1 = dq[0];
                        int pos2 = dq[K-1];
                        int cnt = pos2 - pos1 + 1 - K;
                        if(cnt < Q+1){
                            ans = min(ans,A[i] - min_a);
                        }
                        else if(cnt == Q+1){
                            ans = min(ans, A[i] - rmq.query(pos1, pos2 + 1));
                        }

                        if(dq[0] == i) break;
                        dq.pop_front();
                    }
                    else{
                        dq.pop_front();
                    }
                }
            }
        }
        else{
            continue;
        }
    }

    cout << ans << endl;

}

