bool possible(int large, int small){
    int streak = 0;
    int inRange = 0;
    int taken = 0;
    for(int i = 0; i < N; i++){
        if(a[i] < small){
            inRange = 0;
            streak = 0;
            continue;
        }
        streak++;
        if(a[i] >= small && a[i] <= large) inRange++;
        if(streak >= K && inRange > 0){
            inRange--;
            taken++;
        }
    }
    return taken >= Q;
}

