int lmao(int p) {
    used[n + 1] = 1;
    int cnt = 0, ret = 0;
    while(!pq.empty()) pq.pop();
    while(!pq1.empty()) pq1.pop();
    for(int i = p - 1; i >= 1; i--) {
        if(used[i]) break;
        cnt++;
    }
    for(int i = p; i <= n; i++) {
        if(used[i]) break;
        cnt++;
    }
    if(cnt < k) return LLONG_MAX;
    for(int i = 1; i <= n + 1; i++) {
        if(used[i]) {
            while(pq.size() >= k) {
                pq1.push(pq.top());
                pq.pop();
            }
            while(!pq.empty()) pq.pop();
        }
        else
            pq.push(a[i]);
    }
    cnt = pq1.size();
    if(cnt < q) return LLONG_MAX;
    cnt = q;
    while(cnt--) {
        ret = max(pq1.top(), ret);
        pq1.pop();
    }
    return ret;
}

