class RMQ{
public:
  typedef long long ll;
  ll INF = 1LL<<55;
  Int n,n_;
  vector<P> dat;
  Int toMax;

  //初期化
  RMQ(){n=-1;}
  RMQ(Int n_,Int toMax = 0):n_(n_),toMax(toMax){
    n=1;
    while(n<n_)n*=2;
    dat.resize(2*n-1,P(INF,INF));
  }

  //k番目の値をaに変更
  void update(Int k,P a){
    //if(toMax) a *= -1;
    k+=n-1;
    dat[k]=a;
    while(k>0){
      k=(k-1)/2;
      dat[k]=min(dat[k*2+1],dat[k*2+2]);
    }
  }

  //[a,b)の最小値を求める query(a,b,0,0,n)
  P find(Int a,Int b,Int k,Int l,Int r){
    if(r<=a||b<=l)return P(INF,INF);
    if(a<=l&&r<=b)return dat[k];
    P vl = find(a,b,k*2+1,l,(l+r)/2);
    P vr = find(a,b,k*2+2,(l+r)/2,r);
    return min(vl,vr);
  }

  P find(Int a,Int b){
    assert(a <= b), assert(a <= n_ && b <= n_), assert(a >= 0 && a >= 0);
    return /*(toMax? -1:1) * */ find(a,b,0,0,n);
  }
};



Int sim(Int n,Int K,Int Q, vector<Int> A,Int limit){
  priority_queue<Int,vector<Int>, greater<Int> > num;
  vector<Int> B;
  for(Int i=0;i<n;i++) {
    if(A[i] < limit){
      while((Int)num.size() >= K) B.push_back(num.top()), num.pop();
      while(!num.empty()) num.pop();
    }
    else num.push(A[i]);
  }
  while((Int)num.size() >= K) B.push_back(num.top()), num.pop();
  sort(B.begin(), B.end());
  if((Int)B.size() < Q) return INF;
  return B[Q-1] - B[0];
}

signed main(){
  cin.tie(0);
  ios_base::sync_with_stdio(0);
  cout << fixed << setprecision(12);

  Int n, K, Q;
