int main() {
	using uint = std::size_t;

	uint n, k, q;
	std::cin >> n >> k >> q;
	std::vector<uint> a(n), b(n);
	for (auto &&e : a)
		std::cin >> e;

	std::iota(b.begin(), b.end(), 0);
	std::sort(b.begin(), b.end(),
		[&a](uint x, uint y) {return a[x] > a[y];});

	IntervalHeap<uint> H;
	std::vector<PairingHeap<uint>> P(n);
	UnionFind U(n);
	for (uint i = 0;i < n;++i)
		P[i].push(a[i]);

	std::vector<char> use(n, 0);
	uint ans = std::numeric_limits<uint>::max();
	for (const auto i : b) {
		use[i] = 1;
		std::array<uint, 2> s = { i - 1,i + 1 };
		for (const auto d : s) {
			if (d < n && use[d]) {
				uint x = U.find(d);
				uint y = U.find(i);
				U.unite(x, y);
				if (U.find(x) != x)
					std::swap(x, y);
				P[x].meld(P[y]);
				while (P[x].size() >= k) {
					H.emplace(P[x].top());
					P[x].pop();
				}
			}
		}
		if (H.size() >= q) {
			while (H.size() > q)
				H.pop_max();
			ans = std::min(ans, H.max() - H.min());
		}
	}

	std::cout << ans << std::endl;

	return 0;
}

