ll solve(ll i)
{
	ll x=a[i];
	ll l=0,r=x+1;
	ll mid=(l+r)>>1;
	if(!check(0,x))return INF;
	if(check(x,x))return 0;
	while(r-l>1)
	{
		if(check(mid,x))
			l=mid;
		else
			r=mid;
		mid=(l+r)>>1;
	}
	if(mid<x&&check(mid+1,x))mid++;
	if(!check(mid,x))mid--;
	return (x-mid);
}
