            }
            sort(foo.begin(), foo.end(), greater<int>());
            int sz2 = foo.size();
            for(int x = k - 1; x < sz2; ++x){
                val.push_back(foo[x]);
            }
        }
        if(val.size() < q)  continue;
        sort(val.begin(), val.end());
        chmin(ans, val[q - 1] - val[0]);
    }
    cout << ans << endl;
}

