bool ers(ll pos) {
	ll l1=sorted[pos], r1=-1;
	while(l1-r1>1) {
		ll m1=(l1+r1)/2;
		if(rmq.query(m1,pos)>=a[sorted[pos]]) {
			l1=m1;
		} else {
			r1=m1;
		}
	}
	ll l2=sorted[pos],r2=n;
	while(r2-l2>1) {
		ll m2=(l2+r2)/2;
		if(rmq.query(pos,m2)>=a[sorted[pos]]) l2=m2;
		else r2=m2;
	}
	if((l2-l1+1)-rsq.query(l1,l2+1)>=k) {
		rsq.update(sorted[pos],1);
		rmq.update(sorted[pos],INF*INF);
		return true;
	} else return false;
}

ll calc(ll mini_idx) {
	ll pos=mini_idx;
	ll ret=0;
	while(pos<n&&ret<q) {
		if(ers(pos)) {
			ret++;
		}
		pos++;
	}
	REP(i,n) rsq.update(i,-rsq.query(i,i+1));
	REP(i,n) rmq.update(i,a[i]);
	if(ret==q) return a[sorted[pos-1]];
	else return -1;
}

