        i64 hi = sorted.back();
        int l = -1;

        while (lo <= hi)
        {
            i64 mid = (lo + hi) / 2;

            int c = 0;
            int s = 0;
            int prev = 0;

            for (int j = 0; j < n; j++)
            {
                if (arr[j] < sorted[i])
                {
                    int ss = min(s, j - prev - k + 1);
                    c += max(ss, 0);

                    prev = j + 1;
                    s = 0;
                }
                else if (arr[j] <= mid)
                    s++;
            }

            int ss = min(s, n - prev - k + 1);
            c += max(ss, 0);

            if (c >= q)
            {
                l = mid;
                hi = mid - 1;
            }
            else
            {
                lo = mid + 1;
            }
        }

        if (l != -1)
            ans = min(ans, l - sorted[i]);
    }

    printf("%d\n", ans);

    return 0;
}

