template<class T>
using minheap = priority_queue<T, vector<T>, greater<T>>;

class dsu
{
    vector<int> par, siz;
    vector<minheap<int>> val;
    priority_queue<int> avail;

    int k, q;

public:
    dsu (const vector<int> &arr, int k, int q) : par (arr.size (), -1),
        siz (arr.size (), 1), val (arr.size ()), k (k), q (q)
    {
        for (int i = 0; i < arr.size (); i++)
            val[i].push (arr[i]);
    }

    int get_class (int t)
    {
        return par[t] == -1 ? t : par[t] = get_class (par[t]);
    }

    void mark (int a)
    {
        a = get_class (a);

        while (val[a].size () >= k)
        {
            avail.push (val[a].top ());
            val[a].pop ();

            if (avail.size () > q)
                avail.pop ();
        }
    }

    bool unite (int a, int b)
    {
        a = get_class (a);
        b = get_class (b);

        if (a == b)
            return false;

        uniform_int_distribution<int> uid (0, siz[a] + siz[b] - 1);

        if (val[b].size () > val[a].size ())
            val[a].swap (val[b]);

        while (!val[b].empty ())
        {
            val[a].push (val[b].top ());
            val[b].pop ();
        }

        while (val[a].size () >= k)
        {
            avail.push (val[a].top ());
            val[a].pop ();

            if (avail.size () > q)
                avail.pop ();
        }

        if (uid (mt) < siz[a])
        {
            par[b] = a;
            siz[a] += siz[b];
        }
        else
        {
            par[a] = b;
            siz[b] += siz[a];
            val[a].swap (val[b]);
        }

        return true;
    }

    int get () const
    {
        return avail.size () == q ? avail.top () : numeric_limits<int>::max ();
    }
};

void solve (istream &cin = std::cin, ostream &cout = std::cout)
{
    int n, k, q;

    cin >> n >> k >> q;

    vector<int> arr (n);

    for (auto &it : arr)
        cin >> it;

    dsu slv (arr, k, q);

    vector<pair<int, int>> ord (n);

    for (int i = 0; i < ord.size (); i++)
        ord[i] = make_pair(arr[i], i);

    sort (ord.begin (), ord.end (), greater<pair<int, int>> ());

