priority_queue<int, vector<int>> challengers;



bool check(int up, int down, const vector<int> &values)
{
	fill(kick, kick + m, 0);
	vector<int> maxes(m), curs(m);

	for (int i = 0; i < n; ++i)
	{
		positions[values[i]][maxes[values[i]]] = i;
		maxes[values[i]]++;
	}


	int l = 0, r = 0, cnt = 0, num = 0;

	while (l < n)
	{
		while (r < n && num < k)
		{
			challengers.push(-values[r]);
			num++;
			r++;

			while (challengers.size() && kick[-challengers.top()])
			{
				kick[-challengers.top()]--;
				challengers.pop();
			}
		}

		if (num != k)
			break;

		int vl = -challengers.top();
		if (vl <= up && vl >= down)
		{
			cnt++;
			num--;
			challengers.pop();
			curs[vl]++;
		}
		else
		{
			if (maxes[values[l]] != curs[values[l]] && positions[values[l]][curs[values[l]]] == l)
			{
				curs[values[l]]++;
				kick[values[l]]++;
				num--;
			}

			l++;
		}
	}

	while (challengers.size())
		challengers.pop();

	return cnt >= q;
}


