    int ans = 2000000000;
    for(int i = 0; i < N; i++){
        int X = A[i];
        vector<vector<int> > seqs;

        // Xより小さいものはフィルタする
        for(int j = 0; j < N; j++){
            if(X > A[j]) continue;
            vector<int> seq;
            while(j < N && A[j] >= X){
                seq.push_back(A[j]);
                j++;
            }
            sort(seq.begin(), seq.end());
            if((int)seq.size() >= K)
                seqs.push_back(seq);
        }

        vector<int> indices(seqs.size(), 0);
        priority_queue<pii, vector<pii>, greater<pii> > pq;
        for(int j = 0; j < (int)seqs.size(); j++){
            int index = indices[j];
            int v = seqs[j][index];
            pq.push(pii(v, j));
        }
        int Y = -1;
        bool ok = true;
        for(int cnt = 0; cnt < Q; cnt++){
            if(pq.size() == 0){
                ok = false;
                break;
            }
            else{
                Y = pq.top().first;
                int seq_num = pq.top().second; 
                pq.pop();
                vector<int> &seq = seqs[seq_num];
                if((int)seq.size() - (indices[seq_num] + 1) >= K){
                    indices[seq_num]++;
                    pq.push(pii(seq[indices[seq_num]], seq_num));
                }
            }
        }

        if(ok){
            ans = min(ans, Y - X);
        }
