ll dat[1 << K];

void update(int A) {
	dat[A] = min(dat[A * 2], dat[A * 2 + 1]);
	if (A != 1) update(A / 2);
}

void add(int A, ll B) {
	int C = A + KM;
	dat[C] = B;
	update(C / 2);
}

ll check(int L, int R, int A, int l, int r) {
	if (L <= l && r <= R) return dat[A];
	if (r <= L || R <= l) return 1ll << 60;
	return min(check(L, R, A * 2, l, (l + r) / 2), check(L, R, A * 2 + 1, (l + r) / 2, r));
}

ll query(int L, int R) {
	return check(L, R, 1, 0, KM);
}

