int solve(int Y, const vector<int>& v, int K, int Q){
  vector<vector<int>> w;
  vector<int> tmp;
  rep(i,v.size()){
    if(v[i] >= Y){
      tmp.push_back(v[i]);
    }else{
      if(tmp.size() > 0) w.push_back(tmp);
      tmp.clear();
    }
  }
  if(tmp.size() > 0) w.push_back(tmp);

  vector<int> ww;
  rep(i,w.size()){
    if(w[i].size() >= K){
      sort(ALLOF(w[i]));
      rep(j,w[i].size()-K+1){
        ww.push_back(w[i][j]);
      }
    }
  }

  if(ww.size() < Q) return 1000000005;

  sort(ALLOF(ww));

  return ww[Q-1] - ww[0];
}

