using namespace std;

int N;
const int MAX_N = 5000;

int tree[MAX_N];

void bit_add(int pos, int val) {
    do  {
        tree[pos] += val;
        pos += (pos)&(-pos);
    } while (pos <= N);
}

int bit_read(int pos)  {
    int sum = 0;

    while (pos > 0) {
        sum += tree[pos]; pos = pos&(pos-1);
    }

    return sum;
}

int main()
{

    int n, k, q;
    cin >> n >> k >> q;

    N = n;

    vector<int> A(n + 1);

    for (int i=1; i<=n; i++) {
        cin >> A[i];
    }

    int good_left[n+1];
    int good_right[n+1];

    long long best = 1000000000000000000LL;

    for (int z=1; z<=n; z++) {
        long long y = A[z];
        memset(tree, 0, sizeof(tree));

        memset(good_left, 0, sizeof(good_left));
        memset(good_right, 0, sizeof(good_right));

        good_left[1] = 0;
        good_right[n] = 0;

        for (int i=2; i<=n; i++) {
            good_left[i] = (A[i-1] >= y ? good_left[i-1] + 1 : 0);
        }

        for (int i=n-1; i>=1; i--) {
            good_right[i] = (A[i+1] >= y ? good_right[i+1] + 1 : 0);
        }

        set<pair<int, int> > s;
        for (int i=1; i<=n; i++) {
            if (A[i] >= y) {
                s.insert({ A[i], i });
            }
        }

        int actual_ops = 0;
        long long x = y;

        for (int op=0; op<q && !s.empty(); op++) {

            auto current = s.begin();
            auto current_val = *current;

            s.erase(current);

            int val = current_val.first, index = current_val.second;

            int ok_left = good_left[index], ok_right = good_right[index];
            ok_left -= (bit_read(index) - bit_read(index - ok_left - 1));
            ok_right -= (bit_read(index+ok_right) - bit_read(index-1));

            if (ok_left + ok_right + 1 >= k) {
                //we can take this one
                x = val;
                bit_add(index, 1);

                actual_ops++;
                continue;
            }


            op--; //retry it
        }

        if (actual_ops == q)
            best = min(best, (x-y));
    }

    cout << best << endl;
    return 0;
}

