template< typename Monoid >
struct SegmentTree{
  using F = function< Monoid(Monoid, Monoid) >;

  int sz;
  vector< Monoid > seg;

  const F f;
  const Monoid M1;

  //SegmentTree(n,f,M1):サイズnの初期化，fは2つの苦汗の要素をマージする二項演算，M1はモノイドの単位元
  SegmentTree(int n, const F f, const Monoid &M1) : f(f), M1(M1){
    sz = 1;
    while(sz < n) sz<<=1;
    seg.assign(2*sz,M1);
  }

  //set(k,x):k番目の要素にxを代入
  void set(int k, const Monoid &x){
    seg[k+sz] = x;

  }

  //build():segTreeの構築
  void build(){
    for(int k = sz-1; k>0; --k){
      seg[k] = f(seg[2*k+0], seg[2*k+1]);
    }
  }

  //update(k,x):k番目の要素をxに変更
  void update(int k, const Monoid &x){
    k += sz;
    seg[k] = x;
    while(k>>=1) seg[k] = f(seg[2*k+0],seg[2*k+1]);
  }

  //区間[a,b)のMonoidを計算
  Monoid query(int a, int b){
    Monoid L = M1, R = M1;
    for(a += sz, b+=sz; a < b; a>>=1, b>>=1){
      if(a&1) L = f(L,seg[a++]);
      if(b&1) R = f(seg[--b],R);
    }
    return f(L,R);
  }

  //operator[k]:k番目の要素を返す
  Monoid operator[](const int &k) const{
    return seg[k+sz];
  }
};

int main(void){
  SPEEDUP
  cout << setprecision(15);
  int N,K,Q;cin >> N >> K >> Q;
  vector<int> v(N);
  //範囲の最小値を返すsegTree
  SegmentTree<int> minseg(N, [](int a, int b){ return min(a,b); }, INT_MAX);
  rep(i,N){
    cin >> v[i];
    minseg.set(i,v[i]);
  }
  minseg.build();

  //w[i]:v[i]を消すのに必要な最大の数値 -1で作れない．
  vector<int> w(N);
  rep(i,N){
    w[i] = v[i];
    int s = i+1,e=i+1;
    int count = 0;
    while(count<K && s>0) if(v[--s] >= v[i])++count;

    while(count<K && e<N) if(v[e++] >= v[i])++count;

    if(count<K){
      w[i]=-1;
      continue;
    }

    int m = -1;
    while(s<=i&&e<=N){
      m = max(m,minseg.query(s,e));
      while(v[++s]<v[i]);
      while(v[++e]<v[i])if(e==N)break;
    }
    w[i] = min(w[i],m);
  }

  int ans = MAX_I;
  rep(i,N){
    if(w[i]==-1)continue;
    vector<int> del;
    rep(j,N){
      if(v[j]<v[i] || w[j]<v[i])continue;
      del.push_back(v[j]);
    }
    if(del.size()<Q)continue;
    sort(all(del));
    ans = min(ans,del[Q-1]-v[i]);
  }
  cout << ans << endl;
  return 0;
}

