				int width=tmp.size();
				if(width>=k){
					partial_sort(tmp.begin(),tmp.begin()+width-k+1,tmp.end());
					b.insert(b.end(),tmp.begin(),tmp.begin()+width-k+1);
				}
				tmp.clear();
			}
		}

		if(b.size()>=q){
			nth_element(b.begin(),b.begin()+q-1,b.end());
			ans=min(ans,b[q-1]-a[i]);
		}
	}
	printf("%d\n",ans);

	return 0;
}

