		++C[i];
}
int sum(int x)
{
	int ret = 0;
	for(int i = x; i; i -= lowbit(i))
		ret += C[i];
	return ret;
}
bool solve(int now)
{
	memset(C, 0, sizeof(C));
	pii x = b[now];
	int val = x.first, pos = x.second;
	set<int> S;
	S.insert(0); S.insert(n + 1);
