void solve() {
  REP(i, N) B[i] = make_pair(A[i], i);
  sort(B, B + N);
  ss[N] = 0;
  int ans = INF;
  int i = 0;
  while (true) {
    // printf("i: %d\n", i);
    vs.clear();
    ITR(ss, it) {
      int l = it->second;
      int r = it->first;
      int w = r - l;
      // printf(" l: %d, r: %d, w: %d", l, r, w);
      if (w >= K) {
        copy(A + l, A + r, ws);
        sort(ws, ws + w);
        vs.insert(vs.end(), ws, ws + w - K + 1);
        // printf(" : add %d items", w - K + 1);
      }
      // puts("");
    }
    // printf(" vs.size(): %d\n", vs.size());
    if (vs.size() < Q) break;
    sort(vs.begin(), vs.end());
    // printf(" vs[0]: %d, vs[%d]: %d\n", vs[0], Q - 1, vs[Q - 1]);
    ans = min(ans, vs[Q - 1] - vs[0]);
