int check(int minimum_val)
{
    vector<int> block, pool;
    for (int i = 1; i <= n + 1; i++)
        if (ai[i] >= minimum_val)
            block.push_back(ai[i]);
        else
        {
            if (block.size() >= k)
            {
                sort(block.begin(), block.end());
                int len = block.size();
                for (int i = 0; i <= len - k; i++)
                    pool.push_back(block[i]);
            }
            block.clear();
        }
    sort(pool.begin(), pool.end());
    if (pool.size() < q)
        return 1e9;
    return pool[q - 1] - minimum_val;
}

