				sort(part.begin(), part.end());
				for(int j=0;j<part.size()-K+1;j++){
					cur.push_back(part[j]);
				}
				part.clear();
			};
			for(int i=0;i<N;i++){
				if(A[i] <= wall){
					pushPart();
				} else {
					part.push_back(A[i]);
				}
			}
			if(!part.empty()){
				pushPart();
			}
			if(cur.size() < Q) break;
			sort(cur.begin(), cur.end());
			res = min(res, (long long)cur[Q-1] - cur[0]);
		}
