			continue;
		}
		if (b[i] == 1) {
			q1++;
		} else {
			q2++;
		}
		if (q1 + q2 >= k) {
			if (q1 > 0) {
				res++;
				q1--;
//				err("i = %d res = %d q1 = %d q2 = %d\n", i, res, q1, q2);
			}
		}
	}


	return res;
}

