const ll N = 2000;
ll n, k, q, a[N], dp[N][N];

ll rec(ll l, ll r) {
	if(r < l) return INF;
	if(r-l+1 < q+k-1) return INF;
	ll& memo = dp[l][r];
	if(memo != -1) return memo;
	vector<ll> v, midxs;
	ll minidx = l;
	midxs.push_back(l);
	FOR(i, l, r) {
		v.push_back(a[i]);
		if(a[i] < a[minidx]) {
			minidx = i;
			midxs.clear();
			midxs.push_back(i);
		} else if(a[i] == a[minidx]) {
			midxs.push_back(i);
		}
	}
	sort(v.begin(), v.end());
	ll res = v[q-1]-v[0];
	for(int m : midxs) {
		res = min(res, rec(l, m-1));
		res = min(res, rec(m+1, r));
	}
	return memo = res;
}

