    for(int i = 0;i < n;i++){
        if(no[i] == 1){
            while(!que.empty()) que.pop();
        }else{
            que.push(a[i]);
            if(que.size() == k){
                ans.push_back(que.top());
                que.pop();
            }
        }
    }

    if(ans.size() >= q){
        sort(ans.begin(), ans.end());
        return ans[q-1] - ans[0];
    }else{
        return INT_MAX;
    }
}

