// $ g++ -std=c++11 -Wall -O2 -D_GLIBCXX_DEBUG x.cpp && ./a.out
const int MAX_N=2001;
int N,K,Q;
LL A[MAX_N];
const LL Inf=1e10;
LL f(int p) {
  LL piv=A[p];
  vector<vector<LL>> X;
  vector<LL> cur;
  REP(i,N) {
    if(A[i]<piv) {
      if(SZ(cur)>=K) X.push_back(cur);
      cur.clear();
    } else {
      cur.push_back(A[i]);
    }
  }
  if(SZ(cur)>=K) X.push_back(cur);
//  dump2(p,piv);
  vector<LL> Y;
  FORR(x,X) {
    sort(x.begin(),x.end());
//    dumpAR(x);
    REP(i,SZ(x)-K+1) Y.push_back(x[i]);
  }
  sort(Y.begin(),Y.end());
//  dumpAR(Y);
  return SZ(Y)<Q?Inf:Y[Q-1]-piv;
}

LL solve() {
  LL res=Inf;
  REP(i,N) SMIN(res,f(i));
  return res;
}

int main() {
