    while(ok-ng>1){
      int bf=-1,cnt=0,res=0;
      mid=(ok+ng)>>1;
      rep(i,N){
        if(a[i]<v[j]){
          res+=max(min(cnt,i-bf-K),0);
          bf=i;
        }else if(a[i]<=v[mid]){
          ++cnt;
        }
      }
      res+=max(min(cnt,i-bf-K),0);
      if(res>=Q){
        ok=mid;
      }else{
        ng=mid;
      }
    }
    if(ok==(int)v.size())break;
    chmin(ans,v[ok]-v[j]);
  }
  print(ans);
}

