void solve(long long N, long long K, long long Q, vector<long long> A){
	LL ans=INT_MAX;
	A.push_back(-1);
	for(int i=0; i<N; ++i) {
		int Min=A[i];
		int l=0;
		int c=0;
		for(int j=0; j<=N; ++j) {
			if (A[j]<Min) {
				int r=j-1;
				if (r-l+1>=K) {
					for(int p=l; p<=r; ++p) {
						t[p]=A[p];
					}
					int num=r-l+1-K+1;
					std::nth_element(t+l,t+(l+num-1),t+r+1);
					for(int p=l; p<=l+num-1; ++p) {
						t2[++c]=t[p];
					}
				} 
				l=j+1;
			}
		}
		if (c<Q) continue;
		std::nth_element(t2+1,t2+Q,t2+1+c);
		ans=min(ans,t2[Q]-Min);
	}
	cout<<ans<<endl;
}

