bool can(int interval_left, int interval_right)
{
    int tot=0;
    vector<bool> available(n, true);
    int ptr1=k-1;
    int ptr2=0;
    priority_queue< pair<int, int>, vector< pair<int, int> >, greater< pair<int, int> > > pq;
    for(int i=0; i<k; i++) pq.push(make_pair(v[i], i));
    while(true)
    {
        if(ptr1>=n) break;
        pair<int, int> p = pq.top();
        int val = p.first;
        int idx = p.second;
        if(!(ptr2 <= idx && idx <= ptr1))
        {
            pq.pop();
            continue;
        }
        if(interval_left <= val && val <= interval_right)
        {
            available[idx]=false;
            pq.pop();
            tot++;
            ptr1++;
            if(ptr1>=n) break;
            pq.push(make_pair(v[ptr1], ptr1));
        }
        else
        {
            ptr2++;
            while(ptr2<n && !available[ptr2]) ptr2++;
            ptr1++;
            if(ptr1>=n) break;
            pq.push(make_pair(v[ptr1], ptr1));
        }
    }
    return tot>=q;
}

