  ll ans = LINF;
  FOR(i,0,n+1-q){
    //break;
    ll mx = -LINF, mn = LINF; int q_ = q;

    SegmentTree< int > sgt(n+5,[](int a, int b)->int{return a+b;},0);
    V<int> ad(n);
    FOR(j,0,n) ad[j] = a[j];

    int cur = i+1;
    while(cur<=place.size() && q_>0){
      for(auto x: place[cur]){
        int R=x, L=x;
        while(R+1<n && ad[R+1]>=ad[x]) ++R;
