        if(R-L+1-sgt.query(L,R+1) >=k){
          --q_;
          mx = max(mx,mp[cur]);
          mn = min(mn,mp[cur]);
          sgt.update(x,1);
          ad[x] = IINF;
        }
        if(q_==0) break;
      }
      ++cur;
    }


    if(q_==0 && (mx-mn)<LINF ) ans = min(ans, mx-mn);
    //couts(mx); coutn(mn);
  }
