bool judge(int mid)
{
    //printf("mid : %d\n", mid);

    int mem[2010] = {0};
    for(int i = 0; i < N; i++)
    {
        memset(mem, 0, sizeof(mem));
        //printf(" bottom : %d\n",A[i]);
        for(int j = 0; j < N; j++)
        {
            if(A[j] < A[i])mem[j] = 2;
            else if(A[j] <= A[i] + mid)mem[j] = 1;
            else mem[j] = 0;
        }

        /*
        printf("  mem : ");
        for(int j = 0; j < N; j++)printf("%d ",mem[j]);printf("\n");
        */

        int q = 0;
        int cnt = 0, len = 0;
        for(int j = 0; j <= N; j++)
        {
            if(j == N || mem[j] == 2)
            {
                q += max(min(len - K + 1, cnt), 0);
                cnt = len = 0;
            }
            else
            {
                if(mem[j] == 1)cnt++;
                len++;
            }
        }

        //printf("  q : %d\n",q);

        if(q >= Q)return true;
    }

    return false;
}

