    while(!pq1.empty()) pq1.pop();
    for(int i = p - 1; i >= 1; i--) {
        if(used[i]) break;
        cnt++;
    }
    for(int i = p; i <= n; i++) {
        if(used[i]) break;
        cnt++;
    }
    if(cnt < k) return LLONG_MAX;
    for(int i = 1; i <= n + 1; i++) {
