int calc(int x) {
	int l = 0, r = 0;
	segs.clear();
	for (int i = 1; i <= n; ++i) if (a[i] >= x) {
		if (i == 1 || a[i - 1] < x) l = i, r = 0;
		if (i == n || a[i + 1] < x) r = i;
		if (r) segs.push_back({l, r});
	}
	priority_queue<int, vector<int>, greater<int>> pq;
