          t++
        }
        // xs[s]..xs[t] is a valid range.
        val segmentLength = t - s + 1
        if (segmentLength >= k) {
          val segmentValues = mutableListOf<Int>()
          for (i in s..t) {
            segmentValues.add(xs[i])
          }
          segmentValues.sort()
          for (i in 0 until segmentLength - k + 1) {
            mutCandidates.add(segmentValues[i])
          }
        }
        s = t + 1
      }
    }

    if (mutCandidates.size < q) continue

    val candidates = mutCandidates.toIntArray()
    candidates.sort()
    val u = candidates[q - 1]
    ans = Math.min(u - l, ans)
  }
  println(ans)
}

