const int sze = 1 << 11, INF = 1e9 + 10;


int n, k, q;


bool check(int up, int down, const vector<int> &values)
{
	multiset<int> challengers;
	vector<int> positions[sze];

	int ind = 0;
	for (int v : values)
		positions[v].push_back(ind++);

	for (int i = 0; i < sze; ++i)
		sort(positions[i].rbegin(), positions[i].rend());


	//Если на отрезке несколько одинаковых, какой ты удаляешь???
	int l = 0, r = 0, cnt = 0;

	while (l < n)
	{
		while (r < n && challengers.size() < k)
		{
			challengers.insert(values[r]);
			r++;
		}

		if (challengers.size() != k)
			break;

		int vl = *challengers.begin();
		if (vl <= up && vl >= down)
		{
			cnt++;
			auto it = challengers.lower_bound(vl);
			challengers.erase(it);//по итератору
			positions[vl].pop_back();
		}
		else
		{
			if (positions[values[l]].size() && positions[values[l]][positions[values[l]].size() - 1] == l)
			{
				positions[values[l]].pop_back();
				auto it = challengers.lower_bound(values[l]);
				challengers.erase(it);//По итератору
			}

			l++;
		}
	}

	return cnt >= q;
}


signed main()
{
	ios::sync_with_stdio(false);
	cin.tie(NULL);
	cout.tie(NULL);

	cin >> n >> k >> q;

	vector<int> values(n), challengers;

	for (int i = 0; i < n; ++i)
		cin >> values[i];

	challengers = values;
	sort(challengers.begin(), challengers.end());


	int M = unique(challengers.begin(), challengers.end()) - challengers.begin();
	challengers.resize(M);

	map<int, int> trans;
	for (int i = 0; i < M; ++i)
		trans[challengers[i]] = i;

	for (int i = 0; i < n; ++i)
		values[i] = trans[values[i]];

	int ans = INF;
	int m = challengers.size();
	for (int i = 0; i < m; ++i)
	{
		int l = i - 1, r = m;

		while (r - l > 1)
		{
			int mid = (l + r) >> 1;
			int up = mid, down = i;

			if (check(up, down, values))
				r = mid;
			else
				l = mid;
		}

		if (r != m)
			ans = min(ans, challengers[r] - challengers[i]);
	}

	cout << ans;
	return 0;
}

