template<typename T>
struct SegmentTree {
	typedef function<T(T,T)> F;
    typedef function<T(T,T)> G;
    int n;
    F f;
    G g;
    T e;

    vector<T> val;

    SegmentTree(vector<T> a, F f_, G g_, T e):
        f(f_), g(g_), e(e){
            int sz = a.size();
            n = 1;

            while (n < sz) n <<= 1;
            val.resize(2 * n - 1, e);
            for (int i = 0; i < sz; i++) val[i + n - 1] = a[i];
            for (int i = n - 2; i >= 0; i--) val[i] = f(val[i * 2 + 1], val[i * 2 + 2]);
        }

        SegmentTree() {}

        void update(int pos, T v) {
            // 0-indexed
            int k = pos + n - 1;
            val[k] = g(val[k], v);
            while (k > 0) {
                k = (k - 1) / 2;
                val[k] = f(val[k * 2 + 1], val[k * 2 + 2]);
            }
        }

        T get(int pos) {
            // 0-indexed
            int k = pos + n - 1;
            return val[k];
        }

        T query(int a, int b, int k = 0, int l = 0, int r = -1) {
            // 0-indexed
            // [a,b)に対してquery
            if (r < 0) r = n;
            if (r <= a || b <= l) return e;
            if (a <= l && r <= b) return val[k];
            T lv = query(a, b, k * 2 + 1, l, (l + r) / 2);
            T rv = query(a, b, k * 2 + 2, (l + r) / 2, r);
            return f(lv, rv);
        }
};

template<class T>
void remove_duplication(vector<T> &v){
    sort(v.begin(), v.end());
	v.erase(unique(v.begin(), v.end()), v.end());
}

void Main(){
    int N,K,Q; cin >> N >> K >> Q;
    VI A(N); REP(i,N) cin >> A[i];
    VI B(A); remove_duplication(B);

    SegmentTree<int> st(A,[](int a,int b){return min(a,b);},[](int a,int b){return b;},INF);

    int ans = INF;
    int k = B.size();
    REP(i,k){
        int ptr = 0;
        VI q;
        while(ptr<N-K+1){
            while(ptr<N-K+1 && A[ptr] < B[i]) ptr++;
            if(ptr == N-K+1) break;

            int l = ptr+K-2, r = N+1;
            while(r-l>1){
                int x = (l+r)/2;
                if(st.query(ptr,x) < B[i]) r = x;
                else l = x;
            }
            if(l-ptr < K){
                ptr = l;
                continue;
            }

            int len = l-ptr;
            VI cand;
            FOR(j,ptr,l) cand.push_back(A[j]);
            SORT(cand);
            REP(j,len-K+1) q.push_back(cand[j]);

            ptr = l;
        }

        if(q.size() < Q) break;
        SORT(q);
        chmin(ans, q[Q-1] - q[0]);
    }

    cout << ans << en;
    return;
}

