struct BinaryIndexTree {
	int a[MAXN], n;
	void init(int x) {
		n = x;
		memset(a, 0, sizeof(a));
	}
	void modify(int pos, int d) {
		for (int i = pos; i <= n; i += i & -i)
			a[i] += d;
	}
	int query(int l, int r) {
		int ans = 0;
		for (int i = r; i >= 1; i -= i & -i)
			ans += a[i];
		for (int i = l - 1; i >= 1; i -= i & -i)
			ans -= a[i];
		return ans;
	}
} BIT; 
struct info {int val, home; } a[MAXN];
bool cmp(info a, info b) {
	return a.val < b.val;
}
int main() {
	int n, k, q;
	read(n), read(k), read(q);
	for (int i = 1; i <= n; i++) {
		int x; read(x);
		a[i] = (info) {x, i};
	}
	sort(a + 1, a + n + 1, cmp);
	int ans = INF;
	for (int i = 1; i <= n; i++) {
		BIT.init(n);
		static set <int> st;
		st.clear(); st.insert(0), st.insert(n + 1);
		for (int j = 1; j <= i - 1; j++)
			st.insert(a[j].home);
		BIT.init(n + 1);
		for (int j = i; j <= n; j++)
			BIT.modify(a[j].home, 1);
		int rit = INF, req = q;
		for (int j = i; j <= n; j++) {
			set <int> :: iterator tmp = st.lower_bound(a[j].home);
			int r = *tmp; tmp--; int l = *tmp;
			if (BIT.query(l, r) >= k) {
				if (--req == 0) {
					rit = a[j].val;
					break;
				}
			} else st.insert(a[j].home);
			BIT.modify(a[j].home, -1);
		}
		if (req != 0) break;
		chkmin(ans, rit - a[i].val);
	}
	writeln(ans);
	return 0;
}

