	for(int i=1;i<=n;i++) 
	{
		int size=0;
		for(int j=1;j<=n;j++) 
		{
			if(a[j]<a[i]) continue;
			int now=j;
			while(now<=n&&a[now+1]>=a[i]) now++;
			int num=now-j+1-k+1;
			if(num<=0) continue;
			int cnt=0;
			for(int l=j;l<=now;l++) b[++cnt]=a[l];
			sort(b+1,b+cnt+1);
			for(int l=1;l<=num;l++) c[++size]=b[l];
			j=now;
		}
		if(size<q) continue;
		sort(c+1,c+size+1);
		mini=min(mini,c[q]-a[i]);
	}
	printf("%d\n",mini);
	return 0;
}

