const int N = (1 << 11), K = 11;
int n, k, q, a[N], val[N], used[N], m;
vector <int> pos[N];
int par[N];
multiset <int> st[N];

struct Fen {
	int f[N], sz = 0;
	Fen() {
		memset(& f, 0, sizeof(f));
	}
	void upd(int x, int y) {
		sz += y;
		for (; x < (1 << K); x |= (x + 1))
			f[x] += y;
	}
	int kth(int k) {
		if (sz < k)
			return -1;
		int cur = 0, s = 0;
		for (int i = (1 << (K - 1)); i > 0; i >>= 1)
			if (s + f[cur + i - 1] < k)
				s += f[cur + i - 1], cur += i;
		return cur;
	}
};
Fen F;

void upd(int x) {
	while ((int)st[x].size() > k - 1) {
		F.upd(*st[x].begin(), 1);
		st[x].erase(st[x].begin());
	}
}

void make_set(int x) {
	par[x] = x;
	st[x].insert(a[x]);
	upd(x);
}

int find_set(int x) {
	if (x == par[x]) return x;
	return par[x] = find_set(par[x]);
}

void union_set(int x, int y) {
	x = find_set(x), y = find_set(y);
	if (x == y) return;
	if ((int)st[x].size() < (int)st[y].size())
		swap(x, y);
	par[y] = x;
	for (int i : st[y])
		st[x].insert(i);
	upd(x);
}

void add(int x) {
	used[x] = 1;
	if (used[x - 1])
		union_set(x - 1, x);
	if (used[x + 1])
		union_set(x, x + 1);
}

