int main() {

    ios::sync_with_stdio(false); // stdioを使うときはコメントアウトすること
    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    ll n, k, q; cin >> n >> k >> q;
    vector<ll> a = qin(n);

    // とれるだけ区間の最小値が大きくなるようにとる
    ll ans = INF;
    REP(i, n) {

        vector<int> okay(n+1, true); okay.back() = false;
        REP(j, n) okay[j] = a[i] <= a[j];

        vector<vector<ll>> heaps;
        vector<ll> h;
        REP(j, n+1) {
            if (okay[j]) {
                h.push_back(a[j]);
            } else if (h.size()) {
                if (h.size() >= k) {
                    heaps.emplace_back(h);
                }
                vector<ll>().swap(h);
            }
        }
        // DUMP(heaps);
        vector<ll> available;
        for (auto &hp : heaps) {
            sort(ALL_OF(hp));
            REP(j, hp.size()-k+1) available.push_back(hp[j]);
        }
        sort(ALL_OF(available));
        // DUMP(available);
        if (available.size() >= q) {
            chmin(ans, available[q-1] - available[0]);
        }
    }
    say(ans);

}

