const int INF = 1 << 30;
const ll INFL = 1LL << 60;


class Solver {
  public:
    bool solve() {
        int N, K, Q; cin >> N >> K >> Q;
        vector<int> A(N); cin >> A;
        vector<int> B = A;
        sort(all(B));
        B.erase(unique(B.begin(), B.end()), B.end());
        ll ans = INFL;

        for(int mini : B) {
            int cnt = 0;
            vector<int> vv;
            rep(l, N) {
                int r = l;
                while(r < N and A[r] >= mini) r++;
                if(r - l >= K) {
                    cnt += r - l - K + 1;
                    vector<int> v;
                    repeat(j, l, r) v.push_back(A[j]);
                    sort(all(v));
                    rep(j, r - l -  K + 1) vv.push_back(v[j]);
                }
                //
                while(r < N and A[r] < mini) r++;
                l = r;
            }
            //cerr << i << " ~ :" <<  cnt << " : " << mx << " - " << mini << endl;
            if(cnt >= Q) {
                sort(all(vv));
                int mx = vv[Q - 1];
                set_min<ll>(ans, mx - mini);
            }
        }
        cout << ans << endl;
        return 0;
    }
};

