int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin>>N>>K>>Q;
    A.resize(N);
    B.resize(N);
    rep(i,0,N){
        cin>>A[i];
        B[i]=A[i];
    }
    sor(B);
    uniq(B);
    map<ll,ll> m;
    map<ll,ll> revm;
    rep(i,0,sz(B)){
        m[B[i]]=i;
        revm[i]=B[i];
    }
