        A[i]=m[A[i]];
    }
    ll ans=1e12;
    int n=sz(B);
    rep(i,0,n){
        int ng=-1, ok=n-i;
        while(ok-ng>1){
            int mid=(ok+ng)/2;
            int l=0, r=0;
            int cnt=0;
            int res=0;
            while(l<N){
                cnt=0;
                while(r<N&&A[r]<i){
                    r++;
                }
                l=r;
                while(r<N&&A[r]>=i){
                    if(A[r]<=i+mid) cnt++;
                    r++;
                }
                res+=min(r-l-K+1,cnt);
                l=r;
            }
            if(res>=Q) ok=mid;
            else ng=mid;
        }
        if(ok==n-i) continue;
        else ans=min(ans,revm[i+ok]-revm[i]);
    }
