struct segtree {
private:
	ll n;
	vector<ll>node;
	//最下段はノードがN個、それより上にはN-1個
	//親→子:親(k)x2+(1or2)
	//子→親:{子{2k+(1or2)}-1}/2
public:
	segtree(vector<ll>v, ll fi) {//宣言例 segtree seg(vec,INF)

								 // 最下段のノード数は元配列のサイズ以上になる最小の 2 冪 -> これを n とおく
								 // セグメント木全体で必要なノード数は 2n-1 個である
		ll sz = v.size();
		n = 1;while (n < sz)n *= 2;
		node.resize(2 * n - 1, fi);
		// 最下段に値を入れたあとに、下の段から順番に値を入れる
		// 値を入れるには、自分の子の 2 値を参照すれば良い
		for (int i = 0;i < sz;i++)node[i + n - 1] = v[i];
		for (int i = n - 2;i >= 0;i--)node[i] = min(node[2 * i + 1], node[2 * i + 2]);
	}

	void update(ll x, ll val) {
		// 最下段のノードにアクセスする
		x += (n - 1);
		// 最下段のノードを更新したら、あとは親に上って更新していく
		node[x] = val;
		while (x > 0) {
			x = (x - 1) / 2;
			node[x] = min(node[2 * x + 1], node[2 * x + 2]);
		}
	}

	// 要求区間 [a, b) 中の要素の最小値を答える
	// k := 自分がいるノードのインデックス
	// 対象区間は [l, r) にあたる

	ll getmin(int a, int b, int k = 0, int l = 0, int r = -1) {
		// 最初に呼び出されたときの対象区間は [0, n)
		if (r < 0) r = n;

		// 要求区間と対象区間が交わらない -> 適当に返す
		if (r <= a || b <= l) return INF2;

		// 要求区間が対象区間を完全に被覆 -> 対象区間を答えの計算に使う
		if (a <= l && r <= b) return node[k];

		// 要求区間が対象区間の一部を被覆 -> 子について探索を行う
		// 左側の子を vl ・ 右側の子を vr としている
		// 新しい対象区間は、現在の対象区間を半分に割ったもの
		ll vl = getmin(a, b, 2 * k + 1, l, (l + r) / 2);
		ll vr = getmin(a, b, 2 * k + 2, (l + r) / 2, r);
		return min(vl, vr);
	}
};

ll div(segtree seg, ll mini) {
	int l = 0, r = 1;
	vector<ll>v;
	for (;l < N&&r <= N;) {
		priority_queue<ll, vector<ll>, greater<ll>>pq;
		for (;seg.getmin(l, r) >= mini && r <= N;r++) { 
			l++;
			pq.push(a[l]);
		}
		r++;
		l = r - 1;
		while(pq.size() >= k) {
			v.eb(pq.top());
			pq.pop();
		}
	}
	sort(ALL(v));
	if (v.size() < q)return INF2;
	return v[q - 1];
}

int main() {
	cin >> N >> k >> q;
	a.resize(N);
	for (int i = 0;i < N;i++) {
		cin >> a[i];
	}
	segtree seg(a, 0);
	for (int i = 0;i < N;i++) {
		ans = min(ans, div(seg, a[i]) - a[i]);
	}
	cout << ans << endl;
	return 0;
}

