const int INF = 1 << 30;
const ll INFL = 1LL << 60;


class Solver {
  public:
    bool solve() {
        ll N, K, Q; cin >> N >> K >> Q;
        vector<ll> A(N); cin >> A;
        vector<ll> B = A;
        sort(all(B));
        B.erase(unique(B.begin(), B.end()), B.end());
        ll ans = INFL;

        for(ll mini : B) {
            ll cnt = 0;
            vector<ll> vv;
            rep(l, N) {
                while(l < N and A[l] < mini) l++;
                ll r = l;
                while(r < N and A[r] >= mini) r++;
                if(r - l + 1 >= K) {
                    cnt += r - l - K + 1;
                    vector<ll> v;
                    repeat(j, l, r) v.push_back(A[j]);
                    sort(all(v));
                    rep(j, r - l -  K + 1) vv.push_back(v[j]);
                }
                l = r;
            }
            //cerr << i << " ~ :" <<  cnt << " : " << mx << " - " << mini << endl;
            if(cnt >= Q) {
                sort(all(vv));
                ll mx = vv[Q - 1];
                assert(mx >= mini);
                if(vv[0] == mini) set_min<ll>(ans, mx - mini);
            }
        }
        assert(ans != INFL);
        cout << ans << endl;
        return 0;
    }
};

