int check(int mn, int mx) {
    int c1 = 0, c2 = 0;
    int ret = 0;
    for(int i = 1; i <= n; i++) {
        if(a[i] < mn) {
            ret += min(c1, max(0, c1 + c2 - k + 1));
            c1 = 0; c2 = 0;
        } else if(a[i] >= mn && a[i] <= mx) c1++;
        else c2++;
    }
    if(a[n] >= mn) ret += min(c1, max(0, c1 + c2 - k + 1));
    // printf("%d %d %d\n", mn, mx, ret);
    return ret;
}

