ll rec(ll l, ll r) {
	if(r < l) return INF;
	if(r-l+1 < q+k-1) return INF;
	vector<ll> v;
	ll minidx = l;
	FOR(i, l, r) {
		v.push_back(a[i]);
		if(a[i] < a[minidx]) minidx = i;
	}
	sort(v.begin(), v.end());
	ll res = v[q-1]-v[0];
	res = min(res, rec(l, minidx-1));
	res = min(res, rec(minidx+1, r));
	return res;
}

