class fenwick {
  private:
    Z n;
    vector<Z> data;
  public:
    fenwick(Z n): n(n), data(n + 1) {}

    Z sum(Z x) {
      x++;
      Z total = 0;
      for (Z i = x; i > 0; i -= i & -i)
        total += data.at(i);
      return total;
    }

    void add(Z x, Z v) {
      x++;
      for (Z i = x; i <= n; i += i & -i)
        data.at(i) += v;
    }
};

int main() {
