          li = -1;
        else {
          right--;
          li = *right;
        }
        dump(li);
        dump(ri);
        Z sz = fwt.sum(ri - 1) - fwt.sum(li);
        dump(fwt.sum(ri - 1));
        dump(fwt.sum(li));
        dump(sz);
        if (sz >= K) {
