#define rrep(i, n) for (auto i = n; i >= 0; i--)
#define all(c) begin(c), end(c)

class fenwick {
  private:
    Z n;
    vector<Z> data;
  public:
    fenwick(Z n): n(n), data(n + 1) {}

    Z sum(Z x) {
      x++;
      Z total = 0;
      for (Z i = x; i > 0; i -= i & -i)
        total += data.at(i);
      return total;
    }

    void add(Z x, Z v) {
      x++;
      for (Z i = x; i <= n; i += i & -i)
        data.at(i) += v;
    }
};

int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  using pz = pair<Z, Z>;
  Z n, K, q;
  cin >> n >> K >> q;
  vector<Z> as(n);
  for (auto& a : as) cin >> a;
  vector<pz> sorted(n);
  rep (i, n) {
    sorted[i].first = as[i];
    sorted[i].second = i;
  }
  sort(all(sorted));
  set<Z> removed;
  Z minimum = INF;
  rep (i, n) {
    dump(i);
    Z first = -1, last = -1;
    Z k = i;
    fenwick fwt(n);
    rep (j, n)
      if (!removed.count(j))
        fwt.add(j, 1);
    mesg("fenwick init complete");
    rep (j, q) {
      for (; k < n; k++) {
        auto right = removed.lower_bound(sorted[k].second);
        Z li, ri;
        ri = right == end(removed) ? n : *right;
        if (right == begin(removed))
          li = -1;
        else {
          right--;
          li = *right;
        }
        dump(li);
        dump(ri);
        Z sz = fwt.sum(ri - 1) - fwt.sum(li);
        dump(fwt.sum(ri - 1));
        dump(fwt.sum(li));
        dump(sz);
        if (sz >= K) {
          mesg("update");
          fwt.add(sorted[k].second, -1);
          if (j == 0)
            first = sorted[k].first;
          last = sorted[k].first;
          k++;
          break;
        }
      }
    }
    if (k == n) break;
    dump(first);
    dump(last);
    minimum = min(minimum, last - first);
    dump(minimum);
    removed.insert(sorted[i].second);
  }
  cout << minimum << endl;
  return 0;
}

