    int s=0,num=0,j;
    for(int i=1;i<=n+1;i++)
    {
        if(a[i]>=a[x])
        {
            if(s==0) s=i;//标记大于等于该数的位置
        }
         if(s)
            {
                if(i-s>=k)
                {
                    for(j=s;j<i;j++)
                    {
                        t[j-s+1]=a[j];
                    }
                    sort(t+1,t+i-s+1);
                    for(j=1;j+k-1<=i-s;j++)
                    {
                        num++;
                        al[num]=t[j];
                    }
                }
                s=0;
            }
    }
    if(num<q) return inf;
    sort(al+1,al+num+1);
    return al[q]-a[x];
}



