int n, k, q;

vector<pii> get_ps(int i) {
	vector<pii> rst;
	for (int j = 0; j <= n; j++) {
		if (j < n && a[j] >= a[i]) {
			if (rst.empty() || rst.back().second != j - 1) {
				rst.push_back({ j, j });
			}

			rst.back().second = j;
		}
		else {
			if (!rst.empty() && rst.back().second - rst.back().first + 1 < k) {
				rst.pop_back();
			}
		}
	}
	return rst;
}

int tmp[MAXN];
int solve(int i) {
	auto ps = get_ps(i);
	bool hasi = false;
	int cnt = 0;

	for (auto &p : ps) {
		if (p.first <= i && i <= p.second) {
			hasi = true;
		}
		int num = p.second - p.first + 1;
		partial_sort_copy(a + p.first, a + p.second + 1, b + cnt, b + cnt + num - k + 1);
		cnt += num;
	}

	if (!hasi) return INF;
	if (cnt < q) return INF;
	nth_element(b, b + q, b + cnt);
	return b[q-1] - a[i];
}

