lng power(lng b, lng e) {lng sol=1; while(e>0) {if(e&1) {sol=sol*b;} e>>=1; b*= b;} return sol;}

void quickSort(int l, int r, int* a, int* b) {
	if(l >= r) return;
	int piv = a[r];
	int i = l - 1;
	for(int j=l; j<r; j++) {
		if(a[j] <= piv) {
			i++;
			swap(a[i], a[j]);
			swap(b[i], b[j]);
		}
	}
	swap(a[i+1], a[r]);
	swap(b[i+1], b[r]);
	quickSort(l, i, a, b);
	quickSort(i+2, r, a, b);
}

int main() {
