		}
		split.pb(N);
		//↑列分割完成
		vector<int> seqMin;
		int spSz = SZ(split);
		int left = 0;
		REP(i, spSz) {
			vector<int> part;
			FOR(j, left, split[i]-1) {
				part.pb(a[j]);
			}
			sort(ALL(part));
			REP(j, split[i]-left-K+1) {
				seqMin.pb(part[j]);
			}
			left = split[i]+1;
		}
		if(SZ(seqMin) >= Q) {
			ans = min(ans, seqMin[Q-1] - seqMin[0]);
		}
	}

	cout << ans << endl;
}

