int minimize(vector<int> const &A, int Y){
    vector<int> a(A);
    a.push_back(-1);//番兵
    vector<int> cnd;

    int stt = 0;
    for (int i = 0; i < N+1; i++){
        if (a[i] < Y){
            int end = i;
            vector<int> sub(a.begin()+stt, a.begin()+end);
            sort(sub.begin(), sub.end());
            for (int j = 0; j < (int)sub.size()-K+1; j++){
                cnd.push_back(sub[j]);
            }
            stt = i + 1;
        }
    }
    assert (stt == N+1);

    sort(cnd.begin(), cnd.end());
    if (cnd.size() < Q) {
        return -1;
    } else {
        return cnd[Q-1];
    }
}

