namespace adaptor = boost::adaptors;

typedef std::pair<std::int64_t, std::int64_t> int64pair;

int run(lib::optional_dual_array<std::pair<int, int>>const& rngminmax, int min, int max, int now, int rest, int N, int K)
{
	if (N - now < K)
	{
		return std::numeric_limits<int>::max();
	}
	DEFINE_STRUCT2(dmin, dmax, *rngminmax[now][rest]);
	int tmin = std::max(dmax, max) - std::min(dmin, min);
	if (N - now == rest)
	{
		return tmin;
	}
	for (int i : boost::irange(K, rest))
	{
		DEFINE_STRUCT2(nmin, nmax, *rngminmax[now][i]);
		tmin = std::min(tmin,
			run(rngminmax, std::min(nmin, min), std::max(nmax, max), now + i + 1, rest - i, N, K));
	}
	return std::min(tmin, run(rngminmax, min, max, now + 1, rest, N, K));
}

void Main()
{
	int N, K, Q;
	std::cin >> N >> K >> Q;
	std::vector<int> vec(N);
	for (auto& v : vec)
	{
		std::cin >> v;
	}
	lib::optional_dual_array<std::pair<int, int>> rngminmax(boost::extents[N - K + 1][N + 1]);
	for (int i : boost::irange(0, N - K + 1))
	{
		std::set<int> data;
		for (int k : boost::irange(0, K - 1))
		{
			data.emplace(vec[i + k]);
		}
		rngminmax[i][K - 1] = std::make_pair(lib::max_value<int>, lib::min_value<int>);
		for (int k : boost::irange(i + K - 1, N))
		{
			data.emplace(vec[k]);
			auto v = *data.begin();
			data.erase(v);
			DEFINE_STRUCT2(bmin, bmax, *rngminmax[i][k - i]);
			rngminmax[i][k - i + 1] = std::make_pair(std::min(bmin, v), std::max(bmax, v));
		}
	}
	out::write_line(run(rngminmax, lib::max_value<int>, lib::min_value<int>, 0, K + Q - 1, N, K));
}

int main()
{
	std::cin.tie(nullptr);
	std::cin.sync_with_stdio(false);
	std::cout << std::fixed;
	Main();
}

