	vector<int> temp(N);//候補
	vector<int> temp2(N);//候補候補
	for (int i = 0; i < N; ++i) {
		int X = A[i];
		int num = 0;//選択候補確定
		int cnt = 0;
		/*
		数列分解して、除ける最小値候補を選択
		*/
		for (int j = 0; j < N; ++j) {
			if (A[j] >= X) {
				temp2[cnt] = A[j];
				++cnt;
			}
			else if(A[j] < X ){
				int ter = cnt - K +1;
				if(ter>0){
					sort(temp2.begin(),temp2.begin()+cnt);
					for (int k = 0; k < ter; ++k) {
						temp[num] = temp2[k];
						++num;
					}
				}
				cnt = 0;
			}
		}
		if (cnt) {
			int ter = cnt - K + 1;
			if (ter > 0) {
