        s.insert(a[i]);
    }
    int ans = 1e9 + 1;
    for (int minimum : s) {
        if (cal(minimum) > 1e9) continue;
        ans = min(ans, cal(minimum) - minimum);
    }
    cout << ans << endl;
    return 0;
}

