struct unionfind{
  private:
  int maxN;
  vector<int> par,treesize,maxid,minid;
  public:unionfind(int N) :maxN(N),par(N),treesize(N,1){
    int i;
    for(i=0;i<maxN;++i)par[i]=i;
    maxid=minid=par;
  }
  int root(int x){
    if(par[x]==x)return x;
    int r=root(par[x]);
    if(par[x]!=r){
      treesize[r]+=treesize[x];
      treesize[x]=0;
      par[x]=r;
    }
    return r;
  }
  bool unite(int x,int y){
    int px=root(x);
    int py=root(y);
    if(px!=py){
      par[px]=py;
      treesize[py]+=treesize[px];
      treesize[px]=0;
      maxid[px]=maxid[py]=max(maxid[px],maxid[py]);
      minid[px]=minid[py]=min(minid[px],minid[py]);
    }
    return px!=py;
  }
  void used(int x){
    --treesize[root(x)];
  }
  bool parcheck(int x,int y){
    return root(x)==root(y);
  }
  pair<int,int> I(int x){
    return pair<int,int>(minid[root(x)],maxid[root(x)]+1);
  }
  int size(int x){
    return treesize[root(x)];
  }
  void clear(){
    int i;
    for(i=0;i<maxN;++i){
      par[i]=i;
      treesize[i]=1;
    }
  }
};
template<typename T> struct segtree{
private:
  int N=1;
  T E;
  using func=function<T(T,T)>;
  func f,g;
  vector<T> tree;
public:
  segtree(vector<T>& v,T e,func Merge,func Act):E(e),f(Merge),g(Act){
    int i,K=v.size();
    while(N<K)N<<=1;
    tree.resize(N<<1);
    For(i,N,N+K)tree[i]=v[i-N];
    For(i,N+K,N<<1)tree[i]=E;
    brep1(i,N)tree[i]=f(tree[i<<1],tree[(i<<1)|1]);
  }
  segtree(vector<T>& v,T e,func Merge){*this=segtree(v,e,Merge,Merge);};
  segtree(int N,T e,func F){
    vector<T> res(N,e);
    *this=segtree(res,e,F);
  }
  void action(int i,T a){
    if((i<0)|(i>=N))return;
    i+=N;
    tree[i]=g(tree[i],a);
    while(i>1){
      i>>=1;
      tree[i]=f(tree[i<<1],tree[(i<<1)|1]);
    }
  }
  void input(int i,T a){
    if((i<0)|(i>=N))return;
    tree[i+=N]=a;
    while(i>1){
      i>>=1;
      tree[i]=f(tree[i<<1],tree[(i<<1)|1]);
    }
  }
  T queli(int a,int b){
    if((a>=b)|(a<0)|(b<=0)|(a>=N)|(b>N))return E;
    T l(E),r(E);
    for(a+=N,b+=N;a<b;a>>=1,b>>=1){
      if(a&1)l=f(l,tree[a++]);
      if(b&1)r=f(tree[--b],r);
    }
    return f(l,r);
  }
};

