    for(auto v:ms){
      if(usable==0){
        break;
      }
      use.push_back(v);
      usable--;
    }
    ms.clear();
    if((ll)use.size()<q){
      break;
    }
    sort(use.begin(),use.end());
    ans = min(ans,use[q-1]-use[0]);
  }
  cout << ans << endl;
}

