void solve()
{
	READ(int, N, K, Q);
	auto A = read<int>(N);
	if (Q == 1)
	{
		WRITE(0);
		return;
	}

	int ans = INF(int);
	auto C = A; sort(allof(C));
	REP(i, N - Q + 1)
	{
		int k = C[i];
		vector<int> mc;
		mc.reserve(N);

		int ok = 0;
		int s = 0;
		REP(j, N)
		{
			if (A[j] < k)
			{
				continue;
			}
			int s = j;
			while (j < N && A[j++] >= k) continue;
			int cnt = j - s;
			if (cnt >= K)
			{
				FOR(i, s, j)
				{
					mc.push_back(A[i]);
				}
			}
			ok += cnt - K + 1;
		}

		if (ok >= Q)
		{
			sort(allof(mc));
			ans = min(ans, mc[Q - 1] - mc[0]);
		}
	}
	WRITE(ans);
}

