int n, k, q;
vector<long long> a;

bool f(long long x, long long y) {
  vector<long long> c;
  int d = 0;
  for (int i = 0; i < n; i++) {
    if (a[i] >= x)
      c.push_back(a[i]);
    else {
      if (c.size() < k) {
        c.clear();
        continue;
      }
      sort(c.begin(), c.end());
      auto it = upper_bound(c.begin(), c.end(), x + y);
      it--;
      d += min((int)(it - c.begin() + 1), (int)(c.size() - k + 1));
    }
  }
  if (c.size() >= k) {
    sort(c.begin(), c.end());
    auto it = upper_bound(c.begin(), c.end(), x + y);
    it--;
    d += min((int)(it - c.begin() + 1), (int)(c.size() - k + 1));
  }
  return d >= q;
}

