    long long minS = 1000000001, maxS = -1;
    while (minS - maxS > 1) {
      int s = (maxS + minS) / 2;
      if (f(b[i], s)) {
        minS = s;
      } else {
        maxS = s;
      }
    }
    ans = min(ans, minS);
  }
  cout << ans << endl;
  return 0;
}

