      ll temp = min(counter - k + 1, okcounter);
      if (temp > 0) sum += temp;
      counter = okcounter = 0;
    } else {
      counter++;
      if (a[i] <= mx) okcounter++;
    }
  }
  ll temp = min(counter - k + 1, okcounter);
  if (temp > 0) sum += temp;
  return sum >= q;
}

