const int inf = 1 << 30;

int solve(const vector<int> &a, int k, int v, int q) {
  const int n = a.size();

  int cnt = 0;
  vector<vector<int> > t;
  for(int i = 0; i < n; ){
    if(a[i] > v){ i++; continue; }

    vector<int> tt;
    for(; i < n && a[i] <= v; i++) tt.push_back(a[i]);

    if(k <= (int)tt.size()){
      sort(tt.begin(), tt.end());
      REP(j,k-1) tt.pop_back();
      t.push_back(tt);
      cnt += tt.size();
    }
  }

  if(cnt < q) return inf;

  const int m = t.size();

  int mn = inf;
  REP(i,m){
    const vector<int> &tt = t[i];
    mn = min(mn, tt[0]);
  }

  int ans = inf;
  REP(i,m){
    const vector<int> &tt = t[i];
    ans = min(ans, tt[min((int)tt.size(), q) - 1] - tt[0]);
    if(q != 1 && mn != tt[0]) ans = min(ans, tt[min((int)tt.size(), q - 1) - 1] - mn);
  }

  return ans;
}

