ll A[SIZE], par[SIZE];
multiset<ll> mst[SIZE], num;
bool used[SIZE];

void merge(ll i, ll j) {
    ll pi = par[i];
    ll pj = par[j];
    if(pi == pj) return;
    if(mst[pi].size() < mst[pj].size()) swap(pi, pj);
    for(ll e : mst[pj]) mst[pi].insert(e);
    par[pj] = pi;
    mst[pj].clear();
}

ll find_par(ll i) {
    return i == par[i] ? i : (par[i] = find_par(par[i]));
}

const ll inf = 5e15;

int main() {
    ll N, K, Q;
