    V<ll> ord(N);
    iota(ALL(ord), 0ll);
    sort(ALL(ord), [&](ll i, ll j) { return A[i] > A[j]; });
    ll ans = inf;

    for(ll idx : ord) {
        if(0 < idx && used[idx - 1]) merge(idx, find_par(idx - 1));
        if(idx + 1 < N && used[idx + 1]) merge(idx, find_par(idx + 1));
        used[idx] = true;
        ll p = find_par(idx);
        while(K <= mst[p].size()) {
            auto ite = mst[p].begin();
            num.insert(*ite);
            mst[p].erase(ite);
        }
        while(Q < num.size()) {
            auto ite = prev(num.end());
            num.erase(ite);
        }

        if(num.size() == Q) chmin(ans, *num.rbegin() - *num.begin());
    }

    cout << ans << endl;
    return 0;
}

