template <int char_size>
struct TrieNode {
	int nxt[char_size];

	int exist;
	vector<int> accept;	 // このノードで終わりの単語の番号(追加順)を入れた配列

	TrieNode() : exist(0) { memset(nxt, -1, sizeof(nxt)); }
};
template <int char_size = 26, int margin = 'a'> /* <26,'a'> など */
struct Trie {
	using Node = TrieNode<char_size>;

	vector<Node> nodes;
	int root;

	Trie() : root(0) { nodes.push_back(Node()); }

	//
	void update_direct(int node, int id) { nodes[node].accept.push_back(id); }

	// nodeの重さ(要素数)1増大
	void update_child(int node, int child, int id) { ++nodes[node].exist; }

	void add(const string &str, int str_index, int node_index, int id) {
		if(str_index == str.size()) {
			update_direct(node_index, id);	// 単語の終わりを示す
		} else {
			const int c = str[str_index] - margin;
			if(nodes[node_index].nxt[c] == -1) {
				nodes[node_index].nxt[c] = (int)nodes.size();
				nodes.push_back(Node());
			}
			add(str, str_index + 1, nodes[node_index].nxt[c], id);
			update_child(node_index, nodes[node_index].nxt[c], id);
		}
	}

	void add(const string &str, int id) { add(str, 0, 0, id); }

	void add(const string &str) { add(str, nodes[0].exist); }

	void query(const string &str, const function<void(int)> &f, int str_index, int node_index) {
		for(auto &idx : nodes[node_index].accept) f(idx);
		if(str_index == str.size()) {
			return;
		} else {
			const int c = str[str_index] - margin;
			if(nodes[node_index].nxt[c] == -1) return;
			query(str, f, str_index + 1, nodes[node_index].nxt[c]);
		}
	}

	void query(const string &str, const function<void(int)> &f) { query(str, f, 0, 0); }

	int count() const { return (nodes[0].exist); }	// 単語数(重複含む)

	int size() const { return ((int)nodes.size()); }  // node数
};

