    auto it = cnt.begin();
    for(; it!=cnt.end(); ++it) {
        int tmp0=it->first;
        vector<int> save;
        int cnt = 0;
        for (i = 0; i < n; i++) {
            int val = z[i].first;
            int id = z[i].second;
