        save.push_back(n);
        sort(save.begin(), save.end());
        int siz = (int)save.size();

        ll ans0 = -INF;
        vector<int> num(siz);
        int cnt0 = 0;
        for (; i < n; i++) {
            int val = z[i].first;
            int id = z[i].second;
