int a[maxN];
int ans = 2 * (int)1e9 + 10;
vector < int > g[maxN];
int id[maxN];
int sz[maxN];
void go(int val) {
    int l = 1;
    int r = 1;
    int cnt = 0;
    while (l <= n) {
        if (a[l] < val) {
            l++;
            r++;
            continue;
        }
        while (a[r] >= val && r <= n) r++; r--;
        r = min(r, n);
        if ((r - l + 1) >= k) {
            cnt++;
            g[cnt].clear();
            for (int j = l; j <= r; j++) {
                g[cnt].push_back(j);
                id[j] = cnt;
            }
            sz[cnt] = g[cnt].size();
        }
        l = r + 1;
        r = r + 1;
    }
    int mx = val;
    int nq = q;
    set < pair < int, int > > s;
    for (int v = 1; v <= cnt; v++) {
        for (int j = 0; j < g[v].size(); j++) {
            s.insert(make_pair(a[g[v][j]], g[v][j]));
        }
    }
    while (nq > 0) {
        if (s.empty()) return;
        auto t = (*s.begin());
        s.erase(s.begin());
        int val = t.first;
        int num = t.second;
        mx = val;
        nq--;
        sz[id[num]]--;
        if (sz[id[num]] < k) {
            int v = id[num];
            for (int j = 0; j < g[v].size(); j++) {
                s.erase(make_pair(a[g[v][j]], g[v][j]));
            }
        }
    }
    ans = min(ans, mx - val);
}
int main() {
    //freopen("input.txt", "r", stdin);
    ios_base::sync_with_stdio(false);
    cin >> n >> k >> q;
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 1; i <= n; i++) {
        go(a[i]);
    }
    cout << ans;
	return 0;
}

