#define INTSPACE 12
char _buf[INTSPACE*1000000 + 3];

int loadint() {
    if (fgets(_buf, INTSPACE+3, stdin)==NULL) return 0;
    return atoi(_buf);
}
int loadvec(vector<int>& v, int N=-1) {
    if (N == -1) {
        N = loadint();
        if (N==0) return 0;
    }
    int bufsize = INTSPACE*N + 3;
    if (fgets(_buf, bufsize, stdin)==NULL) return 0;
    v.resize(N);

    int i=0;
    bool last = false;
    for (char *p=&_buf[0]; ;) {
        char *q = p;
        while (*q > ' ') ++q;
        if (*q == 0x0D || *q == 0x0A) last = true;
        *q = 0;
        v[i++] = atoi(p);
        if (last || i == N) break;
        p = q+1;
    }
    // assert(i <= N);
    return i;
}

int N,K,Q;
vector<int> a;



ll solve() {
#ifdef DEBUG
    printf("N=%d K=%d Q=%d\n", N,K,Q);
#endif

    map<int,vi> mu;
    rep(i,N) mu[ a[i] ].pb(i);

    vector<ii> ranges;
    ranges.pb(ii(0, N-1)); // inclusive
#ifdef DEBUG
    cerr << ranges << endl;
#endif
    int best = 0x7fffffff;

    for (auto p: mu) {
        int smallest = p.first;
#ifdef DEBUG
        cerr << smallest << " " << p.second << endl;
#endif

        vi smalls;
        int takable_total = 0;
        //cerr << " {{ ";
        for (ii range : ranges) {
            int width = range.second - range.first + 1;
            int takable = width - K + 1;
            if (takable < 1) continue;
            vi tmp;
            for (int i=range.first; i<=range.second; ++i) {
                tmp.pb(a[i]);
            }
            //cerr << tmp << ", ";
            takable_total += takable;
            sort(ALL(tmp));
            int valid = tmp.size() - (K-1);
            smalls.insert(smalls.end(), tmp.begin(), tmp.begin()+valid);
        }
        //cerr << "}}" << endl;
        if (takable_total < Q) break;
        sort(ALL(smalls));
        assert(smalls[0] == smallest);
        int score = smalls[Q-1] - smalls[0];
        best = min(best, score);

#ifdef DEBUG
        cerr << "ranges=" << ranges << ", score=" << score << endl;
#endif

        for (int i : p.second) {
            // dividing
            for (int j=ranges.size()-1; j>=0; --j) {
                if (IN(i, ranges[j].first, ranges[j].second)) {
#ifdef DEBUG
//                    printf(" %d in (%d,%d)...\n", i, ranges[j].first, ranges[j].second);
#endif
                    if (i+1 +(K-1) <= ranges[j].second) {
                        ranges.insert(ranges.begin()+j+1, ii(i+1, ranges[j].second));
                    }
                    if (ranges[j].first +(K-1) <= i-1) {
                        ranges[j].second = i-1;
                    } else {
                        ranges.erase(ranges.begin()+j);
                    }
                    break;
                }
            }
            if (ranges.empty()) goto break_loop;
        }
    }
break_loop:

    return best;
}

