        segtree<int> seg(VI(n, 1), 0);
        int cnt = 0;
        FOR(j, i, n) {
            auto itr = t.lower_bound(p[j].second);
            int r = *itr;
            --itr;
            int l = *itr + 1;
            if (seg.value(l, r) < k)t.insert(p[j].second);
            else {
                ++cnt;
                seg.update(p[j].second, -1);
                if (cnt == q) {
                    chmin(ans, p[j].first - p[i].first);
                    break;
                }
            }
        }
