void solve(long long N, long long K, long long Q, std::vector<long long> A){
  auto AA = A;
  sort(AA.begin(),AA.end());
  ll l=0;
  ll ans=AA[Q-1]-AA[0];
  while(l<N){
    ll cnt=0;
    ll sum=0;
    REP(N){
