const int maxn=4e3+5, INF=1e9;
int n, k, q, cntc, a[maxn], b[maxn], dable[maxn], ans=INF;
int fa[maxn], len[maxn];  //len表示一个结点所代表的区间长度

struct Node{  //对能选的数排序
    int v, id;
}c[maxn];

bool cmp(const Node &a, const Node &b){ return a.v<b.v; }

int main(){
    scanf("%d%d%d", &n, &k, &q); int x, cnt, minm, t;
    for (int i=1; i<=n; ++i){ scanf("%d", &a[i]); b[i]=a[i]; }
    sort(b+1, b+n+1);
    for (int i=1; i<=n; ++i){ x=b[i];  //x表示最小的最小元素
        memset(dable, 0, sizeof(dable));
        memset(fa, 0, sizeof(fa)); cntc=0; t=1;
        for (int j=1; j<=n; ++j) if (a[j]<x) dable[j]=1;  //比x小的数不能选
        for (int j=1; j<=n; ++j){  //j-t表示区间长度 t是区间起点
            if (!dable[j]) fa[j]=t, c[++cntc].v=a[j], c[cntc].id=j;
            if (dable[j]) len[t]=j-t, t=j+1;
        }
        len[t]=n+1-t;
        sort(c+1, c+cntc+1, cmp); cnt=1;
        for (int j=1; cnt<=q&&j<=cntc; ++j){  //取q个数
            if (len[fa[c[j].id]]<k) continue;
            --len[fa[c[j].id]];  //取完以后所在的区间长度-1
            minm=c[j].v; ++cnt;  //minm表示最小的最大元素
        }
        if (cnt<=q) break;
        ans=min(ans, minm-x);
    }
    printf("%d\n", ans);
    return 0;
}

