const int INF = 1e9 + 239;

int can(vector<int> a, int l, int r, int q, int k) {
	int n = (int)a.size();
	int c = 0;
	for (int i = 0; i < n; i++) {
		if (a[i] < l) {
			continue;
		} else {
			int p = i;
			int cnt_less_r = 0;
			if (a[i] <= r) cnt_less_r++;
			vector<int> sb = {a[i]};
			while (p + 1 < n && a[p + 1] >= l) {
				if (a[p + 1] <= r) {
					cnt_less_r++;
				}
				sb.push_back(a[p + 1]);
				p++;
			}
			int len = p - i + 1;
			if (len >= k) {
				c += min(len - k + 1, cnt_less_r);
			}
			i = p;
		}
	}
	return c >= q;
}

