class RSQ {
public:
	RSQ(int n) {
		_n=1;
		while(_n<n) _n*=2;
		_dat.resize(2*_n-1);
		for(int i=0;i<2*_n-1;++i) _dat[i]=0;
	}
	int size() {
		return _n;
	}
	void update(int k,long long a) {
		k+=_n-1;
		_dat[k]+=a;
		while(k>0) {
			k=(k-1)/2;
			_dat[k]+=a;
		}
	}
	// return the sum of [a,b)
	// external call should be written like query(a,b,0,0,_n)
	ll query(int a,int b,int k=0,int l=0,int r=-1) {
		if(r==-1) r=_n;
		if(r<=a||b<=l) return 0;
		if(a<=l&&r<=b) return _dat[k];
		else {
			ll vl=query(a,b,k*2+1,l,(l+r)/2);
			ll vr=query(a,b,k*2+2,(l+r)/2,r);
			return vl+vr;
		}
	}
private:
	int _n;
	vector<ll> _dat;
};
class RMQ {
#define RMQ_MAX ((1ll<<60)-1)
public:
	RMQ(int n) {
		_n=1;
		while(_n<n) _n*=2;
		_dat.resize(2*_n-1);
		for(int i=0;i<2*_n-1;++i) _dat[i]=(RMQ_MAX);
	}
	int size() {
		return _n;
	}
	void update(int k,long long a) {
		k+=_n-1;
		_dat[k]=a;
		while(k>0) {
			k=(k-1)/2;
			_dat[k]=min(_dat[k*2+1],_dat[k*2+2]);
		}
	}
	// return the minimum number in [a,b)
	// external call should be written like query(a,b,0,0,_n)
	ll query(int a,int b,int k=0,int l=0,int r=-1) {
		if(r==-1) r=_n;
		if(r<=a||b<=l) return RMQ_MAX;
		if(a<=l&&r<=b) return _dat[k];
		else {
			ll vl=query(a,b,k*2+1,l,(l+r)/2);
			ll vr=query(a,b,k*2+2,(l+r)/2,r);
			return min(vl,vr);
		}
	}
private:
	int _n;
	vector<ll> _dat;
};
RSQ rsq(2020);
RMQ rmq(2020);
vector<ll> sorted;
vector<ll> a;
ll n,k,q;

bool ers(ll pos) {
	ll l1=sorted[pos], r1=-1;
	while(l1-r1>1) {
		ll m1=(l1+r1)/2;
		if(rmq.query(m1,pos)>=a[sorted[pos]]) {
			l1=m1;
		} else {
			r1=m1;
		}
	}
	ll l2=sorted[pos],r2=n;
	while(r2-l2>1) {
		ll m2=(l2+r2)/2;
		if(rmq.query(pos,m2)>=a[sorted[pos]]) l2=m2;
		else r2=m2;
	}
	if((l2-l1+1)-rsq.query(l1,l2+1)>=k) {
		rsq.update(sorted[pos],1);
		rmq.update(sorted[pos],INF*INF);
		return true;
	} else if((l2-l1+1)>=k) {
		rsq.update(sorted[pos],1);
		rmq.update(sorted[pos],INF*INF);
		return false;
	} else return false;
}

ll calc(ll mini_idx) {
	ll pos=mini_idx;
	ll ret=0;
	while(pos<n&&ret<q) {
		if(ers(pos)) {
			ret++;
		}
		pos++;
	}
	REP(i,n) rsq.update(i,-rsq.query(i,i+1));
	REP(i,n) rmq.update(i,a[i]);
	if(ret==q) return a[sorted[pos-1]];
	else return -1;
}

