	REP(i,n) cin>>a[i];
	vector<P> b(n);
	sorted.resize(n);
	REP(i,n) {
		b[i].first=a[i];
		b[i].second=i;
	}
	sort(ALL(b));
	REP(i,n) sorted[i]=b[i].second;

	REP(i,n) rsq.update(i,-rsq.query(i,i+1));
	REP(i,n) rmq.update(i,a[i]);
	ll ans=INF*INF;
	REP(i,n) {
		ll buf=calc(i);
		//cout<<i<<" "<<buf<<endl;
		if(buf!=-1) ans=min(ans,buf-a[sorted[i]]);
	}
	cout<<ans<<endl;
}

