i64 solve(vector<vector<pi> > As, i64 K, i64 Q) {
  i64 i, j;
  vector<pi> nums;
  REP(0, sz(As), i) {
    sort(all(As[i]));
    REP(0, sz(As[i])-(K-1), j) {
      nums.pb(As[i][j]);
    }
  }
  if(sz(nums) < Q) {
    return -1;
  }
  sort(all(nums));
  return nums[Q - 1].first - nums[0].first;
}


