class RMQ {
private:
    int n;
    vector<int> dat;
    //[a,b)の最小値を返す
    //kは節点の番号l,rはその節点が[l,r)を保持している
    int rec(int a, int b, int k, int l, int r) {
        if (b <= l || r <= a) {
            return INF;
        }

        if (a <= l && r <= b) {
            return dat[k];
        } else {
            int rl = rec(a, b, 2 * k + 1, l, (l + r) / 2);
            int rr = rec(a, b, 2 * k + 2, (l + r) / 2, r);
            return std::min(rl, rr);
        }
    }

public:
    void init(int n_) {
        n = 1;
        while (n < n_) n *= 2;
        dat.resize(2 * n - 1);
        for (int i = 0; i < 2 * n - 1; i++) {
            dat[i] = INF;
        }
    }

    //kをaに変更
    void update(int k, int a) {
        int reaf = k + n - 1;
        dat[reaf] = a;
        while (reaf > 0) {
            reaf = (reaf - 1) / 2;
            dat[reaf] = std::min(dat[reaf * 2 + 1], dat[2 * reaf + 2]);
        }
    }

    //query[a,b]の範囲内の最小値を返す
    int query(int a, int b) {
        return rec(a, b + 1, 0, 0, n);
    }
};

int N, K, Q;
