struct block {
    int l, r;
    int mini;
    vector<pii> sorted;
    int size;

    block(int l, int r, int mini) : l(l), r(r), mini(mini), size(r - l) {
        for (int i = l; i < r; ++i) {
            sorted.push_back(pii(A[i], i));
        }
        sort(sorted.begin(), sorted.end(), greater<pii>());
    }

    bool operator<(const block &right) const {
        return mini < right.mini;
    }

};

priority_queue<block> blocks;

