    rep(i, N) {
        cin >> A[i];
        rmq.update(i, A[i]);
    }
    blocks.push(block(0, N, rmq.query(0, N)));
    int Y = rmq.query(0, N);
    int X = Y;
    vector<pii> vec = blocks.top().sorted;
    rep(i, Q) {
        X = vec[vec.size() - 1].first;
        vec.pop_back();
    }
    int ans = X - Y;

    vector<int> idxs;
    for (;;) {
        while (!blocks.empty()) {
            blocks.pop();
        }
        rep(i, N) {
            if (A[i] == Y)
                idxs.push_back(i);
        }
        sort(idxs.begin(), idxs.end());
        if (idxs[0] - 0 >= K)blocks.push(block(0, idxs[0], rmq.query(0, idxs[0])));
        rep(i, idxs.size() - 1) {
            if (idxs[i + 1] - idxs[i] - 1 >= K)
                blocks.push(block(idxs[i] + 1, idxs[i + 1], rmq.query(idxs[i] + 1, idxs[i + 1])));
        }
        if (N - idxs[idxs.size() - 1] - 1 >= K)
            blocks.push(block(idxs[idxs.size() - 1] + 1, N, rmq.query(idxs[idxs.size() - 1] + 1, N)));

        Y = blocks.top().mini;
        rep(i, Q) {
            X = blocks.top().mini;
            if (blocks.empty())goto printans;
            block block2 = blocks.top();
            block2.sorted.pop_back();
            block2.mini = block2.sorted[block2.sorted.size() - 1].first;
            block2.size--;
            blocks.pop();
            if (block2.size >= K)blocks.push(block2);
        }
        ans = min(ans, X - Y);
    }
    printans:
    cout << ans << endl;
    return 0;
}

