	ll n, k, q;
	cin >> n >> k >> q;
	ll a[n+1];
	rep(i, 1, n){cin >> a[i];}

	bool use[n+2];
	memset(use, 0, sizeof(use));
	use[0] = true;
	use[n+1] = true;

	vector<P> pos;
	rep(i, 1, n){pos.push_back(P(a[i], i));}
	sort(pos.begin(), pos.end());

	ll pospos[n+1];
	zep(i, 0, n){pospos[pos[i].second] = i;}

	ll ans = pos[q-1].first-pos[0].first;

	ll high = q-1;
	for(ll low = 0; high < n; low++){
		ll at = pos[low].second;
		if(!use[at]){
			use[at] = true;

			ll l = at;
			ll r = at;
			rep(i, at+1, min(at+k, n+1)){if(use[i]){r = i;}}
			rrep(i, at-1, max(at-k, 0LL)){if(use[i]){l = i;}}
			ll cnt = 1;
			rep(i, l, r){
				if(!use[i]){
					use[i] = true;
					if(1 <= i && i <= n && pospos[i] <= high){cnt++;}
				}
			}

			while(cnt > 0 && high < n){
				high++;
				if(high < n && !use[pos[high].second]){
					cnt--;
				}
			}
			if(high < n){
				ans = min(pos[high].first-pos[low].first, ans);
			}
		}
	}
	print(ans)
	return 0;
}

