	sort(b + 1, b + bcnt + 1);
	for (int i = 1; i <= bcnt - k + 1; ++i) c[++ccnt] = b[i];
}

void solve(int v) {
	bcnt = ccnt = 0;
	for (int i = 1; i <= n; ++i)
		if (a[i] >= v) b[++bcnt] = a[i];
