int N, K, Q;
int A[2010];
int res=1000000000;
int idx[2010];

bool cmp(int aa, int bb)
{
	return A[aa] < A[bb];
}

int calc(int ii, int jj)
{
	int i;
	int bN = 0, s = 0;
	int d = A[idx[ii]], u = A[idx[jj]];
	int c = 0;
	for(i=0; i<N; i++){
		if(A[i] < d){
			bN = s = 0;
			continue;
		}
		if(A[i] > u)
			bN ++;
		else
			s ++;
		if(bN >= K)
			bN --;
		if(bN + s == K){
			s --;
			c ++;
		}
	}
	if(c >= Q)
		return 1;
	else
		return 0;
}

int bsrch(int ii)
{
	int l=ii, r=N;
	int m;
	while(l<r){
		m = (l+r)/2;
		if(calc(ii, m) == 1)
			r = m;
		else
			l = m+1;
	}
	return l;
}

void solve()
{
	int i;
	for(i=0; i<N; i++)
		idx[i] = i;
	sort(idx, idx+N, cmp);
	int l, tmp;
	for(i=0; i<N; i++){
		l = bsrch(i);
		if(l < N){
			tmp = A[idx[l]] - A[idx[i]];
			if(tmp < res)
				res = tmp;
		}
	}
	printf("%d\n", res);
}

