template<class T>
struct SegmentTree {
private:
    int n;
    vector<T> node;
    T def;
    function<T(T,T)> lop;
    function<T(T,T)> out;

public:
    SegmentTree() {}
    SegmentTree(const vector<T> &v, T _def, function<T(T,T)> _lop, function<T(T,T)> _out) {
        int vl = (int)v.size();
        n = 1;
        while(n < vl) n *= 2;
        def = _def; lop = _lop; out = _out;
        node = vector<T>(2 * n - 1, def);
        for(int i = 0; i < vl; i++) node[i + n - 1] = v[i];
        for(int i = n - 2; i >= 0; i--) node[i] = out(node[i * 2 + 1], node[i * 2 + 2]);
    }

    void update(int idx, T val) {
        idx += (n - 1);
        node[idx] = lop(node[idx], val);
        while(idx > 0) {
            idx = (idx - 1) / 2;
            node[idx] = out(node[idx * 2 + 1], node[idx * 2 + 2]);
        }
    }

    T query(int a, int b, int k = 0, int l = 0, int r = -1) {
        if (r < 0) r = n;
        if ((r <= a) || (b <= l)) return def;
        if ((a <= l) && (r <= b)) return node[k];
        return out(query(a, b, 2 * k + 1, l, (l + r) / 2), query(a, b, 2 * k + 2, (l + r) / 2, r));
    }
};

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);
    // ifstream in("input.txt");
    // cin.rdbuf(in.rdbuf());
    const ll inf = LONG_LONG_MAX / 2 - 1;
    ll n, k, q;
    cin >> n >> k >> q;
    vector<ll> a(n);
    rep(i, n) cin >> a[i];
    vector<pair<ll, ll>> ai(n);
    rep(i, n) ai[i] = make_pair(a[i], i);
    auto lop = [](pair<ll, ll> a, pair<ll, ll> b){ return b; };
    auto out = [](pair<ll, ll> a, pair<ll, ll> b){ return min(a, b); };
    SegmentTree<pair<ll, ll>> st(ai, make_pair(inf, inf), lop, out);
    ll left = LONG_LONG_MAX, right = LONG_LONG_MIN;
    rep(i, q) {
        pair<ll, ll> tmp = make_pair(inf, inf);
        rep(j, n - k + 1) {
            pair<ll, ll> p = st.query(j, j + k);
            if (p.first < tmp.first) {
                tmp = p;
            }
        }
        left = min(left, tmp.first);
        right = max(right, tmp.first);
        st.update(tmp.second, make_pair(inf, tmp.second));
    }
    cout << (right - left) << endl;
    return 0;
}

