	}
	for(int i=1;i<=n;i++){
		priority_queue <int> pr;
		int cnt=0,in=0,ok=1;
		sv.clear();
		for(int j=1;j<=n;j++){
			if(a[j]<a[i]) b[j]=-1;
			else b[j]=a[j];
