				if(in && cnt<k){
					ok=0;
					break;
				}
				while(cnt>=k){
					cnt--;
					sv.push_back(-pr.top());
					pr.pop();
				}
				while(!pr.empty()) pr.pop();
				in=0, cnt=0;
			}
		}
