int calc(const vector<int> &A, int min_value, int N, int K, int Q) {
  vector<int> candidates;
  int l = 0;
  while (l < N) {
    if (A[l] < min_value) {
      l++;
      continue;
    } else {
      int r = l;
      while (r < N && A[r] >= min_value) {
        r++;
      }

      vector<int> local_candidates;
      while (l < r) {
        local_candidates.push_back(A[l++]);
      }
      sort(ALL(local_candidates));
      REP(i, int(local_candidates.size()) - K + 1) {
        candidates.push_back(local_candidates[i]);
      }
    }
  }

  sort(ALL(candidates));
  if (int(candidates.size()) >= Q) {
    return candidates[Q - 1] - candidates[0];
  } else {
    return 1e9;
  }
}

