const double EPS = 1e-10;
const double PI  = acos(-1.0);
const LL MOD = 1e9+7;
const LL INF = 1e15;

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  LL N, K, Q;
  cin >> N >> K >> Q;
  VL xs(N);
  cin >> xs;

  LL ans = INF;
  REP(ii,N){
	LL mn = xs[ii];
	LL lb = mn-1, ub = 1e10;
	while(ub-lb>1){
	  LL m = (lb + ub) / 2;

	  LL sum = 0;
	  LL l = 0, o = 0;
	  REP(j,N){
		if(xs[j] < mn){
		  sum += max(0ll, min(l+o+1-K, l));
		  l = o = 0;
		  continue;
		}
		else if(xs[j] <= m){
		  ++l;
		}
		else
		  ++o;
	  }
	  sum += max(0ll, min(l+o+1-K, l));

	  if(sum >= Q) ub = m;
	  else lb = m;
	}

	if(ub >= mn && ub <= 1e9){
	  mini(ans, ub-mn);
	}
  }
  cout << ans << endl;


  return 0;
}

