void solve() {
  int n, k, q;
  cin >> n >> k >> q;
  vi32 a(n);
  cin >> a;
  int ans = INF;
  rep(i, n) {
    vi32 use(n);
    rep(j, n) if (a[j] >= a[i]) use[j] = 1;
    int id = 0;
    vi32 cnt;
    using T = tuple<int, int>;  // value, group id
    pqasc<T> que;
    rep(j, n) {
