      tie(val, id) = que.top();
      que.pop();
      if (cnt[id] < k) continue;
      c += 1;
      amax(mi, val);
      cnt[id]--;
      if (c == q) break;
    }
    if (c < q) continue;
    amin(ans, mi - a[i]);
  }
