bool possible(const vector<int> &A, int K, int Q, int l, int u) {
	int p = 0;
	int sum = 0;

	while(p < A.size()) {
		int q = p;
		int cnt = 0;
		while(q < A.size() && l <= A[q]) {
			if (A[q] <= u) {
				++cnt;
			}
			q++;
		}
		sum += min(cnt, (q - p + 1) - K + 1);

		p = q + 1;
	}

	return sum >= Q;
}

