bool Solve(int l, int r) {
  int cnt0 = 0, cnt1 = 0, cntop = 0;
  for (int i = 0; i <= n; ++i) {
    if (i == n || a[i] < l) {
      cntop += min(cnt0 + cnt1 - k + 1, cnt0);
      cnt0 = cnt1 = 0;
    } else if (a[i] <= r) {
      ++cnt0;
    } else {
      ++cnt1;
    }
  }
  return cntop >= q;
}

