const int N=2e5+5;

int n, k, q;
int a[N], vis[N];
pair<int, int> b[N];
vector<int> v[2][N];
int connected;
int root[N], sz[N];
map<int, int> store;

void init()
{
	for(int i=1;i<=n;i++)
	{
		root[i]=i;
		sz[i]=1;
	}
	connected=0;
}

int rt(int k)
{
	while(k!=root[k])
	{
		root[k]=root[root[k]];
		k=root[k];
	}
	return k;
}

void merge(int u, int v)
{
	int rt1=rt(u);
	int rt2=rt(v);

	if(rt1==rt2)
		return;

	connected--;

	store[sz[rt1]]--;
	store[sz[rt2]]--;
	store[sz[rt1]+sz[rt2]]++;

	if(store[sz[rt1]]==0)
	{
		store.erase(sz[rt1]);
	}

	if(store[sz[rt2]]==0)
	{
		store.erase(sz[rt2]);
	}

	if(sz[rt2]>=sz[rt1])
	{	
		sz[rt2]+=sz[rt1];
		sz[rt1]=0;
		root[rt1]=root[rt2];
	}
	else
	{
		sz[rt1]+=sz[rt2];
		sz[rt2]=0;
		root[rt2]=root[rt1];
	}
}

int32_t main()
{
    IOS; 
    cin>>n>>k>>q;
    init();
    for(int i=1;i<=n;i++)
    {
    	cin>>a[i];
    	b[i].first=a[i];
    	b[i].second=i;
    }
    sort(b+1, b+n+1);
    int ans=1e18;
    for(int i=n;i>=1;i--)
    {
    	connected++;
		store[1]++;
		int idx=b[i].second;
		vis[idx]=1;
		if(vis[idx-1])
		{
			merge(idx, idx-1);
		}
		if(vis[idx+1])
		{			
			merge(idx, idx+1);
		}
		int cnt=0;
		for(auto it:store)
		{
			cnt+=max(0LL, it.first-k+1)*it.second;
		}
		if(cnt>=q && i+q-1<=n)
		{
			ans=min(ans, b[i+q-1].first-b[i].first);
		}
    }
    cout<<ans;
    return 0;
}

