inline void Solve(int Min)
{
	Ok[0] = 0;
	int l = 1, r = 1;
	while (l <= n)
	{
		C[0] = 0;
		while (A[l] < Min && l <= n) ++l;
		r = l;
		while (A[r] >= Min && r <= n) ++r;
		if (r - l < lim) goto end;
		for (int i = l;i < r; ++i)
			C[++C[0]] = A[i];
		std::sort(C + 1, C + 1 + C[0]);
		for (int i = 1;i <= C[0] - lim + 1; ++i)
			Ok[++Ok[0]] = C[i];
		end:; l = r;
	}
	if (Ok[0] < q) return ;
	std::sort(Ok + 1, Ok + 1 + Ok[0]);
	ans = std::min(ans, Ok[q] - Ok[1]);
}

