inline int read() {
	int x=0,p=1;
	char c=getchar();
	while (!isdigit(c)) { if (c=='-') p=-1; c=getchar();}
	while (isdigit(c)) { x=(x<<1)+(x<<3)+(c-'0'); c=getchar();}
	return x*p;
}

inline int solve(int p) {
	int l=1; N=0;
	For (r,1,n+1) {
		if (a[r]<a[p]) {
			int len=r-l;
			if (len>=m) {
				For (i,l,r-1) b[i-l+1]=a[i];
				sort(b+1,b+len+1);
				For (i,1,len-m+1) c[++N]=b[i];
			}
			if (l) l=r+1;
		}
	}
	if (N<q) return inf;
	return c[q]-a[p];
}

