int main(void) {
  priority_queue<ll,vll,greater<ll>> pq1, pq2;
  vll a[2222];
  SET st;
  ll k, q, ind, ri, le;
  cin >> n >> k >> q;
  FOR(i, 0, n) {
	cin >> x[i];
  }

  FOR(i, 0, n - k + 1) {
	mi = inf;
	FOR(j, 0, k) {
	  if (mi >= x[i + j]) {
		mi = x[i + j];
		ind = i + j;
	  }
	}
	st.insert(ind);
  }

  ans = inf;

  for (auto it : st) {
	while (!pq2.empty()) pq2.pop();
	m = it;
	FOR(i, 0, n) {
	  if (i == m)continue;
	  a[m].pb(x[i]);
	}
	le = ri = 0;
	while (1) {
	  if (le + (k - 1) >= a[m].size()) break;
	  ok = true;
	  FOR(i, 0, k) {
		if (a[m][le + i] < x[m]) {
		  ok = false;
		  tmp = le + i;
		}
	  }
	  if (!ok) {
		le = tmp + 1;
		continue;
	  }

	  while (!pq1.empty()) pq1.pop();
	  FOR(i, 0, k-1) {
		pq1.push(a[m][le + i]);
	  }

	  ri = le + k - 1;

	  while (ri < a[m].size()) {
		if (a[m][ri] < x[m]) {
		  le = ri + 1;
		  break;
		}
		pq1.push(a[m][ri]);
		pq2.push(pq1.top());
		pq1.pop();
		ri++;
	  }
	  le = ri + 1;
	}
	if (pq2.empty()) continue;
	if (pq2.size() < q - 1) continue;
	FOR(i, 0, q - 2) pq2.pop();
	ans = min(ans, pq2.top() - x[m]);
  }

  cout << ans << endl;

  return 0;
}

