template<class C> C compress(vector<C> &v) {//{//prefer using unique+function with lower_bound when compressing combined vectors
    int sz = sz(v);
    vector<pair<C, int> > tmp(sz);
    for (int i = 0; i < sz; i++) {
        tmp[i] = {v[i], i};
    }
    sort(begin(tmp), end(tmp));
    int cur = 1;
    for (int i = 0; i < sz; i++) {
        cur += i and tmp[i].first!=tmp[i-1].first;
        v[tmp[i].second] = cur;
    }
    return cur;
