struct Fixed
{
	template<class F>
	struct FixedPoint : F
	{
		template <class...T>
		auto operator()(T&&...p) { return F::operator()(*this, std::forward<T>(p)...); }
		FixedPoint(F&& f) : F(std::forward<F>(f)) {}
	};

	template <class F>
	static auto fixed(F&& f)
	{
		return FixedPoint<F>(std::forward<F>(f));
	}
};


