int n, k, q, a[MAXN], ans = 2e9;

int get(int mn){
	int lo = mn-1, hi = INF;
	while (hi-lo>1){
		int mid = hi+lo>>1, cnt = 0;

		for (int l = 0; l < n;){
			if (a[l] < mn){
				l++;
				continue;
			}

			int r = l;
			while (r < n && a[r] >= mn) r++;
			if (r - l >= k){
				int c = 0, c2 = 0;
				for (; l < r; l++)
					if (a[l] <= mid)
						c++;
					else
						c2++;

				c -= max(0, (k-1 - c2));
				cnt += c;
			}
			l = r;
		}
		if (cnt >= q)
			hi = mid;
		else
			lo = mid;
	}
	return hi == INF? INF: hi-mn;
}

