    int i,j;
    map<int, int> cnt;
    for (i = 0; i < n; i++) {
        scanf("%d", &a[i]);
        z.push_back(make_pair(a[i], i));
        cnt[a[i]]++;
    }
    sort(z.begin(), z.end());

