ll solve(const V<ll> &alist, ll n, ll width, ll qcnt, ll minval)
{
    debug_printf("---- solve ----\n");

    priority_queue_incr<ll> cands;
    priority_queue_incr<ll> removed;

    // alist is tailed
    rep (i, n+1) {
        ll a = alist[i];
        if (a < minval) {
            while (cands.size() >= width) {
                ll cand = cands.top(); cands.pop();
                removed.push(cand);
            }
            while (!cands.empty()) cands.pop();
        }
        else {
            cands.push(a);
        }
    }

    if (removed.size() < qcnt) return 1e18;

    ll maxval = minval;
    rep (i, qcnt) {
        maxval = removed.top();
        removed.pop();
    }

    return maxval - minval;
}

void _main();
int main()
{
    cout << setprecision(12);
    _main();
    return 0;
}

void _main()
{
    ll n; llin(n);
    ll width; llin(width);
    ll qcnt; llin(qcnt);
    V<ll> alist; llina(alist, n);

    ll ans = 1e18;
    V<ll> tail_alist = alist;
    tail_alist.pb(-1e18);

    for (auto minval : alist)
        ans = min(ans, solve(tail_alist, n, width, qcnt, minval));

    cout << ans << endl;
}

