int solve(int l,int r,int x)
{
	int tmp=0;
	for(int i=l;i<=r;i++)
	{
		if(a[i]<=x)tmp++;
	}
	return min(tmp,max(0,r-l-k+2));
}
int tp[N],cnt;
bool pan(int x)
{
	for(int i=1;i<=n;i++)
	{
		int now=0,cnt=0;
		tp[++cnt]=0;
		for(int j=1;j<=n;j++)if(a[j]<b[i])tp[++cnt]=j;
		tp[++cnt]=n+1;
		for(int j=1;j<cnt;j++)
		{
			now+=solve(tp[j]+1,tp[j+1]-1,b[i]+x);
		}
		if(now>=q)return 1;
	}
	return 0;
}
