int main(){
	int a[N];
	int b[N];
	int m[N];
	vector<int>s;
	vector<pair<pair<int, int>,int> >ss;
	int c[N];
	int d[N];
	int n, k, q;
	int x, sum, ans;
	scanf("%d %d %d", &n, &k, &q);
	for (int i = 0; i < n; i++){
		scanf("%d", &a[i]);
	}

	for (int i = 0; i <= (n-k); i++){
		m[i] = MOD;
		for(int j=0;j<k;j++){
			if (m[i] > a[i + j])m[i] = a[i + j];
		}
	}

	for(int i=0;i<n;i++){
		b[i] = -1;
		for(int j=0;j<k;j++){
			if ((i + j) >= (k - 1) && (i + j) <= (n + 1)){
				if (m[(i + j - k + 1)] > b[i])b[i] = m[(i + j - k + 1)];
			}
		}
		s.push_back(b[i]);
		ss.push_back(make_pair(make_pair(a[i], -b[i]), i));
	}
	sort(ss.begin(), ss.end(), greater <pair< pair<int, int>, int> >());
	sort(s.begin(), s.end(), greater<int>());
	c[0] = 1;
	d[0] = s[0];
	x = 0;
	f(i, (n - 1)){
		if (d[x] = s[i + 1])c[x]++;
		else{
			x++;
			c[x] = 1;
			d[x] = s[i + 1];
		}
	}
	ans = MOD;
	f(i, n-q+1){
		sum = 0;
		f(j, x + 1){
			sum += c[j];
			if (sum >= q){
				if ((ss[i].first.first - d[j]) < ans)ans = (ss[i].first.first - d[j]);
				break;
			}
		}
		f(j, x + 1){
			if (d[j] + ss[i].first.second == 0)c[j]--;
		}
	}
  if(ans==MOD)ans=0;
	printf("%d\n", ans);
	return 0;
}

