const int N = 500200;
const int mod = 1e9 + 7;
int n, k, q, a[N], bad[N];

inline bool check(int id, int sub) {
    int up = a[id] + sub;
    int last = 0, ops = 0;
    for(int i = 1; i <= n; ++i) {
        if(bad[i]) {
            int len = i - last - 1;
            if(len >= k) {
                int tmp = 0;
                for(int j = last + 1; j < i; ++j)
                    if(a[j] <= up) ++tmp;
                ops += min(tmp, len - k + 1);
            }
            last = i;
        }
    }
    if(n - last >= k) {
        int tmp = 0;
        for(int j = last + 1; j <= n; ++j) {
            if(a[j] <= up) ++tmp;
        }
        ops += min(tmp, n - last - k + 1);
    }
    return ops >= q;
}
int main() {
    ios::sync_with_stdio(0); cin.tie(0);
    cin >> n >> k >> q;
    fo(i, n) cin >> a[i];
    if(q == 1) return cout << 0, 0;
    vector<int> v;
    int ans = 2e9;
    for(int i = 1; i <= n; ++i) {
        for(int j = 1; j <= n; ++j)
            if(a[j] < a[i]) bad[j] = 1;
            else bad[j] = 0;
        v.clear();
        for(int j = 1; j <= n; ++j)
            if(a[j] >= a[i]) v.pb(a[j] - a[i]);
        sort(v.begin(), v.end());
        v.resize(unique(v.begin(), v.end()) - v.begin());
        int l = -1, r = (int)v.size() - 1;
        while(l + 1 < r) {
            int m = (l + r) >> 1;
            if(check(i, v[m])) r = m;
            else l = m;
        }
        if(check(i, v[r])) ans = min(ans, v[r]);
    }
    cout << ans;
    return 0;
}

