    for(int i = 0; i < N; i++){
        int val = vs[i].first;
        int idx = vs[i].second;
        if(L[idx] + R[idx] + 1 >= K){
            int cnt = 1;
            for(int j = i + 1; j < N; j++){
                idx = vs[j].second;
                if(L[idx] + R[idx] + 1 >= K) cnt++;
                if(cnt == Q){
                    ans = min(ans, vs[j].first - val);
                    break;
                }
            }
        }
        update(vs[i]);
    }
    if(Q == 1) ans = 0;
    return ans;
