const int N=2e3+5;
int n,k,Q,a[N],f[N][N];
priority_queue<int> q;
vector<int> v;
bool check(int pos)
{
	int mn=a[pos];
	for(int i=max(1,pos-k+1);i<=pos;i++)
	{
		if(i+k-1>n)	return false;
		if(f[i][k]==mn)
			return true;
	}
	return false;
}
void update()
{
	while(!q.empty())
	{	
		if(q.size()>=k)
			v.push_back(-q.top());
		q.pop();
	}
}
int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);
	cin>>n>>k>>Q; 
