	{
		f[i][1]=a[i];
		for(int j=i+1;j<=n;j++)
			f[i][j-i+1]=min(f[i][j-i],a[j]);
	}
	int res=2e9;
	for(int i=1;i<=n;i++)
	{
		if(!check(i))	continue;
		int mn=a[i];
