using namespace std;

const int N=2005;

struct node{
	int w,id;
	node(){}
	node(int w,int id):w(w),id(id){}
}b[N];
int n,ans,k,Q;
int a[N],sz[N],fa[N],vis[N];

int find(int k){
	if (fa[k]!=k) fa[k]=find(fa[k]);
	return fa[k];
}

void merge(int x,int y){
	x=find(x); y=find(y);
	if (x!=y){
		fa[x]=y;
		sz[y]+=sz[x];
	}
}

bool cmp(node a,node b){
	return a.w<b.w;
}

void work(int w){
	int i,cnt=0,x;
	memset(vis,0,sizeof(vis));
	for (i=1;i<=n;i++)
		if (a[i]<w) vis[i]=1;
	for (i=1;i<=n;i++) fa[i]=i,sz[i]=1;
	for (i=1;i<n;i++)
		if (a[i]>=w&&a[i+1]>=w) merge(i,i+1);
	for (i=1;i<=n;i++) if (b[i].w>=w){
		x=find(b[i].id);
		if (sz[x]>=k){
			cnt++;
			sz[x]--;
		}
		if (cnt==Q){
			ans=min(ans,b[i].w-w);
			return;
		}
	}
}

int main(){
	int i,j;
	scanf("%d%d%d",&n,&k,&Q);
	for (i=1;i<=n;i++){
		scanf("%d",&a[i]);
		b[i]=node(a[i],i);
	}
	sort(b+1,b+1+n,cmp);
	ans=b[n].w-b[1].w;
	for (i=1;i<=n;i++) work(a[i]);
	printf("%d\n",ans);
	return 0;
}

#include<iostream>
