#define maxn 2020
using namespace std;
int n,k,q,a[maxn];
priority_queue<int>q1,q2;
struct node{int v,id;}b[maxn];
inline bool cmp(node a,node b){return a.v<b.v;}
void init(){
	scanf("%d%d%d",&n,&k,&q);
	for(int i=1;i<=n;++i){
	    scanf("%d",&a[i]);
	    b[i].v=a[i];b[i].id=i;
    }
	sort(b+1,b+n+1,cmp);
}
inline void extend(int l,int r){
	if(l>r)return;
	int s=0;
	while(r-l+1-s>=k){
		int u=q1.top();q1.pop();
		q2.push(u);++s;
	}
}
void solve(){
	int ans=2e9;
	for(int t=1;t<=n;++t){
		int la=1;
		while(!q2.empty())q2.pop();
		for(int i=1;i<=n;++i){
			if(a[i])q1.push(-a[i]);
			if(!a[i]||i==n){
				if(i==n)++i;
				extend(la,i-1);
				la=i+1;
				while(!q1.empty())q1.pop();
			}
		}
		if(q2.size()<q)break;
		int mn=2e9,mx=0;
		for(int i=1;i<=q;++i){
			int u=-q2.top();q2.pop();
			mn=min(mn,u),mx=max(mx,u);
		}
		ans=min(mx-mn,ans);
		a[b[t].id]=0;
	}
	printf("%d\n",ans);
}
int main(){
	init();
	solve();
	return 0;
}

#include <bits/stdc++.h>
using namespace std;
const int maxN = 2005;
int n, k, q;
int a[maxN];
int ans = 2 * (int)1e9 + 10;
vector < int > g[maxN];
int id[maxN];
int sz[maxN];
void go(int i) {
    int l = 1;
    int r = 1;
    int cnt = 0;
    while (l <= n) {
        if (a[l] < a[i]) {
            l++;
            r++;
            continue;
        }
        while (a[r] >= a[i] && r <= n) r++; r--;
        r = min(r, n);
        if (l <= i && i <= r) {
            if ((r - l + 1) < k) return;
        }
        if ((r - l + 1) >= k) {
            cnt++;
            g[cnt].clear();
            for (int j = l; j <= r; j++) {
                if (j == i) continue;
                g[cnt].push_back(a[j]);
                id[j] = cnt;
            }
            if (g[cnt].size() < k) g[cnt].clear();
            sz[cnt] = g[cnt].size();
        }
        l = r + 1;
        r = r + 1;
    }
    int mx = a[i];
    int nq = q - 1;
    set < pair < int, int > > s;
    for (int v = 1; v <= cnt; v++) {
        for (int j = 0; j < g[v].size(); j++) {
            s.insert(make_pair(g[v][j], j));
        }
    }
    while (nq > 0) {
        if (s.empty()) return;
        auto t = (*s.begin());
        s.erase(s.begin());
        int val = t.first;
        int num = t.second;
        mx = val;
        nq--;
        sz[id[num]]--;
        if (sz[id[num]] < k) {
            int v = id[num];
            for (int j = 0; j < g[v].size(); j++) {
                s.erase(make_pair(g[v][j], j));
            }
        }
    }
    ans = min(ans, mx - a[i]);
}
int main() {
    //freopen("input.txt", "r", stdin);
    ios_base::sync_with_stdio(false);
    cin >> n >> k >> q;
    for (int i = 1; i <= n; i++) cin >> a[i];
    for (int i = 1; i <= n; i++) {
        go(i);
    }
    cout << ans;
	return 0;
}

