void Solve(ll) {
  ll n, k, q;
  if (not(cin >> n >> k >> q))
    return;
  vector<ll> arr(n);
  RARA(a, arr) cin >> a;
  auto vals = arr;
  sort(ALL(vals));
  vals.erase(unique(ALL(vals)), vals.end());
  auto is_poss = [&](ll low_val, ll hig_val) {
    ll cnt = 0;
    for (ll i = 0; i < n;) {
      if (arr[i] < low_val) {
        ++i;
        continue;
      }
      ll j = i, in_range = 0;
      while (j < n and arr[j] >= low_val) {
        in_range += (arr[j] <= hig_val);
        ++j;
      }
      cnt += max(ll(0), min(j - i - k + 1, in_range));
      i = j;
    }
    return cnt >= q;
  };
  ll low = 0, hig = 1e9;
  while (low <= hig) {
    const ll mid = (low + hig) / 2;
    bool can = false;
    VEVE(i, 0, n) {
      ll j = i;
      while (j < n and vals[j] - vals[i] <= mid)
        ++j;
      if (i < j and is_poss(vals[i], vals[j - 1])) {
        can = true;
        break;
      }
    }
    if (can) {
      hig = mid - 1;
    } else {
      low = mid + 1;
    }
  }
  cout << (hig + 1) << endl;
}

