class RMQ{
public:
    int n;
    vector<int> dat;
    // 初期化
    void init(int n_){
        n=1;
        while(n<n_)n*=2;
        dat.resize(n * 2 - 1, INT_MAX);
    }
    // k番目の値(0-indexed)をaに変更
    void update(int k,int a){
        // 葉の節点
        k+=n-1;
        dat[k]=a;
        // のぼりながら更新
        while(k>0){
            k=(k-1)/2;
            dat[k]=min(dat[k*2+1],dat[k*2+2]);
        }
    }
    // [a,b)の最小値値を求める
    // kは節点の番号、l,rはその節点が[l,r)に対応づいていることを表す
    // したがって、外からはquery(a,b,0,0,n)として呼ぶ
    int _query(int a,int b,int k,int l,int r){
        if(r<=a||b<=l)return INT_MAX;
        else if(a<=l&&r<=b)return dat[k];
        int vl=_query(a,b,k*2+1,l,(l+r)/2);
        int vr=_query(a,b,k*2+2,(l+r)/2,r);
        return min(vl,vr);
    }
    int query(int a,int b){
        return _query(a,b,0,0,n);	
    }
};


int N, K, Q;
int A[2010];
RMQ rmq;

int main(){

    cin >> N >> K >> Q;
    for(int i = 0; i < N; i++){
        cin >> A[i];
    }

    rmq.init(N);

    int max_a = INT_MIN;
    int min_a = INT_MAX;
    for(int i = 0; i < N; i++){
        min_a = min(min_a, A[i]);
        max_a = max(max_a, A[i]);
        rmq.update(i, A[i]);
    }

    int ans = max_a - min_a;
    // 最大値を決め打ち
    for(int i = 0; i < N; i++){
        int c = 0;
        for(int j = 0; j < N; j++){
            if(A[i] >= A[j]){
                c++;
            }
        }
        if(c < Q){
            continue;
        }

        int max_pos = i;
        vector<int> overs;
        for(int j = 0; j < N; j++){
            // 最大値より大きい要素を列挙
            if(A[j] >= A[max_pos]){
                overs.push_back(j);
            }
        }

        // oversにはmax_posもはいるので、そのmax_posを含むようにK個選んで、それをスライドさせていく
        if((int)overs.size() >= K){
            deque<int> dq;
            bool ok = false;
            for(int j = 0; j < (int)overs.size(); j++){
                if((int)dq.size() < K){
                    dq.push_back(overs[j]);
                    if(overs[j] == i){
                        ok = true;
                    }
                }
                if((int)dq.size() == K){
                    if(ok){

                        // 処理
                        int pos1 = dq[0];
                        int pos2 = dq[K-1];
                        int cnt = pos2 - pos1 + 1 - K;
                        if(cnt+1 < Q){
                            ans = min(ans,A[i] - min_a);
                        }
                        else if(cnt+1 == Q){
                            ans = min(ans, A[i] - rmq.query(pos1, pos2 + 1));
                        }

                        if(dq[0] == i) break;
                        dq.pop_front();
                    }
                    else{
                        dq.pop_front();
                    }
                }
            }
        }
        else{
            continue;
        }
    }

    cout << ans << endl;

}

