int main() {
  cin.tie(0); cin.sync_with_stdio(false);
  int n, k, q;
  cin >> n >> k >> q;
  vector<int> a(n);
  for (int i = 0; i < n; i++) {
    cin >> a[i];
  }
  auto erasable = [&] (const vector<int>& b, int M) {
    int cnt = count_if(b.begin(), b.end(), bind(less_equal<int>(), placeholders::_1, M));
    return max(0, min(cnt, (int)b.size() - k + 1));
  };
  constexpr int inf = 1 << 30;
  int ret = inf;
  for (auto m : a) {
    auto check = [&] (int M) {
      assert(m <= M);
      int now = 0;
      vector<int> tmp;
      auto discharge = [&] () {
        now += erasable(tmp, M);
        tmp = {};
      };
      for (auto crr : a) {
        if (crr >= m) tmp.push_back(crr);
        else discharge();
      }
      discharge();
      return now >= q;
    };
    if (!check(inf)) continue;
    int ok = inf, ng = m - 1, md;
    while (abs(ng - ok) > 1) {
      md = (ok + ng) >> 1;
      if (check(md)) ok = md;
      else ng = md;
    }
    assert(ok - m >= 0);
    cmn(ret, ok - m);
  }
  cout << ret << endl;
  return 0;
