using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define ITR(c,it)  for(auto it = c.begin(); it != c.end(); it++)

const int N_MAX = 2000;
const int INF = 1e9;

int N, K, Q;
int A[N_MAX];

pair<int, int> ps[N_MAX];
map<int, int> ss;
vector<int> vs;
vector<int> ws;

void solve() {
  REP(i, N) ps[i] = make_pair(A[i], i);
  sort(ps, ps + N);
  ss[N] = 0;
  int ans = INF;
  int i = 0;
  while (i < N) {
    // printf("i: %d\n", i);
    vs.clear();
    ITR(ss, it) {
      int l = it->second;
      int r = it->first;
      int w = r - l;
      // printf(" l: %d, r: %d, w: %d", l, r, w);
      if (w >= K) {
        ws.clear();
        ws.insert(ws.end(), A + l, A + r);
        sort(ws.begin(), ws.begin() + w);
        vs.insert(vs.end(), ws.begin(), ws.begin() + w - K + 1);
        // printf(" : add %d items", w - K + 1);
      }
      // puts("");
    }
    // printf(" vs.size(): %d\n", vs.size());
    if (vs.size() < Q) break;
    sort(vs.begin(), vs.end());
    // printf(" vs[0]: %d, vs[%d]: %d\n", vs[0], Q - 1, vs[Q - 1]);
    ans = min(ans, vs[Q - 1] - vs[0]);
    int ai = ps[i].first;
    while (ps[i].first == ai) {
      int ap = ps[i].second;
      auto it2 = ss.lower_bound(ap);
      int l = it2->second;
      int r = it2->first;
      // printf(" x: %d, l: %d, r: %d\n", x, l, r);
      ss.erase(r);
      if (ap > l) ss[ap] = l;
      if (ap + 1 < r) ss[r] = ap + 1;
      i++;
    }
  }
  printf("%d\n", ans);
}

void input() {
  scanf("%d%d%d", &N, &K, &Q);
  REP(i, N) scanf("%d", A + i);
}

int main() {
  input();
  solve();
  return 0;
}

