        if(st < 0) st++;

        int en = i;
        stop_to_count = false;
        for(; en < n; en++){
            if(origin_arr[en] < origin_arr[i] && memo[origin_arr[en]] == 0) {
                stop_to_count = true;
            }
            if(!stop_to_count && origin_arr[en] >= origin_arr[i]) real_count++;
            if(origin_arr[en] >= origin_arr[i]) count++;
            if(origin_arr[en] < origin_arr[i]) rev_count++;
        }

        if(real_count > k) {
            memo[origin_arr[i]] = 1;
        } else if(count > k && rev_count <= q - 1){
