bool check(const vector< vector<int> >& kek, int x) {
    int res = 0;

    for (auto& v : kek)
        res += min(int(upper_bound(v.begin(), v.end(), x) - v.begin()), max(0, sz(v) - k + 1));

    return res >= q;
}

ll calc(int x) {
    vector< vector<int> > kek;
    kek.push_back(vector<int>());

    forn (i, n)
        if (a[i] < x) {
            if (!kek.back().empty())
                kek.push_back(vector<int>());
        } else {
            kek.back().push_back(a[i]);
        }

    for (auto& v : kek)
        sort(v.begin(), v.end());

    if (!check(kek, INF))
        return INF;

    ll l = x, r = INF;

    for (; l < r; ) {
        auto m = (l + r) / 2;

        if (check(kek, m))
            r = m;
        else
            l = m + 1;
    }

    return r - x;
}

void solve() {
    ll ans = INF;

    forn (i, n)
        ans = min(ans, calc(a[i]));

    cout << ans << endl;
}

