template<class Type>
Type solve(Type res = Type()){
    ll N,K,Q; cin >> N >> K >> Q;
    vector<ll> A(N);
    vector<ll> B(N);
    for(int i = 0 ; i<N;i++){
        cin >> A[i];
    }
    B = A;
    sort(A.begin(),A.end());
    res = LINF;
    for(int i = 0; i < N;i++){
        vector<vector<ll>> vals;
        vector<ll> now;
        for(int j = 0; j < N;j++){
            if(B[j] < A[i]){
                vals.push_back(now);
                now.clear();
            }else{
                now.push_back(B[j]);
            }
        }
        vals.push_back(now);

        vector<ll> V;
        for(auto& vec:vals){
            sort(vec.begin(),vec.end());
            int sz = (int)vec.size();
            for(int j = 0; j <= sz-K;j++){
                V.push_back(vec[j]);
            }
        }
        sort(V.begin(),V.end());
        if(V.size() < Q) break;
        res = min(res,V[Q-1] - V[0]);

    }
    return res;
}
