		if(i<mn)mark[id[i]]=-1;
		else if(i>mx)mark[id[i]]=1;
		else mark[id[i]]=0;
	int last=0,cnt=0,tot=0;
	for(int i=1;i<=n;i++)
		if(mark[i]==-1){
			tot+=std::min(std::max((i-last-1)-(k-1),0),cnt);
