const int MAX=2003;
const int MOD=1000000007;
int N,K,Q,A[MAX];
vector<pii> arr;
queue<pii> rng;
vector<int> det[MAX];
priority_queue<pii> seg;
int ans=MOD,pos[MAX],pt[MAX];
main(){
    scanf(" %d %d %d",&N,&K,&Q);
    for(int i=0;i<N;i++) scanf(" %d",&A[i]), arr.push_back(make_pair(A[i],i));
    sort(arr.begin(),arr.end());
    rng.push(make_pair(0,N));
    for(int i=0;i<N;i++){
        int fin=0;
        for(int j=0;j<=i;j++){
            pii tmp=rng.front();
            rng.pop();
            rng.push(tmp);
            det[j].clear();
            for(int k=tmp.first;k<tmp.second;k++) det[j].push_back(A[k]);
            sort(det[j].begin(),det[j].end());
            pos[j]=tmp.second-tmp.first-K+1; pt[j]=0;
            if(pos[j]>0) seg.push(make_pair(-det[j][0],j));
        }
        int mmin=MOD,mmax=0;
        for(int j=0;j<Q;j++){
            if(seg.empty()){
                fin=1;
                break;
            }
            pii tmp=seg.top();
            seg.pop();
            mmin=min(-tmp.first,mmin);
            mmax=-tmp.first;
            pt[tmp.second]++;
            //printf("%d %d %d %d\n",tmp.first,tmp.second,pt[tmp.second],pos[tmp.second]);
            if(pt[tmp.second]<pos[tmp.second]) seg.push(make_pair(-det[tmp.second][pt[tmp.second]],tmp.second));
        }
        if(fin) break;
        ans=min(ans,mmax-mmin);
        while(!seg.empty()){seg.pop();}
        for(int j=0;j<=i;j++) {
            pii tmp=rng.front();
            rng.pop();
            if(tmp.first<=arr[i].second&&arr[i].second<tmp.second){
                rng.push(make_pair(tmp.first,arr[i].second));
                rng.push(make_pair(arr[i].second+1,tmp.second));
            }
            else rng.push(tmp);
        }
    }
    printf("%d\n",ans);
}

