void add(int x, int& pos, vector<int>& v)
{
	priority_queue<int, vector<int>, greater<int>> q;
	for (; pos < N && A[pos] >= x; pos++) {
		q.push(A[pos]);
	}
	int l = q.size();
	rep(i, l-K+1) {
		v.PB(q.top());
		q.pop();
	}
}

int calc(int x)
{
	vector<int> v;
	for (int pos = 0; pos < N; pos++) {
		while (pos < N && A[pos] < x) pos++;
		add(x, pos, v);
	}
//	rep(i, v.size()) {
//		cout << v[i] << " ";
//	}
//	cout << endl;
	if ((int) v.size() < Q) {
		return INF;
	}
	sort(all(v));
	return v[Q-1] - x;
}

void solve()
{
	int res = INF;
	rep(i, N) {
		res = min(res, calc(A[i]));
	}
	cout << res << endl;
}

