void solve() {
    int N, K, Q; cin >> N >> K >> Q;
    if(Q == 1) {
        cout << 0 << endl;
        return;
    }
    vector<int> A(N), B(N);
    rep(i, N) {
        cin >> A[i];
        B[i] = A[i];
    }
    sort(all(B));
    int ans = B[Q - 1] - B[0];
    rep(i, N) {
        int X = B[i];
        vector<int> vec, res;
        rep(j, N) {
            if(A[j] > X) {
                vec.pb(A[j]);
            } else {
                sort(all(vec));
                int M = vec.size();
                rep(k, M - K + 1) {
                    res.pb(vec[k]);
                }
                vec.resize(0);
            }
        }
        sort(all(res));
        if(Q - 1 > res.size()) continue;
        int Y = res[Q - 1];
        int ret = Y - X;
        ans = min(ans, ret);
    }
    cout << ans << endl;
}

