using namespace std;

const int MAXN = 2000;

int a[MAXN + 1], n, k, q;

bool check(int mn, int mx) {
    multiset<pair<int, int> > s;
    for (int i = 0; i < k; i++) {
        s.insert({ a[i], i });
    }
    int nxt = k;
    int j = 0;
    for (int i = 0; i + k - 1 < n && j < q; i++) {
        if (s.size() < k) {
            break;
        }
        if (mn <= s.begin()->first && s.begin()->first <= mx) {
            s.erase(s.begin());
            --i;
            ++j;
        } else if (s.find({ a[i], i }) != s.end()) {
            s.erase(s.find({ a[i], i }));
        }
        if (nxt < n) {
            s.insert({ a[nxt], nxt });
            ++nxt;
        }
    }

    return j == q;
}

