void Dfs( int cnt ){
	//Print();
	if( cnt == q ) return;
	int del = INF,v = 0;
	int i = pre[n+1];
	while(i){
		int tmin = a[i];
		int j = nxt[i],cnt = 1;
		int pos = i;
		while( j < n+1  &&  cnt < k ){
			cnt++;
			if( tmin > a[j] ){
				tmin = a[j];
				pos = j;
			}
			//cout << j << endl;
			j = nxt[j];
		}
		i = pre[i];
		if( cnt < k  ||  tmin < st ) continue;
		int tdel = abs(tmin-st);
		if( tdel < del ){
			del = tdel;
			v = pos;
		}
	}
	if( v == 0 ){
		fail = 1;
		return;
	}
	Delnum(v);
