class Program {
    fun solve() {
        val sc = MyScanner()
        val n = sc.nextInt()
        val k = sc.nextInt()
        val q = sc.nextInt()
        val a = sc.intArray()
        var ans = Int.MAX_VALUE

        for (i in 0 until n) {
            val pq = PriorityQueue<Int>(16)
            var tmp = PriorityQueue<Int>(16)
            var f = false
            for (j in 0 until n) {
                if (a[i] <= a[j]) {
                    if (!f) {
                        f = true
                        tmp = PriorityQueue<Int>(16)
                    }
                    tmp.add(a[j])
                } else {
                    if (f) {
                        while (tmp.size >= k) {
                            pq.add(tmp.poll())
                        }
                        f = false
                    }
                }
            }
            if(f){
                while (tmp.size >= k) {
                    pq.add(tmp.poll())
                }
            }
            if (pq.size >= q) {
                val min = pq.peek()
                for (j in 0 until q - 1) pq.poll()
                val max = pq.peek()
                ans = Math.min(ans, max - min)
            }
        }
        println(ans)
    }
}

