public class Main {


    public void solve(int testNumber, InputReader in, OutputWriter out) {

        int n = in.nextInt();


        int k = in.nextInt();

        int q = in.nextInt();

        Integer[] a = new Integer[n];
        int[] b = new int[n];

        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
            b[i] = a[i];
        }

        Arrays.sort(a);

        long ans = a[n - 1] - a[0];

        for (int i = 0; i < n; i++) {

//            int lo = i;
//            int hi = n - 1;
//
//            while (lo <= hi) {
//                int mid = (lo + hi) / 2;

            int lii = -1;
            long ca = 0;

            List<Integer> cl = new ArrayList<>();
            List<Integer> cll = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (b[j] < a[i]) {
                    int sl = j - lii - 1;

                    if (sl >= k) {
                        ca += sl - k + 1;
                        cl.addAll(cll);
                    }
                    cll.clear();

                    lii = j;
                } else {
                    cll.add(b[j]);
                }
            }

            int sl = n - lii - 1;

            if (sl >= k) {
                cl.addAll(cll);
                ca += sl - k + 1;
            }

            if (ca >= q) {
                cl.sort((x, y) -> x - y);
                ans = Math.min(ans, cl.get(q - 1) - cl.get(0));
            }
        }

        System.out.println(ans);
    }

