import java.util.function.LongUnaryOperator;

class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        int k = in.nextInt();
        int q = in.nextInt();
        int[] a = in.nextIntArray(n);
        long ans = inf;
        for (int i = 0; i < n; i++) {
            int left = a[i], right = 2000000000;
            while (right - left > 1) {
                int mid = (left + right) / 2;
                int cl = 0;
                int ch = 0;
                int can = 0;
                for (int j = 0; j < n; j++) {
                    if (a[i] > a[j]) {
                        can += Math.min(cl + ch - k + 1, cl);
                        cl = 0;
                        ch = 0;
                    } else if (mid >= a[j]) {
                        cl++;
                    } else {
                        ch++;
                    }
                }
                can += Math.min(cl + ch - k + 1, cl);
                if (can >= q) {
                    right = mid;
                } else {
                    left = mid;
                }
            }
            if (right < 2000000000) {
                ans = Math.min(ans, right - a[i]);
            }
        }
        out.println(ans);
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

