	static final int[] DX8 = { -1, -1, -1, 0, 0, 1, 1, 1 }, DY8 = { -1, 0, 1, -1, 1, -1, 0, 1 };
	static final int INF = Integer.MAX_VALUE / 2;
	static final long LINF = Long.MAX_VALUE / 3;
	static final String nextLine = "\n";

	public static void main(String[] args) {
		FastScanner fs = new FastScanner(System.in);
		int n = fs.nextInt(), k = fs.nextInt(), q = fs.nextInt();
		int a[] = fs.nextIntArray(n);

		PriorityQueue<Integer> pq = new PriorityQueue<>();
		for(int i=0;i<n;i++) pq.add(a[i]);

		long ans = LINF;
		while(!pq.isEmpty()) {
			int min = pq.poll();
			List<ArrayList<Integer>> ls = new ArrayList<>();
			ls.add(new ArrayList<>());
			int p = 0;
			List<Integer> maxs = new ArrayList<>();
			for(int i=0;i<n;i++) {
				if(a[i]<min) {
					if(!ls.get(p).isEmpty()) {
						ls.add(new ArrayList<Integer>());
						p++;
					}
				}
				else {
					ls.get(p).add(a[i]);
				}
			}
			for(int i=0;i<ls.size();i++) {
				List<Integer> now = ls.get(i);
				Collections.sort(now);
				while(now.size()>=k) {
					maxs.add(now.get(0));
					now.remove(0);
				}
			}
			Collections.sort(maxs);
			if(maxs.size()>=q&&maxs.get(0)==min) {
				int max = maxs.get(q-1);
				ans = Math.min(ans, max - min);				
			}
		}
		System.out.println(ans);
	}

	//MOD culculations
	static long plus(long x, long y) {
		long res = (x + y) % mod;
		return res < 0 ? res + mod : res;
	}

	static long sub(long x, long y) {
		long res = (x - y) % mod;
		return res < 0 ? res + mod : res;
	}

	static long mul(long x, long y) {
		long res = (x * y) % mod;
		return res < 0 ? res + mod : res;
	}

	static long div(long x, long y) {
		long res = x * pow(y, mod - 2) % mod;
		return res < 0 ? res + mod : res;
	}

	static long pow(long x, long y) {
		if (y < 0)
			return 0;
		if (y == 0)
			return 1;
		if (y % 2 == 1)
			return (x * pow(x, y - 1)) % mod;
		long root = pow(x, y / 2);
		return root * root % mod;
	}
}

//高速なScanner
class FastScanner {
	private BufferedReader reader = null;
	private StringTokenizer tokenizer = null;

	public FastScanner(InputStream in) {
		reader = new BufferedReader(new InputStreamReader(in));
		tokenizer = null;
	}

	public String next() {
		if (tokenizer == null || !tokenizer.hasMoreTokens()) {
			try {
				tokenizer = new StringTokenizer(reader.readLine());
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
		}
		return tokenizer.nextToken();
	}

	public String nextLine() {
		if (tokenizer == null || !tokenizer.hasMoreTokens()) {
			try {
				return reader.readLine();
			} catch (IOException e) {
				throw new RuntimeException(e);
			}
		}
		return tokenizer.nextToken("\n");
	}

	public long nextLong() {
		return Long.parseLong(next());
	}

	public int nextInt() {
		return Integer.parseInt(next());
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}

	public int[] nextIntArray(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)
			a[i] = nextInt();
		return a;
	}

	public long[] nextLongArray(int n) {
		long[] a = new long[n];
		for (int i = 0; i < n; i++)
			a[i] = nextLong();
		return a;
	}
}

