import java.util.PriorityQueue;


public class Main {
  private static void solve() {
    int n = ni();
    int k = ni();
    int q = ni();
    int[] a = na(n);
    int[][] b = new int[n][2];
    for (int i = 0; i < n; i++) {
      b[i][0] = a[i];
      b[i][1] = i;
    }
    Arrays.sort(b, (o1, o2) -> o1[0] - o2[0]);
    int ret = Integer.MAX_VALUE;
    loop: for (int i = 0; i < n; i++) {
      boolean[] ok = new boolean[n];
      Arrays.fill(ok, true);
      int min = b[i][0];
      for (int j = 0; j < n; j++) {
        if (a[j] < min) {
          ok[j] = false;
        }
      }

      Map<int[], Integer> ptr = new HashMap<>();
      PriorityQueue<int[]> queue = new PriorityQueue<>((o1, o2) -> {
        if (o1[0] - o2[0] == 0)
          return o1.hashCode() - o2.hashCode();
        else
          return o1[ptr.get(o1)] - o2[ptr.get(o2)];
      });
      for (int s = 0; s < n;) {
        int e = s;
        for (; e < n && ok[e]; e++) {
        }
        if (e == s) {
          s ++;
          continue;
        }

        if (e - s >= k) {
          int[] arr = Arrays.copyOfRange(a, s, e);
          Arrays.sort(arr);
          ptr.put(arr, 0);
          queue.add(arr);
        }
        s = e;
      }

      int x = Integer.MAX_VALUE;
      int y = 0;
      for (int j = 0; j < q; j ++) {
        int[] v = queue.poll();
        if (v == null) {
          continue loop;
        }
        int p = ptr.get(v);
        x = Math.min(x, v[p]);
        y = Math.max(y, v[p]);

        if (v.length - p > k) {
          ptr.put(v, p + 1);
          queue.add(v);
        }
      }
      ret = Math.min(ret, y - x);
    }
    System.out.println(ret);
  }

