import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		int n = Integer.parseInt(sa[0]);
		int k = Integer.parseInt(sa[1]);
		int q = Integer.parseInt(sa[2]);
		sa = br.readLine().split(" ");
		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = Integer.parseInt(sa[i]);
		}
		br.close();

		int[] b = new int[n];
		System.arraycopy(a, 0, b, 0, n);
		Arrays.parallelSort(b);

		int ok = 0;
		int ng = b.length;

		while (Math.abs(ng - ok) > 1) {
			int mid = (ng + ok) / 2;
			int min = b[mid];
			int cnt = 0;
			int sum = 0;
			boolean flg = false;
			boolean flg2 = false;
			for (int i = 0; i < n; i++) {
				if (a[i] == min) {
					flg = true;
					cnt++;
				} else if (a[i] > min) {
					cnt++;
				} else {
					int rem = Math.max(cnt - k + 1, 0);
					if (flg && rem > 0) {
						flg2 = true;
					}
					sum += rem;
					cnt = 0;
					flg = false;
				}
			}
			sum += Math.max(cnt - k + 1, 0);
			if (flg2 && sum >= q) {
				ok = mid;
			} else {
				ng = mid;
			}
		}
		int min = b[ok];

		int ans = b[n - 1] - b[0];
		for (int i = 0; i + q - 1 < n; i++) {
			if (b[i] > min) {
				break;
			}
			int val = b[i + q - 1] - b[i];
			ans = Math.min(ans, val);
		}
		System.out.println(ans);
	}
}

import java.util.Arrays;
import java.util.Comparator;
import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

	void run() {
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int K = sc.nextInt();
		int Q = sc.nextInt();
		int[] A = new int[N];
		int ans = Integer.MAX_VALUE;
		for (int i = 0; i < N; ++i) {
			A[i] = sc.nextInt();
		}
		for (int trial = 0; trial < N; ++trial) {
			PriorityQueue<PriorityQueue<Integer>> pq = new PriorityQueue<>(new Comparator<PriorityQueue<Integer>>() {
				@Override
				public int compare(PriorityQueue<Integer> o1, PriorityQueue<Integer> o2) {
					return Integer.compare(o1.peek(), o2.peek());
				}
			});
			for (int i = 0; i < N; ++i) {
				int t = i;
				PriorityQueue<Integer> tmp = new PriorityQueue<>();
				while (t < N && A[t] >= A[trial]) {
					tmp.add(A[t]);
					++t;
				}
				if (tmp.size() >= K) {
					pq.add(tmp);
				}
				i = t;
			}
			int cnt = 0;
			int max = 0;
			while (cnt < Q && !pq.isEmpty()) {
				PriorityQueue<Integer> cand = pq.poll();
				++cnt;
				max = Math.max(max, cand.poll());
				if (cand.size() >= K)
					pq.add(cand);
			}
			if (cnt == Q) {
				ans = Math.min(ans, max - A[trial]);
			}
		}
		System.out.println(ans);
	}

	public static void main(String[] args) {
		new Main().run();
	}

	void tr(Object... objects) {
		System.out.println(Arrays.deepToString(objects));
	}
}

