    void solve() {
        int n = in.nextInt();
        int k = in.nextInt();
        int q = in.nextInt();
        int[] a = in.nextIntArray(n);
        long ans = inf;
        for (int i = 0; i < n; i++) {
            long left = a[i], right = 2000000000;
            while (right - left > 1) {
                long mid = (left + right) / 2;
                int cl = 0;
                int ch = 0;
                int can = 0;
                for (int j = 0; j < n; j++) {
                    if (a[i] > a[j]) {
