public class Main {

	public static void main(String[] args) throws IOException {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		MyInput in = new MyInput(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		TaskX solver = new TaskX();
		solver.solve(1, in, out);
		out.close();
	}

	static int INF = 1 << 30;
	static long LINF = 1L << 55;
	static int MOD = 1000000007;
	static int[] mh4 = { 0, -1, 1, 0 };
	static int[] mw4 = { -1, 0, 0, 1 };
	static int[] mh8 = { -1, -1, -1, 0, 0, 1, 1, 1 };
	static int[] mw8 = { -1, 0, 1, -1, 1, -1, 0, 1 };

	static class TaskX {

		int n, k ,q;
		Set<Integer> set = new HashSet<>();
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			n = in.nextInt(); k = in.nextInt(); q = in.nextInt();
			List<List<Integer>> lists = new ArrayList<>();
			List<Integer> tmp = new ArrayList<>();
			List<Integer> slist = new ArrayList<>();
			for (int i = 0; i < n; i++) {
				int num = in.nextInt();
				tmp.add(num);
				slist.add(num);
			}
			lists.add(tmp);
			slist.add(-1);
			Collections.sort(slist);

			long ans = LINF;
			for (int num : slist) {
				if (set.contains(num)) continue;
				set.add(num);

				List<List<Integer>> newLists = split(lists, num);
				List<Integer> tar = new ArrayList<>();
				for (List<Integer> list : newLists) {
					int m = list.size();
					tmp = new ArrayList<>(list);
					Collections.sort(tmp);
					for (int i = 0; i < m - k + 1; i++) tar.add(tmp.get(i));
				}
				Collections.sort(tar);
				if (tar.size() >= q) {
					ans = Math.min(ans, tar.get(q-1) - tar.get(0));
				}
				lists = new ArrayList<>(newLists);
			}

			out.println(ans);
		}

		List<List<Integer>> split(List<List<Integer>> lists, int num) {
			List<List<Integer>> newLists = new ArrayList<>();
			for (List<Integer> list : lists) {
				int from = 0;
				for (int i = 0; i < list.size(); i++) {
					if (list.get(i) == num) {
						if (from == i) {
							from = i+1;
							continue;
						}
						newLists.add(list.subList(from, i));
						from = i+1;
					}
				}
				newLists.add(list.subList(from, list.size()));
			}
			return newLists;
		}
	}

	static class MyInput {
		private final BufferedReader in;
		private static int pos;
		private static int readLen;
