	private static void solve() {
		int n = nei();
		int k = nei();
		int q = nei();
		int[] as = nis(n);
		TreeSet<Integer> nums = new TreeSet<Integer>();
		for (int i = 0; i < n; i++) {
			nums.add(as[i]);
		}
		int[] sorted = new int[nums.size()];
		int cnt = 0;
		for (Integer aaa : nums) {
			sorted[cnt++] = aaa;
		}
		Arrays.sort(sorted);
		int m = sorted.length;
		int ans = Integer.MAX_VALUE;
		for (int i = 0; i < m; i++) {
			int x = sorted[i];
			int min = i - 1; // excl
			int max = m - 1; // incl
			while (max - min > 1) {
				int mid = min + max >> 1;
				int y = sorted[mid];
				if (isOk(as, n, x, y, k, q)) {
					max = mid;
				} else {
					min = mid;
				}
			}
			int y = sorted[max];
			if (!isOk(as, n, x, y, k, q))
				continue;
			ans = min(ans, y - x);
		}
		out(ans);
	}

	static boolean isOk(int[] as, int n, int min, int max, int k, int q) {
		int prev;
		int next = -1;
		int total = 0;

		while (next < n) {
			prev = next;
			next = prev + 1;
			while (next < n) {
				if (as[next] < min)
					break;
				next++;
			}

			int interval = next - prev - 1;
			int maxSelect = interval - k + 1;
			int count = 0;
			for (int i = prev + 1; i < next; i++) {
				if (as[i] <= max)
					count++;
			}
			total += min(maxSelect, count);
		}

		return total >= q;
	}

	static int[] lis(int[] s) {
		int n = s.length;
		int[] dp = new int[n];
		int[] ids = new int[n];
		int[] pids = new int[n];
		dp[0] = s[0];
		int len = 1;
		int lidx = 0;
		for (int i = 1; i < n; i++) {
			int idx = bs(s[i], dp, 0, len);
			dp[idx] = s[i];
			ids[idx] = i;
			if (idx == len) {
				lidx = i;
				len++;
			}
			if (idx > 0)
				pids[i] = ids[idx - 1];
		}
		int[] lis = new int[len];
		lis[len - 1] = s[lidx];
		for (int i = len - 1; i >= 0; i--) {
			lis[i] = s[lidx];
			lidx = pids[lidx];
		}
		return lis;
	}

	static int bs(int a, int[] as, int from, int num) {
		int min = from;
		int max = from + num - 1;
		while (min < max) {
			int mid = min + max >> 1;
			if (as[mid] < a)
				min = mid + 1;
			else if (as[mid] > a)
				max = mid;
			else
				return mid;
		}
		return as[min] < a ? min + 1 : min;
	}

	static int gcd(int x, int y) {
		x = (x ^ x >> 31) - (x >> 31);
		y = (y ^ y >> 31) - (y >> 31);
		if (x < y) {
			x ^= y;
			y ^= x;
			x ^= y;
		}
		int z = x % y;
		if (z == 0)
			return y;
		return gcd(y, z);
	}

	static long gcd(long x, long y) {
		x = (x ^ x >> 63) - (x >> 63);
		y = (y ^ y >> 63) - (y >> 63);
		if (x < y) {
			x ^= y;
			y ^= x;
			x ^= y;
		}
		long z = x % y;
		if (z == 0)
			return y;
		return gcd(y, z);
	}

	static int lcm(int x, int y) {
		x = (x ^ x >> 31) - (x >> 31);
		y = (y ^ y >> 31) - (y >> 31);
		return x / gcd(x, y) * y;
	}

	static long lcm(long x, long y) {
		x = (x ^ x >> 63) - (x >> 63);
		y = (y ^ y >> 63) - (y >> 63);
		return x / gcd(x, y) * y;
	}

