class UnionFind {
	int[] parent;
	int[] rank;
	UnionFindRoot[] root;

	UnionFind(int n) {
		parent = new int[n];
		root = new UnionFindRoot[n];
		rank = new int[n];

		for (int i = 0; i < n; i++) {
			parent[i] = i;
			root[i] = new UnionFindRoot(i);
		}
	}

	int rootIndex(int i) {
		int p = parent[i];
		if (i == p) {
			return i;
		}
		return parent[i] = rootIndex(p);
	}

	UnionFindRoot root(int i) {
		int p = parent[i];
		if (i == p) {
			return root[i];
		}
		return root[parent[i] = rootIndex(p)];
	}

	void union(int i, int j) {
		int root1 = rootIndex(i);
		int root2 = rootIndex(j);

		if (root2 == root1)
			return;

		UnionFindRoot newRoot = root[root1].combine(root[root2]);

		if (rank[root1] > rank[root2]) {
			parent[root2] = root1;
			root[root1] = newRoot;
		} else if (rank[root2] > rank[root1]) {
			parent[root1] = root2;
			root[root2] = newRoot;
		} else {
			parent[root2] = root1;
			root[root1] = newRoot;
			rank[root1]++;
		}
	}

	int size(int x) {
		return root(x).size;
	}

	class UnionFindRoot {
		int size;

		UnionFindRoot(int index) {
			size = 0;
		}

		UnionFindRoot combine(UnionFindRoot another) {
			UnionFindRoot newRoot = new UnionFindRoot(0);
			newRoot.size = size + another.size;
			return newRoot;
		}
	}
}

final class IO {
	private static final InputStream in = System.in;
	private static final PrintWriter out = new PrintWriter(System.out, false);
	private static final byte[] buffer = new byte[1024];
	private static int ptr = 0;
	private static int len = 0;

	private static boolean hasNextByte() {
		if (ptr < len)
			return true;
		ptr = 0;
		try {
			len = in.read(buffer);
		} catch (IOException e) {
			e.printStackTrace();
		}
		return len > 0;
	}

	private static int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	static boolean hasNext() {
		byte c;
		while (hasNextByte() && ((c = buffer[ptr]) < '!' || c > '~'))
			ptr++;
		return hasNextByte();
	}

	static String next() {
		if (!hasNext())
			throw new NoSuchElementException();
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (b >= '!' && b <= '~') {
			sb.append((char) b);
			b = readByte();
		}
		return sb.toString();
	}

	static char nextChar() {
		if (!hasNext())
			throw new NoSuchElementException();
		return (char) readByte();
	}

	static long nextLong() {
		if (!hasNext())
			throw new NoSuchElementException();
		long n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static int nextInt() {
		if (!hasNext())
			throw new NoSuchElementException();
		int n = 0;
		int sign = 1;
		int b = readByte();
		if (b == '-') {
			sign = -1;
			b = readByte();
		}
		if (b < '0' || '9' < b)
			throw new NumberFormatException();
		while (true) {
			if ('0' <= b && b <= '9')
				n = n * 10 + b - '0';
			else if (b == -1 || b < '!' || b > '~')
				return n * sign;
			else
				throw new NumberFormatException();
			b = readByte();
		}
	}

	static double nextDouble() {
		return Double.parseDouble(next());
	}

	static void out(String val) {
		out.println(val);
	}

	static void flush() {
		out.flush();
	}
}

import java.io.*;
import java.util.*;

class Solver {
  final int n, k, q;
  final int[] as;

  Solver(int n, int k, int q, int[] as) {
    this.n = n;
    this.k = k;
    this.q = q;
    this.as = as;
  }

  private int solve(int aThreshold) {
    PriorityQueue<PriorityQueue<Integer>> queueQueue = new PriorityQueue<PriorityQueue<Integer>>(
      new Comparator<PriorityQueue<Integer>>() {
        public int compare(PriorityQueue<Integer> q1, PriorityQueue<Integer> q2) {
          return q1.peek() - q2.peek();
        }
      }
    );
    PriorityQueue<Integer> queue = new PriorityQueue<>();
    for (int a : as) {
      if (a < aThreshold) {
        if (queue.size() >= k) {
          queueQueue.add(queue);
        }
        queue = new PriorityQueue<>();
      } else {
        queue.add(a);
      }
    }
    if (queue.size() >= k) {
      queueQueue.add(queue);
    }

    int minValue = Integer.MAX_VALUE;
    int maxValue = 0;
    for (int i = 0; i < q; i++) {
      queue = queueQueue.poll();
      if (queue == null) {
        return Integer.MAX_VALUE;
      }
      int v = queue.poll();
      minValue = Math.min(minValue, v);
      maxValue = Math.max(maxValue, v);
      if (queue.size() >= k) {
        queueQueue.add(queue);
      }
    }
    return maxValue - minValue;
  }

  public int solve() {
    int answer = Integer.MAX_VALUE;
    for (int a : as) {
      answer = Math.min(answer, solve(a));
    }
    return answer;
  }
}

