    private void solve() throws IOException {
//        Random rnd = new Random(322);
//        int n = 2000;
//        int k = 1900;
//        int q = 1000;
//        int[] originalA = new int[n];
//        for (int i = 0; i < n; i++) {
//            originalA[i] = rnd.nextInt(1000 * 1000 * 1000);
