        int i = 1;
        for(; i<=n-k-q+1; i++){
            //避けられるなら次
            if(simyu(i, b, n, k, q)) continue;
            //
            break;
        }

        //System.out.println(i);


        long ans = inf;
        for(int j=0; j<i; j++){
            long tmp = b[j+q-1].val - b[j].val;
            ans = Math.min(ans, tmp);
        }

        System.out.println(ans);
    }

    public static boolean simyu(int ti, Val_idx[] b, int n, int k, int q){
        int[] c = new int[ti+2];
        for(int i=0; i<ti; i++){
            c[i+1] = b[i].idx;
        }
        c[0] = -1;
        c[ti+1] = n;

        int sum = 0;
        for(int i=0; i<c.length-1; i++){
            int tmp = c[i+1] - c[i] - k;
            sum += Math.max(0, tmp);
        }

        if(sum >= q){
            return true;
        }else{
            return false;
        }
    }
}

