import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.InputMismatchException;
import java.util.NoSuchElementException;
import java.util.PriorityQueue;

public class Main {

	public static void main(String[] args) {
		IO io = new IO();
		int n = io.nextInt();
		int k = io.nextInt();
		int q = io.nextInt();
		int[] a = new int[n+1];
		for(int i=0;i<n;i++) a[i] = io.nextInt();
		a[n] = -1;
		int ans = Integer.MAX_VALUE;
		for(int ix=0;ix<n;ix++) {
			int x = a[ix];
			PriorityQueue<Integer> pq = new PriorityQueue<>();
			ArrayList<Integer> al = new ArrayList<>();
			int l = 0;
			for(int r=0;r<=n;r++) {
				if (a[r] < x) {
					int count = r - l - k + 1;
					if (count > 0) {
						al.sort(null);
						for(int i=0;i<count;i++) {
							pq.add(al.get(i));
						}
					}
					al.clear();
					l = r + 1;
				}else {
					al.add(a[r]);
				}
			}
			int y = 0;
			if (pq.size() >= q) {
				for(int i=0;i<q;i++) {
					y = pq.poll();
				}
				ans = Math.min(ans, y - x);
			}
		}
		System.out.println(ans);
	}

}
class IO extends PrintWriter {
	private final InputStream in;
	private final byte[] buffer = new byte[1024];
	private int ptr = 0;
	private int buflen = 0;

	public IO() {
		this(System.in);
	}

	public IO(InputStream source) {
		super(System.out);
		this.in = source;
	}

	private boolean hasNextByte() {
		if (ptr < buflen) {
			return true;
		} else {
			ptr = 0;
			try {
				buflen = in.read(buffer);
			} catch (IOException e) {
				e.printStackTrace();
			}
			if (buflen <= 0) {
				return false;
			}
		}
		return true;
	}

	private int readByte() {
		if (hasNextByte())
			return buffer[ptr++];
		else
			return -1;
	}

	private static boolean isPrintableChar(int c) {
		return 33 <= c && c <= 126;
	}

	private static boolean isNewLine(int c) {
		return c == '\n' || c == '\r';
	}

	public boolean hasNext() {
		while (hasNextByte() && !isPrintableChar(buffer[ptr]))
			ptr++;
		return hasNextByte();
	}

	public boolean hasNextLine() {
		while (hasNextByte() && isNewLine(buffer[ptr]))
			ptr++;
		return hasNextByte();
	}

	public String next() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (isPrintableChar(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public char[] nextCharArray(int len) {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		char[] s = new char[len];
		int i = 0;
		int b = readByte();
		while (isPrintableChar(b)) {
			if (i == len) {
				throw new InputMismatchException();
			}
			s[i++] = (char) b;
			b = readByte();
		}
		return s;
	}

	public String nextLine() {
		if (!hasNextLine()) {
			throw new NoSuchElementException();
		}
		StringBuilder sb = new StringBuilder();
		int b = readByte();
		while (!isNewLine(b)) {
			sb.appendCodePoint(b);
			b = readByte();
		}
		return sb.toString();
	}

	public long nextLong() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		long n = 0;
		boolean minus = false;
		int b = readByte();
		if (b == '-') {
			minus = true;
			b = readByte();
		}
		if (b < '0' || '9' < b) {
			throw new NumberFormatException();
		}
		while (true) {
			if ('0' <= b && b <= '9') {
				n *= 10;
				n += b - '0';
			} else if (b == -1 || !isPrintableChar(b)) {
				return minus ? -n : n;
			} else {
				throw new NumberFormatException();
			}
			b = readByte();
		}
	}

	public int nextInt() {
		long nl = nextLong();
		if (nl < Integer.MIN_VALUE || nl > Integer.MAX_VALUE) {
			throw new NumberFormatException();
		}
		return (int) nl;
	}

	public char nextChar() {
		if (!hasNext()) {
			throw new NoSuchElementException();
		}
		return (char) readByte();
	}

	public double nextDouble() {
		return Double.parseDouble(next());
	}

	public int[] nextIntArray(int n) {
		int[] a = new int[n];
		for (int i = 0; i < n; i++)
			a[i] = nextInt();
		return a;
	}

	public long[] nextLongArray(int n) {
		long[] a = new long[n];
		for (int i = 0; i < n; i++)
			a[i] = nextLong();
		return a;
	}

	public double[] nextDoubleArray(int n) {
		double[] a = new double[n];
		for (int i = 0; i < n; i++)
			a[i] = nextDouble();
		return a;
	}

	public void nextIntArrays(int[]... a) {
		for (int i = 0; i < a[0].length; i++)
			for (int j = 0; j < a.length; j++)
				a[j][i] = nextInt();
	}

	public int[][] nextIntMatrix(int n, int m) {
		int[][] a = new int[n][];
		for (int i = 0; i < n; i++)
			a[i] = nextIntArray(m);
		return a;
	}

	public char[][] nextCharMap(int n, int m) {
		char[][] a = new char[n][];
		for (int i = 0; i < n; i++)
			a[i] = nextCharArray(m);
		return a;
	}

	public void close() {
		super.close();
		try {
			in.close();
		} catch (IOException e) {
		}
	}
}

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.*;

public class Main {
    int n, k, q;
    int[] as;

    public static void main(String args[]) {
        new Main().run();
    }

    void run() {
        FastReader sc = new FastReader();
        n = sc.nextInt();
        k = sc.nextInt();
        q = sc.nextInt();
        as = new int[n];
        for (int i = 0; i < n; i++) {
            as[i] = sc.nextInt();
        }
        solve();
    }

    void solve() {
        int[] bs = as.clone();
        Arrays.sort(bs);
        int prevMin = -1;
        int diff = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            int minNum = bs[i];
            if (prevMin == minNum) {
                prevMin = minNum;
                continue;
            }
            prevMin = minNum;
            int l = 0;
            List<Integer> candidates = new ArrayList<>();
            PriorityQueue<Integer> pQueue = new PriorityQueue<>();
            for (int j = 0; j <= n; j++) {
                if (j == n || as[j] < minNum) {
                    if (j - l >= k) {
                        PriorityQueue<Integer> tempQueue = new PriorityQueue<>();
                        for (int m = l; m < j; m++) {
                            tempQueue.offer(as[m]);
                        }
                        for (int m = 0; m < j - l - k + 1; m++) {
                            candidates.add(tempQueue.poll());
                        }
                    }
                    l = j + 1;
                }
            }
            if (candidates.size() < q) {
                continue;
            }
            Collections.sort(candidates);
            int tempDiff = candidates.get(q - 1) - candidates.get(0);
            if (tempDiff < diff) {
                diff = tempDiff;
            }
        }
        System.out.println(diff);
    }

    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new
                    InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements())
            {
                try
                {
                    st = new StringTokenizer(br.readLine());
                }
                catch (IOException e)
                {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt()
        {
            return Integer.parseInt(next());
        }

        long nextLong()
        {
            return Long.parseLong(next());
        }

        double nextDouble()
        {
            return Double.parseDouble(next());
        }

        String nextLine() {
            String str = "";
            try
            {
                str = br.readLine();
            }
            catch (IOException e)
            {
                e.printStackTrace();
            }
            return str;
        }
    }
}

import java.io.DataInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import java.util.TreeSet;


public class Main {

	public static void main(String[] args) throws IOException {
		Main m = new Main();
		//*
		m.input();
		m.solve();
		m.output();
		/*/
		m.debug();
		//*/
	}

	public void debug() {
	}

	InputUtil in = new InputUtil();
	PrintWriter out = new PrintWriter(System.out);

	int N, K, Q;
	int[] A,ASorted;
	Map<Integer,List<Integer>> Amap = new HashMap<>();
	long ans = 0;
//	boolean ans = false;

	public void input() throws IOException {
		N = in.nextInt();
		K = in.nextInt();
		Q = in.nextInt();
		A = in.nextInt(new int[N]);
		ASorted = new int[N];
		System.arraycopy(A, 0, ASorted, 0, N);
		Arrays.sort(ASorted);
		for (int i=0; i<N; i++) {
			addAmap(A[i],i);
		}
	}

	private void addAmap (int key, int val) {
		List<Integer> valList;
		if (Amap.containsKey(key)) {
			valList = Amap.get(key);
		} else {
			valList = new ArrayList<>();
			Amap.put(key, valList);
		}
		valList.add(val);
	}

	public void solve() throws IOException {
		ans = Integer.MAX_VALUE;
		TreeSet<Integer> ngIdxSet = new TreeSet<>();
		TreeMap<Integer,Integer> rangesMap = new TreeMap<>();
		rangesMap.put(0,N-1);

		LOOP1:
		for (int i=0; i<N-Q && ans > 0; ) {
			List<Integer> AmapList = null;

			if (ans > A[i+Q-1] - A[i]) {
				int result = check(i,ngIdxSet, rangesMap);
				switch (result) {
				case -1:
					// この数字はNGだがそれ以上のチェックも必要
					break;
				case -2:
					// それ以上のチェック不可
					break LOOP1;
				default:
					//この数字はOK
					ans = (ans>result)?result:ans;
					break;
				}
			}
			i += (AmapList == null)?1:AmapList.size();
			AmapList = Amap.get(ASorted[i]);
			for (int elem : AmapList) { 
				ngIdxSet.add(elem);
				int rangeStartIdx = rangesMap.floorKey(elem);
				int rangeEndIdx = rangesMap.get(rangeStartIdx);
				if (rangeStartIdx == elem) {
					rangesMap.remove(rangeStartIdx);
					if (rangeEndIdx > elem){
						rangesMap.put(elem+1, rangeEndIdx);
					}
				} else {
					rangesMap.put(rangeStartIdx, elem-1);
					if (rangeEndIdx >= elem+1) {
						rangesMap.put(elem+1, rangeEndIdx);
					}
				}
			}
		}
	}

	private int check(int idx, TreeSet<Integer> ngIdxSet, TreeMap<Integer,Integer> rangesMap) {
		int checkResult = 0;
		if (idx==0) {
			checkResult = ASorted[Q-1] - ASorted[0];
		} else if (idx>0) {
			//選択しない数字の最大値と、選択する可能性のある数字の最小値が等しい場合、その数字では分けられないためスキップ
			if (ASorted[idx-1] == ASorted[idx]) {
				return -1;
			}
			List<Integer> exList = new ArrayList<>();

			//領域ごとに選択できる要素数を確定
			Map<Integer,Integer> rangeCountMap = new HashMap<>();
			int activeRanges = 0;
			for (Map.Entry<Integer, Integer> e : rangesMap.entrySet()) {
				int k = e.getKey();
				int v = e.getValue();
				int rangeCount = v-k+1-K;
				rangeCountMap.put(k, rangeCount);
				if (rangeCount >= 0) {
					activeRanges ++;
				}
			}

			List<Integer> AmapList = null;
			for (int j=idx; j<N && exList.size() < Q && activeRanges>0; j+=AmapList.size()) {
				AmapList = Amap.get(ASorted[j]);
				for (int elem: AmapList) {
					int rangeStartIdx = rangesMap.floorKey(elem);
					int rangeCount = rangeCountMap.get(rangeStartIdx);
					if (rangeCount>=0) {
						exList.add(A[elem]);
					}
					rangeCountMap.put(rangeStartIdx, rangeCount--);
					if (rangeCount == -1) {
						activeRanges--;
					}
					if (activeRanges <= 0) {
						break;
					}
				}
			}
			if (exList.size() < Q) {
				return -2;
			}
			Collections.sort(exList);
			checkResult = exList.get(Q-1) - exList.get(0);

		} else {
			return -2;
		}
		return checkResult;
	}



	public void output() {
		out.println(ans);
		out.flush();
	}
}

class InputUtil {
	//Static Fields
	private static final int BUFSIZ = 100000;
	boolean lineMode = false;

	//Fields
	protected InputStream in;
	private byte[] buf = null;
	private int ptr = 0;
	private int max = -1;
	private DataInputStream dis = null;
	//Constructors
	public InputUtil() {this(System.in,BUFSIZ);}
	public InputUtil(InputStream in, int bufsiz) {
		initBuf(bufsiz);
		initIn(in);
	}

	//Methods
	//Initializer
	protected void initIn(InputStream in) {dis = new DataInputStream(this.in = in);}
	protected void initBuf(int bufsiz) {buf = new byte[bufsiz];}

	//buffer operation
	private void next() throws IOException {ptr++; readBuf();}
	private void readBuf() throws IOException {
		if(ptr >= max && dis.available()>0) {
			if(max>0) Arrays.fill(buf,0,max,(byte)0);
			max = dis.read(buf);
			ptr = 0;
		}
	}


	//String Input Reader/Parser
	private boolean isCrLf(byte b) {return b == 0x0a || b == 0x0d; }

	private void skipOneCrLf() throws IOException {
		byte b = buf[ptr];
		if (isCrLf(b)) {
			ptr++;
			if (b == 0x0d) {
				readBuf();
				if (ptr < max && buf[ptr] == 0x0a) {
					ptr++;
				}
			}
		}
	}

	public String nextLine() throws IOException {
		StringBuilder sb = new StringBuilder();
		boolean isFirst = true;
		for(readBuf(); ptr < max ;readBuf()) {
			byte b = buf[ptr];
			if(isCrLf(b)) {
				skipOneCrLf();
				if (!isFirst || lineMode) {
					break;
				}
			}else{
				int strPtr = ptr++;
				int endPtr = -1;
				for(int i = ptr; i<max; i++) {
					if(isCrLf(buf[i])) {
						endPtr = i;
						break;
					}
				}
				if(endPtr == -1) endPtr = max;
				sb.append(new String(buf,strPtr,endPtr-strPtr,"UTF-8"));
				ptr = endPtr;
			}
			isFirst = false;
		}
		lineMode = true;
		return sb.toString();
	}

	public byte nextByte() throws IOException {
		lineMode=false;
		readBuf();
		if(ptr < max) {
			return buf[ptr++];
		}else{
			return -1;
		}
	}

	//Number Input Reader/Parser
	private boolean isNum(byte b) {return '0' <= b && b <= '9'; }
	private boolean isMinus(byte b) {return b=='-'; }

	public int nextInt() throws IOException {
		lineMode=false;
		readBuf();
		return (int)_nextLong();
	}

	public int[] nextInt(int[] result) throws IOException {
		lineMode=false;
		readBuf();
		for(int i=0; i<result.length; i++) {
			result[i] = (int)_nextLong();
		}
		return result;
	}

	private long _nextLong() throws IOException {
		int sign = 1;
		long res = 0;
		byte c;
		while (!isNum(c=buf[ptr]) && !isMinus(c)) 
			next();
		if (isMinus(buf[ptr])) {
			sign = -1;
			next();
		}
		while (isNum(c=buf[ptr])) {
			res *= 10;
			res += c - '0' ;
			next();
		}
		next();
		return sign * res;
	}

	public long nextLong() throws IOException {
		lineMode=false;
		readBuf();
		return _nextLong();
	}

	public long[] nextLong(long[] result) throws IOException {
		lineMode=false;
		readBuf();
		for(int i=0; i<result.length; i++) {
			result[i] = _nextLong();
		}
		return result;
	}

	//Close 
	public void close() throws IOException {
		if(!this.in.equals(System.in)) 
			this.in.close();
	}

}

class OutputUtil {
	public static final String EOF = System.lineSeparator();

	public static void outputDivSpace(PrintWriter out, int[] a) {
		OutputUtil.output(out,a,0,a.length," ");
	}

	public static void outputDivEOF(PrintWriter out, int[] a) {
		OutputUtil.output(out,a,0,a.length,EOF);
	}

	public static void output(PrintWriter out, int[] a, int off, int len, String delim) {
		out.print(a[off]);
		for(int i=off+1; i<len; i++){
			out.print(delim);
			out.print(a[i]);
		}
		out.println("");
		out.flush();
	}
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {
	public static void main(String[] args) throws Exception {
		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String[] sa = br.readLine().split(" ");
		int n = Integer.parseInt(sa[0]);
		int k = Integer.parseInt(sa[1]);
		int q = Integer.parseInt(sa[2]);
		sa = br.readLine().split(" ");
		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = Integer.parseInt(sa[i]);
		}
		br.close();

		int x = k + q - 1;
		int min = Integer.MAX_VALUE;
		for (int i = 0; i < x; i++) {
			min = Math.min(min, a[i]);
		}
		for (int i = n - x; i < n; i++) {
			min = Math.min(min, a[i]);
		}

		Arrays.parallelSort(a);

		int ans = a[n - 1] - a[0];
		for (int i = 0; i + q - 1 < n; i++) {
			if (a[i] > min) {
				break;
			}
			int val = a[i + q - 1] - a[i];
			ans = Math.min(ans, val);
		}
		System.out.println(ans);
	}
}

import java.io.*;
import java.util.*;

public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();
		int k = sc.nextInt();
		int q = sc.nextInt();

		int[] a = new int[n];
		for (int i = 0; i < n; i++) {
			a[i] = sc.nextInt();
		}
//		Arrays.sort(a);

		int min = Integer.MAX_VALUE;
		for (int i = 0; i + n - (k + q - 1) <= n; i++) {
			List<Integer> tmp = new ArrayList<>(k + q - 1);
			for (int j = 0; j < n; j++) {
				if (j < i || j >= i + n - (k + q - 1)) {
					tmp.add(a[j]);
				}
			}
			Collections.sort(tmp);

			min = Math.min(min, tmp.get(q - 1) - tmp.get(0));
		}

		pr.println(min);
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(INPUT == null ? System.in : new ByteArrayInputStream(INPUT.getBytes()));
		pr = new Printer(System.out);

		solve();

//		pr.close();
		pr.flush();
//		sc.close();
	}

	static String INPUT = null;

	@SuppressWarnings("unused")
	private static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	private static class Printer extends PrintWriter {
		Printer(OutputStream out) {
			super(out);
		}
	}
}

