        int[] a = new int[n];
        TreeSet<Integer> set = new TreeSet<>();
        for(int i = 0; i < n; i++){
            a[i] = ni();
            set.add(a[i]);
        }
        long ans = inf;
        for(int y : set){
            for(int i = 0; i < n; i++){
                if(a[i]<y) a[i] = -1;
            }
            TreeMap<Integer, Integer> map = new TreeMap<>();
            int s = 0;
            int t = 0;
            while(true){
                // System.err.println(s+" "+t+" "+y);
                if(t>=n) break;
                if(a[t]!=-1) t++;
                else{
                    if(s==t){
                        s++;
                        t++;
                        continue;
                    }
                    ArrayList<Integer> list = new ArrayList<>();
                    for(int i = s; i < t; i++){
                        list.add(a[i]);
                    }
                    Collections.sort(list);
                    // System.err.println(s+" "+t+" "+y);
                    for(int i = 0; i < t-s+1-k; i++){
                        map.merge(list.get(i), 1, (e,f)->e+f);
                    }
                    s = t;
                }
            }
            if(s!=t){
                ArrayList<Integer> list = new ArrayList<>();
                for(int i = s; i < t; i++){
                    list.add(a[i]);
                }
                Collections.sort(list);
                // System.err.println(s+" "+t+" "+y);
                for(int i = 0; i < t-s+1-k; i++){
                    map.merge(list.get(i), 1, (e,f)->e+f);
                }
