                x = i;
                p += map.get(i);
                // out.println(x+" "+p);
                if(p>=q) break;
            }
            // out.println(x+" "+p+" "+1);
            if(x==-1||p<q) continue;
            ans = Math.min(ans, x-y);
        }
        out.println(ans);
    }

