public class Main {


    public void solve(int testNumber, InputReader in, OutputWriter out) {

        int n = in.nextInt();


        int k = in.nextInt();

        int q = in.nextInt();

        Integer[] a = new Integer[n];
        int[] b = new int[n];

        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
            b[i] = a[i];
        }

        Arrays.sort(a);

        long ans = a[q - 1] - a[0];

        for (int i = 0; i < n; i++) {

            int lo = i;
            int hi = n - 1;

            while (lo <= hi) {
                int mid = (lo + hi) / 2;

                int lii = -1;
                long ca = 0;

                for (int j = 0; j < n; j++) {
                    if (b[j] < a[i] || b[j] > a[mid]) {
                        int sl = j - lii - 1;

                        if (sl >= k) {
                            ca += sl - k + 1;
                        }
                        lii = j;
                    }
                }

                int sl = n - lii - 1;

                if (sl >= k) {
                    ca += sl - k + 1;
                }

                if (ca >= q) {
                    ans = Math.min(ans, a[mid] - a[i]);
                    hi = mid - 1;
                } else {
                    lo = mid + 1;
                }
            }
        }

        System.out.println(ans);
    }

