        for (int i = 0; i < n; i++) {
            a[i] = in.nextInt();
            b[i] = a[i];
        }

        Arrays.sort(a);

        long ans = a[q - 1] - a[0];

        for (int i = 0; i < n; i++) {

//            int lo = i;
