//
//            while (lo <= hi) {
//                int mid = (lo + hi) / 2;

            int lii = -1;
            long ca = 0;

            List<Integer> cl = new ArrayList<>();
            for (int j = 0; j < n; j++) {
                if (b[j] < a[i]) {
                    int sl = j - lii - 1;

                    if (sl >= k) {
                        ca += sl - k + 1;
                    }
                    lii = j;
                } else {
                    cl.add(a[j]);
