public class Main {
    public static void main(String[] args) throws Exception {
        Field f = System.out.getClass().getDeclaredField("autoFlush");
        f.setAccessible(true);
        f.set(System.out, false);
        execute(System.in, System.out);
    }

    public static void execute(InputStream in, OutputStream out) {
        ExtendedScanner s = new ExtendedScanner(in);
        Out o = new Out(out);
        solve(s, o);
        o.flush();
        o.close();
    }

    public static void solve(ExtendedScanner sc, Out out) {
        int n = sc.nextInt();
        int k = sc.nextInt();
        int q = sc.nextInt();
        int[] a = sc.ints(n);
        int[] b = new int[n];
        PriorityQueue<Integer> pq = new PriorityQueue<>();
        int min = Integer.MAX_VALUE;
        for (int i = 0; i < n; i++) {
            pq.clear();
            IntArrayList l = new IntArrayList();
            l.add(-1);
            for (int j = 0; j < n; j++) {
                if (a[j] < a[i]) {
                    l.add(j);
                }
            }
            int m = l.size();
            l.add(n);
            System.arraycopy(a, 0, b, 0, n);
            for (int u = 0; u < m; u++) {
                int x = l.get(u) + 1;
                int y = l.get(u + 1);
                if (y - x < k) continue;
                Arrays.sort(b, x, y);
                for (int z = 0; z < y - x - k + 1; z++) {
                    pq.add(b[x + z]);
                }
            }
            if (pq.size() < q) continue;
            int x = -1;
            int y = -1;
            for (int t = 0; t < q; t++) {
                int v = pq.poll();
                if (t == 0) x = v;
                if (t == q - 1) y = v;
            }
            min = Math.min(min, y - x);

        }
        out.writeln(min);
    }
}


