            for (int j = le + 1; j < ri; j++)
                if (!use[j]) ct++;
            use[idx[i].v2] = true;
            ng.Add(idx[i - Q + 1].v2);
            if (ct >= K)
                chmin(ref res, idx[i].v1 - idx[i - Q + 1].v1);
        }
        WriteLine(res);
