        var A = sc.ArrInt;
        var use = new bool[N];
        var idx = A.Select((v, id) => new Pi(v, id)).ToArray();
        Array.Sort(idx, (a, b) => a.v1 - b.v1);
        var ng = new Set<int>();ng.Add(-1);ng.Add(N);
        var res = int.MaxValue;
        for (int i = 0; i < Q-1; i++)
        {
            use[idx[i].v2] = true;
        }
        for(int i = Q - 1; i < N; i++)
        {
            int ct = 0, lw = ng.UpperBound(idx[i].v2);
            int le = ng[lw - 1], ri = ng[lw];
            for (int j = le + 1; j < ri; j++)
                if (!use[j]) ct++;
            use[idx[i].v2] = true;
            ng.Add(idx[i - Q + 1].v2);
            if (ct >= K)
                chmin(ref res, idx[i].v1 - idx[i - Q + 1].v1);
            else break;
        }
        WriteLine(res);
    }
