    readonly int[] dd = { 0, 1, 0, -1, 0 }; //→↓←↑
    readonly int mod = 1000000007;
    void chmax<T>(ref T a, T b) where T : IComparable<T> { a = a.CompareTo(b) < 0 ? b : a; }
    void chmin<T>(ref T a, T b) where T : IComparable<T> { a = a.CompareTo(b) < 0 ? a : b; }

    void solve()
    {
        int N = cin.nextint;
        int K = cin.nextint;
        int Q = cin.nextint;
        var A = cin.scanint;
        var ans = long.MaxValue;

        for (int i = 0; i < N; i++)
        {
            var Z = A[i];
            var W = new List<int>();

            var P = new List<int>();

            for (int r = 0; r <= N; r++)
            {
                if (r == N || A[r] < Z)//Zより小さいものは使わない
                {
                    if (P.Count < K) continue;
                    P.Sort();
                    for (int j = 0; j < P.Count - K + 1; j++)
                    {
                        W.Add(P[j]);
                    }
                    P = new List<int>();
                }
                else
                {
                    P.Add(A[r]);
                }
            }
            if (W.Count < Q) continue;
            W.Sort();
            chmin(ref ans, W[Q - 1] - W[0]);
        }

        WriteLine(ans);
    }

