using System;
using System.Text;
using System.Collections.Generic;
using System.Linq;
class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        int K = re.i();
        int Q = re.i();
        long[] A = re.la();
        Heap H1 = new Heap(N+1);
        Heap H2 = new Heap(N+1);
        long count = 100000000000;
        for(int i=0;i<N;i++){
            long min = A[i];
            int last = -1;
            for(int j=0;j<N;j++){
                if(A[j] >= min){
                    if(H1.size == 0){
                        last = j;
                    }
                    H1.push(A[j]);
                }
                if(H1.size != 0 && (j == N-1 || A[j+1] < min)){
                    int L = j-last+1;
                    for(int k=0;k<L-K+1;k++){
                        H2.push(H1.pop());
                    }
                    H1.size = 0;
                }
            }
            long max = 0;
            for(int j=0;j<Q;j++){
                if(H2.size == 0){
                    max = 10000000000000;
                    break;
                }
                else{
                    max = Math.Max(max,H2.pop());
                }
            }
            H2.size = 0;
            count = Math.Min(count,max-min);
        }
        sb.Append(count+"\n");
    }
}
class Heap{
    public int size;
    long[] obj;

    public Heap(int maxsize){
        size = 0;
        obj = new long[maxsize];
    }
    public bool Compare(long a,long b){
        return a <= b;
    }
    public void push(long a){
        int i = size;
        size++;
        while(i > 0){
            int p = (i - 1)/2;
            if(Compare(obj[p],a)){
                obj[i] = a;
                break;
            }
            obj[i] = obj[p];
            i = p;
        }
        if(i == 0){
            obj[0] = a;
        }
    }
    public long pop(){
        long t = obj[0];
        int i = 0;
        size--;
        while(2*i+1 < size){
            int p = 2*i+1;
            if(p+1 < size && Compare(obj[p+1],obj[p])){
                p++;
            }
            if(Compare(obj[p],obj[size])){
                obj[i] = obj[p];
                i = p;
            }
            else{
                obj[i] = obj[size];
                break;
            }
        }
        if(2*i+1 >= size){
            obj[i] = obj[size];
        }
        return t;
    }
}
