class Solver {
    StreamWriter sw;
    Scan sc;
    void Prt(string a) => sw.WriteLine(a);
    void Prt<T>(IEnumerable<T> a) => Prt(string.Join(" ", a));
    void Prt(params object[] a) => Prt(string.Join(" ", a));
    public Solver(StreamWriter sw) {
        this.sw = sw;
        this.sc = new Scan();
    }

    public void solve() {
        int n, k, q;
        sc.Multi(out n, out k, out q);
        var a = sc.IntArr;
        var b = a.Distinct().ToArray();
        Array.Sort(b);
        int ans = M;
        foreach (var item in b)
        {
            var lis = new List<int>();
            var l = new List<int>();
            for (int i = 0; i < n; i++)
            {
                if (a[i] < item) {
                    if (l.Count >= k) {
                        l.Sort();
                        for (int j = 0; j < l.Count - k + 1; j++)
                        {
                            lis.Add(l[j]);
                        }
                    }
                    l = new List<int>();
                }
                else {
                    l.Add(a[i]);
                }
            }
            if (l.Count >= k) {
                l.Sort();
                for (int j = 0; j < l.Count - k + 1; j++)
                {
                    lis.Add(l[j]);
                }
            }
            if (lis.Count >= q) {
                lis.Sort();
                ans = Math.Min(ans, lis[q - 1] - lis[0]);
            }
        }
        Prt(ans);

    }
}

class pair<T, U> : IComparable<pair<T, U>> {
    public T v1;
    public U v2;
