    public static long pow(long a, long b) {
        if (a >= Mod) return pow(a % Mod, b);
        if (a == 0) return 0;
        if (b == 0) return 1;
        var t = pow(a, b / 2);
        if ((b & 1) == 0) return t * t % Mod;
        return t * t % Mod * a % Mod;
    }
    public static long inv(long a) => pow(a, Mod - 2);
    public static long gcd(long a, long b) {
        while (b > 0) { var t = a % b; a = b; b = t; } return a;
    }
    // a x + b y = gcd(a, b)
    public static long extgcd(long a, long b, out long x, out long y) {
        long g = a; x = 1; y = 0;
        if (b > 0) { g = extgcd(b, a % b, out y, out x); y -= a / b * x; }
        return g;
    }
    public static long lcm(long a, long b) => a / gcd(a, b) * b;

    static long[] facts;
    public static long[] setfacts(int n) {
        facts = new long[n + 1];
        facts[0] = 1;
        for (int i = 0; i < n; i++) facts[i + 1] = facts[i] * (i + 1) % Mod;
        return facts;
    }
    public static long comb(int n, int r) {
        if (n < 0 || r < 0 || r > n) return 0;
        if (n - r < r) r = n - r;
        if (r == 0) return 1;
        if (r == 1) return n;
        if (facts != null && facts.Length > n) return facts[n] * inv(facts[r]) % Mod * inv(facts[n - r]) % Mod;
        int[] numer = new int[r], denom = new int[r];
        for (int k = 0; k < r; k++) { numer[k] = n - r + k + 1; denom[k] = k + 1; }
        for (int p = 2; p <= r; p++) {
            int piv = denom[p - 1];
            if (piv > 1) {
                int ofst = (n - r) % p;
                for (int k = p - 1; k < r; k += p) { numer[k - ofst] /= piv; denom[k] /= piv; }
            }
        }
        long ret = 1;
        for (int k = 0; k < r; k++) if (numer[k] > 1) ret = ret * numer[k] % Mod;
        return ret;
    }
    public static long[][] getcombs(int n) {
        var ret = new long[n + 1][];
        for (int i = 0; i <= n; i++) {
            ret[i] = new long[i + 1];
            ret[i][0] = ret[i][i] = 1;
            for (int j = 1; j < i; j++) ret[i][j] = (ret[i - 1][j - 1] + ret[i - 1][j]) % Mod;
        }
        return ret;
    }
    // nC0, nC2, ..., nCn
    public static long[] getcomb(int n) {
        var ret = new long[n + 1];
        ret[0] = 1;
        for (int i = 0; i < n; i++) ret[i + 1] = ret[i] * (n - i) % Mod * inv(i + 1) % Mod;
        return ret;
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		int n = int.Parse(input[0]);
		int k = int.Parse(input[1]);
    int q = int.Parse(input[2]);
		long[] nums = Array.ConvertAll(Console.ReadLine().Split(' '),long.Parse);
    long minNum = 0;
    long answer = long.MaxValue;
    int countMemo = 0;
    List<long> answerList = new List<long>();
    List<long> answerSubList = new List<long>();

    for(int i = 0; i < n; i++)//最小値の選択
    {
      minNum = nums[i];
      answerList.Clear();
      answerSubList.Clear();
      for(int j = 0; j < n; j++)
      {
        if(nums[j] >= minNum)
        {
          countMemo++;
          if(countMemo == k)
          {
            for(int l = 0; l < k; l++)
            {
              answerSubList.Add(nums[j-l]);
            }
          }else if(countMemo > k) answerSubList.Add(nums[j]);
        }else
        {
          if(countMemo >= k)
          {
            answerSubList.Sort((a, b) => a.CompareTo(b));
            for(int l = 0; l < answerSubList.Count()-k+1; l++)
            {
              answerList.Add(answerSubList[l]);
            }
          }
          answerSubList.Clear();
          countMemo = 0;
        }
      }
      if(countMemo >= k)
      {
        answerSubList.Sort((a, b) => a.CompareTo(b));
        for(int l = 0; l < answerSubList.Count()-k+1; l++)
        {
          answerList.Add(answerSubList[l]);
        }
      }
      if(answerList.Count() < q) continue;
      else
      {
        answerList.Sort((a, b) => a.CompareTo(b));
        answer = Math.Min(answer, answerList[q-1]-minNum);
      }
    }

		Console.WriteLine(answer);
	}
}

