class Solver
{
    public void Solve(Scanner sc)
    {
        int N, K, Q;
        sc.Make(out N, out K, out Q);
        var A = sc.ArrInt;
        var idx = A.Select((v, id) => new Pi(v, id)).ToArray();
        Array.Sort(idx, (a, b) => a.v1 - b.v1);

        var use = new bool[N];
        var res = int.MaxValue;
        for (int k = 0; k < N; k++)
        {
            var l = new List<int>();
            var pq = new PriorityQueue<int>();
            for (int i = 0; i < N; i++)
                if (use[i])
                {
                    while (pq.Count >= K) l.Add(pq.Pop());
                    pq.Clear();
                }
                else pq.Push(A[i]);
            while (pq.Count >= K) l.Add(pq.Pop());
            l.Sort();
            for (int i = 0; i <= l.Count - Q; i++)
                chmin(ref res, l[i + Q - 1] - l[i]);
            use[idx[k].v2] = true;
        }
        WriteLine(res);
    }
}

public class PriorityQueue<T>
{
    private List<T> data = new List<T>();
    private Comparison<T> cmp;
    public int Count { get { return data.Count; } }
    public T Top { get { return data[0]; } }
    public PriorityQueue() { cmp = cmp ?? Comparer<T>.Default.Compare; }

    public PriorityQueue(Comparison<T> comparison) { cmp = comparison; }

    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Parent(int i)
        => (i - 1) >> 1;
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    private int Left(int i)
        => (i << 1) + 1;
    public T Push(T val)
    {
        int i = data.Count;
        data.Add(val);
        while (i > 0)
        {
            int p = Parent(i);
            if (cmp(data[p], val) <= 0)
                break;
            data[i] = data[p];
            i = p;
        }
        data[i] = val;
        return val;
    }
    public T Pop()
    {
        var ret = data[0];
        var p = 0;
        var x = data[data.Count - 1];
        while (Left(p) < data.Count - 1)
        {
            var l = Left(p);
            if (l < data.Count - 2 && cmp(data[l + 1], data[l]) < 0) l++;
            if (cmp(data[l], x) >= 0)
                break;
            data[p] = data[l];
            p = l;
        }
        data[p] = x;
        data.RemoveAt(data.Count - 1);
        return ret;
    }
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public bool Any() => data.Count > 0;
    public void Clear() => data.Clear();
}
