public class Solver
{
	public void Solve()
	{
		int N = GetInt();
		int K = GetInt();
		int Q = GetInt();
		int[] A = GetInts(N);

		int ans = int.MaxValue;
		for(int i = 0; i < N; i++)
		{
			var removable = new List<int>();
			var tmp = new List<int>();
			for(int j = 0; j < N; j++)
			{
				if(A[j] >= A[i])
				{
					tmp.Add(A[j]);
				}
				else
				{
					addRemovable(K, removable, tmp);
					tmp = new List<int>();
				}
			}
			addRemovable(K, removable, tmp);

			if(removable.Count < Q)
				continue;

			removable.Sort();
			chmin(ref ans, removable[Q - 1] - A[i]);
		}

		WriteLine(ans);
	}

	private void addRemovable(int K, List<int> removable, List<int> tmp)
	{
		tmp.Sort();
		removable.AddRange(tmp.GetRange(0, Max(0, tmp.Count - K + 1)));
	}
}

