            for(int l = 0; l < answerSubList.Count()-k+1; l++)
            {
              answerList.Add(answerSubList[l]);
            }
          }
          answerSubList.Clear();
          countMemo = 0;
        }
      }
      if(answerList.Count() < q) continue;
      else
