			A[i] = long.Parse(str2[i]);
		}
		long mmin = 9999999999;
		long imin = Math.Max(N-(K+Q-1),0);
		long imax = Math.Min(K+Q-1,N);
		for(var i=imin;i<imax;i++){
			mmin = Math.Min(A[i],mmin);
		}
		Array.Sort(A);
		long min = 9999999999;
		for(var i=0;i<N;i++){
			long sum = A[i+Q-1] - A[i];
			min = Math.Min(min, sum);
