using System;
using System.Collections.Generic;
using System.Linq;
using static System.Math;

class Program
{
    static int n, k, q;
    static int[] a;
    static void Main()
    {
        /* 入力の受け取り */
        string[] input = Console.ReadLine().Split();
        n = int.Parse(input[0]);
        k = int.Parse(input[1]);
        q = int.Parse(input[2]);
        a = Console.ReadLine().Split().Select(int.Parse).ToArray();
        /* Y=aiと固定して最小値を求めていく */
        int ans = int.MaxValue;
        for (int i = 0;i < n; i++) // Y=aiと固定
        {
            int Y = a[i];
            List<List<int>> sec = new List<List<int>>();
                                     // Y未満で分割した区間を管理
            sec.Add(new List<int>());
            for (int j = 0;j < n; j++)
            {
                if (a[j] < Y) // Y未満の処理
                {
                    sec.Add(new List<int>()); 
                    continue;
                }
                sec[sec.Count - 1].Add(a[j]);
            }
            List<int> removes = new List<int>(); // 取り除く候補を管理
            foreach (var b in sec) // 分割した各区間について
            {
                b.Sort();
                int m = Max(0,Min(q,b.Count - k + 1));
                for (int j = 0;j < m; j++)
                    removes.Add(b[j]);
            }
            removes.Sort();
            if (removes.Count < q) // q個も取り除けなかった場合
                continue;
            if (removes[0] != Y) // aiが取り除けなかった場合
                continue;
            ans = Min(ans,removes[q - 1] - Y); // 解の検討
        }
        Console.WriteLine(ans);
    }
}

