	A       []int
)

func main() {
	n, k, q = ReadInt3()
	A = ReadIntSlice(n)

	if q == 1 {
		fmt.Println(0)
		return
	}

	ans := INF_BIT60
	for i := 0; i < n; i++ {
		a := A[i]

		// 最大値の候補
		candidates := []int{}

		C := []int{}
		for j := 0; j < n; j++ {
			if j == i || A[j] < a {
				continue
			}

			C = append(C, A[j])

			if j == n-1 || (j+1 < n && A[j+1] < a) {
				// PrintfDebug("a: %d, C: %v\n", a, C)

				sort.Sort(sort.IntSlice(C))
				if len(C)-k+1 > 0 {
					candidates = append(candidates, C[:len(C)-k+1]...)
				}

				C = []int{}
			}
		}

		if len(candidates) < q-1 {
			continue
		}

		sort.Sort(sort.IntSlice(candidates))
		ChMin(&ans, candidates[q-2]-a)
	}

	fmt.Println(ans)
}

// ChMin accepts a pointer of integer and a target value.
