)

var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  var line, buffer []byte
  var isPrefix bool = true
  var err error
  for isPrefix {
    line, isPrefix, err = reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
  }
  return string(buffer)
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

type Item struct {
  Value int
  Index int
}
type Items []Item
func (A Items) Len() int { return len(A) }
func (A Items) Less(i, j int) bool { return A[i].Value < A[j].Value }
func (A Items) Swap(i, j int) { A[i], A[j] = A[j], A[i] }

func main() {
  NKQ := NextIntVec()
  N, K, Q := NKQ[0], NKQ[1], NKQ[2]
  A := NextIntVec()
  B := make([]Item, N)
  for i := range B {
    B[i] = Item{A[i], i}
  }
  C := make([]int, N + 1)
  C[N] = 1
  dist := 10000000001
  for dist > 0 {
    D := make([]Item, 0)
    s := 0
    for i, c := range C {
      if c == 0 { continue }
      if K <= i - s {
        tmp := make([]Item, 0)
        tmp = append(tmp, B[s:i]...)
        sort.Sort(Items(tmp))
        D = append(D, tmp[:i - s - K + 1]...)
      }
      s = i + 1
    }
    if len(D) < Q { break }
    sort.Sort(Items(D))
    if D[Q - 1].Value - D[0].Value < dist {
      dist = D[Q - 1].Value - D[0].Value
    }
    for _, d := range D {
      if D[0].Value < d.Value { break }
      C[d.Index] = 1
    }
  }
  Write(dist)
  Output()
}

