enum long INF = long.max/5;
enum long MOD = 10L^^9+7;

void main() {
  long N, K, Q;
  scanln(N, K, Q);
  long[] as = readln.split.to!(long[]);
  long[][] bss = as.enumerate.array.sort!"a.value<b.value".chunkBy!"a.value == b.value".map!(map!"a.index").map!array.array.to!(long[][]);
  bss = [[]] ~ bss;

  auto seg = SegTree!(long, (a, b) => min(INF, a+b), 0)(N);
  long[] ones = 1L.repeat(N).array;
  long ans = INF;
  foreach(i, bs; bss) {
    foreach(b; bs) {
      ones[b] = INF;
    }
    seg.update(ones);
    long q = 0;
    long minV = +INF;
    long maxV = -INF;
    foreach(xs; bss[i+1..$]) {
      foreach(x; xs) {
        if (q == Q) break;
        long left, right;
        {
          long l = x;
          long r = N;
          while(r - l > 1) {
            long c = (l + r).floor(2);
            long k = seg.query(x, c+1);
            if (k < INF) {
              l = c;
            } else {
              r = c;
            }
          }
          right = l;
        }
        {
          long r = x;
          long l = -1;
          while(r - l > 1) {
            long c = (l + r).ceil(2);
            long k = seg.query(c, x+1);
            if (k < INF) {
              r = c;
            } else {
              l = c;
            }
          }
          left = r;
        }
        long k = seg.query(left, right+1);
        if (k >= K) {
          seg.update(x, 0);
          q++;
          minV.ch!min(as[x]);
          maxV.ch!max(as[x]);
        }
      }
    }
    if (q == Q) {
      ans.ch!min(maxV - minV);
    }
  }
  ans.writeln;
}

// // RMQ (Range Minimum Query)
// alias RMQ(T) = SegTree!(T, "a<b ? a:b", T.max);

// SegTree (Segment Tree)
//    - with 1-based array
struct SegTree(T, alias fun, T initValue, bool structly = true)
  if (is(typeof(binaryFun!fun(T.init, T.init)) : T)) {

private:
  alias _fun = binaryFun!fun;
  Pair[] _data;
  size_t _size;
  size_t _l, _r;

public:
  // size ... データ数
  // initValue ... 初期値(例えばRMQだとINF)
  this(size_t size) {
    init(size);
  }

  // 配列で指定
  this(T[] ary) {
    init(ary.length);
    update(ary);
  }

  // O(N)
  void init(size_t size){
    _size = 1;
    while(_size < size) {
      _size *= 2;
    }
    _data.length = _size*2;
    _data[] = Pair(size_t.max, initValue);
    _l = 0;
    _r = size;
  }

  // i番目の要素をxに変更
  // O(logN)
  void update(size_t i, T x) {
    size_t index = i;
    _data[i += _size] = Pair(index, x);
    while(i > 0) {
      i >>= 1;
      Pair nl = _data[i*2+0];
      Pair nr = _data[i*2+1];
      _data[i] = select(nl, nr);
    }
  }

  // 配列で指定
  // O(N)
  void update(T[] ary) {
    foreach(i, e; ary) {
      _data[i+_size] = Pair(i, e);
    }
    foreach_reverse(i; 1.._size) {
      Pair nl = _data[i*2+0];
      Pair nr = _data[i*2+1];
      _data[i] = select(nl, nr);
    }
  }

  // 区間[a, b)でのクエリ (valueの取得)
  // O(logN)
  T query(size_t a, size_t b) {
    Pair pair = accumulate(a, b);
    // Pair pair = queryRec(a, b, 0, 0, _size);
    return pair.value;
  }

  // 区間[a, b)でのクエリ (indexの取得)
  // O(logN)
  size_t queryIndex(size_t a, size_t b) out(result) {
    // fun == (a, b) => a+b のようなときはindexを聞くとassertion
    if (structly) assert(result != size_t.max);
  } body {
    Pair pair = accumulate(a, b);
    // Pair pair = queryRec(a, b, 0, 0, _size);
    return pair.index;
  }

  // 区間[a, b)でのクエリ ((index, value)の取得)
  // O(logN)
  Pair queryPair(size_t a, size_t b) out(result) {
    // fun == (a, b) => a+b のようなときはindexを聞くとassertion
    if (structly) assert(result.index != size_t.max);
  } body {
    Pair pair = accumulate(a, b);
    // Pair pair = queryRec(a, b, 0, 0, _size);
    return pair;
  }

  private Pair accumulate(size_t l, size_t r) {
    if (r<=_l || _r<=l) return Pair(size_t.max, initValue);
    Pair accl = Pair(size_t.max, initValue);
    Pair accr = Pair(size_t.max, initValue);
    for (l += _size, r += _size; l < r; l >>= 1, r >>= 1) {
      if (l&1) accl = select(accl, _data[l++]);
      if (r&1) accr = select(accr, _data[r-1]);
    }
    return select(accl, accr);
  }

  // private Pair queryRec(size_t a, size_t b, size_t k, size_t l, size_t r) {
  //   if (b<=l || r<=a) return Pair(size_t.max, initValue);
  //   if (a<=l && r<=b) return _data[k];
  //   size_t c = (l+r)/2;
  //   Pair nl = queryRec(a, b, k*2+0, l, c);
  //   Pair nr = queryRec(a, b, k*2+1, c, r);
  //   return select(nl, nr);
  // }

  private Pair select(Pair nl, Pair nr) {
    T v = _fun(nl.value, nr.value);
    if (nl.value == v) {
      return nl;
    } else if (nr.value == v) {
      return nr;
    } else {
      return Pair(size_t.max, v);
    }
  }

  // O(1)
  T get(size_t i) {
    return _data[_size + i].value;
  }

  // O(N)
  T[] array() {
    return _data[_l+_size.._r+_size].map!"a.value".array;
  }

  struct Pair {
    size_t index;
    T value;
  }
}


