bool test(long[] a, long l, long u, long k, long q) {
  auto b = a.split!(x => x < l);
  return b.map!((long[] x) {
    if(x.length < k) {
      return 0L;
    }
    return min(x.count!(y => y <= u), x.length - k + 1);
  }).sum >= q;
}

void main(){
  long n, k, q;
  readlnTo(n, k, q);
  auto a = readLongs();
  long ans = long.max / 2;
  foreach(i; iota(n)) {
    long l = a[i]-1;
    long u = long.max / 2;
    while(l + 1 < u) {
      auto m = (l+u)/2;
      if(test(a, a[i], m, k, q)) {
        u = m;
      } else {
        l = m;
      }
    }
    ans = min(ans, u-a[i]);
  }
  writeln(ans);
}

