    foreach (x; AS) {
        auto as = AS.dup;
        size_t i;
        long[] cs;
        foreach (j, a; as) {
            if (a < x) {
                if (j-i >= K) {
                    sort(as[i..j]);
                    foreach (k; i..j-K+1) cs ~= as[k];
                }
                i = j+1;
            }
        }
        if (N-i >= K) {
            sort(as[i..$]);
            foreach (k; i..N-K+1) cs ~= as[k];
        }
        if (cs.length >= Q) {
            sort(cs);
            res = min(res, cs[Q-1] - x);
        }
    }
    writeln(res);
}

