using namespace std;
#define mx 2005
inline int min(int x,int y){return x<y?x:y;}
inline int max(int x,int y){return x>y?x:y;}
int n,k,q,qz[mx],qp[mx],ans=2e9+5;
inline bool ck(int kl,int kr)
{
	int nl=0,nw=0,res=0;
	for(int i=1;i<=n;++i)
	{
		if(qz[i]>=kl&&qz[i]<=kr) ++nl,++nw;
		else if(qz[i]>kr) ++nl;
		else res+=max(0,min(nl-k+1,nw)),nl=nw=0;
	}
	res+=max(0,min(nl-k+1,nw)),nl=nw=0;
	return res>=q;
}
int main()
{
	scanf("%d%d%d",&n,&k,&q);
	for(int i=1;i<=n;++i)
		scanf("%d",&qz[i]),qp[i]=qz[i];
	sort(qp+1,qp+n+1);
	for(int i=1;i<=n;++i)
	{
		int l=i,r=n,mid;
		while(l<=r)
		{
			mid=(l+r)/2;
			if(ck(qp[i],qp[mid])) ans=min(ans,qp[mid]-qp[i]),r=mid-1;
			else l=mid+1;
		}
	}
	printf("%d",ans);
	return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define int long long
vector <int> Treeleft, Treeright;
vector <int> Treecnt;
void update1(int v, int l, int r, int al, int ar, int val)
{
	if(l >= al && r <= ar)
	{
		Treeright[v] = min(Treeright[v], val);
	}
	else if(l <= ar && r >= al)
	{
		update1(v * 2, l, (r + l) / 2, al, ar, val);
		update1(v * 2 + 1, (r + l) / 2 + 1, r, al, ar, val);
	}
}
void update2(int v, int l, int r, int al, int ar, int val)
{
	if(l >= al && r <= ar){
		Treeleft[v] = max(Treeleft[v], val);
	}
	else if(l <= ar && r >= al)
	{
		update2(v * 2, l, (r + l) / 2, al, ar, val);
		update2(v * 2 + 1, (r + l) / 2 + 1, r, al, ar, val);
	}
}
int ans1(int v, int l, int r, int ind)
{
	if(l == r)
	{
		return Treeleft[v];
	}
	else if(ind <= (r + l) / 2)
	{
		return max(Treeleft[v], ans1(v * 2, l, (r + l) / 2, ind)); 
	}
	else
	{
		return max(Treeleft[v], ans1(v * 2 + 1, (r + l) / 2 + 1, r, ind));
	}
}
int ans2(int v, int l, int r, int ind)
{
	if(l == r)
	{
		return Treeright[v];
	}
	else if(ind <= (r + l) / 2)
	{
		return min(Treeright[v], ans2(v * 2, l, (r + l) / 2, ind));
	}
	else
	{
		return min(Treeright[v], ans2(v * 2 + 1, (r + l) / 2 + 1, r, ind));
	}
}
void update3(int v, int l, int r, int ind)
{
	if(l == r)
	{
		Treecnt[v]++;
	}
	else if(ind <= (r+ l) / 2)
	{
		update3(v * 2, l, (r + l) / 2, ind);
		Treecnt[v]++;
	}
	else
	{
		update3(v * 2 + 1, (r + l) / 2 + 1, r, ind);
		Treecnt[v]++;
	}
}
int ans3(int v, int l, int r, int al, int ar)
{
	if(al <= l && r <= ar)
	{
		return Treecnt[v];
	}
	else if(al <= r && ar >= l)
	{
		return ans3(v * 2, l, (r + l) / 2, al, ar) + ans3(v * 2 + 1, (r + l) / 2 + 1, r, al, ar);
	}
	else
	{
		return 0;
	}
}
signed main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);
	cout.tie(NULL);
	int n, k, q;
	cin >> n >> k >> q;
	Treecnt.resize(4 * n);
	Treeleft.resize(4 * n);
	Treeright.resize(4 * n);
	vector <int> A(n);
	vector <pair <int, int> > B(n);
	for(int i = 0; i < n; i++)
	{
		cin >> A[i];
		B[i] = {A[i], i};
	}
	sort(B.begin(), B.end());
	int ans = 1e9;
	for(int i = 0; i < n; i++)
	{
		for(int j = 0; j < 4 * n; j++)
		{
			Treeright[j] = n;
			Treeleft[j] = -1;
			Treecnt[j] = 0;
		}
		for(int j = 0; j < i; j++)
		{
			update1(1, 0, n - 1, 0, B[j].second, B[j].second);
			update2(1, 0, n - 1, B[j].second, n - 1, B[j].second);
		}
		int cnt = 0;
	//	cout << i << "\n";
