type Range = tuple [s, t: int]

proc solve(n, k, q: int; a: seq[int]; x: int): int =
  var mark = newSeq[bool](n)
  mark.fill(true)

  for i in 0..<n:
    if a[i] < x:
      mark[i] = false

  var rs = newSeq[Range](0)
  var p = 0
  var erasableCount = 0
  while p < n:
    if not mark[p]:
      p += 1
      continue
    let s = p
    while p < n and mark[p]:
      p += 1
    let t = p

    if t - s >= k:
      rs.add((s, t))
      erasableCount += t - s - k + 1

  if erasableCount < q:
    return INF

  var candi = newSeq[int](0)
  for r in rs:
    let c = (r.t - r.s) - k + 1
    let b = a[r.s..<r.t].sorted(cmp[int])
    for i in 0..<c:
      candi.add(b[i])

  candi.sort(cmp[int])
  return candi[q - 1] - candi[0]

