def groups(gs, m, k):
    new_gs = []
    for g in gs:
        new_gs.extend(groups_1(g, m, k))
    return new_gs

def groups_1(a, m, k):
    g = []

    pos = 0
    while pos < len(a):
        i = pos
        while i < len(a) and a[i] < m:
            i += 1

        j = i
        while j < len(a) and a[j] >= m:
            j += 1

        if j - i >= k:
            g.append(a[i:j])

        pos = j

    return g

