def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, K, Q, A):

    ans = sys.maxsize
    for a in A:
        P = []
        s = None
        for i in range(N):
            if A[i] >= a:
                if s is None:
                    s = i
            else:
                if s is not None:
                    P.append((s, i))
                    s = None
        if s is not None:
            P.append((s, N))
        B = []
        for s, e in P:
            if e - s - K + 1 > 0:
                t = sorted(A[s:e + 1])[:e - s - K + 1]
                B.extend(t)

        B.sort()
        if len(B) > Q - 1:
            ans_cnd = B[Q - 1] - B[0]
            ans = ans if ans < ans_cnd else ans_cnd
    return ans


