def slv(N, K, Q, A):
    if Q == 1:
        return 0
    ans = sys.maxsize
    for i in range(N):
        x = A[i]
        s = 0
        yc = []
        for j in range(N):
            if A[j] < x:
                for c in sorted(A[s:j])[:len(A[s:j]) - Q + 1]:
                    bisect.insort(yc, c)
                s = j + 1
        else:
            for c in sorted(A[s:])[:len(A[s:]) - Q + 1]:
                bisect.insort(yc, c)

        if yc and len(yc) > Q - 1:
            ans = ans if ans < yc[Q - 1] - x else yc[Q - 1] - x

    return ans


