def mt(f):
    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(N, K, Q, A):
    if Q == 1:
        return 0
    ans = sys.maxsize
    for i in range(N):
        x = A[i]
        s = 0
        yc = []
        for j in range(N):
            if A[j] < x or i == j:
                for c in sorted(A[s:j])[:len(A[s:j]) - Q + 2]:
                    bisect.insort(yc, c)
                s = j + 1
        else:
            for c in sorted(A[s:])[:len(A[s:]) - Q + 2]:
                bisect.insort(yc, c)

        if yc and len(yc) > Q - 2:
            # print(yc, yc[Q - 2], x, yc[Q - 2] - x)
            ans = ans if ans < yc[Q - 2] - x else yc[Q - 2] - x

    return ans


