    luck_flag[j] = 1
    N = len(luck_flag)
    if j < K:
        luck_flag[:K] = 1
    elif j >= N - K:
        luck_flag[-K:] = 1
    else:
        for k in range(1, K+1):
            if luck_flag[j - k] == 1:
                for p in range(k+1):
                    luck_flag[j - p] = 1
                break
        for k in range(1, K+1):
            if luck_flag[j + k] == 1:
                for p in range(k+1):
                    luck_flag[j + p] = 1
                break  

    return luck_flag


