            let mut chunk = chunk.to_owned();
            chunk.sort();
            available.extend(chunk.into_iter().rev().skip(K - 1));
        }

        if available.len() < Q {
            continue;
        }

        available.sort();
        debug!(available);

        let y = available[0];
        let x = available[Q - 1];
        mi = min(mi, x - y);
    }

    println!("{}", mi)
}

