        if cc.iter().any(|&x| {
            let mut sum = 0;
            for i in 0..n {
                if aa[i] >= x && aa[i] <= x + mid && ll[i] + rr[i] >= k - 1 {
                    sum += 1;
                }
            }
            sum >= q
        }) {
            r = mid;
        } else {
            l = mid + 1;
        }
    }

