use procon::*;
use std::cmp::{max, min};
use std::collections::*;
use std::ops::*;
use std::*;

fn solve(K: usize, Q: usize, A: Vec<i64>) -> i64 {
    let mut score = std::i64::MAX;

    for y in A.iter().cloned() {
        // 最良のスコア X - Y が Y >= y で与えられるケースだけ考える。
        // y 未満の要素を含む部分列は選択できない。
        // y 未満の要素で数列を切断して、各部分を島と呼ぶ。
        // 各島について操作を行うとき、長さ K 以上なら、必ず最小値を消すことができる。
        // 各操作において、長さ K 以上の島に含まれる要素の中で最小のもの、を消すのが常に最善。
        // X が最小化されてベスト。

        let mut islands = Vec::new();
        let mut island = Vec::new();
        for a in A.iter().cloned() {
            if a < y {
                if island.len() >= K {
                    islands.push(island);
                    island = Vec::new();
                }
            } else {
                island.push(a);
            }
        }

        if island.len() >= K {
            islands.push(island);
        }

        //println!("y={} {:?}", y, islands);

        // Q 番目に小さい数を探す
        let mut heap = BinaryHeap::new();

        // 長さ K 未満の島からはドロップできないので、小さいものから (N-K+1) 個しか使えない

        for mut island in islands {
            island.sort();
            for &a in &island[0..(island.len() + 1 - K)] {
                heap.push(-a); // maxがpopされるので符号を反転しておく
            }
        }

        if heap.len() < Q {
            // Y >= y になる操作が存在しない
            continue;
        }

        let mut x = std::i64::MIN;
        let mut y = std::i64::MAX;
        for _ in 0..Q {
            let a = heap.pop().map(|a| -a).unwrap();
            x = max(x, a);
            y = min(y, a);
        }

        score = min(score, x - y);
    }
    score
}

