fn construct_usables(k: usize, min_candidate_a: u64, a: &Vec<u64>) -> Vec<u64> {
    let mut usables = Vec::new();

    let mut is_seeking = false;
    let mut start_seeking_index = 0usize;

    for j in 0..a.len() {
        if a[j] >= min_candidate_a {
            if !is_seeking {
                is_seeking = true;
                start_seeking_index = j;
            }
        }
        if is_seeking && (a[j] < min_candidate_a || j == a.len() - 1) {
            let mut end_idx = j;
            if j == a.len() - 1 {
                end_idx += 1;
            }
            is_seeking = false;
            if end_idx - start_seeking_index < k {
                continue;
            }

            let mut pocket_values = Vec::new();
            for ii in start_seeking_index..end_idx {
                pocket_values.push(a[ii]);
            }
            pocket_values.sort();

            let width = end_idx - start_seeking_index;
            for ii in 0..width - k + 1 {
                usables.push(pocket_values[ii]);
            }
        }
    }
    usables.sort();
    usables
}

