use io::*;
use std::cmp::{max, min};

fn main() {
    let con = read_string();
    let mut sc = Scanner::new(&con);

    let n: usize = sc.next();
    let k: usize = sc.next();
    let q: usize = sc.next();

    let a: Vec<u32> = sc.next_vec(n);

    let mut ans = u32::max_value();

    for &th in a.iter() {
        let mut tmp = vec![];
        let mut l = 0;
