use std::io::*;
use std::str::FromStr;
use std::collections::VecDeque;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn solve(seq: &Vec<i32>, k: usize, q: usize, min_value: i32, max_value: i32) -> bool {
    let n = seq.len();
    let mut que = VecDeque::<usize>::new();
    let mut use_flags = vec![false; n];
    let mut l = 0;
    let mut cnt = 0;
    let mut small_value = 0;
    let mut large_value = 0;
    let mut ans = 0;
    for i in 0..n {
        cnt += 1;
        if seq[i] < min_value {
            small_value += 1;
        } else if max_value < seq[i] {
            large_value += 1;
        } else {
            que.push_back(i);
        }
        while cnt > k {
            let v = seq[l];
            if v < min_value {
                small_value -= 1;
                cnt -= 1;
            } else if max_value < v {
                large_value -= 1;
                cnt -= 1;
            } else if !use_flags[l] {
                que.pop_front();
                cnt -= 1;
            }
            l += 1;
        }
        if cnt == k && small_value == 0 && large_value != k {
            let index = que.pop_front().unwrap();
            use_flags[index] = true;
            cnt -= 1;
            ans += 1;
            if ans == q {
                return true;
            }
        }
    }
    return false;
}

fn main() {
    let n = read::<usize>();
    let k = read::<usize>();
    let q = read::<usize>();
    let mut seq = vec![0; n];
    for i in 0..n {
        seq[i] = read::<i32>();
    }
    let mut ans = sort_seq[n - 1] - sort_seq[0];
    for i in 0..n {
        let min_value = sort_seq[i];
        let mut left = best_values[i] - 1;
        let mut right = ans;
        while right - left > 1 {
            let mid = (left + right) / 2;
            if solve(&seq, k, q, min_value, min_value + mid) {
                right = mid;
            } else {
                left = mid;
            }
        }
        ans = right;
    }
    println!("{}", ans);
}

use std::io::*;
use std::str::FromStr;
use std::collections::BTreeMap;

#[allow(dead_code)]
fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn remove_value(open: &mut BTreeMap<i32, usize>, v: i32, cnt: &mut usize) {
    let mut rm = false;
    if let Some(counter) = open.get_mut(&v) {
        *cnt -= 1;
        *counter -= 1;
        if *counter == 0 {
            rm = true;
        }
    }
    if rm {
        open.remove(&v);
    }
}

fn solve(seq: &Vec<i32>, k: usize, q: usize, min_value: i32, max_value: i32) -> i32 {
    let n = seq.len();
    let mut open = BTreeMap::<i32, usize>::new();
    let mut l = 0;
    let mut cnt = 0;
    let mut ans_seq = vec![];
    let mut small_value = 0;
    let mut large_value = 0;
    for i in 0..n {
        cnt += 1;
        if seq[i] < min_value {
            small_value += 1;
        } else if max_value < seq[i] {
            large_value += 1;
        } else {
            *open.entry(seq[i]).or_insert(0) += 1;
        }
        while cnt > k {
            let v = seq[l];
            l += 1;
            if v < min_value {
                small_value -= 1;
                cnt -= 1;
            } else if max_value < v {
                large_value -= 1;
                cnt -= 1;
            } else {
                remove_value(&mut open, v, &mut cnt);
            }
        }
        if cnt == k && small_value == 0 && large_value != k {
            let &v = open.iter().next().unwrap().0;
            ans_seq.push(v);
            remove_value(&mut open, v, &mut cnt);
            if ans_seq.len() == q {
                break;
            }
        }
    }
    if ans_seq.len() < q {
        return max_value;
    }
    ans_seq.sort();
    let ret = ans_seq[q - 1] - ans_seq[0];
    // println!("{:?}", ans_seq);
    assert!(ret <= max_value - min_value);
    ret
}

fn main() {
    let n = read::<usize>();
    let k = read::<usize>();
    let q = read::<usize>();
    let mut seq = vec![0; n];
    for i in 0..n {
        seq[i] = read::<i32>();
    }
    let mut sort_seq = seq.clone();
    sort_seq.sort();
    let mut best_values = vec![1e+9 as i32; n];
    for i in 0..n {
        if i + q - 1 < n {
            best_values[i] = sort_seq[i + q - 1] - sort_seq[i];
        }
    }
    let mut ans = 1e+9 as i32;
    for i in 0..n {
        if i != 0 && sort_seq[i - 1] == sort_seq[i] {
            continue;
        }
        let min_value = sort_seq[i];
        let mut left = best_values[i];
        let mut right = ans;
        while right - left > 1 {
            let mid = (left + right) / 2;
            let v = solve(&seq, k, q, min_value, min_value + mid);
            // println!("{} {} {} {}", left, right, mid, v);
            if v <= mid {
                right = v;
            } else {
                left = mid;
            }
        }
        ans = right;
        if right != 1 {
            ans = std::cmp::min(ans, solve(&seq, k, q, min_value, min_value + right - 1));
        }
    }
    println!("{}", ans);
}

use io::*;
use std::cmp::{max, min};
use std::collections::BTreeMap;

fn main() {
    let con = read_string();
    let mut sc = Scanner::new(&con);

    let n: usize = sc.next();
    let k: usize = sc.next();
    let q: usize = sc.next();

    let a: Vec<u32> = sc.next_vec(n);

    let mut mm: BTreeMap<u32, i32> = BTreeMap::new();
    for i in 0..k {
        *mm.entry(a[i]).or_insert(0) += 1;
    }

    // let mut ok = 0, ng = u32::max_value();

    // while (ok-ng).abs() > 1 {

    // }

    let mut cands = vec![];
    cands.push(*mm.iter().next().unwrap().0);

    for i in 0..n - k {
        *mm.entry(a[i + k]).or_insert(0) += 1;
        *mm.entry(a[i]).or_insert(0) -= 1;
        if mm[&a[i]] == 0 {
            mm.remove(&a[i]);
        }
        cands.push(*mm.iter().next().unwrap().0);
    }
    cands.sort();

    let mut ans = u32::max_value();

    for cand in cands {
        let mut a2 = a.clone();
        let ix = a2.iter().position(|&e| e == cand).unwrap();
        a2.remove(ix);

        let cur = solve(a2, cand, k, q);
        if cur == u32::max_value() {
            break;
        }

        ans = min(ans, cur);
        break;
    }

    println!("{}", ans);
}

fn solve(mut v: Vec<u32>, th: u32, k: usize, q: usize) -> u32 {
    let mut ma = th;

    for _ in 0..q - 1 {
        let n = v.len();

        let mut mm: BTreeMap<u32, i32> = BTreeMap::new();
        for i in 0..k {
            *mm.entry(v[i]).or_insert(0) += 1;
        }

        let mut cand = u32::max_value();
        let t = *mm.iter().next().unwrap().0;
        if t >= th {
            cand = min(cand, t);
        }

        for i in 0..n - k {
            *mm.entry(v[i + k]).or_insert(0) += 1;
            *mm.entry(v[i]).or_insert(0) -= 1;
            if mm[&v[i]] == 0 {
                mm.remove(&v[i]);
            }
            let t = *mm.iter().next().unwrap().0;
            if t >= th {
                cand = min(cand, t);
            }
        }

        if cand == u32::max_value() {
            return u32::max_value();
        }

        ma = max(ma, cand);

        let ix = v.iter().position(|&e| e == cand).unwrap();
        v.remove(ix);
    }

    ma - th
}

