fn main() {
    let con = read_string();
    let mut sc = Scanner::new(&con);

    let n: usize = sc.next();
    let k: usize = sc.next();
    let q: usize = sc.next();

    let a: Vec<u32> = sc.next_vec(n);

    let mut mm: BTreeMap<u32, i32> = BTreeMap::new();
    for i in 0..k {
        *mm.entry(a[i]).or_insert(0) += 1;
    }

    // let mut ok = 0, ng = u32::max_value();

    // while (ok-ng).abs() > 1 {

    // }

    let mut cands = vec![];
    cands.push(*mm.iter().next().unwrap().0);

    for i in 0..n - k {
        *mm.entry(a[i + k]).or_insert(0) += 1;
        *mm.entry(a[i]).or_insert(0) -= 1;
        if mm[&a[i]] == 0 {
            mm.remove(&a[i]);
        }
        cands.push(*mm.iter().next().unwrap().0);
    }

    // let mut ans = u32::max_value();

    cands.sort();

    for cand in cands {
        let mut a2 = a.clone();
        let ix = a2.iter().position(|&e| e == cand).unwrap();
        a2.remove(ix);

        let cur = solve(a2, cand, k, q);
        if cur == u32::max_value() {
            break;
        }

        ans = min(ans, cur);
    }

    println!("{}", ans);
}

fn solve(mut v: Vec<u32>, th: u32, k: usize, q: usize) -> u32 {
    let mut ma = th;

    for _ in 0..q - 1 {
        let n = v.len();

        let mut mm: BTreeMap<u32, i32> = BTreeMap::new();
        for i in 0..k {
            *mm.entry(v[i]).or_insert(0) += 1;
        }

        let mut cand = u32::max_value();
        let t = *mm.iter().next().unwrap().0;
        if t >= th {
            cand = min(cand, t);
        }

        for i in 0..n - k {
            *mm.entry(v[i + k]).or_insert(0) += 1;
            *mm.entry(v[i]).or_insert(0) -= 1;
            if mm[&v[i]] == 0 {
                mm.remove(&v[i]);
            }
            let t = *mm.iter().next().unwrap().0;
            if t >= th {
                cand = min(cand, t);
            }
        }

        if cand == u32::max_value() {
            return u32::max_value();
        }

        ma = max(ma, cand);

        let ix = v.iter().position(|&e| e == cand).unwrap();
        v.remove(ix);
    }

    ma - th
}

