    let v = read_vec::<usize>();
    let (n, k, q) = (v[0], v[1], v[2]);
    let a = read_vec::<u64>();

    let mut ans = std::u64::MAX;
    for i in 0..n {
        let min_candidate_a = a[i];
        let usables = construct_usables(k, min_candidate_a, &a);
        if usables.len() >= q {
            assert_eq!(usables[0], min_candidate_a);
            ans = min(ans, usables[q - 1] - min_candidate_a);
        }
    }
    println!("{}", ans);
}

use std::io::*;
