fn main() {
    input! { n, k, q, a: [usize; n] };
    let mut b = a.iter().cloned().collect::<Vec<_>>();
    b.sort();
    let mut ans = b[q - 1] - b[0];
    for i in 1..n - q + 1 {
        let res = b[i + q - 1] - b[i];
        let mut l = 0;
        let mut acc = 0;
        loop {
            while l < n && b[i] > a[l] {
                l += 1;
            }
            if l == n {
                break;
            }
            let mut r = l;
            let mut c = 0;
            while r < n && b[i] <= a[r] {
                if a[r] <= b[i + q - 1] {
                    c += 1;
                }
                r += 1;
            }
            acc += min(c, max(0, (r - l + 1) as isize - k as isize));
            l = r;
        }
        if acc >= q as isize {
            ans = min(ans, res);
        }
    }
    println!("{}", ans);
}

