        // 各島について件のルールで最小値を消していくとき、常に列島の最小値は選択できる。とにかく最小値を消していくことでXを最小化できて、ベスト。

        let mut islands = Vec::new();
        let mut island = min_heap();
        for a in A.iter().cloned() {
            if a < y {
                if island.len() >= K {
                    islands.push(island);
                    island = min_heap();
                }

            // ignore leading <y s
            } else {
                island.push(-a);
            }
        }

        if island.len() >= K {
            islands.push(island);
        }

        //println!("y={} {:?}", y, islands);

        // Q 番目に小さい数を探す
        // 長さ K 未満の島からはドロップできないので注意
        let mut heap = min_heap();

        for mut island in islands {
            let c = island.len() + 1 - K;
            for _ in 0..c {
                heap.push(island.pop().unwrap());
            }
        }

        let mut x = None;
        for _ in 0..Q {
            x = heap.pop();
        }

        if let Some(x) = x {
            score = min(score, (-x) - y);
        }
    }
    score
}

