    let mut ans = 1_001_001_001;
    'outer: for i in 0..n - q + 1 {
        let l = b[i].0;
        let r = if i + q < n { b[i + q].0 } else { 1_001_001_001 };
        let mut c1 = 0;
        let mut c2 = 0;
        for j in 0..n {
            if l <= a[j] {
                c1 += 1;
                if a[j] < r {
                    c2 += 1;
                }
            } else {
                if c2 > 0 && c1 - c2 + 1 < k {
                    continue 'outer;
                }
                c1 = 0;
                c2 = 0;
            }
        }
        if c2 > 0 && c1 - c2 + 1 < k {
            continue 'outer;
        }
        ans = std::cmp::min(ans, b[i + q - 1].0 - b[i].0);
    }
    println!("{}", ans);
}

