fn argsort<T: std::cmp::Ord + std::marker::Copy>(v: &Vec<T>) -> Vec<usize> {
    let mut sort_v = Vec::new();
    for i in 0..v.len() {
        sort_v.push((v[i], i));
    }
    sort_v.sort();
    sort_v.iter().map(|x| x.1).collect::<Vec<usize>>()
}

#[derive(Debug)]
struct Pocket {
    width: usize,
    used_count: usize,
}

fn construct_pockets(min_candidate_a: u64, a: &Vec<u64>) -> (Vec<Pocket>, HashMap<usize, usize>) {
    let mut array_idx_to_pocket_idx = HashMap::<usize, usize>::new();
    let mut pockets = Vec::new();

    // make pocket
    let mut is_seeking = false;
    let mut start_seeking_index = 0usize;

    for j in 0..a.len() {
        if a[j] >= min_candidate_a {
            if !is_seeking {
                is_seeking = true;
                start_seeking_index = j;
            }
        }
        if is_seeking {
            array_idx_to_pocket_idx.insert(j, pockets.len());
        }
        if is_seeking && (a[j] < min_candidate_a || j == a.len() - 1) {
            let mut end_idx = j;
            if j == a.len() - 1 {
                end_idx += 1;
            }
            is_seeking = false;
            let new_pocket = Pocket {
                width: end_idx - start_seeking_index,
                used_count: 0,
            };
            pockets.push(new_pocket);
        }
    }

    (pockets, array_idx_to_pocket_idx)
}

fn main() {
    let v = read_vec::<usize>();
    let (n, k, q) = (v[0], v[1], v[2]);
    let a = read_vec::<u64>();

    if q == 1 {
        println!("0");
        return;
    }

    let sorted_indexes = argsort(&a);
    let mut sorted_indexes_dict = vec![0; n];

    for i in 0..n {
        sorted_indexes_dict[sorted_indexes[i]] = i;
    }

    let mut ans = std::u64::MAX;
    for i in 0..n - q + 1 {
        let min_candidate_a = a[i];
        let (pockets, array_idx_to_pocket_idx) = construct_pockets(min_candidate_a, &a);
        let mut pockets = pockets;
        // println!("pocket {:?}", (min_candidate_a, &pockets));
        // println!("{:?}", array_idx_to_pocket_idx);

        let mut total_used_count = 0;
        let mut next_a_index = i;
        loop {
            let mut next_pocket = &mut pockets[array_idx_to_pocket_idx[&next_a_index]];
            if next_pocket.width - next_pocket.used_count >= k {
                next_pocket.used_count += 1;
                total_used_count += 1;
            }
            if sorted_indexes_dict[next_a_index] == n - 1 {
                break;
            }
            if total_used_count == q {
                break;
            }
            next_a_index = sorted_indexes[(sorted_indexes_dict[next_a_index] + 1)];
        }
        if total_used_count == q {
            // println!("{0} {1}", a[next_a_index], min_candidate_a);
            ans = min(ans, a[next_a_index] - min_candidate_a);
        }
    }
    println!("{}", ans);
}

