use std::collections::{HashMap, BTreeSet};
use std::iter::once;
use std::cmp;

struct Segments {
    starts: BTreeSet<usize>,
    ends: BTreeSet<usize>,
    k: usize,
    count: usize,

}

impl Segments {
    fn new(n: usize, k: usize) -> Segments {
        Segments {
            starts: once(0).collect(),
            ends: once(n).collect(),
            k,
            count: n - k + 1
        }
    }

    fn divide(&mut self, i: usize) {
        let start = *self.starts.range(..=i).last().unwrap();
        let end = *self.ends.range(i+1..).next().unwrap();
        self.ends.insert(i);
        self.starts.insert(i+1);

        let len0 = end - start;
        let count0 = len0.saturating_sub(self.k-1);
        let len1 = i - start;
        let count1 = len1.saturating_sub(self.k-1);
        let len2 = end - (i+1);
        let count2 = len2.saturating_sub(self.k-1);

        self.count += count1 + count2;
        self.count -= count0;
    }

    fn count_selectable(&self) -> usize {
        self.count
    }
}

fn main() {
    read!(n = usize, k = usize, q = usize);
    read!(mut aa = Vec<usize>);
    let mut a_to_is = HashMap::new();
    for (i, &a) in aa.iter().enumerate() {
        a_to_is.entry(a).or_insert(Vec::new()).push(i)
    }
    let mut segs = Segments::new(n, k);

    aa.sort();
    let ans = once(aa[q-1] - aa[0]).chain(
        aa.windows(q+1)
            .take_while(|w| {
                let i = a_to_is.get_mut(&w[0]).unwrap().pop().unwrap();
                segs.divide(i);
                segs.count_selectable() >= q
            })
            .map(|w| {
                let first = w[1];
                let last = *w.last().unwrap();
                last - first
            })
    ).min().unwrap();
    println!("{}", ans);
}
